function ftzIcon(name, size, color) {
  const svg = _svgIcons[name];
  if (!svg) return '';
  let out = svg;
  if (size) out = out.replace(/width="1em"/, `width="${size}"`).replace(/height="1em"/, `height="${size}"`);
  if (color) out = out.replace(/stroke="currentColor"/g, `stroke="${color}"`).replace(/fill="currentColor"/g, `fill="${color}"`);
  return out;
}
// Shorthand icon helpers — Radiance & Onyx use PNG images (displayed inline like SVGs), Boost uses SVG
function _onyxImg(size){const s=size||'18';return '<img src="/fortized badges/onyx.png" width="'+s+'" height="'+s+'" style="display:inline-block;vertical-align:middle;object-fit:contain;" alt="Onyx">';}
function _radianceImg(size){const s=size||'16';return '<img src="/fortized badges/basic radiance.png" width="'+s+'" height="'+s+'" style="display:inline-block;vertical-align:middle;object-fit:contain;" alt="Radiance">';}
function _radiancePlusImg(size){const s=size||'16';return '<img src="/fortized badges/radiance+.png" width="'+s+'" height="'+s+'" style="display:inline-block;vertical-align:middle;object-fit:contain;" alt="Radiance+">';}
function _boostSvg(size){return ftzIcon('boost',size||'18','currentColor');}

// ══════════════════════════════════════════════════════════
// COMPANION BRIDGE  (localhost process scanner)
// ══════════════════════════════════════════════════════════
// The Fortized Companion is a tiny local helper (Python script) that
// exposes running processes on http://127.0.0.1:47832.
// If it's not running we fall back to manual activity picking.
const COMPANION_PORT = 47832;
const COMPANION_BASE = 'http://127.0.0.1:' + COMPANION_PORT;
let _companionOnline = false;

async function companionFetch(path) {
  try {
    const r = await fetch(COMPANION_BASE + path, { signal: AbortSignal.timeout(1500) });
    if (!r.ok) return null;
    _companionOnline = true;
    return await r.json();
  } catch {
    _companionOnline = false;
    return null;
  }
}

async function companionGetProcesses() {
  const data = await companionFetch('/processes');
  return data?.processes || null;
}

async function companionGetIdleTime() {
  const data = await companionFetch('/idle');
  return data?.idle_seconds ?? null;
}

async function companionPing() {
  const data = await companionFetch('/ping');
  _companionOnline = !!(data?.status === 'ok');
  return _companionOnline;
}

