// FAVICON NOTIFICATION SWAP
// ══════════════════════════════════════════════════════════
let _faviconHasNotif = false;
function setFaviconNotif(hasNotif) {
  if (_faviconHasNotif === hasNotif) return;
  _faviconHasNotif = hasNotif;
  const el = document.getElementById('favicon');
  if (el) el.href = hasNotif ? '/Fortized icon notif.png' : '/Fortized icon.png';
}

