let CU = null;
const _pfpCache = {};
const _pfpCropCache = {}; // username -> {leftPct, topPct, widthPct} for GIF avatar CSS cropping
const _liveStatusCache = {}; // username -> status, updated by real-time presence events
let curBastion = null;
let curChannel = null;
let curDM = null;
// ── Chat scroll position persistence ──
const _chatScrollPositions = {};
function _saveChatScroll(key, el) {
  if (!el || !key) return;
  _chatScrollPositions[key] = { top: el.scrollTop, height: el.scrollHeight };
}
function _restoreChatScroll(key, el) {
  if (!el || !key) return false;
  const saved = _chatScrollPositions[key];
  if (!saved) return false;
  // If the scroll height changed significantly (new messages loaded), go to bottom
  if (Math.abs(el.scrollHeight - saved.height) > 200) return false;
  el.scrollTop = saved.top;
  return true;
}
// Unread tracking per channel: Map<bastionIdx_chIdx, {count:number, mentions:number}>
const _channelUnread = new Map();
function getChannelUnreadKey(bIdx, chIdx) { return bIdx+'_'+chIdx; }
function getChannelUnread(bIdx, chIdx) { return _channelUnread.get(getChannelUnreadKey(bIdx,chIdx)) || {count:0, mentions:0}; }
function markChannelUnread(bIdx, chIdx, mentionMe) {
  const k = getChannelUnreadKey(bIdx,chIdx);
  const cur = _channelUnread.get(k) || {count:0, mentions:0};
  cur.count++;
  if (mentionMe) cur.mentions++;
  _channelUnread.set(k, cur);
  // Re-render sidebar to show badge
  const scroll = document.querySelector('.sidebar-scroll');
  if (curBastion === bIdx && scroll) renderBastionSidebar(scroll);
}
function clearChannelUnread(bIdx, chIdx) {
  _channelUnread.delete(getChannelUnreadKey(bIdx,chIdx));
}
