// Constants for moderation and age tiers

const REPORT_REASONS = ['Harassment','Hate Speech','NSFW / Explicit Content','Spam or Scam','Threats or Violence','Self-Harm or Suicide','Illegal Content','Other'];
const AGE_TIERS = {CHILD:'child',TEEN:'teen',ADULT:'adult'};

// ── Helpers ──────────────────────────────────────────────────
function saveLocal() {
  if (!CU?.username) return;
  localStorage.setItem('ftz_current', CU.username);
  localStorage.setItem('fortized_current_user', CU.username);
  try { localStorage.setItem('ftz_user_' + CU.username, JSON.stringify(CU)); } catch(e) { console.warn('localStorage save failed:', e); }
}
let _saveUserTimer = null;
let _saveUserPromise = null;
let _isSaving = false; // Prevent concurrent saves
async function saveUser(immediate) {
  saveLocal();
  if (!immediate && _saveUserTimer) clearTimeout(_saveUserTimer);
  const doSave = async () => {
    // Wait for any in-flight save to complete
    if (_isSaving) {
      while (_isSaving) await new Promise(r => setTimeout(r, 50));
      return;
    }
    if (_saveUserPromise) await _saveUserPromise.catch(()=>{});
    _isSaving = true;
    _saveUserPromise = (async () => {
      try {
        await FortizedSocial.saveUserObject(CU);
      } catch(e) {
        console.warn('saveUser failed, retrying:', e);
        try { await new Promise(r => setTimeout(r, 1000)); await FortizedSocial.saveUserObject(CU); }
        catch(e2) { console.error('saveUser retry failed:', e2); toast('Failed to save data. Check your connection.', 'error'); }
      } finally { _saveUserPromise = null; _isSaving = false; }
    })();
    return _saveUserPromise;
  };
  if (immediate) return doSave();
  return new Promise(resolve => {
    _saveUserTimer = setTimeout(() => { doSave().then(resolve).catch(resolve); }, 300);
  });
}
// Sync a local bastion's data to the global bastions collection
async function _syncBastionToGlobal(bastionIdx) {
  try {
    const b = CU?.bastions?.[bastionIdx];
    if (!b) return;
    // Ensure bastion always has a unique globalId
    if (!b.globalId) {
      b.globalId = (b.owner || CU.username) + '_' + Date.now();
      await saveUser();
      await FortizedSocial.addBastionMember(b.globalId, CU.username);
    }
    const bid = b.globalId;
    const globalData = {...b, id: bid, owner: b.owner || CU.username, memberCount: b.memberCount || 1};
    delete globalData.globalId; // avoid nesting
    await FortizedSocial.saveGlobalBastion(bid, globalData);
  } catch(e) {
    console.warn('Bastion sync to global failed:', e);
    // Retry once
    try { await new Promise(r => setTimeout(r, 1000)); const b2 = CU?.bastions?.[bastionIdx]; if (b2?.globalId) await FortizedSocial.saveGlobalBastion(b2.globalId, {...b2, id: b2.globalId, owner: b2.owner || CU.username}); } catch(e2) { console.warn('[Bastion] Retry sync also failed:', e2?.message); }
  }
}
// Pull fresh bastion data from global for non-owners so banner/emblem/roles/moods stay current
async function _syncBastionFromGlobal(bastionIdx) {
  try {
    const b = CU?.bastions?.[bastionIdx];
    if (!b || !b.globalId) return;
    const global = await FortizedSocial.getGlobalBastion(b.globalId);
    if (!global) return;
    // Merge global fields into local copy (owner-managed data)
    const syncFields = ['name','emblem','icon','banner','tagline','desc','channels','roles','memberRoles','public','automod','boostLevel','customEmojis','invites','moodDisabled','moodLocked','lockedMood','customMood','memberCount','owner','overview'];
    let changed = false;
    for (const key of syncFields) {
      if (global[key] !== undefined && JSON.stringify(b[key]) !== JSON.stringify(global[key])) {
        b[key] = global[key];
        changed = true;
      }
    }
    if (changed) {
      await saveUser();
      // Re-render sidebar if this bastion is currently open
      if (curBastion === bastionIdx) {
        const scroll = document.getElementById('sidebar-scroll');
        if (scroll) renderBastionSidebar(scroll);
        renderRailBastions();
      }
    }
  } catch(e) { console.warn('[Bastion] Sync from global failed:', e?.message); }
}
async function refreshCU() {
  if (!CU?.username) return;
  try {
    const prevRad = CU.radianceUntil, prevPlus = CU.radiancePlus;
    const prevBastions = CU.bastions;
    const prevStatus = CU.status;
    const fresh = await Promise.race([
      FortizedSocial.getUserByName(CU.username, { noCache: true }),
      new Promise((_,r)=>setTimeout(()=>r(new Error('timeout')),5000))
    ]);
    if (fresh?.username) {
      console.debug('[refreshCU] Fresh data from DB:', { username: fresh.username, pfp: fresh.pfp ? 'set' : 'null', friends: fresh.friends?.length || 0 });

      // Preserve radiance data if DB returned null but local had active values
      if(!fresh.radianceUntil && prevRad && new Date(prevRad)>new Date()) fresh.radianceUntil=prevRad;
      if(!fresh.radiancePlus && prevPlus && new Date(prevPlus)>new Date()) fresh.radiancePlus=prevPlus;
      // Preserve bastions if they were already loaded with full data (avoid losing channel/role data)
      if (prevBastions && Array.isArray(prevBastions) && prevBastions.length > 0 && (!fresh.bastions || fresh.bastions.length === 0)) {
        fresh.bastions = prevBastions;
      } else if (prevBastions && Array.isArray(prevBastions) && fresh.bastions && Array.isArray(fresh.bastions)) {
        // Merge: keep local bastion data (channels, roles etc.) that may not be in the DB user row
        fresh.bastions = fresh.bastions.map(fb => {
          const local = prevBastions.find(lb => (lb.globalId||lb.name) === (fb.globalId||fb.name));
          if (local) return { ...local, ...fb, channels: fb.channels || local.channels, roles: fb.roles || local.roles, memberRoles: fb.memberRoles || local.memberRoles };
          return fb;
        });
      }
      // IMPORTANT: Trust database for PFP, messages, friends (don't preserve local copy)
      // These fields are the source of truth from the database and should override local data
      // Preserve locally-known live status (Socket.IO is source of truth, not stale DB)
      if (prevStatus && prevStatus !== 'offline') fresh.status = prevStatus;
      // Preserve quest/onyx data — local is source of truth since saves may be in-flight
      const prevOnyx = CU.onyx;
      const prevLastDaily = CU.lastDailyReward || CU.lastDaily;
      if (prevOnyx !== undefined && (fresh.onyx === undefined || fresh.onyx < prevOnyx)) fresh.onyx = prevOnyx;
      if (CU.lastDailyReward && !fresh.lastDailyReward) fresh.lastDailyReward = CU.lastDailyReward;
      if (CU.lastDaily && !fresh.lastDaily) fresh.lastDaily = CU.lastDaily;
      if (CU.dailyStreak && !fresh.dailyStreak) fresh.dailyStreak = CU.dailyStreak;
      if (CU.questsDailyLog) fresh.questsDailyLog = { ...(fresh.questsDailyLog||{}), ...CU.questsDailyLog };
      if (CU.completedQuests?.length) {
        const merged = new Set([...(fresh.completedQuests||[]), ...CU.completedQuests]);
        fresh.completedQuests = [...merged];
      }
      if (CU.questsRewarded?.length) {
        const merged = new Set([...(fresh.questsRewarded||[]), ...CU.questsRewarded]);
        fresh.questsRewarded = [...merged];
      }
      // Preserve shop inventory — local is source of truth since saves may be in-flight
      if (CU.unlockedAppearances?.length && (!fresh.unlockedAppearances?.length || fresh.unlockedAppearances.length < CU.unlockedAppearances.length)) {
        const merged = new Set([...(fresh.unlockedAppearances||[]), ...CU.unlockedAppearances]);
        fresh.unlockedAppearances = [...merged];
      }
      if (CU.ownedDecorations?.length && (!fresh.ownedDecorations?.length || fresh.ownedDecorations.length < CU.ownedDecorations.length)) {
        const merged = new Set([...(fresh.ownedDecorations||[]), ...CU.ownedDecorations]);
        fresh.ownedDecorations = [...merged];
      }
      if (CU.activeDecoration && !fresh.activeDecoration) fresh.activeDecoration = CU.activeDecoration;
      if (CU.onyxBadge && !fresh.onyxBadge) { fresh.onyxBadge = true; fresh.onyxBadgeSpent = Math.max(fresh.onyxBadgeSpent||0, CU.onyxBadgeSpent||0); }
      // Preserve display name style settings
      if (CU.displayFont && !fresh.displayFont) fresh.displayFont = CU.displayFont;
      if (CU.displayEffect && !fresh.displayEffect) fresh.displayEffect = CU.displayEffect;
      if (CU.displayColor && !fresh.displayColor) fresh.displayColor = CU.displayColor;
      if (CU.profileTheme && !fresh.profileTheme) fresh.profileTheme = CU.profileTheme;
      if (CU.wantToPlay?.length && !fresh.wantToPlay?.length) fresh.wantToPlay = CU.wantToPlay;
      // Preserve profile widgets
      if (CU.profileWidgets?.length && !fresh.profileWidgets?.length) fresh.profileWidgets = CU.profileWidgets;
      // Preserve Spotify connection data
      if (CU.spotifyConnected && !fresh.spotifyConnected) fresh.spotifyConnected = CU.spotifyConnected;
      if (CU.spotifyToken && !fresh.spotifyToken) fresh.spotifyToken = CU.spotifyToken;
      if (CU.spotifyRefreshToken && !fresh.spotifyRefreshToken) fresh.spotifyRefreshToken = CU.spotifyRefreshToken;
      if (CU.spotifyTokenExpiry && !fresh.spotifyTokenExpiry) fresh.spotifyTokenExpiry = CU.spotifyTokenExpiry;
      if (CU.spotifyNowPlaying && !fresh.spotifyNowPlaying) fresh.spotifyNowPlaying = CU.spotifyNowPlaying;
      // Preserve game collection
      if (CU.gameCollection?.length && (!fresh.gameCollection?.length || fresh.gameCollection.length < CU.gameCollection.length)) fresh.gameCollection = CU.gameCollection;
      CU = fresh; saveLocal();
      // Check for admin force-logout flag
      _checkForceLogout(fresh);
    }
  } catch(e) { console.warn('[RefreshCU] Failed to refresh user data:', e?.message); }
}
function _checkForceLogout(user) {
  if (!user) return;
  const forceLogoutAt = user.forceLogoutAt || (user.raw && user.raw.forceLogoutAt);
  if (!forceLogoutAt) return;
  const lastChecked = localStorage.getItem('ftz_force_logout_ack');
  if (lastChecked === forceLogoutAt) return; // Already acknowledged
  // Force logout
  localStorage.setItem('ftz_force_logout_ack', forceLogoutAt);
  toast('You have been logged out by an administrator.', 'error');
  setTimeout(() => {
    FortizedSocial.logout();
    location.reload();
  }, 1500);
}
function escapeHTML(s) {
  if (!s) return '';
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
}


function _getTrustedDomains() {
  const builtIn = ['youtube.com','youtu.be','spotify.com','github.com','twitter.com','x.com','twitch.tv','reddit.com','itch.io','roblox.com','steam','fortized.com','giphy.com','klipy.com','tenor.com'];
  try { const user = JSON.parse(localStorage.getItem('ftz_trusted_domains')||'[]'); return [...builtIn, ...user]; } catch (e) { console.debug('[URL] trusted domains parse failed', e); return builtIn; }
}
function _trustDomain(domain) {
  try {
    const user = JSON.parse(localStorage.getItem('ftz_trusted_domains')||'[]');
    if (!user.includes(domain)) { user.push(domain); localStorage.setItem('ftz_trusted_domains', JSON.stringify(user)); }
  } catch (e) { console.debug('[URL] trust domain save failed', e); }
}
function openExternalLink(e, url) {
  if (e) e.preventDefault();
  if (!url) return;
  const trustedDomains = _getTrustedDomains();
  let isTrusted = false;
  let urlDomain = '';
  try { urlDomain = new URL(url).hostname; isTrusted = trustedDomains.some(d => urlDomain.includes(d)); } catch (e) { console.debug('[URL] parse failed', e); }
  if (isTrusted) {
    window.open(url, '_blank', 'noopener,noreferrer');
  } else {
    _showLeavingFortizedModal(url, urlDomain);
  }
}
function _showLeavingFortizedModal(url, domain) {
  const overlay = document.createElement('div');
  overlay.className = 'input-dialog-overlay';
  overlay.className = 'input-dialog-overlay ftz-confirm-overlay';
  // Bold the domain in the displayed URL
  const displayUrl = escapeHTML(url.length > 120 ? url.slice(0,120)+'…' : url).replace(escapeHTML(domain), '<strong style="color:#fff;">'+escapeHTML(domain)+'</strong>');
  overlay.innerHTML = `
    <div style="background:var(--panel,#13161d);border:1px solid rgba(255,249,62,.1);border-radius:16px;width:440px;max-width:92vw;box-shadow:0 24px 80px rgba(0,0,0,.8),0 0 0 1px rgba(255,255,255,.03) inset;animation:ftzSlideUp .2s ease;">
      <div style="padding:28px 28px 0;">
        <div style="display:flex;align-items:center;gap:10px;margin-bottom:16px;">
          <div style="width:36px;height:36px;border-radius:10px;background:rgba(255,249,62,.08);display:flex;align-items:center;justify-content:center;flex-shrink:0;">
            <svg width="18" height="18" viewBox="0 0 16 16" fill="none" stroke="var(--accent,#fff93e)" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M7 2H3a1 1 0 0 0-1 1v10a1 1 0 0 0 1 1h10a1 1 0 0 0 1-1V9"/><path d="M9 1h6v6"/><path d="M15 1L7 9"/></svg>
          </div>
          <h3 style="font-family:var(--font-display,'Syne',sans-serif);font-size:18px;font-weight:700;color:#fff;margin:0;">Leaving Fortized</h3>
        </div>
        <p style="font-size:13px;color:rgba(255,255,255,.55);line-height:1.55;margin-bottom:16px;">You're about to visit an external website. Make sure you trust this link before continuing.</p>
        <div style="background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.06);border-radius:10px;padding:12px 14px;font-family:'DM Mono',monospace,var(--font-body);font-size:12.5px;color:rgba(255,255,255,.45);word-break:break-all;line-height:1.5;margin-bottom:16px;">${displayUrl}</div>
        <label style="display:flex;align-items:center;gap:9px;cursor:pointer;padding:10px 0 4px;user-select:none;" id="ftz-trust-label">
          <input type="checkbox" id="ftz-trust-check" style="appearance:none;width:16px;height:16px;border:1.5px solid rgba(255,249,62,.25);border-radius:4px;background:rgba(255,249,62,.04);cursor:pointer;flex-shrink:0;position:relative;transition:all .15s;">
          <span style="font-size:12.5px;color:rgba(255,255,255,.5);">Trust <strong style="color:rgba(255,255,255,.7);">${escapeHTML(domain)}</strong> links from now on</span>
        </label>
      </div>
      <div style="display:flex;gap:10px;padding:20px 28px 24px;justify-content:flex-end;">
        <button id="ftz-ext-back" style="padding:9px 20px;border-radius:10px;border:1px solid rgba(255,255,255,.08);background:rgba(255,255,255,.04);color:rgba(255,255,255,.7);font-size:13px;font-weight:600;cursor:pointer;transition:all .15s;font-family:var(--font-body);">Go Back</button>
        <button id="ftz-ext-visit" style="padding:9px 20px;border-radius:10px;border:1px solid rgba(255,249,62,.2);background:rgba(255,249,62,.08);color:var(--accent,#fff93e);font-size:13px;font-weight:600;cursor:pointer;transition:all .15s;font-family:var(--font-body);">Visit Site</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  // Checkbox visual
  const chk = document.getElementById('ftz-trust-check');
  if (chk) chk.addEventListener('change', function() {
    this.style.background = this.checked ? 'var(--accent,#fff93e)' : 'rgba(255,249,62,.04)';
    this.style.borderColor = this.checked ? 'var(--accent,#fff93e)' : 'rgba(255,249,62,.25)';
    this.style.boxShadow = this.checked ? '0 0 8px rgba(255,249,62,.3)' : 'none';
  });
  document.getElementById('ftz-ext-back').onclick = () => overlay.remove();
  document.getElementById('ftz-ext-visit').onclick = () => {
    if (chk && chk.checked && domain) _trustDomain(domain);
    overlay.remove();
    window.open(url, '_blank', 'noopener,noreferrer');
  };
  overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
  overlay.addEventListener('keydown', e => { if (e.key === 'Escape') overlay.remove(); });
  // Hover effects
  const backBtn = document.getElementById('ftz-ext-back');
  const visitBtn = document.getElementById('ftz-ext-visit');
  if (backBtn) { backBtn.onmouseenter = () => { backBtn.style.background='rgba(255,255,255,.08)'; backBtn.style.color='#fff'; }; backBtn.onmouseleave = () => { backBtn.style.background='rgba(255,255,255,.04)'; backBtn.style.color='rgba(255,255,255,.7)'; }; }
  if (visitBtn) { visitBtn.onmouseenter = () => { visitBtn.style.background='rgba(255,249,62,.15)'; visitBtn.style.boxShadow='0 0 16px rgba(255,249,62,.15)'; }; visitBtn.onmouseleave = () => { visitBtn.style.background='rgba(255,249,62,.08)'; visitBtn.style.boxShadow='none'; }; }
}
function autoResize(el) {
  el.style.height = 'auto';
  el.style.height = Math.min(el.scrollHeight, 200) + 'px';
  // Sync live preview overlay height
  if (el._previewEl) {
    el._previewEl.style.height = el.style.height;
  }
  // Show/hide send button based on content
  const outer = el.closest('.chat-input-outer');
  if (outer) {
    const sendBtn = outer.querySelector('.chat-send-btn');
    if (sendBtn) sendBtn.classList.toggle('visible', el.value.trim().length > 0);
  }
}
// Clear chat input properly — resets value, height, and live preview overlay
function clearChatInput(inp) {
  if (!inp) return;
  inp.value = '';
  inp.style.height = 'auto';
  inp.style.color = '';
  if (inp._previewEl) {
    inp._previewEl.innerHTML = '';
  }
}
// Silent send — hold send button to send without notification
let _silentSendTimer = null;
let _silentSendTriggered = false;
function _silentSendStart(btn) {
  _silentSendTriggered = false;
  _silentSendTimer = setTimeout(() => {
    _silentSendTriggered = true;
    const tip = btn.parentElement.querySelector('.silent-send-tip');
    if (tip) { tip.style.opacity = '1'; }
    window._sendSilent = true;
    btn.style.background = 'rgba(255,255,255,.15)';
    const _svg = btn.querySelector('svg');
    if (_svg) _svg.style.fill = 'var(--accent)';
  }, 600);
}
function _silentSendEnd(btn) {
  clearTimeout(_silentSendTimer);
  const tip = btn.parentElement.querySelector('.silent-send-tip');
  if (tip) tip.style.opacity = '0';
  btn.style.background = '';
  const svg = btn.querySelector('svg');
  if (svg) svg.style.fill = '';
  if (_silentSendTriggered) {
    // Silent send was triggered — the onclick will fire with window._sendSilent = true
    setTimeout(() => { window._sendSilent = false; }, 100);
  }
}
function scrollBottom(id, instant) {
  const el = document.getElementById(id);
  if (el) {
    if (instant) {
      el.scrollTop = el.scrollHeight;
    } else {
      el.scrollTo({ top: el.scrollHeight, behavior: 'smooth' });
    }
    // Update state if tracked
    if (_chatAutoScroll[el.id]) _chatAutoScroll[el.id].atBottom = true;
    // Re-scroll after images/embeds load to stay at bottom
    requestAnimationFrame(() => { if (el) el.scrollTop = el.scrollHeight; });
    // Hide new messages bar when scrolling to present
    const newMsgBar = id.includes('dm') ? 'dm-new-msgs-bar' : id.includes('gc') ? 'gc-new-msgs-bar' : null;
    if (newMsgBar) document.getElementById(newMsgBar)?.classList.remove('show');
  }
}

function markDMRead() {
  document.getElementById('dm-new-msgs-bar')?.classList.remove('show');
  if (curDM) FortizedSocial.markNotificationReadBySource('dm:'+curDM);
}

function markGCRead() {
  document.getElementById('gc-new-msgs-bar')?.classList.remove('show');
  if (typeof curGC !== 'undefined' && curGC) FortizedSocial.markNotificationReadBySource('gc:'+curGC);
}

function markChannelRead(bastionIdx) {
  const bar = document.getElementById(`ch-new-msgs-bar-${bastionIdx}`);
  if (bar) bar.classList.remove('show');
  const b = CU?.bastions?.[bastionIdx];
  if (b && curChannel !== null) {
    const ch = b.channels?.[curChannel];
    if (ch) FortizedSocial.markNotificationReadBySource(`ch:${b.globalId||b.name}:${ch.name}`);
  }
}

function showNewMessagesBar(chatType, count = 1) {
  const barId = chatType === 'dm' ? 'dm-new-msgs-bar' : chatType === 'gc' ? 'gc-new-msgs-bar' : `ch-new-msgs-bar-${chatType}`;
  const textId = chatType === 'dm' ? 'dm-new-msgs-text' : chatType === 'gc' ? 'gc-new-msgs-text' : `ch-new-msgs-text-${chatType}`;
  const bar = document.getElementById(barId);
  const text = document.getElementById(textId);
  if (bar && text) {
    const msg = count === 1 ? '1 new message' : `${count} new messages`;
    text.textContent = msg;
    bar.classList.add('show');
  }
}
function scrollToMsg(msgId) {
  if(!msgId)return;
  try {
    const row=document.querySelector(`[data-msgid="${CSS.escape(String(msgId))}"]`);
    if(row){row.scrollIntoView({behavior:'smooth',block:'center'});row.style.background='rgba(255,249,62,.06)';row.style.transition='background .3s';setTimeout(()=>row.style.background='',1500);}
  } catch(e) { console.warn('scrollToMsg', e); }
}
// Smart auto-scroll: track whether user is at bottom
let _chatAutoScroll={};
let _chatScrollDebounce={};
let _chatObservers={};
function _initChatScroll(msgsEl){
  if(!msgsEl)return;
  const id=msgsEl.id;
  _chatAutoScroll[id]={atBottom:true,newCount:0,newBarInserted:false};
  msgsEl.addEventListener('scroll',()=>{
    // Debounce scroll calculations to avoid jank
    if(_chatScrollDebounce[id]) return;
    _chatScrollDebounce[id]=true;
    requestAnimationFrame(()=>{
      _chatScrollDebounce[id]=false;
      const atBot=msgsEl.scrollHeight-msgsEl.scrollTop-msgsEl.clientHeight<150;
      _chatAutoScroll[id].atBottom=atBot;
      const pastBar=msgsEl.querySelector('.chat-past-bar');
      if(pastBar){
        const scrolledUp=msgsEl.scrollTop<msgsEl.scrollHeight-msgsEl.clientHeight-300;
        pastBar.classList.toggle('show',scrolledUp);
      }
      if(atBot){
        _chatAutoScroll[id].newCount=0;
        // Remove the NEW bar when user scrolls to bottom
        _removeNewMsgBar(id);
        const btn=msgsEl.parentElement?.querySelector('.chat-new-msg-btn');
        if(btn)btn.classList.remove('show');
      }
    });
  },{passive:true});
  // Observe DOM changes — when new messages are appended, auto-scroll if at bottom
  if(_chatObservers[id]){try{_chatObservers[id].disconnect();}catch{}}
  const obs=new MutationObserver(()=>{
    if(_chatAutoScroll[id]?.atBottom){
      msgsEl.scrollTop=msgsEl.scrollHeight;
    }
  });
  obs.observe(msgsEl,{childList:true,subtree:true});
  _chatObservers[id]=obs;
  // Handle images/embeds loading after render — keep scroll at bottom
  msgsEl.addEventListener('load',function(e){
    if(e.target.tagName==='IMG'&&_chatAutoScroll[id]?.atBottom){
      msgsEl.scrollTop=msgsEl.scrollHeight;
    }
  },true);
}
function _notifyNewMsg(msgsElId){
  const state=_chatAutoScroll[msgsElId];
  if(!state||state.atBottom){scrollBottom(msgsElId);requestAnimationFrame(()=>scrollBottom(msgsElId,true));return;}
  state.newCount++;
  const msgsEl=document.getElementById(msgsElId);
  if(!msgsEl)return;

  // Show sticky notification banner
  const chatType = msgsElId.includes('dm') ? 'dm' : msgsElId.includes('gc') ? 'gc' : msgsElId.match(/\d+/)?.[0];
  if (chatType) showNewMessagesBar(chatType, state.newCount);

  // Insert the NEW bar before the first new (unread) message if not yet inserted
  if(!state.newBarInserted){
    state.newBarInserted=true;
    const allRows=msgsEl.querySelectorAll('.msg-row');
    const lastRow=allRows.length?allRows[allRows.length-1]:null;
    if(lastRow){
      const bar=document.createElement('div');
      bar.className='new-msg-bar';
      bar.id='new-msg-bar-'+msgsElId;
      bar.innerHTML='<span class="new-msg-label">New</span>';
      // Insert before the last row (which is the first new message)
      lastRow.parentElement.insertBefore(bar,lastRow);
    }
  }
  let btn=msgsEl.parentElement?.querySelector('.chat-new-msg-btn');
  if(!btn){
    btn=document.createElement('div');btn.className='chat-new-msg-btn';
    btn.onclick=()=>{
      const el=document.getElementById(msgsElId);
      if(el) el.scrollTo({top:el.scrollHeight,behavior:'smooth'});
      btn.classList.remove('show');state.newCount=0;
      _removeNewMsgBar(msgsElId);
    };
    msgsEl.parentElement.appendChild(btn);
  }
  btn.innerHTML=`${state.newCount} New Message${state.newCount>1?'s':''} <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="6,9 12,15 18,9"/></svg>`;
  btn.classList.add('show');
}
function _removeNewMsgBar(msgsElId){
  const state=_chatAutoScroll[msgsElId];
  if(state) state.newBarInserted=false;
  const bar=document.getElementById('new-msg-bar-'+msgsElId);
  if(bar) bar.remove();
}
function formatTimeAgo(iso) {
  if (!iso) return '';
  const d = new Date(iso), now = new Date();
  const diff = (now - d) / 1000;
  if (diff < 60) return 'just now';
  if (diff < 3600) return Math.floor(diff/60) + 'm ago';
  if (diff < 86400) return Math.floor(diff/3600) + 'h ago';
  return Math.floor(diff/86400) + 'd ago';
}
function _formatElapsed(startIso) {
  if (!startIso) return '';
  const diff = (Date.now() - new Date(startIso).getTime()) / 1000;
  if (diff < 60) return 'a few seconds';
  if (diff < 3600) return Math.floor(diff/60) + ' min';
  const h = Math.floor(diff/3600);
  const m = Math.floor((diff%3600)/60);
  return h + 'h ' + (m > 0 ? m + 'm' : '');
}
function handleSearch(q) {}
function attachFile(inputId) { openFileUpload(inputId || 'ch-input'); }

// ── Role System ──
function isSuperAdmin() { return CU?.username && SUPER_ADMINS.includes(CU.username); }
function _getStaffData() {
  try { return JSON.parse(localStorage.getItem('ftz_staff')||'{}'); } catch(e) { console.warn('[Staff] Parse failed:', e); return {admins:[], moderators:[]}; }
}
function isAdmin() {
  if (isSuperAdmin()) return true;
  const staff = _getStaffData();
  return CU?.username && (staff.admins||[]).includes(CU.username);
}
function isModerator() {
  if (isAdmin()) return true;
  const staff = _getStaffData();
  return CU?.username && (staff.moderators||[]).includes(CU.username);
}
function getStaffRole(username) {
  if (!username) return null;
  if (SUPER_ADMINS.includes(username)) return 'superadmin';
  const staff = _getStaffData();
  if ((staff.admins||[]).includes(username)) return 'admin';
  if ((staff.moderators||[]).includes(username)) return 'moderator';
  return null;
}
function hasStaffAccess() { return isModerator(); } // any staff role

async function logAudit(action, target, note='') {
  const entry = {action,target,note,by:CU?.username,at:new Date().toISOString()};
  let log = [];
  try { log = JSON.parse(localStorage.getItem('ftz_audit_log')||'[]'); } catch(e) { console.warn('[Audit] Parse failed:', e); }
  log.unshift(entry);
  localStorage.setItem('ftz_audit_log', JSON.stringify(log.slice(0,500)));
  try { await FortizedSocial.adminPushAuditLog(entry); } catch(e) { console.warn('[Audit] Push failed:', e?.message); }
}

