// SOFT REFRESH + NAV KEYBINDS
// ════════════════════════════════════════════
// Soft refresh: re-render current view without full page reload
function _ftzSoftRefresh() {
  if (_currentView === 'home') { try { renderHomePanel(); } catch(e) { console.warn('[Refresh] Home failed:', e?.message); } }
  else if (_currentView === 'dms' || _currentView === 'friends') { try { showDMFriendsHome(); } catch(e) { console.warn('[Refresh] DMs failed:', e?.message); } }
  else if (_currentView === 'discover') { try { renderDiscoverGrid(); } catch(e) { console.warn('[Refresh] Discover failed:', e?.message); } }
  else if (_currentView === 'atelier') { try { refreshCU().then(()=>{ switchAtelierTab(_atelierTab||'overview'); }).catch(()=>{ switchAtelierTab(_atelierTab||'overview'); }); } catch(e) { console.warn('[Refresh] Atelier failed:', e?.message); } }
  else if (_currentView === 'bastion' && curBastion !== null) {
    try { if (curChannel === 'overview') renderOverviewRoom(); else if (curChannel !== null) selectChannel(curChannel); } catch(e) { console.warn('[Refresh] Bastion failed:', e?.message); }
  }
  // Spin the refresh icon
  const btn = document.getElementById('tb-nav-refresh');
  if (btn) { btn.classList.add('spinning'); setTimeout(() => btn.classList.remove('spinning'), 600); }
}

// Keybinds: Alt+← (back), Alt+→ (forward), Ctrl+R (soft refresh)
document.addEventListener('keydown', function(e) {
  // Skip keyboard shortcuts if user is typing in an input/textarea
  const tag = document.activeElement?.tagName;
  const isTyping = tag === 'INPUT' || tag === 'TEXTAREA' || document.activeElement?.isContentEditable;

  // Alt+ArrowLeft = Back
  if (e.altKey && e.key === 'ArrowLeft') { e.preventDefault(); history.back(); return; }
  // Alt+ArrowRight = Forward
  if (e.altKey && e.key === 'ArrowRight') { e.preventDefault(); history.forward(); return; }
  // Ctrl+R = Full page reload
  if (e.ctrlKey && !e.shiftKey && e.key === 'r') { e.preventDefault(); location.reload(); return; }

  // ── Quick Navigation Shortcuts (only when not typing) ──
  if (isTyping) return;

  // Ctrl+K = Focus search bar
  if (e.ctrlKey && e.key === 'k') {
    e.preventDefault();
    const searchInput = document.querySelector('.tb-search input') || document.querySelector('#global-search');
    if (searchInput) searchInput.focus();
    return;
  }
  // Ctrl+Shift+M = Go to Messages/DMs
  if (e.ctrlKey && e.shiftKey && e.key === 'M') { e.preventDefault(); showView('dms'); return; }
  // Ctrl+Shift+H = Go to Home
  if (e.ctrlKey && e.shiftKey && e.key === 'H') { e.preventDefault(); showView('home'); return; }
  // Ctrl+Shift+D = Go to Discover
  if (e.ctrlKey && e.shiftKey && e.key === 'D') { e.preventDefault(); showView('discover'); return; }
  // Ctrl+Shift+A = Go to Atelier (profile/settings)
  if (e.ctrlKey && e.shiftKey && e.key === 'A') { e.preventDefault(); showView('atelier'); return; }
});

// ════════════════════════════════════════════
// VIEW MANAGEMENT + CLIENT-SIDE ROUTING
// ════════════════════════════════════════════
let _currentView = 'home';

// ── Subpage Router ──
// Maps URL paths to views:
//   /app/           → home
//   /app/messages   → dms (DMs + friends)
//   /app/discover   → discover
//   /app/atelier    → atelier
//   /app/bastion?[bastionGlobalId]/[channelIdx] → bastion
const _ftzRouter = {
  // Path → view name mapping
  routes: {
    '/app':          'home',
    '/app/':         'home',
    '/app/messages': 'dms',
    '/app/discover': 'discover',
    '/app/atelier':  'atelier',
    '/app/bastion':  'bastion',
  },
  // View → path mapping (reverse)
  paths: {
    'home':     '/app/',
    'dms':      '/app/messages',
    'friends':  '/app/messages',
    'discover': '/app/discover',
    'atelier':  '/app/atelier',
    'bastion':  '/app/bastion',
  },
  // Parse current URL to determine view + params
  parseRoute: function() {
    const path = window.location.pathname.replace(/\/+$/, '') || '/app';
    const search = window.location.search;
    const view = this.routes[path] || this.routes[path + '/'] || 'home';
    let bastionId = null, roomId = null;
    if (view === 'bastion' && search) {
      // Format: /app/bastion?[bastionGlobalId]/[roomIdx]
      const raw = search.substring(1); // strip leading ?
      const parts = raw.split('/');
      bastionId = decodeURIComponent(parts[0] || '');
      roomId = parts[1] ? decodeURIComponent(parts[1]) : null;
    }
    return { view, bastionId, roomId };
  },
  // Push a new URL without reloading
  pushState: function(view, params) {
    let url = this.paths[view] || '/app/';
    if (view === 'bastion' && params?.bastionId) {
      url = '/app/bastion?' + encodeURIComponent(params.bastionId);
      if (params.roomId != null) url += '/' + encodeURIComponent(params.roomId);
    }
    if (window.location.pathname + window.location.search !== url) {
      history.pushState({ view, params: params || {} }, '', url);
    }
  },
  // Replace current URL (for initial load, no history entry)
  replaceState: function(view, params) {
    let url = this.paths[view] || '/app/';
    if (view === 'bastion' && params?.bastionId) {
      url = '/app/bastion?' + encodeURIComponent(params.bastionId);
      if (params.roomId != null) url += '/' + encodeURIComponent(params.roomId);
    }
    history.replaceState({ view, params: params || {} }, '', url);
  },
  // Navigate to initial view based on URL or _initialView (called after init)
  applyInitialRoute: function() {
    const { view: urlView, bastionId, roomId } = this.parseRoute();
    // Use _initialView from the subpage HTML if the URL is just /app/ or /app
    const view = (urlView === 'home' && window._initialView && window._initialView !== 'home') ? window._initialView : urlView;
    if (view === 'bastion' && bastionId) {
      // Find bastion by globalId and open it
      const idx = (CU.bastions || []).findIndex(b => b.globalId === bastionId);
      if (idx >= 0) {
        openBastion(idx);
        if (roomId != null) {
          const chIdx = parseInt(roomId);
          if (!isNaN(chIdx) && chIdx >= 0) {
            requestAnimationFrame(() => selectChannel(chIdx));
          } else if (roomId === 'overview') {
            requestAnimationFrame(() => openOverviewRoom());
          }
        }
        return;
      }
      // Bastion not found — fall through to home
    }
    if (view === 'dms' || view === 'friends') {
      showView('dms');
      return;
    }
    if (view === 'discover' || view === 'atelier') {
      showView(view);
      return;
    }
    showView('home');
  }
};

// Handle browser back/forward
window.addEventListener('popstate', function(e) {
  const state = e.state;
  if (!state || !state.view) {
    // No state — parse from URL
    const { view, bastionId, roomId } = _ftzRouter.parseRoute();
    if (view === 'bastion' && bastionId) {
      const idx = (CU.bastions || []).findIndex(b => b.globalId === bastionId);
      if (idx >= 0) { openBastion(idx); return; }
    }
    showView(view || 'home', true);
    return;
  }
  if (state.view === 'bastion' && state.params?.bastionId) {
    const idx = (CU.bastions || []).findIndex(b => b.globalId === state.params.bastionId);
    if (idx >= 0) {
      openBastion(idx);
      if (state.params.roomId != null) {
        const chIdx = parseInt(state.params.roomId);
        if (!isNaN(chIdx)) requestAnimationFrame(() => selectChannel(chIdx));
        else if (state.params.roomId === 'overview') requestAnimationFrame(() => openOverviewRoom());
      }
      return;
    }
  }
  showView(state.view || 'home', true);
});
function showView(v, _skipPush) {
  // ── Settings & bastion settings open as modals over the current page ──
  if (v === 'profile') {
    closeModal('modal-bsettings'); // close other if open
    openModal('modal-settings');
    _settingsOriginal = CU ? structuredClone({displayName:CU.displayName,bio:CU.bio,email:CU.email,password:CU.password,pfp:CU.pfp,banner:CU.banner,socials:CU.socials,notifSettings:CU.notifSettings,pronouns:CU.pronouns,profileTheme:CU.profileTheme}) : null;
    clearSettingsDirty();
    buildProfileNav(document.getElementById('profile-nav'));
    buildProfileView('myprofile');
    return;
  }
  if (v === 'bsettings') {
    closeModal('modal-settings'); // close other if open
    openModal('modal-bsettings');
    return;
  }

  // Close settings/bsettings modals when navigating to a normal view
  closeModal('modal-settings');
  closeModal('modal-bsettings');
  clearSettingsDirty();

  _currentView = v;
  // Update URL (skip for bastion — openBastion handles that)
  if (!_skipPush && v !== 'bastion' && typeof _ftzRouter !== 'undefined') {
    if (_ftzRouter._initialLoad) _ftzRouter.replaceState(v);
    else _ftzRouter.pushState(v);
  }
  // Close mobile sidebars on navigation
  if (typeof closeMobileSidebar === 'function') closeMobileSidebar();
  // Sync mobile tab bar
  setTimeout(() => { try { _syncMobileTabBar(); } catch (e) { console.debug('[Mobile] tab bar sync failed', e); } }, 50);
  const _mtb = document.getElementById('mobile-tab-bar');
  if (_mtb) _mtb.style.display = '';
  // Stop admin polling when leaving admin view
  if (v !== 'admin' && _reportPollInterval) { clearInterval(_reportPollInterval); _reportPollInterval = null; }
  // Stop Joyster bubbles when leaving home — Joyster only lives on the homepage
  if (v !== 'home' && typeof _stopJoysterBubbles === 'function') _stopJoysterBubbles();
  // Clean up GC panel when leaving DMs view
  if (v !== 'dms') document.getElementById('gc-member-panel')?.remove();

  // Restore sidebar if it was hidden (e.g. after profile view)
  const _sb = document.querySelector('.sidebar');
  if (_sb) _sb.style.display = '';

  // Hide ALL views explicitly (override any inline display styles)
  document.querySelectorAll('.view').forEach(el => {
    el.style.display = 'none';
    el.classList.remove('active');
  });

  // Show only the target view
  const vEl = document.getElementById('view-' + v);
  if (vEl) {
    vEl.style.display = 'flex';
    vEl.classList.add('active');
    // Smooth fade + slide in
    vEl.style.opacity = '0';
    vEl.style.transform = 'translateY(4px)';
    requestAnimationFrame(() => {
      vEl.style.transition = 'opacity .22s cubic-bezier(.22,1,.36,1), transform .22s cubic-bezier(.22,1,.36,1)';
      vEl.style.opacity = '1';
      vEl.style.transform = 'translateY(0)';
      setTimeout(() => { vEl.style.transition = ''; vEl.style.transform = ''; }, 260);
    });
  }

  // Nav active state
  document.querySelectorAll('.rail-btn').forEach(el => el.classList.remove('active'));
  document.querySelectorAll('.rail-bastion').forEach(el => el.classList.remove('active'));
  // (home btn is now a rail-btn, handled by the loop above)
  const rBtn = document.getElementById('rb-' + v);
  if (rBtn) rBtn.classList.add('active');

  // Post-show callbacks
  if (v === 'atelier') { _atelierTab = 'overview'; renderAtelierTab('overview'); setTimeout(() => { refreshCU().then(()=>{ switchAtelierTab('overview'); refreshDailyBtn(); }).catch(()=>{ switchAtelierTab('overview'); refreshDailyBtn(); }); }, 0); }
  if (v === 'home') setTimeout(() => renderHomePanel(), 0);
  if (v === 'friends') setTimeout(() => renderFriendsList('all'), 0);
  if (v === 'dms' && !curDM && !curGC) setTimeout(() => { showDMFriendsHome(); }, 50);

  updateTopbar(v);
  updateSidebar(v);
}

function updateTopbar(v) {
  const title = document.getElementById('topbar-title');
  const desc = document.getElementById('tb-desc');
  const sep = document.getElementById('tb-sep');
  const acts = document.getElementById('tb-actions');
  if (!title) return;
  if (sep) sep.style.display = 'none';
  if (desc) desc.textContent = '';
  if (acts) acts.innerHTML = '';
  const labels = {home:'Home',dms:'Direct Messages',friends:'Direct Messages',discover:'Discover',atelier:'Atelier',profile:'Settings',bsettings:'Bastion Settings',bhub:'Overview'};
  if (v === 'bastion') {
    const b = CU?.bastions?.[curBastion];
    title.textContent = b?.name || 'Bastion';
  } else if (labels[v]) title.textContent = labels[v];
  // Update document title for subpage (Discord-style: Fortized | Page)
  const docTitles = {home:null,dms:'Friends',friends:'Friends',discover:'Discover',atelier:'Atelier',profile:'Settings',bsettings:'Bastion Settings',bhub:'Overview'};
  if (v === 'bastion') {
    _updateBastionTitle();
  } else {
    document.title = docTitles[v] ? 'Fortized | ' + docTitles[v] : 'Fortized';
  }
  // On mobile, add member list toggle for bastion views
  if (_isMobile() && v === 'bastion' && acts) {
    acts.insertAdjacentHTML('beforeend', '<button class="tb-act-btn" title="Members" onclick="toggleMobileMemberPanel()" style="position:relative;"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 00-3-3.87"/><path d="M16 3.13a4 4 0 010 7.75"/></svg></button>');
  }
  updateOnyxDisplay();
}
// Update document title for bastion view: Fortized | #room | Bastion Name
function _updateBastionTitle() {
  const b = CU?.bastions?.[curBastion];
  if (!b) { document.title = 'Fortized'; return; }
  const bName = b.name || 'Bastion';
  const tbTitle = document.getElementById('topbar-title');
  if (tbTitle) tbTitle.textContent = bName;
  if (curChannel === 'overview' || curChannel === null) {
    document.title = 'Fortized | ' + bName;
  } else {
    const ch = b.channels?.[curChannel];
    const chName = ch?.name || 'channel';
    document.title = 'Fortized | #' + chName + ' | ' + bName;
  }
}
