function updateSidebar(v) {
  const scroll = document.getElementById('sidebar-scroll');
  const hdrTitle = document.getElementById('sidebar-title');
  const hdrActs = document.getElementById('sidebar-hdr-actions');
  const hdr = document.getElementById('sidebar-header');
  const ctx = document.getElementById('sidebar-ctx');
  if (!scroll) return;
  if (hdrActs) hdrActs.innerHTML = '';
  scroll.innerHTML = '';

  // Views that use the secondary sidebar
  const ctxViews = ['home','dms','friends','discover','atelier','bastion'];
  const ctxVisible = ctxViews.includes(v);
  if (ctx) ctx.style.display = ctxVisible ? 'flex' : 'none';
  updateUserbarWidth();
  if (typeof _updateMobileBackBtn === 'function') _updateMobileBackBtn();

  if (v==='home') {
    if (hdr) hdr.style.display = '';
    if (hdrTitle) hdrTitle.textContent = 'Direct Messages';
    if (hdrActs) hdrActs.innerHTML = `
      <button onclick="openModal('modal-new-dm');switchNewDMTab('dm')" class="sidebar-hdr-btn" title="New DM"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg></button>
      <button onclick="openModal('modal-add-friend')" class="sidebar-hdr-btn" title="Add Friend"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M16 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="8.5" cy="7" r="4"/><line x1="20" y1="8" x2="20" y2="14"/><line x1="23" y1="11" x2="17" y2="11"/></svg></button>`;
    renderDMSidebar(scroll);
  } else if (v==='dms' || v==='friends') {
    if (hdr) hdr.style.display = '';
    if (hdrTitle) hdrTitle.textContent = 'Direct Messages';
    if (hdrActs) hdrActs.innerHTML = `
      <button onclick="openModal('modal-new-dm');switchNewDMTab('dm')" class="sidebar-hdr-btn" title="New DM"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg></button>
      <button onclick="openModal('modal-new-dm');switchNewDMTab('gc')" class="sidebar-hdr-btn" title="New Group Chat"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg></button>
      <button onclick="openModal('modal-add-friend')" class="sidebar-hdr-btn" title="Add Friend"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M16 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="8.5" cy="7" r="4"/><line x1="20" y1="8" x2="20" y2="14"/><line x1="23" y1="11" x2="17" y2="11"/></svg></button>`;
    renderDMSidebar(scroll);
    if (v==='friends') { setTimeout(() => renderFriendsList('all'), 0); }
  } else if (v==='discover') {
    if (hdr) hdr.style.display = '';
    if (hdrTitle) hdrTitle.textContent = 'Direct Messages';
    if (hdrActs) hdrActs.innerHTML = `
      <button onclick="openModal('modal-new-dm');switchNewDMTab('dm')" class="sidebar-hdr-btn" title="New DM">${ftzIcon('pencil','14')}</button>
      <button onclick="openModal('modal-add-friend')" class="sidebar-hdr-btn" title="Add Friend">${ftzIcon('addUser','14')}</button>`;
    renderDMSidebar(scroll);
    loadDiscover();
  } else if (v==='atelier') {
    if (hdr) hdr.style.display = '';
    if (hdrTitle) hdrTitle.textContent = 'Atelier';
    if (hdrActs) hdrActs.innerHTML = '';
    renderAtelierSidebar(scroll);
  } else if (v==='bastion') {
    // Header hidden — bastion sidebar renders its own hero banner
    renderBastionSidebar(scroll);
  } else if (v==='bhub') {
    // bastion hub: hide sidebar-ctx, render hub
    if (ctx) ctx.style.display = 'none';
    updateUserbarWidth();
  } else if (v==='admin') {
    // admin console has its own nav inside view-admin; hide sidebar-ctx
    if (ctx) ctx.style.display = 'none';
    updateUserbarWidth();
  }
}

// ════════════════════════════════════════════
// USERBAR & ONYX
// ════════════════════════════════════════════
function updateUserbar() {
  if (!CU) return;
  const ua = document.getElementById('ua');
  const uaName = document.getElementById('ua-name');
  const uaStatusText = document.getElementById('ua-status-text');
  const uaDot = document.getElementById('ua-status-dot');
  const st = FtzStatus.sanitize(CU.status || 'online');
  // Avatar — 34px to match redesigned userbar
  if (ua) {
    ua.innerHTML = buildAvatarHTML(CU.pfp, CU.displayName||CU.username, 34, CU.pfpCrop);
    // Add decoration overlay on userbar avatar
    if (CU.activeDecoration) {
      ua.style.position='relative'; ua.style.overflow='visible';
      const decoSrc = getDecorationSrc(CU.activeDecoration);
      if (decoSrc) ua.insertAdjacentHTML('beforeend', `<img src="${decoSrc}" class="profile-decoration-overlay-sm" onerror="this.style.display='none'">`);
    }
    if (!ua.querySelector('#ua-status-dot')) {
      const d = document.createElement('span');
      d.id = 'ua-status-dot'; d.className = 'ua-status-dot';
      d.dataset.dotSize = '13';
      ua.appendChild(d);
    }
  }
  if (document.getElementById('ua-status-dot')) {
    const uaDotEl = document.getElementById('ua-status-dot');
    uaDotEl.innerHTML = FtzStatus.dotSvg(st, 14);
    uaDotEl.style.background = 'none';
  }
  if (uaName) {
    uaName.textContent = CU.displayName || CU.username;
    const font = getDisplayFont(CU);
    uaName.style.fontFamily = font;
  }
  if (uaStatusText) {
    if (CU.customStatus?.text) {
      uaStatusText.textContent = (CU.customStatus.emoji||'') + ' ' + CU.customStatus.text;
    } else {
      uaStatusText.textContent = FtzStatus.label(st);
    }
  }
  // Status sync handled by FtzStatus.set() and presence system — no redundant broadcast here
  _updateUserbarActivity();
  updateOnyxDisplay();
  refreshCustomStatusBubble();
  // Sync rail userbar (full userbar in fortized sidebar)
  const railUbAvatar = document.getElementById('rail-ub-avatar');
  if (railUbAvatar) {
    const _defPfpRail = _defaultPfpUrl(CU.displayName||CU.username);
    const railInner = CU.pfp
      ? `<img src="${CU.pfp}" style="width:100%;height:100%;border-radius:50%;object-fit:cover;" onerror="this.src='${_defPfpRail}'">`
      : `<img src="${_defPfpRail}" style="width:100%;height:100%;border-radius:50%;object-fit:cover;">`;
    railUbAvatar.innerHTML = railInner;
    const railDot = document.createElement('span');
    railDot.id = 'rail-ub-status-dot'; railDot.className = 'ua-status-dot';
    railDot.dataset.dotSize = '14';
    railDot.innerHTML = FtzStatus.dotSvg(st, 14);
    railUbAvatar.appendChild(railDot);
  }
  // Sync rail userbar name & status text
  const railUbName = document.getElementById('rail-ub-name');
  if (railUbName) railUbName.textContent = CU.displayName || CU.username || 'User';
  const railUbStatus = document.getElementById('rail-ub-status');
  if (railUbStatus) {
    if (CU.customStatus?.text) {
      railUbStatus.textContent = (CU.customStatus.emoji||'') + ' ' + CU.customStatus.text;
    } else {
      railUbStatus.textContent = FtzStatus.label(st);
    }
  }
  _syncRailUserbarActivity();
  // Update mobile tab bar avatar and badges
  try { _updateMobileTabAvatar(); _updateMobileNotifBadge(); } catch(e) { console.debug('[Mobile] Tab update:', e?.message); }
}
function _isMobile() { return window.innerWidth <= 768; }
function _isTablet() { return window.innerWidth <= 1024 && window.innerWidth > 768; }
function updateUserbarWidth() {
  // Hide rail-userbar when sidebar-ctx is visible to avoid duplicate userbars
  const ctx = document.getElementById('sidebar-ctx');
  const railUb = document.getElementById('rail-userbar');
  if (railUb) railUb.style.display = (ctx && ctx.style.display !== 'none') ? 'none' : '';
  _updateUserbarActivity();
}
function _updateUserbarActivity() {
  const row = document.getElementById('ub-activity-row');
  const nameEl = document.getElementById('ub-activity-name');
  const iconEl = document.getElementById('ub-activity-icon');
  if (!row || !nameEl) return;
  const actionBtn = document.getElementById('ub-activity-action');
  const activityEnabled = localStorage.getItem('ftz_activity_detection') !== 'false';
  const primary = activityState.primary;

  if (primary && activityEnabled) {
    row.classList.add('active');
    row.style.display = '';

    const isSpotify = primary.type === 'listening';
    const labelEl = row.querySelector('.ub-activity-label');
    if (labelEl) labelEl.textContent = isSpotify ? 'Listening to Spotify' : 'Playing';

    // Color for Spotify
    if (isSpotify) {
      row.style.background = 'rgba(29,185,84,.04)';
      row.style.borderColor = 'rgba(29,185,84,.08)';
    } else {
      row.style.background = '';
      row.style.borderColor = '';
    }

    // Activity display text
    const displayText = formatActivityDisplay(primary);
    nameEl.textContent = displayText;

    // Icon/Cover
    if (iconEl) {
      if (isSpotify && primary.metadata?.spotifyAlbumArt) {
        iconEl.innerHTML = '<img src="'+escapeHTML(primary.metadata.spotifyAlbumArt)+'" style="width:26px;height:26px;border-radius:4px;object-fit:cover;">';
        iconEl.style.background = 'rgba(29,185,84,.1)';
        iconEl.style.borderColor = 'rgba(29,185,84,.18)';
      } else if (primary.metadata?.coverThumb) {
        iconEl.innerHTML = '<img src="'+escapeHTML(primary.metadata.coverThumb)+'" style="width:24px;height:32px;border-radius:4px;object-fit:cover;" onerror="this.parentElement.textContent=\''+escapeHTML(primary.icon)+'\';this.style.display=\'none\'">';
        iconEl.style.background = '';
        iconEl.style.borderColor = '';
      } else {
        iconEl.innerHTML = '<span style="font-size:15px;">' + primary.icon + '</span>';
        iconEl.style.background = '';
        iconEl.style.borderColor = '';
      }
    }

    if (actionBtn) {
      actionBtn.title = 'Stop Activity';
      actionBtn.innerHTML = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#f87171" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>';
    }

    // Elapsed time
    const timeEl = row.querySelector('.ub-activity-time');
    if (primary.since) {
      const elapsed = isSpotify && primary.metadata?.spotifyDuration
        ? primary.metadata.spotifyDuration
        : _formatActivityElapsed(primary.since);
      if (timeEl) {
        timeEl.textContent = elapsed;
      } else {
        const infoEl = document.getElementById('ub-activity-info');
        if (infoEl) {
          const t = document.createElement('span');
          t.className = 'ub-activity-time';
          t.textContent = elapsed;
          infoEl.appendChild(t);
        }
      }
    }
  } else {
    row.classList.remove('active');
    row.style.display = 'none';
    nameEl.textContent = '—';
    if (iconEl) iconEl.innerHTML = '';
    const timeEl = row.querySelector('.ub-activity-time');
    if (timeEl) timeEl.remove();
  }
}

function _syncRailUserbarActivity() {
  const row = document.getElementById('rail-ub-activity-row');
  const nameEl = document.getElementById('rail-ub-activity-name');
  const iconEl = document.getElementById('rail-ub-activity-icon');
  if (!row || !nameEl) return;
  const activityEnabled = localStorage.getItem('ftz_activity_detection') !== 'false';
  const primary = activityState.primary;

  if (primary && activityEnabled) {
    const isSpotify = primary.type === 'listening';
    row.classList.add('active');
    row.style.display = '';
    const displayText = formatActivityDisplay(primary);
    nameEl.textContent = displayText;

    if (iconEl) {
      if (isSpotify) {
        iconEl.innerHTML = '<span style="font-size:11px;">🎵</span>';
        iconEl.style.background = 'rgba(29,185,84,.1)';
        iconEl.style.borderColor = 'rgba(29,185,84,.18)';
        iconEl.style.color = '#1DB954';
      } else {
        iconEl.innerHTML = '<span style="font-size:11px;">' + primary.icon + '</span>';
        iconEl.style.background = '';
        iconEl.style.borderColor = '';
        iconEl.style.color = '';
      }
    }
  } else {
    row.classList.remove('active');
    row.style.display = 'none';
    nameEl.textContent = '';
  }
}

function _formatActivityElapsed(since) {
  const diff = Date.now() - new Date(since).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return 'just now';
  if (mins < 60) return mins + 'm elapsed';
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return hrs + 'h ' + (mins % 60) + 'm elapsed';
  return Math.floor(hrs / 24) + 'd ' + (hrs % 24) + 'h elapsed';
}
// Tick elapsed time every 30s while an activity is active
setInterval(() => { if (activityState.primary) _updateUserbarActivity(); }, 30000);

