function _mobileTab(tab) {
  // Close any open drawers
  closeMobileSidebar();
  _closeMobileSettings();
  // Update active tab
  document.querySelectorAll('.mobile-tab-item').forEach(t => t.classList.remove('active'));
  const tabEl = document.getElementById('mtab-' + tab);
  if (tabEl) tabEl.classList.add('active');
  // Navigate
  if (tab === 'home') showView('home');
  else if (tab === 'notifs') { if (typeof toggleNotifPanel === 'function') toggleNotifPanel(); }
  else if (tab === 'profile') _openMobileSettings();
}

