// ── Realm friends loader (horizontal avatars) ──
async function _loadRealmFriends(friends, container, countEl) {
  const _realmSlice = friends.slice(0, 20);
  let _realmPresence = {};
  try { const pr = await FortizedSocial.queryPresence(_realmSlice); if (pr) _realmPresence = pr; } catch(e) { console.warn('[Presence] Realm query failed:', e?.message); }
  const results = await Promise.all(_realmSlice.map(async f => {
    try {
      const u = await FortizedSocial.getUserByName(f);
      const _rLiveSt = _realmPresence[f]?.status;
      const st = FtzStatus.sanitize(_rLiveSt !== undefined ? _rLiveSt : (u?.status || 'offline'));
      return {username:f, displayName:u?.displayName||f, pfp:u?.pfp||null, status:st};
    } catch { return {username:f, displayName:f, pfp:null, status:'offline'}; }
  }));
  const online = results.filter(r => FtzStatus.isPresent(r.status));
  const offline = results.filter(r => !FtzStatus.isPresent(r.status));
  if (countEl) countEl.textContent = online.length ? online.length + ' online' : '';
  if (!online.length) {
    container.innerHTML = '<div style="padding:8px;font-size:13px;color:var(--muted);">All friends offline</div>';
    return;
  }
  container.innerHTML = online.map(r=>{
    return `<div class="realm-friend" onclick="openDMView('${escapeHTML(r.username)}')" title="${escapeHTML(r.displayName)}">
      <div class="rf-av">
        <div style="width:44px;height:44px;border-radius:50%;overflow:hidden;background:var(--panel2);display:flex;align-items:center;justify-content:center;font-size:16px;">${buildAvatarHTML(r.pfp,r.displayName,44)}</div>
        <span class="rf-status profile-status-dot" data-for="${escapeHTML(r.username)}" data-dot-size="16">${FtzStatus.dotSvg(r.status, 16)}</span>
      </div>
      <div class="rf-name">${escapeHTML(r.displayName)}</div>
    </div>`;
  }).join('') || '<div style="padding:8px;font-size:13px;color:var(--muted);">All friends offline</div>';
}

// ── Right panel friends loader (async with status) ──
async function _loadRPFriends(friends, container, countEl) {
  if (!friends.length) {
    container.innerHTML = '<div class="ftz-empty"><div class="ftz-empty-icon">👥</div><div class="ftz-empty-title">No friends yet</div><div class="ftz-empty-text">Add friends by username to get started!</div></div>';
    return;
  }
  const _rpSlice = friends.slice(0, 15);
  let _rpPresence = {};
  try { const pr = await FortizedSocial.queryPresence(_rpSlice); if (pr) _rpPresence = pr; } catch(e) { console.warn('[Presence] RP query failed:', e?.message); }
  const results = await Promise.all(_rpSlice.map(async f => {
    try {
      const u = await FortizedSocial.getUserByName(f);
      const _rpLiveSt = _rpPresence[f]?.status;
      const st = FtzStatus.sanitize(_rpLiveSt !== undefined ? _rpLiveSt : (u?.status || 'offline'));
      return {username:f, displayName:u?.displayName||f, pfp:u?.pfp||null, status:st, customStatus:u?.customStatus||null, game:u?.currentGame||null};
    } catch { return {username:f, displayName:f, pfp:null, status:'offline'}; }
  }));
  const online = results.filter(r => FtzStatus.isPresent(r.status));
  const offline = results.filter(r => !FtzStatus.isPresent(r.status));
  if (countEl) countEl.textContent = online.length ? online.length + ' online' : '';
  container.innerHTML = [...online,...offline].map(r=>{
    const activity = r.customStatus?.text ? `${r.customStatus.emoji||''} ${escapeHTML(r.customStatus.text)}` : r.game ? `Playing ${escapeHTML(r.game.name)}` : FtzStatus.publicLabel(r.status);
    return `<div class="rp-friend-item" onclick="openDMView('${escapeHTML(r.username)}')" title="${escapeHTML(activity)}">
      <div class="rp-friend-av">
        <div style="width:28px;height:28px;border-radius:50%;overflow:hidden;display:flex;align-items:center;justify-content:center;background:var(--panel);font-size:12px;">${buildAvatarHTML(r.pfp,r.displayName,28)}</div>
        <span class="rp-friend-status profile-status-dot" data-for="${escapeHTML(r.username)}" data-dot-size="12">${FtzStatus.dotSvg(r.status, 12)}</span>
      </div>
      <div style="flex:1;min-width:0;">
        <div class="rp-friend-name">${escapeHTML(r.displayName)}</div>
        <div class="rp-friend-activity">${escapeHTML(activity)}</div>
      </div>
    </div>`;
  }).join('') || '<div style="padding:10px;font-size:12px;color:var(--muted);text-align:center;">All friends offline</div>';
}

// ── Animated counter ──
function _animateCounter(elId, target) {
  const el = document.getElementById(elId);
  if (!el) return;
  const start = parseInt(el.textContent)||0;
  if (start === target) { el.textContent = target; return; }
  const duration = 400;
  const startTime = performance.now();
  function tick(now) {
    const progress = Math.min((now - startTime) / duration, 1);
    const eased = 1 - Math.pow(1 - progress, 3);
    el.textContent = Math.round(start + (target - start) * eased);
    if (progress < 1) requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
}

// ── Hero floating items & sparkles ──
function _initHeroEffects() {
  // Sparkles
  const sparkleContainer = document.getElementById('hero-sparkles');
  if (sparkleContainer && !sparkleContainer.children.length) {
    for (let i = 0; i < 12; i++) {
      const s = document.createElement('div');
      s.className = 'hero-sparkle';
      s.style.left = Math.random() * 100 + '%';
      s.style.top = (40 + Math.random() * 50) + '%';
      s.style.animationDelay = (Math.random() * 6) + 's';
      s.style.animationDuration = (4 + Math.random() * 4) + 's';
      sparkleContainer.appendChild(s);
    }
  }
  // Floating items
  const floatContainer = document.getElementById('hero-float-items');
  if (floatContainer && !floatContainer.children.length) {
    const items = ['🎲','#','🎮','🎧','⚔️','🛡️','💎','🏰'];
    items.forEach((item, i) => {
      const el = document.createElement('div');
      el.className = 'hero-float-item';
      el.textContent = item;
      el.style.left = (8 + (i / items.length) * 80) + '%';
      el.style.top = (15 + Math.random() * 55) + '%';
      el.style.animationDelay = (Math.random() * 8) + 's';
      el.style.animationDuration = (10 + Math.random() * 8) + 's';
      el.style.fontSize = (14 + Math.random() * 10) + 'px';
      floatContainer.appendChild(el);
    });
  }
}

