// Hidden DMs — persisted in localStorage per user
function _hiddenDMsKey() { return 'ftz_hidden_dms_' + (CU?.username||''); }
function getHiddenDMs() { try { return JSON.parse(localStorage.getItem(_hiddenDMsKey()) || '[]'); } catch { return []; } }
function setHiddenDMs(arr) { localStorage.setItem(_hiddenDMsKey(), JSON.stringify(arr)); }
function hideDMConversation(id) {
  const hidden = getHiddenDMs();
  if (!hidden.includes(id)) { hidden.push(id); setHiddenDMs(hidden); }
  renderDMSidebar(document.getElementById('sidebar-scroll'));
}
function unhideDMConversation(id) {
  setHiddenDMs(getHiddenDMs().filter(h => h !== id));
  renderDMSidebar(document.getElementById('sidebar-scroll'));
}

// Helper: DM path for Firebase queries (avoids loading ALL messages)
function P_dm_path(a, b) { return `dms/${[a, b].sort().join('__')}`; }

async function renderDMSidebar(scroll) {
  const friends = CU?.friends||[];
  const gcs = CU?.groupChats||[];
  const hidden = getHiddenDMs();

  let html = '';

  // ── Friends quick link (always at top) ──────────────────
  html += `<div class="ch-item dm-friends-link" style="margin:4px 8px;border-radius:10px;display:flex;align-items:center;gap:10px;font-weight:700;" onclick="showDMFriendsHome()">
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="flex-shrink:0;opacity:.7;"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>
    Friends</div>`;

  // ── Section label: Direct Messages ──────────────────
  html += '<div class="sec-label" style="display:flex;align-items:center;justify-content:space-between;padding-right:10px;" oncontextmenu="event.preventDefault();showDMSectionCtxMenu(event)">Direct Messages <button onclick="openModal(\'modal-new-dm\');switchNewDMTab(\'dm\')" style="background:transparent;border:none;color:var(--muted);cursor:pointer;font-size:14px;line-height:1;" title="New DM">✏️</button></div>';

  // Build a unified list of all conversations (DMs + GCs), will be sorted chronologically
  const _dmEntries = [];

  // Add 1-on-1 DMs (friends only, filter out hidden)
  friends.forEach(f => {
    if (hidden.includes('dm_' + f)) return;
    _dmEntries.push({ type: 'dm', id: 'dm_' + f, username: f, lastTime: 0 });
  });

  // Add group chats (filter out hidden)
  gcs.forEach(gc => {
    if (hidden.includes('gc_' + gc.id)) return;
    _dmEntries.push({ type: 'gc', id: 'gc_' + gc.id, gc, lastTime: 0 });
  });

  // Render entries immediately (will be sorted async after fetching timestamps)
  if (_dmEntries.length === 0) {
    html += '<div class="ftz-empty" style="padding:14px;"><div class="ftz-empty-icon">💬</div><div class="ftz-empty-title">No conversations yet</div><div class="ftz-empty-text">Start chatting with friends!</div></div>';
  } else {
    html += '<div id="dm-sorted-list">';
    _dmEntries.forEach(entry => {
      if (entry.type === 'dm') {
        const f = entry.username;
        html += `
      <div class="friend-item dm-sortable" id="dm-fi-${escapeHTML(f)}" data-dm-id="dm_${escapeHTML(f)}" data-last-time="0" onclick="openDMView('${escapeHTML(f)}')" oncontextmenu="event.preventDefault();showDMCtxMenu(event,'${escapeHTML(f)}')">
        <div style="position:relative;flex-shrink:0;">
          <div class="fa" id="dm-av-${escapeHTML(f)}" style="width:34px;height:34px;font-size:13px;overflow:hidden;">${buildAvatarHTML(null,f,34)}</div>
          <span class="profile-status-dot" data-for="${escapeHTML(f)}" data-dot-size="12" style="position:absolute;bottom:-1px;right:-1px;width:12px;height:12px;">${FtzStatus.dotSvg('offline', 12)}</span>
        </div>
        <div class="fi-info" style="min-width:0;flex:1;">
          <div class="fi-name" id="dm-dn-${escapeHTML(f)}" style="font-weight:600;">${escapeHTML(f)}</div>
          <div id="dm-preview-${escapeHTML(f)}" style="font-size:11px;color:var(--muted);overflow:hidden;white-space:nowrap;text-overflow:ellipsis;max-width:120px;"></div>
        </div>
        <div style="display:flex;flex-direction:column;align-items:flex-end;gap:2px;flex-shrink:0;">
          <div id="dm-time-${escapeHTML(f)}" style="font-size:10px;color:rgba(255,255,255,.15);white-space:nowrap;"></div>
          <button class="dm-close-btn" onclick="event.stopPropagation();hideDMConversation('dm_${escapeHTML(f)}')" title="Hide conversation">×</button>
        </div>
      </div>`;
      } else {
        const gc = entry.gc;
        html += `
      <div class="friend-item dm-sortable" id="gc-fi-${escapeHTML(gc.id)}" data-dm-id="gc_${escapeHTML(gc.id)}" data-last-time="0" onclick="openGroupChatView('${escapeHTML(gc.id)}')">
        <div style="width:34px;height:34px;border-radius:12px;background:linear-gradient(135deg,${gc.color||'#7c5cbf'},${gc.color2||'#3ecf6e'});display:flex;align-items:center;justify-content:center;font-size:16px;flex-shrink:0;">${gc.emoji||'👥'}</div>
        <div class="fi-info" style="min-width:0;flex:1;">
          <div class="fi-name" style="font-weight:600;">${escapeHTML(gc.name)}</div>
          <div id="gc-preview-${escapeHTML(gc.id)}" style="font-size:11px;color:var(--muted);overflow:hidden;white-space:nowrap;text-overflow:ellipsis;max-width:120px;">${(gc.members||[]).length} members</div>
        </div>
        <button class="dm-close-btn" onclick="event.stopPropagation();hideDMConversation('gc_${escapeHTML(gc.id)}')" title="Hide conversation">×</button>
      </div>`;
      }
    });
    html += '</div>';
  }

  scroll.innerHTML = html;

  // ── Async: fetch last message timestamps, PFPs, display names, status, then sort ─────────
  // Load all friends and GCs in parallel (no staggered delays)
  const visibleFriends = friends.filter(f => !hidden.includes('dm_' + f));
  const visibleGCs = gcs.filter(gc => !hidden.includes('gc_' + gc.id));

  // Bulk-fetch live presence for all visible friends via Socket.IO
  let _dmPresenceMap = {};
  try {
    const presenceResult = await FortizedSocial.queryPresence(visibleFriends);
    if (presenceResult) _dmPresenceMap = presenceResult;
  } catch(e) { console.warn('[Presence] DM query failed:', e?.message); }

  // Batch-fetch all friend profiles in ONE query instead of N separate queries
  let _friendProfileMap = {};
  try {
    const profiles = await (FortizedSocial.getUsersByNames ? FortizedSocial.getUsersByNames(visibleFriends) : Promise.all(visibleFriends.map(f => FortizedSocial.getUserByName(f))));
    (profiles || []).forEach(u => { if (u) _friendProfileMap[u.username] = u; });
  } catch(e) { console.warn('[Friends] Batch profile fetch failed:', e?.message); }

  const friendPromises = visibleFriends.map(async f => {
    try {
      // Use batch-fetched profile, fetch only latest 1 DM for preview
      const u = _friendProfileMap[f] || _friendProfileMap[f.toLowerCase()] || null;
      const dmMsgs = await FortizedSocial.getDMMessages(CU.username, f, 1);
      if (u) {
        const avEl = document.getElementById('dm-av-'+f);
        if (avEl) avEl.innerHTML = buildAvatarHTML(u.pfp||null, u.displayName||f, 34);
        const dnEl = document.getElementById('dm-dn-'+f);
        if (dnEl) {
          dnEl.textContent = u.displayName || f;
          if (u.displayFont && u.displayFont !== 'default') dnEl.style.fontFamily = _getDisplayFontCSS(u.displayFont);
          if (u.displayColor && u.displayColor !== '#fff') dnEl.style.cssText += _getDisplayEffectCSS(u.displayEffect || 'solid', u.displayColor);
        }
        // Use live Socket.IO presence — default to offline if no live data (DB status can be stale)
        const liveSt = _dmPresenceMap[f]?.status;
        const st = FtzStatus.sanitize(liveSt !== undefined ? liveSt : 'offline');
        FtzStatus.updateDots(f, st);
      }
      let lastTime = 0;
      if (dmMsgs && dmMsgs.length > 0) {
        const last = dmMsgs[dmMsgs.length - 1];
        if (last) {
          lastTime = last.timestamp || last.time || 0;
          const el = document.getElementById('dm-preview-'+f);
          if (el) {
            const preview = (last.from===CU.username?'You: ':'') + (last.text||'').replace(/\[FTZ[A-Z]+:[^\]]+\]/g,'📎 File').slice(0,40);
            el.textContent = preview;
          }
          // Show relative timestamp
          const timeEl = document.getElementById('dm-time-'+f);
          if (timeEl && lastTime) {
            const d = new Date(typeof lastTime === 'number' ? lastTime : Date.parse(lastTime));
            const now = new Date();
            const diffMs = now - d;
            const diffMin = Math.floor(diffMs / 60000);
            const diffHr = Math.floor(diffMs / 3600000);
            const diffDay = Math.floor(diffMs / 86400000);
            if (diffMin < 1) timeEl.textContent = 'now';
            else if (diffMin < 60) timeEl.textContent = diffMin + 'm';
            else if (diffHr < 24) timeEl.textContent = diffHr + 'h';
            else if (diffDay < 7) timeEl.textContent = diffDay + 'd';
            else timeEl.textContent = d.toLocaleDateString([], {month:'short', day:'numeric'});
          }
        }
      }
      const row = document.getElementById('dm-fi-'+f);
      if (row) row.dataset.lastTime = lastTime;
    } catch(e) { console.debug('[DM] Friend row update:', e?.message); }
  });

  const gcPromises = visibleGCs.map(async gc => {
    let lastTime = 0;
    try {
      const snap = await firebase.database().ref('groupChats/'+gc.id+'/messages').orderByKey().limitToLast(1).get();
      if (snap.exists()) {
        const last = Object.values(snap.val())[0];
        lastTime = last.time || last.timestamp || 0;
        const el = document.getElementById('gc-preview-'+gc.id);
        if (el && last) {
          el.textContent = (last.from===CU.username?'You: ':last.from+': ') + (last.text||'').slice(0,35);
        }
      }
    } catch(e) { console.debug('[GC] Preview update:', e?.message); }
    const row = document.getElementById('gc-fi-'+gc.id);
    if (row) row.dataset.lastTime = lastTime;
  });

  // After all fetches complete, sort the list by lastTime descending
  Promise.allSettled([...friendPromises, ...gcPromises]).then(() => {
    const listEl = document.getElementById('dm-sorted-list');
    if (!listEl) return;
    const items = Array.from(listEl.querySelectorAll('.dm-sortable'));
    items.sort((a, b) => (parseInt(b.dataset.lastTime)||0) - (parseInt(a.dataset.lastTime)||0));
    items.forEach(item => listEl.appendChild(item));
  });
}

// ── DM Friends Home (shown when no DM selected) ──
let _dmFriendsFilter = 'online';
async function renderDMFriendsHome() {
  const list = document.getElementById('dm-friends-list');
  if (!list) return;
  const friends = CU?.friends || [];
  const filter = _dmFriendsFilter;

  if (!friends.length) {
    list.innerHTML = `<div style="text-align:center;padding:48px 20px;">
      <div style="margin-bottom:14px;"><svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="rgba(255,255,255,.15)" stroke-width="1.5"><path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 00-3-3.87"/><path d="M16 3.13a4 4 0 010 7.75"/></svg></div>
      <div style="font-family:var(--font-display);font-size:16px;font-weight:800;margin-bottom:8px;color:rgba(255,255,255,.7);">No Friends Yet</div>
      <div style="font-size:12.5px;color:rgba(255,255,255,.3);margin-bottom:18px;line-height:1.5;">Add friends by their username to start chatting</div>
      <button class="btn-a" onclick="openModal('modal-add-friend')" style="padding:9px 20px;border-radius:12px;font-size:12px;display:inline-flex;align-items:center;gap:6px;"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg> Add Friend</button>
    </div>`;
    return;
  }

  // Show skeleton loading state while data loads
  list.innerHTML = friends.slice(0, 6).map(() => `<div style="display:flex;align-items:center;gap:14px;padding:10px 16px;"><div class="skeleton skeleton-avatar" style="width:42px;height:42px;flex-shrink:0;"></div><div style="flex:1;"><div class="skeleton skeleton-text" style="width:60%;"></div><div class="skeleton skeleton-text" style="width:40%;height:8px;"></div></div></div>`).join('');

  // Build friend cards with async status lookup
  let html = '';
  const pending = CU?.friendRequestsReceived || [];
  if (filter === 'all' && pending.length) {
    html += `<div style="font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);margin-bottom:8px;">PENDING — ${pending.length}</div>`;
    pending.forEach(f => {
      // Get activity for pending user (will be updated when friend data loads)
      let activityHTML = '';
      html += `<div id="dm-home-pending-${escapeHTML(f)}" style="display:flex;align-items:center;gap:12px;padding:10px 14px;border-radius:12px;transition:background .12s;">
        <div style="position:relative;flex-shrink:0;"><div class="fa" id="dm-home-pav-${escapeHTML(f)}" style="width:40px;height:40px;font-size:15px;">${buildAvatarHTML(null,f,40)}</div></div>
        <div style="flex:1;min-width:0;"><div id="dm-home-pdn-${escapeHTML(f)}" style="font-weight:600;font-size:13.5px;">${escapeHTML(f)}</div><div style="font-size:11.5px;color:var(--muted);">Incoming friend request</div><div id="dm-home-pact-${escapeHTML(f)}" style="font-size:10px;color:rgba(255,255,255,.35);margin-top:2px;"></div></div>
        <div style="display:flex;gap:6px;">
          <button class="btn-a" style="padding:6px 14px;font-size:12px;" onclick="acceptFriend('${escapeHTML(f)}')">Accept</button>
          <button class="btn-g" style="padding:6px 14px;font-size:12px;" onclick="declineFriend('${escapeHTML(f)}')">Ignore</button>
        </div>
      </div>`;
    });
    html += '<div style="height:12px;"></div>';
  }

  html += `<div style="font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);margin-bottom:8px;">${filter==='online'?'ONLINE':'ALL FRIENDS'} — ${friends.length}</div>`;

  friends.forEach(f => {
    html += `<div class="dm-friend-row" data-user="${escapeHTML(f)}" style="display:flex;align-items:center;gap:14px;padding:10px 16px;border-radius:12px;transition:all .18s cubic-bezier(.22,1,.36,1);cursor:pointer;border:1px solid transparent;background:transparent;" onclick="openDMView('${escapeHTML(f)}')">
      <div style="position:relative;flex-shrink:0;">
        <div class="fa" id="dm-home-av-${escapeHTML(f)}" style="width:42px;height:42px;font-size:15px;border:2px solid rgba(255,255,255,.06);">${buildAvatarHTML(null,f,42)}</div>
        <span class="dm-home-status" data-for="${escapeHTML(f)}" style="position:absolute;bottom:-1px;right:-1px;width:12px;height:12px;border-radius:50%;background:#6b7280;border:2.5px solid var(--bg);"></span>
      </div>
      <div style="flex:1;min-width:0;">
        <div id="dm-home-dn-${escapeHTML(f)}" style="font-weight:700;font-size:13.5px;font-family:var(--font-display);">${escapeHTML(f)}</div>
        <div style="display:flex;flex-direction:column;gap:1px;margin-top:2px;">
          <div class="dm-home-status-text" data-for="${escapeHTML(f)}" style="font-size:11px;color:rgba(255,255,255,.25);">Offline</div>
          <div id="dm-home-activity-${escapeHTML(f)}" style="font-size:10px;color:rgba(255,255,255,.2);"></div>
        </div>
      </div>
      <div style="display:flex;gap:6px;">
        <button class="friend-msg-btn" onclick="event.stopPropagation();openDMView('${escapeHTML(f)}')">
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15a2 2 0 01-2 2H7l-4 4V5a2 2 0 012-2h14a2 2 0 012 2z"/></svg> Message</button>
      </div>
    </div>`;
  });

  list.innerHTML = html;

  // Update stat bar
  const statOnline = document.getElementById('dm-stat-online');
  const statTotal = document.getElementById('dm-stat-total');
  const statBastions = document.getElementById('dm-stat-bastions');
  if (statTotal) statTotal.textContent = friends.length;
  if (statBastions) statBastions.textContent = (CU?.bastions||[]).length;

  // Async: fetch real PFPs, display names, and statuses
  // First, bulk-fetch live presence via Socket.IO for ALL friends at once
  let _friendPresenceMap = {};
  const allUsers = [...new Set([...friends, ...pending])];
  try {
    const presenceResult = await FortizedSocial.queryPresence(allUsers);
    if (presenceResult) _friendPresenceMap = presenceResult;
  } catch(e) { console.warn('[Presence] Home query failed:', e?.message); }

  // Batch-fetch all friend/pending profiles in ONE query instead of N separate queries
  let _homeProfileMap = {};
  try {
    const profiles = await (FortizedSocial.getUsersByNames ? FortizedSocial.getUsersByNames(allUsers) : Promise.all(allUsers.map(f => FortizedSocial.getUserByName(f))));
    (profiles || []).forEach(u => { if (u) _homeProfileMap[u.username] = u; });
  } catch(e) { console.warn('[Friends] Home profile fetch failed:', e?.message); }

  let _onlineCount = 0;
  allUsers.forEach(async f => {
    try {
      const u = _homeProfileMap[f] || _homeProfileMap[f.toLowerCase()] || null;
      if (!u) return;

      // Update friend row avatar + display name
      const avEl = document.getElementById('dm-home-av-'+f);
      if (avEl) avEl.innerHTML = buildAvatarHTML(u.pfp||null, u.displayName||f, 42);
      const dnEl = document.getElementById('dm-home-dn-'+f);
      if (dnEl) dnEl.textContent = u.displayName || f;

      // Update pending row avatar + display name
      const pavEl = document.getElementById('dm-home-pav-'+f);
      if (pavEl) pavEl.innerHTML = buildAvatarHTML(u.pfp||null, u.displayName||f, 40);
      const pdnEl = document.getElementById('dm-home-pdn-'+f);
      if (pdnEl) pdnEl.textContent = u.displayName || f;

      // Use LIVE Socket.IO presence — default to offline if no live data (DB status can be stale)
      const liveSt = _friendPresenceMap[f]?.status;
      const st = FtzStatus.sanitize(liveSt !== undefined ? liveSt : 'offline');
      const dot = document.querySelector(`.dm-home-status[data-for="${CSS.escape(f)}"]`);
      if (dot) { dot.style.background = FtzStatus.color(st); dot.style.boxShadow = '0 0 8px '+FtzStatus.color(st)+'55'; }
      const stText = document.querySelector(`.dm-home-status-text[data-for="${CSS.escape(f)}"]`);
      if (stText) {
        const csText = u.customStatus?.text || u.customStatus;
        stText.textContent = csText || FtzStatus.publicLabel(st);
      }

      // Update activity display
      let activityText = '';
      if (u.activityState?.activities?.length) {
        const primaryActivity = u.activityState.activities.sort((a, b) => (b.priority || 2) - (a.priority || 2))[0];
        if (primaryActivity) activityText = formatActivityDisplay(primaryActivity);
      } else if (u.gameActivity?.name) {
        activityText = formatActivityDisplay({
          id: u.gameActivity._spotify ? 'spotify' : 'game',
          type: u.gameActivity._spotify ? 'listening' : 'playing',
          name: u.gameActivity.name,
          metadata: { genre: u.gameActivity.genre }
        });
      }
      const actEl = document.getElementById('dm-home-activity-'+f);
      if (actEl) actEl.textContent = activityText ? '🎮 ' + activityText : '';

      // Update pending activity display
      const pendActEl = document.getElementById('dm-home-pact-'+f);
      if (pendActEl) pendActEl.textContent = activityText ? '🎮 ' + activityText : '';
      // Track online count
      if (FtzStatus.isPresent(st)) {
        _onlineCount++;
        const sob = document.getElementById('dm-stat-online');
        if (sob) sob.textContent = _onlineCount;
      }
      // If filtering online and user is offline, hide row
      if (filter === 'online' && !FtzStatus.isPresent(st)) {
        const row = document.querySelector(`.dm-friend-row[data-user="${CSS.escape(f)}"]`);
        if (row) row.style.display = 'none';
      }
    } catch (e) { console.debug('[DM] friend status update failed', e); }
  });
}

function dmFriendsFilter(filter, btn) {
  _dmFriendsFilter = filter;
  document.querySelectorAll('#dm-friends-tabs .disc-tab').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  renderDMFriendsHome();
}

function filterDMFriendsList(query) {
  const q = (query||'').toLowerCase().trim();
  document.querySelectorAll('.dm-friend-row').forEach(row => {
    const user = (row.getAttribute('data-user')||'').toLowerCase();
    const nameEl = row.querySelector('[id^="dm-home-dn-"]');
    const name = nameEl ? nameEl.textContent.toLowerCase() : '';
    row.style.display = (user.includes(q) || name.includes(q)) ? '' : 'none';
  });
}

// ── Active Now Sidebar ──────────────────────────────
async function renderActiveNowSidebar(containerId) {
  const container = document.getElementById(containerId);
  if (!container) return;
  const friends = CU?.friends || [];
  if (!friends.length) {
    container.innerHTML = `<div class="active-now-empty">
      <div class="an-empty-icon"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="rgba(255,255,255,.15)" stroke-width="1.5"><circle cx="12" cy="12" r="10"/><path d="M8 14s1.5 2 4 2 4-2 4-2"/><line x1="9" y1="9" x2="9.01" y2="9"/><line x1="15" y1="9" x2="15.01" y2="9"/></svg></div>
      <div class="an-empty-text">It's quiet for now...<br>When friends come online, they'll appear here.</div>
    </div>`;
    return;
  }

  container.innerHTML = '<div style="padding:12px;text-align:center;"><div class="pl-spinner" style="width:16px;height:16px;border-width:2px;margin:0 auto;"></div></div>';

  // Bulk-fetch live presence via Socket.IO FIRST (fast, real-time accurate)
  const friendsSlice = friends.slice(0, 30);
  let _anPresence = {};
  try {
    const presenceResult = await FortizedSocial.queryPresence(friendsSlice);
    if (presenceResult) _anPresence = presenceResult;
  } catch(e) { console.warn('[Presence] Announce query failed:', e?.message); }

  const results = await Promise.all(friendsSlice.map(async f => {
    try {
      const u = await FortizedSocial.getUserByName(f);
      // Use LIVE Socket.IO presence, fallback to DB status only if Socket.IO unavailable
      const liveSt = _anPresence[f]?.status;
      const liveGA = _anPresence[f]?.gameActivity;
      const st = liveSt !== undefined ? liveSt : (u?.status || 'offline');
      const csText = u?.customStatus?.text || (typeof u?.customStatus === 'string' ? u.customStatus : '');
      const gameAct = liveGA?.name || u?.gameActivity?.name || '';
      return {username:f, displayName:u?.displayName||f, pfp:u?.pfp||null, status:st, customStatus:csText, gameActivity:gameAct};
    } catch { return {username:f, displayName:f, pfp:null, status:'offline', customStatus:'', gameActivity:''}; }
  }));

  const online = results.filter(r => FtzStatus.isPresent(r.status));

  if (!online.length) {
    container.innerHTML = `<div class="active-now-empty">
      <div class="an-empty-icon"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="rgba(255,255,255,.15)" stroke-width="1.5"><circle cx="12" cy="12" r="10"/><path d="M8 14s1.5 2 4 2 4-2 4-2"/><line x1="9" y1="9" x2="9.01" y2="9"/><line x1="15" y1="9" x2="15.01" y2="9"/></svg></div>
      <div class="an-empty-text">It's quiet for now...<br>When friends come online, they'll appear here.</div>
    </div>`;
    return;
  }

  container.innerHTML = online.map(u => {
    const activityText = u.gameActivity
      ? `<svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="opacity:.6;flex-shrink:0;"><line x1="6" y1="12" x2="10" y2="12"/><line x1="8" y1="10" x2="8" y2="14"/><line x1="15" y1="13" x2="15.01" y2="13"/><line x1="18" y1="11" x2="18.01" y2="11"/><rect x="2" y="6" width="20" height="12" rx="2"/></svg> Playing: ${escapeHTML(u.gameActivity)}`
      : u.customStatus
        ? escapeHTML(u.customStatus)
        : FtzStatus.label(u.status);
    return `<div class="active-now-item" onclick="viewUserProfile('${escapeHTML(u.username)}')">
      <div class="an-avatar" style="pointer-events:none;">
        <div class="fa" style="width:36px;height:36px;border-radius:50%;overflow:hidden;font-size:13px;">${buildAvatarHTML(u.pfp, u.displayName, 36)}</div>
        <span class="an-status-dot profile-status-dot" data-for="${escapeHTML(u.username)}" data-dot-size="16">${FtzStatus.dotSvg(u.status, 16)}</span>
      </div>
      <div class="an-info" style="pointer-events:none;">
        <div class="an-name">${escapeHTML(u.displayName)}</div>
        <div class="an-activity">${activityText}</div>
      </div>
    </div>`;
  }).join('');
}
let _activeNowRefreshTimer = null;
function _debouncedActiveNowRefresh() {
  if (_activeNowRefreshTimer) clearTimeout(_activeNowRefreshTimer);
  _activeNowRefreshTimer = setTimeout(() => {
    _activeNowRefreshTimer = null;
    const h = document.getElementById('home-active-now-list');
    const d = document.getElementById('dm-active-now-list');
    if (h) renderActiveNowSidebar('home-active-now-list');
    if (d) renderActiveNowSidebar('dm-active-now-list');
  }, 600);
}

