// ════════════════════════════════════════════
// FRIENDS
// ════════════════════════════════════════════
async function renderFriendsList(filter='all') {
  // Use the enhanced sorted friends list
  return renderFriendsSorted(_friendSortMode || 'online');
}
function filterFriends(filter,btn){
  document.querySelectorAll('#friends-tabs .disc-tab').forEach(b=>b.classList.remove('active'));
  if(btn)btn.classList.add('active');
  renderFriendsList(filter);
}
async function sendFriendRequest(){
  const inp=document.getElementById('friend-target');
  const err=document.getElementById('friend-error');
  const succ=document.getElementById('friend-success');
  const btn=document.getElementById('friend-send-btn');
  if(!inp)return;
  const username=inp.value.trim().toLowerCase();
  if(!username){if(err)err.textContent='Enter a username';return;}
  if(username===CU.username){if(err)err.textContent="Can't add yourself";return;}
  if(isUserBlocked(username)){if(err)err.textContent="Can't send friend requests to blocked users";return;}
  if(err)err.textContent='';if(succ)succ.textContent='';
  if(btn)btn.classList.add('btn-loading');
  try{
    const r=await FortizedSocial.sendFriendRequest(CU.username, username);
    if(r.ok){
      if(succ) succ.textContent=r.msg;
      inp.value='';
      const hint=document.getElementById('friend-target-hint');
      if(hint){hint.style.color='var(--accent)';hint.textContent='⏳ Friend request sent!';}
      await refreshCU();
      renderFriendsList();
    } else {
      if(err) err.textContent=r.msg||'Failed';
    }
  } catch(e){ console.error(e); if(err) err.textContent='Connection error'; }
  finally { if(btn) btn.classList.remove('btn-loading'); }
}
async function acceptFriend(username){
  try{
    await FortizedSocial.acceptFriendRequest(CU.username, username);
    await refreshCU();
    toast('Now friends with '+username+'!','success');
    showFeedbackToast('adding a friend', 'friend_accept');
    renderFriendsList();
    renderDMSidebar(document.getElementById('sidebar-scroll'));
    // Auto-open DM
    openDMView(username);
  } catch(e){ console.error('[Friends] Accept failed:', e); toast('Failed to accept friend request. Please try again.','error'); }
}
async function declineFriend(username){
  try{
    await FortizedSocial.declineFriendRequest(CU.username, username);
    await refreshCU();
    renderFriendsList();
    toast('Declined','info');
  } catch(e){ console.error(e); }
}
async function removeFriend(username){
  showCustomConfirm('Remove '+username+' from friends?', async()=>{
    try{
      await FortizedSocial.removeFriend(CU.username, username);
      await refreshCU();
      toast('Removed '+username,'info');
      renderFriendsList();
      renderDMSidebar(document.getElementById('sidebar-scroll'));
    } catch(e){ console.error(e); toast('An error occurred. Please try again.','error'); }
  });
}

