function pickCBEmoji(event){
  const emojis=['🏰','⚔️','🛡️','🔮','🏹','🌟','🔥','❄️','🌊','⛩️','🎮','🎨','🎵','🎭','🎯','🧩','⚡','🌺','🦋','🐉','🦅','🌈','🦁','🐺','🦊','🎪','🚀','💫','🌙','☀️'];
  const x=event&&event.clientX||window.innerWidth/2;
  const y=event&&event.clientY||window.innerHeight/2;
  showCtxMenu(x,y,[{items:emojis.map(e=>({icon:e,label:e,action:()=>selectCBEmoji(e)}))}]);
}
function setCBVis(v,btn){
  cbVisibility=v;
  document.querySelectorAll('.vis-btn').forEach(b=>b.classList.remove('active'));
  if(btn)btn.classList.add('active');
}
// ── Roblox-style Ban / Suspend / Warning Screens ──
function _fmtDateEU(d) { if (!d) return 'Unknown'; try { const dt = new Date(d); if (isNaN(dt.getTime())) return 'Unknown'; const dd = String(dt.getDate()).padStart(2,'0'); const mm = String(dt.getMonth()+1).padStart(2,'0'); const yy = dt.getFullYear(); const hh = String(dt.getHours()).padStart(2,'0'); const mi = String(dt.getMinutes()).padStart(2,'0'); return dd+'/'+mm+'/'+yy+' — '+hh+':'+mi; } catch { return 'Unknown'; } }
function _fmtDateEUShort(d) { if (!d) return 'Unknown'; try { const dt = new Date(d); if (isNaN(dt.getTime())) return 'Unknown'; const dd = String(dt.getDate()).padStart(2,'0'); const mm = String(dt.getMonth()+1).padStart(2,'0'); const yy = dt.getFullYear(); return dd+'/'+mm+'/'+yy; } catch { return 'Unknown'; } }

function _renderOffendingContent(data) {
  if (!data || typeof data !== 'object') return '';
  let html = '';
  const text = data.offendingText || data.msgText || data.content || '';
  const media = Array.isArray(data.offendingMedia) ? data.offendingMedia : (Array.isArray(data.media) ? data.media : []);
  if (text) {
    const cleanText = text.replace(/\[FTZ(?:IMG|VID|AUD|GIF|STICKER):[^\]]*\]/gi, '').trim();
    if (cleanText) html += `<div style="display:flex;justify-content:flex-start;padding:10px 0;border-bottom:1px solid rgba(255,255,255,.06);flex-direction:column;gap:6px;">
      <span style="color:#5a6478;font-size:13px;">Offending Content</span>
      <div style="background:rgba(248,113,113,.04);border:1px solid rgba(248,113,113,.12);border-left:3px solid #f87171;border-radius:8px;padding:10px 14px;font-size:13px;color:#c8d0dc;line-height:1.6;word-break:break-word;">${escapeHTML(cleanText.slice(0,300))}${cleanText.length>300?'...':''}</div>
    </div>`;
  }
  if (media.length) html += `<div style="padding:10px 0;border-bottom:1px solid rgba(255,255,255,.06);display:flex;flex-direction:column;gap:6px;">
    <span style="color:#5a6478;font-size:13px;">Flagged Media</span>
    <div style="display:flex;gap:8px;flex-wrap:wrap;">${media.map(m => {
      if (m.type === 'video') { const _vp='rvid-'+Math.random().toString(36).slice(2); return `<div style="display:inline-block;max-width:200px;"><div class="ftz-vp" id="${_vp}-wrap" style="border-radius:8px;"><video id="${_vp}" src="${m.url}" style="max-width:200px;max-height:140px;display:block;cursor:pointer;" muted preload="metadata" crossorigin="anonymous" onclick="ftzVideoToggle('${_vp}')" ontimeupdate="ftzVideoTick('${_vp}')" onloadedmetadata="ftzVideoMeta('${_vp}')" onended="ftzVideoEnd('${_vp}')" onerror="ftzVideoError('${_vp}')"></video><div class="ftz-vp-overlay" id="${_vp}-overlay" onclick="ftzVideoToggle('${_vp}')"><div class="ftz-vp-overlay-btn" style="width:32px;height:32px;"><svg width="14" height="14" viewBox="0 0 24 24" fill="#fff"><polygon points="6 3 20 12 6 21 6 3"/></svg></div></div></div></div>`; }
      return `<img src="${m.url}" style="max-width:200px;max-height:140px;border-radius:8px;border:1px solid rgba(255,255,255,.06);object-fit:cover;background:rgba(0,0,0,.3);" onerror="this.style.display='none'">`;
    }).join('')}</div>
  </div>`;
  return html;
}

function _showBanScreen(ban) {
  if (!ban || typeof ban !== 'object') ban = {};
  const bannedAt = ban.bannedAt || ban.at || ban.date || null;
  const reason = ban.reason || ban.note || '';
  const category = ban.category || 'Account behavior';
  const bannedBy = ban.bannedBy || ban.by || 'Fortized Moderation';
  document.body.innerHTML = `<div style="position:fixed;inset:0;z-index:9999;background:var(--rail);display:flex;align-items:center;justify-content:center;font-family:var(--font-display);">
    <div style="background:rgba(19,22,29,.95);border:1px solid #252b3a;border-radius:22px;width:100%;max-width:580px;padding:48px 40px;text-align:center;box-shadow:0 32px 80px rgba(0,0,0,.7);">
      <div style="width:68px;height:68px;border-radius:18px;background:rgba(248,113,113,.08);border:1px solid rgba(248,113,113,.18);display:flex;align-items:center;justify-content:center;margin:0 auto 20px;">
        <svg width="32" height="32" viewBox="0 0 24 24" fill="none">
          <circle cx="12" cy="12" r="11" stroke="#f87171" stroke-width="2" fill="none"/>
          <path d="M8 8l8 8M16 8l-8 8" stroke="#f87171" stroke-width="2" stroke-linecap="round"/>
        </svg>
      </div>
      <div style="font-size:28px;font-weight:800;color:#fff;margin-bottom:6px;letter-spacing:-.5px;">Account Banned</div>
      <div style="font-size:14px;color:#8b95a8;margin-bottom:28px;line-height:1.7;">Our content monitors have determined that your behavior at Fortized has been in violation of our <a href="/terms" target="_blank" rel="noopener noreferrer" style="color:var(--accent);text-decoration:none;font-weight:600;">Terms of Use</a>.</div>
      <div style="background:#13161d;border:1px solid #252b3a;border-radius:14px;padding:20px 24px;text-align:left;margin-bottom:24px;">
        <div style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid rgba(255,255,255,.06);">
          <span style="color:#5a6478;font-size:13px;">Reviewed</span>
          <span style="color:#c8d0dc;font-size:13px;font-weight:600;">${_fmtDateEU(bannedAt)}</span>
        </div>
        <div style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid rgba(255,255,255,.06);">
          <span style="color:#5a6478;font-size:13px;">Moderator Note</span>
          <span style="color:#c8d0dc;font-size:13px;font-weight:600;">${reason ? escapeHTML(reason) : 'No reason provided'}</span>
        </div>
        <div style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid rgba(255,255,255,.06);">
          <span style="color:#5a6478;font-size:13px;">Category</span>
          <span style="color:#c8d0dc;font-size:13px;font-weight:600;">${escapeHTML(category)}</span>
        </div>
        ${_renderOffendingContent(ban)}
        <div style="display:flex;justify-content:space-between;padding:10px 0;">
          <span style="color:#5a6478;font-size:13px;">Actioned by</span>
          <span style="color:#c8d0dc;font-size:13px;font-weight:600;">${escapeHTML(bannedBy)}</span>
        </div>
      </div>
      <div style="font-size:12px;color:#5a6478;margin-bottom:24px;">If you wish to appeal, please visit <a href="/support#contact" target="_blank" rel="noopener noreferrer" style="color:var(--accent);text-decoration:none;font-weight:600;">Fortized Support</a></div>
      <button onclick="localStorage.removeItem('ftz_current');localStorage.removeItem('fortized_current_user');window.location.href='/login'" style="padding:12px 48px;background:var(--red);border:none;border-radius:10px;color:#fff;font-size:14px;font-weight:700;cursor:pointer;font-family:inherit;transition:all .18s;">Log Out</button>
    </div>
  </div>`;
}

function _showSuspendScreen(data) {
  if (!data || typeof data !== 'object') data = {};
  const until = data.until ? new Date(data.until) : null;
  const reason = data.reason || data.note || 'No reason provided';
  const moderator = data.suspendedBy || data.by || 'Fortized Moderation';
  const modMessage = data.moderatorMessage || data.message || '';
  const suspendedAt = data.suspendedAt || data.at || data.date || null;
  const durationText = _fmtDateEU(data.until);
  // Auto-refresh when suspension expires
  if (until && until > new Date()) {
    const msLeft = until.getTime() - Date.now();
    if (msLeft > 0 && msLeft < 86400000 * 30) { // only set timer if <30 days
      setTimeout(() => { location.reload(); }, msLeft + 1000);
    }
  }
  document.body.innerHTML = `<div style="position:fixed;inset:0;z-index:9999;background:var(--rail);display:flex;align-items:center;justify-content:center;font-family:var(--font-display);">
    <div style="background:rgba(19,22,29,.95);border:1px solid #252b3a;border-radius:22px;width:100%;max-width:580px;padding:48px 40px;text-align:center;box-shadow:0 32px 80px rgba(0,0,0,.7);">
      <div style="width:68px;height:68px;border-radius:18px;background:rgba(245,158,11,.08);border:1px solid rgba(245,158,11,.18);display:flex;align-items:center;justify-content:center;margin:0 auto 20px;">
        <svg width="32" height="32" viewBox="0 0 24 24" fill="none">
          <circle cx="12" cy="12" r="11" stroke="#f59e0b" stroke-width="2" fill="none"/>
          <rect x="11" y="6" width="2" height="7" rx="1" fill="#f59e0b"/>
          <circle cx="12" cy="16.5" r="1.2" fill="#f59e0b"/>
        </svg>
      </div>
      <div style="font-size:28px;font-weight:800;color:#fff;margin-bottom:6px;letter-spacing:-.5px;">Account Suspended</div>
      <div style="font-size:14px;color:#8b95a8;margin-bottom:28px;line-height:1.7;">Our content monitors have determined that your behavior at Fortized has been in violation of our <a href="/terms" target="_blank" rel="noopener noreferrer" style="color:var(--accent);text-decoration:none;font-weight:600;">Terms of Use</a>. As a result, your account has been temporarily suspended.</div>
      <div style="background:#13161d;border:1px solid #252b3a;border-radius:14px;padding:20px 24px;text-align:left;margin-bottom:24px;">
        <div style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid rgba(255,255,255,.06);">
          <span style="color:#5a6478;font-size:13px;">Reviewed</span>
          <span style="color:#c8d0dc;font-size:13px;font-weight:600;">${_fmtDateEU(suspendedAt)}</span>
        </div>
        <div style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid rgba(255,255,255,.06);">
          <span style="color:#5a6478;font-size:13px;">Reason</span>
          <span style="color:#c8d0dc;font-size:13px;font-weight:600;">${escapeHTML(reason)}</span>
        </div>
        ${modMessage ? `<div style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid rgba(255,255,255,.06);">
          <span style="color:#5a6478;font-size:13px;">Moderator Message</span>
          <span style="color:#c8d0dc;font-size:13px;font-weight:600;">${escapeHTML(modMessage)}</span>
        </div>` : ''}
        ${_renderOffendingContent(data)}
        <div style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid rgba(255,255,255,.06);">
          <span style="color:#5a6478;font-size:13px;">Reactivation</span>
          <span style="color:#c8d0dc;font-size:13px;font-weight:600;">${durationText}</span>
        </div>
        <div style="display:flex;justify-content:space-between;padding:10px 0;">
          <span style="color:#5a6478;font-size:13px;">Actioned by</span>
          <span style="color:#c8d0dc;font-size:13px;font-weight:600;">${escapeHTML(moderator)}</span>
        </div>
      </div>
      <div style="font-size:12px;color:#5a6478;margin-bottom:24px;">Your account will be reactivated on <span style="color:var(--accent);font-weight:600;">${durationText}</span>. To appeal, visit <a href="/support#contact" target="_blank" rel="noopener noreferrer" style="color:var(--accent);text-decoration:none;font-weight:600;">Fortized Support</a></div>
      <button onclick="localStorage.removeItem('ftz_current');localStorage.removeItem('fortized_current_user');window.location.href='/login'" style="padding:12px 48px;background:#f59e0b;border:none;border-radius:10px;color:var(--rail);font-size:14px;font-weight:700;cursor:pointer;font-family:inherit;transition:all .18s;">Log Out</button>
    </div>
  </div>`;
}

function _showWarningOverlay(reason, issuedBy, contentData) {
  if (document.getElementById('ftz-warning-overlay')) return;
  const safeReason = (reason && typeof reason === 'string') ? reason : 'Violation of Terms of Use';
  const safeMod = (issuedBy && typeof issuedBy === 'string') ? issuedBy : 'Fortized Moderation';
  const overlay = document.createElement('div');
  overlay.id = 'ftz-warning-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;z-index:9999;background:rgba(8,10,15,.92);backdrop-filter:blur(12px);display:flex;align-items:center;justify-content:center;font-family:"Syne",system-ui,-apple-system,sans-serif;animation:fadeIn .3s ease;';
  overlay.innerHTML = `<div style="background:rgba(19,22,29,.95);border:1px solid #252b3a;width:100%;max-width:520px;padding:40px 36px;text-align:center;border-radius:22px;box-shadow:0 32px 80px rgba(0,0,0,.7);">
    <div style="width:60px;height:60px;border-radius:16px;background:rgba(245,158,11,.08);border:1px solid rgba(245,158,11,.18);display:flex;align-items:center;justify-content:center;margin:0 auto 18px;">
      <svg width="28" height="28" viewBox="0 0 24 24" fill="none">
        <path d="M12 2L1 21h22L12 2z" stroke="#f59e0b" stroke-width="2" fill="none" stroke-linejoin="round"/>
        <rect x="11" y="9" width="2" height="5" rx="1" fill="#f59e0b"/>
        <circle cx="12" cy="17" r="1.2" fill="#f59e0b"/>
      </svg>
    </div>
    <div style="font-size:24px;font-weight:800;color:#fff;margin-bottom:6px;letter-spacing:-.3px;">Warning</div>
    <div style="font-size:14px;color:#8b95a8;margin-bottom:24px;line-height:1.7;">You have been issued a warning by a Fortized moderator.</div>
    <div style="background:#13161d;border:1px solid #252b3a;border-radius:14px;padding:18px 22px;text-align:left;margin-bottom:24px;">
      <div style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid rgba(255,255,255,.06);">
        <span style="color:#5a6478;font-size:13px;">Issued</span>
        <span style="color:#c8d0dc;font-size:13px;font-weight:600;">${_fmtDateEU(new Date())}</span>
      </div>
      <div style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid rgba(255,255,255,.06);">
        <span style="color:#5a6478;font-size:13px;">Reason</span>
        <span style="color:#c8d0dc;font-size:13px;font-weight:600;max-width:260px;text-align:right;">${escapeHTML(safeReason)}</span>
      </div>
      ${contentData && typeof contentData === 'object' ? _renderOffendingContent(contentData) : ''}
      <div style="display:flex;justify-content:space-between;padding:10px 0;">
        <span style="color:#5a6478;font-size:13px;">Actioned by</span>
        <span style="color:#c8d0dc;font-size:13px;font-weight:600;">${escapeHTML(safeMod)}</span>
      </div>
    </div>
    <div style="font-size:12px;color:#5a6478;margin-bottom:20px;">Please review our <a href="/terms" target="_blank" rel="noopener noreferrer" style="color:var(--accent);text-decoration:none;font-weight:600;">Terms of Use</a> to avoid further action on your account.</div>
    <button onclick="document.getElementById('ftz-warning-overlay').remove()" class="warning-ack-btn">Acknowledge</button>
  </div>`;
  document.body.appendChild(overlay);
}

function banUser(username,permanent=true){
  if (username === JOYSTER_ACCOUNT) { toast('Joyster is protected and cannot be banned.','error'); return; }
  if (username === FORTIZED_ACCOUNT) { toast('Fortized is protected and cannot be banned.','error'); return; }
  showCustomInput('Ban Reason','Enter reason:',reason=>{
    if(!reason)return;
    const bans=JSON.parse(localStorage.getItem('ftz_bans')||'[]');
    const banObj = {username,reason,bannedBy:CU.username,permanent,bannedAt:new Date().toISOString()};
    bans.push(banObj);
    localStorage.setItem('ftz_bans',JSON.stringify(bans));
    _saveBanToFirebase(banObj);
    logAudit(permanent?'permanent_ban':'temp_ban',username,reason);
    toast(username+' banned','success');
    loadAdminTab('users');
  });
}
function unbanUser(username){
  const bans=JSON.parse(localStorage.getItem('ftz_bans')||'[]');
  localStorage.setItem('ftz_bans',JSON.stringify(bans.filter(b=>b.username!==username)));
  _removeBanFromFirebase(username);
  logAudit('unban',username,'Unbanned by admin');
  toast(username+' unbanned','success');
  _loadAdminPage(adminTab);
}
function updateDOBField(){
  const input=document.getElementById('dob-input');
  if(!input?.value)return;
  const tier=getAgeTier(input.value);
  const labels={child:'🧒 Protected (13–15)',teen:'🧑 Teen (16–17)',adult:'🧑‍🦳 Adult (18+)'};
  const hint=document.getElementById('dob-tier-hint');
  if(hint)hint.textContent=tier?'Age tier: '+labels[tier]:'⚠️ Must be 13+';
}

function initFortizedUXResilience() {
  let _uxResizeTimer;
  window.addEventListener('resize', () => {
    clearTimeout(_uxResizeTimer);
    _uxResizeTimer = setTimeout(() => {
      if (window.innerWidth > 900) {
        document.getElementById('mobile-overlay')?.classList.remove('active');
        document.getElementById('sidebar')?.classList.remove('mobile-open');
      }
    }, 100);
  });
  document.addEventListener('error', (e) => {
    const t = e.target;
    if (!(t instanceof HTMLImageElement)) return;
    if (t.dataset.fallbackApplied) return;
    t.dataset.fallbackApplied = '1';
    t.src = '/default pfp2.png';
  }, true);
}

// ════════════════════════════════════════════
// APP INIT
// ════════════════════════════════════════════
(async function appInit(){
  const _sl=document.getElementById('app-loading');
  const _st=setTimeout(()=>{if(_sl){_sl.style.opacity='0';setTimeout(()=>{_sl.style.display='none';},300);}},10000);
  window._loadingSafetyTimer = _st;
  try{
  if (document.readyState==='loading') await new Promise(r=>document.addEventListener('DOMContentLoaded',r));

  // Wait for CDN scripts + FortizedSocial to be available (max 5s with faster check)
  if (typeof FortizedSocial === 'undefined') {
    await Promise.race([
      new Promise(r => { const iv = setInterval(() => { if (typeof FortizedSocial !== 'undefined') { clearInterval(iv); r(); } }, 50); }),
      new Promise(r => setTimeout(r, 5000))
    ]);
  }
  if (typeof FortizedSocial === 'undefined') {
    // Scripts never loaded — show offline state from cache if possible
    const lbl = document.querySelector('#app-loading .lbl');
    if (lbl) lbl.textContent = '⚠️ Network issue — loading cached data…';
  }

  // Detect Electron desktop app via preload bridge OR User-Agent string
  const _isElectronApp = !!(window.fortizedDesktop?.isDesktopApp || navigator.userAgent.includes('FortizedApp') || navigator.userAgent.includes('Electron'));
  if (_isElectronApp) {
    document.body.classList.add('is-desktop-app');
    // Ensure the fortizedDesktop bridge is available for feature checks
    if (!window.fortizedDesktop) {
      window.fortizedDesktop = { isDesktopApp: true };
    }
  }

  // Get username — FortizedSocial stores plain string
  let username=localStorage.getItem('ftz_current')||localStorage.getItem('fortized_current_user');
  if (!username){window.location.href='/login';return;}
  // Handle old format that stored full JSON object
  if (username.startsWith('{')){try{username=JSON.parse(username).username;}catch(e){console.warn('[Init] Username parse failed:', e?.message);}}
  username=username.replace(/^["']|["']$/g,'').trim();
  if (!username){window.location.href='/login';return;}

  // CRITICAL: Always fetch fresh user data from database on page load
  // This ensures PFP changes, messages, and friends sync properly across sessions
  // Only use localStorage as a fallback if database fetch fails
  let usedCache = false;
  if (!navigator.onLine || typeof FortizedSocial === 'undefined') {
    // Offline or scripts failed — use cache as fallback
    const cached=localStorage.getItem('ftz_user_'+username);
    if (cached){
      try{CU=JSON.parse(cached);}catch{CU=null;}
      usedCache = true;
      console.debug('[Init] Using cached user data (offline mode)');
    }
    if (!CU?.username) {
      localStorage.removeItem('ftz_current');
      localStorage.removeItem('fortized_current_user');
      window.location.href='/login';
      return;
    }
  } else {
    // Online — fetch fresh data from database (bypass cache to ensure latest)
    const lbl=document.querySelector('#app-loading .lbl');
    if(lbl)lbl.textContent='Fetching your profile…';
    try{
      CU=await Promise.race([
        FortizedSocial.getUserByName(username, { noCache: true }),
        new Promise((_,r)=>setTimeout(()=>r(new Error('timeout')),7000))
      ]);
    }catch(e){
      CU=null;
      if(lbl)lbl.textContent='⚠️ Connection timeout. Trying cache…';
      // Fall back to cache if database fetch times out
      const cached=localStorage.getItem('ftz_user_'+username);
      if (cached){
        try{CU=JSON.parse(cached);}catch{CU=null;}
        usedCache = true;
        console.warn('[Init] Cache fallback after timeout:', e?.message);
      }
    }
    if (!CU?.username){
      // Last attempt with longer timeout
      try{
        await new Promise(r=>setTimeout(r,1500));
        CU=await Promise.race([
          FortizedSocial.getUserByName(username, { noCache: true }),
          new Promise((_,r)=>setTimeout(()=>r(new Error('timeout')),5000))
        ]);
      }catch(e){
        console.warn('[Init] Retry failed:', e?.message);
      }
    }
    if (!CU?.username){
      localStorage.removeItem('ftz_current');
      localStorage.removeItem('fortized_current_user');
      window.location.href='/login?error=auth_failed';
      return;
    }
    // Always cache the fresh data
    localStorage.setItem('ftz_user_'+username,JSON.stringify(CU));
  }

  // Set defaults
  if (!CU.bastions)CU.bastions=[];
  if (!CU.friends)CU.friends=[];
  if (CU.onyx===undefined)CU.onyx=0;
  notifSettings=CU.notifSettings||notifSettings;

  // ── Enforce bans & suspensions (skip when offline to avoid hanging) ──
  if (navigator.onLine) {
    try {
      // Check ban from Supabase user data (already loaded as CU)
      if (CU.banned) {
        _showBanScreen({ reason: CU.banReason || 'You have been banned.' });
        return;
      }
      // Check suspension from Supabase user data
      const suspData = CU.suspension || (CU.suspendedUntil ? { until: CU.suspendedUntil } : null);
      if (suspData) {
        const until = new Date(suspData.until);
        if (until > new Date()) {
          _showSuspendScreen(suspData);
          return;
        } else {
          // Suspension expired — clear it
          try { await FortizedSocial.adminUnsuspendUser(username); } catch(e) { console.warn('[Admin] Unsuspend failed:', e?.message); }
        }
      }
    } catch(e) { console.warn('Ban/suspension check skipped:', e); }
  }

  // Migrate: ensure all bastions have unique globalIds
  let _needsSave = false;
  for (const b of CU.bastions) {
    if (!b.globalId) {
      b.globalId = (b.owner || CU.username) + '_' + Date.now() + '_' + Math.random().toString(36).slice(2,5);
      _needsSave = true;
    }
  }
  if (_needsSave && navigator.onLine) { try { await FortizedSocial.saveUserObject(CU); } catch(e) { console.warn('[Init] User save failed:', e?.message); } }

  // Hide loading screen immediately once user data is ready
  const loader=document.getElementById('app-loading');
  if(loader)loader.style.display='none';
  if(window._loadingSafetyTimer)clearTimeout(window._loadingSafetyTimer);

  // Route to the correct view based on URL (or home as fallback)
  _ftzRouter._initialLoad = true;
  _ftzRouter.applyInitialRoute();
  _ftzRouter._initialLoad = false;

  // CRITICAL: Sync fresh user data from database after page load
  // This ensures changes (PFP, messages, friends) made in other sessions are visible
  if (navigator.onLine && typeof FortizedSocial !== 'undefined') {
    setTimeout(async () => {
      try {
        console.debug('[Init] Refreshing user data from database...');
        const refreshed = await refreshCU();
        console.debug('[Init] ✓ User data refreshed from database');
      } catch(e) {
        console.warn('[Init] Refresh failed but continuing:', e?.message);
      }
    }, 50);
  }

  // Trigger new onboarding for first-time users
  setTimeout(showOnboarding, 600);
  initFortizedUXResilience();

  try { saveCurrentToAccounts(); } catch(e) { console.warn('[init] saveCurrentToAccounts:', e); }
  try { updateUserbar(); } catch(e) { console.warn('[init] updateUserbar:', e); }
  try { renderRailBastions(); } catch(e) { console.warn('[init] renderRailBastions:', e); }
  try { if(typeof startVCListener==='function') startVCListener(CU.username); } catch(e) { console.warn('[init] startVCListener:', e); }
  // ── Initialize Socket.io for real-time events ──
  try {
    const _socketCbs = {
      initialStatus: CU.status || 'online',
      initialGameActivity: CU.gameActivity || null,
      onStatusChange: function(data) {
        if (!data || !data.username) return;
        // Cache the live status for use in renderMemberList fallback
        _liveStatusCache[data.username] = data.status;
        const color = typeof FtzStatus !== 'undefined' ? FtzStatus.color(data.status) : (data.status==='online'?'#3ecf6e':data.status==='away'?'#f59e0b':data.status==='dnd'?'#f87171':'rgba(255,255,255,.15)');
        const isOnline = data.status==='online'||data.status==='away'||data.status==='dnd';

        // ── SELF STATUS SYNC (cross-tab/device) ──
        if (data.username === CU.username) {
          // Only update if not a self-triggered change (avoid loops)
          if (CU.status !== data.status && data.status !== 'offline') {
            CU.status = data.status;
            try { updateUserbar(); } catch(e) { console.debug('[Userbar] Update failed:', e?.message); }
          }
        }

        // ── UPDATE ALL STATUS DOTS EVERYWHERE ──
        FtzStatus.updateDots(data.username, data.status);
        document.querySelectorAll('.profile-status-label[data-for="'+data.username+'"]').forEach(el => {
          el.textContent = typeof FtzStatus !== 'undefined' ? FtzStatus.publicLabel(data.status) : data.status;
        });
        // DM sidebar status text
        document.querySelectorAll('.dm-home-status-text[data-for="'+data.username+'"]').forEach(el => { el.textContent = typeof FtzStatus !== 'undefined' ? FtzStatus.publicLabel(data.status) : data.status; });
        // Friend Activity status text
        document.querySelectorAll('.act-status-text[data-for="'+data.username+'"]').forEach(el => {
          el.innerHTML = '<span style="color:'+color+';">'+(typeof FtzStatus!=='undefined'?FtzStatus.publicLabel(data.status):data.status)+'</span>';
        });

        // ── UPDATE MEMBER LIST ENTRIES ──
        document.querySelectorAll('.ml-entry[data-member="'+data.username+'"]').forEach(el => {
          el.dataset.status = data.status;
          // Update opacity for offline dimming
          el.style.opacity = isOnline ? '' : '.4';
          // Re-sort member list if in a bastion view
          if (el.closest('#member-list')) _debouncedMemberListResort();
          // Re-sort GC member panel if in a group chat view
          if (el.closest('#gc-member-panel')) _debouncedGCMemberResort();
        });

        // ── UPDATE GAME/SPOTIFY ACTIVITY ──
        const _actPrimary = data.activityState?.activities?.length
          ? data.activityState.activities.sort((a, b) => (b.priority || 2) - (a.priority || 2))[0]
          : null;
        const _actGame = _actPrimary || data.gameActivity;
        if (_actGame && _actGame.name) {
          const isSpotifyAct = !!_actGame._spotify;
          document.querySelectorAll('.ml-entry[data-member="'+data.username+'"] .ml-custom-status').forEach(el => {
            if (isSpotifyAct) {
              el.innerHTML = '<span style="opacity:.7;font-size:11px;color:#1DB954;">🎵 Listening to Spotify</span>';
            } else {
              el.innerHTML = '<span style="opacity:.6;font-size:11px;">🎮 Playing ' + escapeHTML(_actGame.name||'') + '</span>';
            }
          });
        } else if (!isOnline) {
          // Clear game activity when user goes offline
          document.querySelectorAll('.ml-entry[data-member="'+data.username+'"] .ml-custom-status').forEach(el => {
            el.innerHTML = '';
          });
        }

        // ── REFRESH OPEN PROFILE MODAL IF VISIBLE ──
        // When a user's activity changes while their profile is open, re-render the activity section
        const profileModal = document.getElementById('modal-user');
        if (profileModal && profileModal.style.display !== 'none') {
          const modalUser = document.querySelector('.up-username')?.textContent?.replace('@','') || null;
          if (modalUser === data.username) {
            // Update the activity content section of the open profile
            const actSection = document.querySelector('.up-right-section:has(.up-right-section-title:contains("Active Now"))');
            if (actSection && data.activityState?.activities?.length) {
              // Trigger profile refresh for real-time activity updates
              setTimeout(() => { viewUserProfile(data.username); }, 100);
            }
          }
        }

        // ── REFRESH MINI PROFILE PREVIEW IF VISIBLE ──
        const miniProfile = document.getElementById('mini-profile-preview');
        if (miniProfile) {
          const miniUser = miniProfile.getAttribute('aria-label')?.split(' ').pop() || null;
          if (miniUser === data.username && data.activityState?.activities?.length) {
            // Update mini profile activity section
            const actSection = miniProfile.querySelector('.mpp-section:has(.mpp-section-title:contains("Active Now"))');
            if (actSection) {
              setTimeout(() => { showMiniProfilePreview(data.username, miniProfile); }, 100);
            }
          }
        }

        // ── DM FRIENDS HOME: update row visibility for "online" filter ──
        if ((CU?.friends||[]).includes(data.username)) {
          const friendRow = document.querySelector('.dm-friend-row[data-user="'+data.username+'"]');
          if (friendRow && _dmFriendsFilter === 'online') {
            friendRow.style.display = isOnline ? '' : 'none';
          }
          // Update the online count in DM stats
          try {
            const sob = document.getElementById('dm-stat-online');
            if (sob) {
              const allRows = document.querySelectorAll('.dm-friend-row');
              let onCount = 0;
              allRows.forEach(r => { if (r.style.display !== 'none') onCount++; });
              sob.textContent = _dmFriendsFilter === 'online' ? onCount : sob.textContent;
            }
          } catch (e) { console.debug('[DM] online count update failed', e); }
          // Refresh Active Now sidebar when a friend's status changes
          _debouncedActiveNowRefresh();
        }
      },
      onActivityChange: function(data) {
        if (!data || !data.username) return;
        // Refresh open profile modal with new activity
        const profileModal = document.getElementById('modal-user');
        if (profileModal && profileModal.style.display !== 'none') {
          const modalUser = document.querySelector('.up-username')?.textContent?.replace('@','') || null;
          if (modalUser === data.username) {
            // Re-render the profile to show updated activities
            setTimeout(() => { viewUserProfile(data.username); }, 50);
          }
        }
        // Refresh mini profile preview if open
        const miniProfile = document.getElementById('mini-profile-preview');
        if (miniProfile) {
          const miniUser = miniProfile.getAttribute('aria-label')?.match(/(\S+)$/)?.[1] || null;
          if (miniUser === data.username) {
            // Refresh mini profile to show updated activities
            const anchor = miniProfile.previousElementSibling || document.querySelector('[onclick*="showMiniProfilePreview"]');
            if (anchor) {
              miniProfile.remove();
              showMiniProfilePreview(data.username, anchor);
            }
          }
        }
        // Update friend list activity display
        const friendActEl = document.getElementById('dm-home-activity-'+data.username);
        if (friendActEl && data.activityState?.activities?.length) {
          const primaryActivity = data.activityState.activities.sort((a, b) => (b.priority || 2) - (a.priority || 2))[0];
          if (primaryActivity) {
            const activityText = formatActivityDisplay(primaryActivity);
            friendActEl.textContent = activityText ? '🎮 ' + activityText : '';
          }
        }
        // Update pending friend request activity display
        const pendActEl = document.getElementById('dm-home-pact-'+data.username);
        if (pendActEl && data.activityState?.activities?.length) {
          const primaryActivity = data.activityState.activities.sort((a, b) => (b.priority || 2) - (a.priority || 2))[0];
          if (primaryActivity) {
            const activityText = formatActivityDisplay(primaryActivity);
            pendActEl.textContent = activityText ? '🎮 ' + activityText : '';
          }
        }
        // Update friend list sorted view
        const sortedActEl = document.getElementById('friend-sorted-act-'+data.username);
        if (sortedActEl && data.activityState?.activities?.length) {
          const primaryActivity = data.activityState.activities.sort((a, b) => (b.priority || 2) - (a.priority || 2))[0];
          if (primaryActivity) {
            const activityText = formatActivityDisplay(primaryActivity);
            sortedActEl.textContent = activityText ? '🎮 ' + activityText : '';
          }
        }
        // ── UPDATE MEMBER LIST CUSTOM STATUS (bastion + GC) ──
        document.querySelectorAll('.ml-entry[data-member="'+data.username+'"] .ml-custom-status').forEach(el => {
          if (data.activityState?.activities?.length) {
            const _primary = data.activityState.activities.sort((a, b) => (b.priority || 2) - (a.priority || 2))[0];
            if (_primary?._spotify) {
              el.innerHTML = '<span style="opacity:.7;font-size:11px;color:#1DB954;">🎵 Listening to Spotify</span>';
            } else if (_primary?.name) {
              el.innerHTML = '<span style="opacity:.6;font-size:11px;">🎮 Playing ' + escapeHTML(_primary.name) + '</span>';
            } else {
              el.innerHTML = '';
            }
          } else if (data.gameActivity?.name) {
            const _isSp = !!data.gameActivity._spotify;
            el.innerHTML = _isSp
              ? '<span style="opacity:.7;font-size:11px;color:#1DB954;">🎵 Listening to Spotify</span>'
              : '<span style="opacity:.6;font-size:11px;">🎮 Playing ' + escapeHTML(data.gameActivity.name) + '</span>';
          } else {
            el.innerHTML = '';
          }
        });
      },
      onMessage: function(room, msg) {
        if (!room || !msg) return;
        console.debug('[Socket.IO] Received message:new event', { room, msgId: msg.id, from: msg.from });
        // Handle DM messages
        if (room.startsWith('dm:') && curDM) {
          const expectedRoom = 'dm:' + [CU.username, curDM].sort().join('__');
          if (room === expectedRoom) {
            const msgsEl = document.getElementById('dm-msgs');
            if (msgsEl) {
              // Check if message already rendered (echo from own send)
              const mid = msg.id != null ? msg.id : (msg.from + msg.timestamp);
              if (!msgsEl.querySelector(`[data-msgid="${CSS.escape(mid)}"]`)) {
                console.debug('[onMessage] Adding DM message to display', { id: mid, from: msg.from });
                const lastRows = msgsEl.querySelectorAll('.msg-row');
                const lastAuthor = lastRows.length ? lastRows[lastRows.length - 1].dataset.from : null;
                appendMessage(msgsEl, msg, 'dm', lastAuthor);
                scrollBottom('dm-msgs');
                if (msg.from !== CU.username && !isUserBlocked(msg.from) && !isUserIgnored(msg.from)) playNotifSound('message');
              }
            }
          }
        }
        // Handle GC (Group Chat) messages
        if (room.startsWith('gc:') && curGC) {
          const expectedRoom = 'gc:' + curGC;
          if (room === expectedRoom) {
            const msgsEl = document.getElementById('gc-msgs');
            if (msgsEl) {
              const mid = msg.id != null ? msg.id : (msg.from + msg.timestamp);
              if (!msgsEl.querySelector(`[data-msgid="${CSS.escape(mid)}"]`)) {
                console.debug('[onMessage] Adding GC message to display', { id: mid, from: msg.from });
                const lastRows = msgsEl.querySelectorAll('.msg-row');
                const lastAuthor = lastRows.length ? lastRows[lastRows.length - 1].dataset.from : null;
                appendMessage(msgsEl, msg, 'gc', lastAuthor);
                scrollBottom('gc-msgs');
                if (msg.from !== CU.username && !isUserBlocked(msg.from) && !isUserIgnored(msg.from)) playNotifSound('message');
              }
            }
          }
        }
        // Handle Bastion channel messages
        if (room.startsWith('bastion:') && curBastion !== null && curChannel !== null) {
          const b = CU.bastions?.[curBastion];
          const ch = b?.channels?.[curChannel];
          if (b && ch) {
            const expectedRoom = 'bastion:' + (b.globalId || b.name) + ':' + ch.name;
            if (room === expectedRoom) {
              const msgsEl = document.getElementById('ch-msgs-' + curChannel);
              if (msgsEl) {
                const mid = msg.id != null ? msg.id : (msg.from + msg.timestamp);
                if (!msgsEl.querySelector(`[data-msgid="${CSS.escape(mid)}"]`)) {
                  console.debug('[onMessage] Adding bastion message to display', { id: mid, from: msg.from });
                  const lastRows = msgsEl.querySelectorAll('.msg-row');
                  const lastAuthor = lastRows.length ? lastRows[lastRows.length - 1].dataset.from : null;
                  appendMessage(msgsEl, msg, 'ch', lastAuthor);
                  scrollBottom('ch-msgs-' + curChannel);
                  if (msg.from !== CU.username && !isUserBlocked(msg.from) && !isUserIgnored(msg.from)) { const isMention = (msg.text||'').includes('@'+CU.username); playNotifSound(isMention ? 'mention' : 'message'); }
                }
              }
            }
          }
        }
      },
      onTyping: function(room, users) {
        if (!room || !users) return;
        const others = (users||[]).filter(u => u !== CU.username);
        // DM typing
        if (room.startsWith('dm:') && curDM) {
          const expectedRoom = 'dm:'+[CU.username, curDM].sort().join('__');
          if (room === expectedRoom) {
            const bar = document.getElementById('dm-typing-bar');
            const txt = document.getElementById('dm-typing-text');
            if (bar && txt) {
              if (others.length > 0) {
                txt.innerHTML = '<strong style="color:rgba(255,255,255,.5);">'+escapeHTML(others[0])+'</strong> is writing\u2026';
                bar.style.opacity = '1';
              } else { bar.style.opacity = '0'; }
            }
          }
        }
        // GC typing
        if (room.startsWith('gc:') && curGC) {
          if (room === 'gc:'+curGC) {
            const bar = document.getElementById('gc-typing-bar');
            const txt = document.getElementById('gc-typing-text');
            if (bar && txt) {
              if (others.length > 0) {
                txt.innerHTML = _formatTypingText(others);
                bar.style.opacity = '1';
              } else { bar.style.opacity = '0'; }
            }
          }
        }
        // Bastion channel typing
        if (room.startsWith('bastion:') && curBastion !== null && curChannel !== null) {
          const b = CU.bastions?.[curBastion]; const ch = b?.channels?.[curChannel];
          if (b && ch) {
            const expectedRoom = 'bastion:'+(b.globalId||b.name)+':'+ch.name;
            if (room === expectedRoom) {
              const bar = document.getElementById('ch-typing-bar');
              const txt = document.getElementById('ch-typing-text');
              if (bar && txt) {
                if (others.length > 0) {
                  txt.innerHTML = _formatTypingText(others);
                  bar.style.opacity = '1';
                } else { bar.style.opacity = '0'; }
              }
            }
          }
        }
      },
      onMessageEdited: function(data) {
        if (!data || !data.messageId) return;
        const row = document.querySelector('[data-msgid="'+CSS.escape(data.messageId)+'"]');
        if (!row) return;
        // Skip if we're the editor (already updated locally in saveEdit)
        if (data.editedBy === CU.username) return;
        const textEl = row.querySelector('.msg-text');
        if (textEl && data.newText) {
          row.dataset.text = data.newText;
          textEl.innerHTML = parseMD(escapeHTML(data.newText)) + '<span class="msg-edited">(edited)</span>';
        }
      },
      onMessageDeleted: function(data) {
        if (!data || !data.messageId) return;
        // Skip if we're the deleter (already removed locally in deleteMsg)
        if (data.deletedBy === CU.username) return;
        const row = document.querySelector('[data-msgid="'+CSS.escape(data.messageId)+'"]');
        if (row) {
          row.style.transition = 'opacity .2s ease, max-height .25s ease';
          row.style.opacity = '0';
          row.style.maxHeight = row.offsetHeight + 'px';
          row.style.overflow = 'hidden';
          setTimeout(() => { row.style.maxHeight = '0'; }, 80);
          setTimeout(() => row.remove(), 300);
        }
      },
      onReaction: function(data) {
        // Real-time reaction updates via Socket.io
        if (!data || !data.messageId || !data.emoji) return;
        if (data.username === CU.username) return; // already updated locally
        // Refresh reaction UI from Supabase (NOT Firebase)
        const row = document.querySelector('[data-msgid="'+CSS.escape(data.messageId)+'"]');
        if (!row) return;
        const ctx = row.closest('#dm-msgs') ? 'dm' : row.closest('#gc-msgs') ? 'gc' : 'ch';

        // Fetch reactions from Supabase based on context
        let fetchPromise = null;
        if (ctx === 'dm' && curDM) {
          const dmKey = [CU.username, curDM].sort().join('__');
          fetchPromise = FortizedSocial.sb.from('dms').select('reactions').eq('dm_key', dmKey).eq('id', data.messageId).maybeSingle();
        } else if (ctx === 'gc' && curGC) {
          fetchPromise = FortizedSocial.sb.from('group_chat_messages').select('reactions').eq('gc_id', curGC).eq('id', data.messageId).maybeSingle();
        } else if (ctx === 'ch' && curBastion !== null) {
          const b = CU.bastions?.[curBastion]; const ch = b?.channels?.[curChannel];
          if (b && ch) fetchPromise = FortizedSocial.sb.from('bastion_msgs').select('reactions').eq('bastion_id', b.globalId||b.name).eq('channel_id', ch.name).eq('id', data.messageId).maybeSingle();
        }
        if (fetchPromise) {
          fetchPromise.then(({data: msgData}) => {
            const reactions = msgData?.reactions || {};
            Object.entries(reactions).forEach(([em, users]) => {
              updateReactionUI(data.messageId, em, Array.isArray(users) ? users : [], ctx);
            });
            // Remove pills for emojis no longer present
            const row2 = document.querySelector('[data-msgid="'+CSS.escape(data.messageId)+'"]');
            if (row2) row2.querySelectorAll('.r-pill').forEach(p => {
              const em = p.getAttribute('data-emoji');
              if (em && !reactions[em]) p.remove();
            });
          }).catch(() => {});
        }
      },
      onPollUpdate: function(data) {
        // Re-fetch polls if viewing the same bastion poll channel
        if (typeof curBastion !== 'undefined' && curBastion !== null) {
          const b = CU?.bastions?.[curBastion];
          if (b && (b.globalId||b.name) === data.bastionId) {
            const ch = b.channels?.[curChannel];
            if (ch && ch.type === 'poll' && ch.name === data.channelName) {
              openPollChannel(curChannel);
            }
          }
        }
      },
      onNewNotification: function(notif) {
        if (!notif || !notif.id) return;
        // Add notification to CU's notifications array if not already there
        if (!CU.notifications) CU.notifications = [];
        const exists = CU.notifications.some(n => n.id === notif.id);
        if (!exists) {
          CU.notifications.push(notif);
          saveLocal();
        }
        // Update notification badge
        updateNotificationBar();
        // Play notification sound if enabled
        if (typeof FortizedSocial !== 'undefined' && typeof FortizedSocial.playNotificationSound === 'function') {
          FortizedSocial.playNotificationSound();
        }
      },
      onAnnouncementNew: function(data) {
        // Trigger the announcement banner
        if (data.text) {
          const existing = document.getElementById('sys-announce-bar');
          if (existing) existing.remove();
          _dismissedAnnouncement = null;
          _listenAnnouncement();
        }
      },
      onAnnouncementCleared: function() {
        const bar = document.getElementById('sys-announce-bar');
        if (bar) { bar.style.opacity='0'; bar.style.transform='translateY(-100%)'; setTimeout(()=>bar.remove(),300); }
      },
      onProfileUpdate: function(data) {
        if (!data || !data.username) return;

        // ── INVALIDATE CACHE for the updated user so others get fresh data ──
        try { FortizedSocial.invalidateUserCache(data.username); } catch(e) {}

        // ── SELF PROFILE SYNC (cross-tab/device) ──
        if (data.username === CU.username) {
          if (data.pfp) CU.pfp = data.pfp;
          if (data.pfpCrop !== undefined) CU.pfpCrop = data.pfpCrop;
          if (data.displayName) CU.displayName = data.displayName;
          saveLocal();
          try { updateUserbar(); } catch(e) { console.debug('[Userbar] Update failed:', e?.message); }
        }

        // ── CACHE PFP CROP DATA ──
        if (data.pfpCrop !== undefined) {
          if (data.pfpCrop) _pfpCropCache[data.username] = data.pfpCrop;
          else delete _pfpCropCache[data.username];
        }

        // ── UPDATE PFP EVERYWHERE ──
        if (data.pfp) {
          _pfpCache[data.username] = data.pfp;
          const _upCrop = data.pfpCrop || _pfpCropCache[data.username] || null;
          // Bastion member list
          document.querySelectorAll('.ml-entry[data-member="'+data.username+'"] .ml-av-wrap').forEach(avWrap => {
            const _dn = data.displayName || data.username;
            avWrap.querySelector('img:not(.profile-status-dot):not(.profile-decoration-overlay-ml)')?.remove();
            avWrap.querySelector('div[style*="overflow:hidden"]')?.remove();
            const dot = avWrap.querySelector('.profile-status-dot');
            const dotHTML = dot ? dot.outerHTML : '';
            if (dot) dot.remove();
            avWrap.insertAdjacentHTML('afterbegin', buildAvatarHTML(data.pfp, _dn, 34, _upCrop) + dotHTML);
          });
          // GC member list
          document.querySelectorAll('.ml-entry[data-member="'+data.username+'"] .gc-ml-av').forEach(avWrap => {
            const _dn = data.displayName || data.username;
            const dot = avWrap.querySelector('.profile-status-dot');
            const dotHTML = dot ? dot.outerHTML : '';
            avWrap.innerHTML = buildAvatarHTML(data.pfp, _dn, 30, _upCrop) + dotHTML;
          });
          // Generic pfp-for markers
          document.querySelectorAll('img[data-pfp-for="'+data.username+'"]').forEach(img => { img.src = data.pfp; });
          // DM sidebar avatars
          const dmAv = document.getElementById('dm-av-'+data.username);
          if (dmAv) dmAv.innerHTML = buildAvatarHTML(data.pfp, data.displayName||data.username, 34, _upCrop);
          // DM friends home avatars
          const dmHomeAv = document.getElementById('dm-home-av-'+data.username);
          if (dmHomeAv) dmHomeAv.innerHTML = buildAvatarHTML(data.pfp, data.displayName||data.username, 42, _upCrop);
          // Message avatars in active chat (if visible)
          document.querySelectorAll('.msg-av-inner[data-av-for="'+data.username+'"] img').forEach(img => { img.src = data.pfp; });
        }

        // ── UPDATE DISPLAY NAME EVERYWHERE ──
        if (data.displayName) {
          // Bastion + GC member list names
          document.querySelectorAll('.ml-entry[data-member="'+data.username+'"] .ml-name').forEach(el => { el.textContent = data.displayName; });
          // DM sidebar display name
          const dmDn = document.getElementById('dm-dn-'+data.username);
          if (dmDn) dmDn.textContent = data.displayName;
          // DM friends home display name
          const dmHomeDn = document.getElementById('dm-home-dn-'+data.username);
          if (dmHomeDn) dmHomeDn.textContent = data.displayName;
        }
        // ── APPLY DISPLAY NAME STYLES (font/effect/color) EVERYWHERE ──
        if (data.displayFont || data.displayEffect || data.displayColor) {
          const _styleEls = [
            ...document.querySelectorAll('.ml-entry[data-member="'+data.username+'"] .ml-name'),
            ...document.querySelectorAll('.msg-author[data-author="'+data.username+'"]')
          ];
          const _dmDnStyle = document.getElementById('dm-dn-'+data.username);
          if (_dmDnStyle) _styleEls.push(_dmDnStyle);
          _styleEls.forEach(el => {
            if (data.displayFont && data.displayFont !== 'default') {
              el.style.fontFamily = _getDisplayFontCSS(data.displayFont);
            }
            if (data.displayColor && data.displayColor !== '#fff') {
              const _eCss = _getDisplayEffectCSS(data.displayEffect || 'solid', data.displayColor);
              el.style.cssText += _eCss;
            }
          });
        }
      },
      onBastionUpdate: function(data) {
        // Re-sync bastion data when roles or member roles change
        if (!CU?.bastions) return;
        CU.bastions.forEach((b, idx) => {
          if ((b.globalId||b.name) === data.bastionId) {
            FortizedSocial.getGlobalBastion(data.bastionId).then(fresh => {
              if (!fresh) return;
              const syncFields = ['roles','memberRoles','channels','name','members','memberCount'];
              syncFields.forEach(f => { if (fresh[f] !== undefined) b[f] = fresh[f]; });
              saveLocal();
              if (curBastion === idx) {
                renderRailBastions();
                if (typeof renderMemberList === 'function') renderMemberList();
              }
            }).catch(()=>{});
          }
        });
      },
      onDMIndexChange: function() {
        // Re-render DM sidebar when DM index changes (new conversation, reordered partners)
        const sb = document.getElementById('sidebar-scroll');
        if (sb) renderDMSidebar(sb);
      },
      onFriendRequest: function(data) {
        if (!data || !data.from) return;
        if (!CU.friendRequestsReceived) CU.friendRequestsReceived = [];
        if (!CU.friendRequestsReceived.includes(data.from)) {
          CU.friendRequestsReceived.push(data.from);
          saveLocal();
          updateNotificationBar();
        }
      },
      onFriendAccepted: function(data) {
        if (!data || !data.username) return;
        if (!CU.friends) CU.friends = [];
        if (!CU.friends.includes(data.username)) {
          CU.friends.push(data.username);
          if (CU.friendRequestsSent) {
            const idx = CU.friendRequestsSent.indexOf(data.username);
            if (idx >= 0) CU.friendRequestsSent.splice(idx, 1);
          }
          saveLocal();
          updateNotificationBar();
        }
      },
      onFriendRequestsUpdate: function(data) {
        if (!data) return;
        console.debug('[onFriendRequestsUpdate] Friend requests changed:', { sent: data.sent?.length || 0, received: data.received?.length || 0 });
        // Update the user object with fresh friend request data
        CU.friendRequestsSent = data.sent || [];
        CU.friendRequestsReceived = data.received || [];
        saveLocal();
        // Refresh friend request UI
        try {
          refreshFriendRequests();
          updateNotificationBar();
        } catch (e) {
          console.warn('[onFriendRequestsUpdate] UI refresh failed:', e?.message);
        }
      },
      onVoiceRoomUpdate: function(data) {
        if (!data) return;
        console.debug('[onVoiceRoomUpdate] Voice room changed:', { bastionId: data.bastionId, channelName: data.channelName, participants: data.participants?.length || 0 });
        // Update voice room participant list
        const voicePanel = document.querySelector(`[data-bastion-id="${CSS.escape(data.bastionId)}"][data-channel-name="${CSS.escape(data.channelName)}"]`);
        if (voicePanel) {
          // Update participants list if visible
          const participantsList = voicePanel.querySelector('.vr-participants-list');
          if (participantsList) {
            participantsList.innerHTML = '';
            (data.participants || []).forEach(username => {
              const pEl = document.createElement('div');
              pEl.className = 'vr-participant';
              pEl.textContent = username;
              participantsList.appendChild(pEl);
            });
          }
        }
        // Trigger room list refresh if it exists
        try {
          const roomList = document.getElementById('voice-rooms-list');
          if (roomList) {
            // Re-render voice rooms list
            loadVoiceRooms();
          }
        } catch (e) {
          console.warn('[onVoiceRoomUpdate] Voice rooms refresh failed:', e?.message);
        }
      },
    };
    window._ftzSocketCallbacks = _socketCbs;
    FortizedSocial.initSocket(CU.username, _socketCbs);
    // Start Supabase real-time polling with callbacks for message delivery
    FortizedSocial.startPolling(CU.username, _socketCbs);
  } catch(e) { console.warn('[init] Socket.io/polling init:', e); }
  // Show offline banner immediately if we loaded from cache while offline
  if (!navigator.onLine) {
    const _ob = document.getElementById('offline-banner');
    if (_ob) _ob.classList.add('visible');
  }
  // Auto-show/hide offline banner on connectivity change
  window.addEventListener('offline', () => {
    const _ob = document.getElementById('offline-banner');
    if (_ob) _ob.classList.add('visible');
  });
  window.addEventListener('online', () => {
    const _ob = document.getElementById('offline-banner');
    if (_ob) _ob.classList.remove('visible');
    toast('Back online!', 'success');
  });
  // Start listeners immediately (not delayed) for instant cross-device sync
  initCrossDeviceSync();
  setTimeout(initNotifToasts, 100);
  // Sync blocked list from Firebase (skip when offline)
  if(navigator.onLine) setTimeout(async()=>{try{const snap=await firebase.database().ref('users/'+CU.username+'/blockedUsers').get();if(snap.exists())localStorage.setItem('ftz_blocked',JSON.stringify(snap.val()));}catch(e){console.warn('[Sync] Blocked list sync failed:', e?.message);}},500);

  setTimeout(_ensureJoysterAccount, 4000);
  setTimeout(_ensureFortizedAccount, 4500);
  // Sync ignore list from Firebase
  setTimeout(_syncIgnoreListFromFirebase, 2000);
  // NSFW scanning disabled — no model preload needed
  updateNotifBadge().catch(()=>{});

  // Sync staff data from Supabase BEFORE checking staff access for sidebar button
  if (navigator.onLine) {
    try {
      const _staffData = await Promise.race([
        FortizedSocial.adminGetStaff(),
        new Promise((_,r)=>setTimeout(()=>r(new Error('timeout')),4000))
      ]);
      if (_staffData && (_staffData.admins || _staffData.moderators)) {
        localStorage.setItem('ftz_staff', JSON.stringify(_staffData));
      } else if (!localStorage.getItem('ftz_staff')) {
        localStorage.setItem('ftz_staff', JSON.stringify({ admins: [], moderators: [] }));
      }
    } catch(e) { console.warn('Staff sync at init failed:', e); }
  }

  // Staff console button (visible to superadmin, admin, moderator)
  if (hasStaffAccess()){
    const rail=document.getElementById('rail');
    if(rail&&!document.getElementById('admin-rail-btn')){
      const role = getStaffRole(CU.username);
      const roleIcon = role === 'superadmin' ? '<img src="/fortized badges/superadmin.png" style="width:16px;height:16px;object-fit:contain;vertical-align:middle;">' : role === 'admin' ? '<img src="/fortized badges/admin.png" style="width:16px;height:16px;object-fit:contain;vertical-align:middle;">' : '<img src="/fortized badges/moderator.png" style="width:16px;height:16px;object-fit:contain;vertical-align:middle;">';
      const roleLabel = role === 'superadmin' ? 'Super Admin' : role === 'admin' ? 'Admin' : 'Moderator';
      const btn=document.createElement('div');
      btn.id='admin-rail-btn';btn.className='rail-btn';
      btn.innerHTML=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg><span>Staff Console</span>`;
      btn.dataset.tip=roleLabel + ' Panel';
      btn.style.cssText='border:1px solid rgba(248,113,113,.2);color:rgba(248,113,113,.7);margin-top:6px;background:rgba(248,113,113,.04);';
      btn.onclick=tryOpenAdmin;
      const sep = document.createElement('div');
      sep.className='rail-sep';sep.style.margin='8px 12px';
      const bastionSection = rail.querySelector('#rail-bastions')?.parentElement || rail;
      // Insert before the Create Bastion button area
      const createBtn = rail.querySelector('[onclick*="modal-create-bastion"]');
      if(createBtn){rail.insertBefore(sep,createBtn);rail.insertBefore(btn,createBtn);}
      else rail.appendChild(btn);
    }
  }

  // Onboarding will be triggered if user is new

  // Check invite link
  try{checkInviteLink();}catch(e){console.warn('[Init] Invite link check:',e?.message);}
  try{checkTrialLink();}catch(e){console.warn('[Init] Trial link check:',e?.message);}
  try{checkPersonalInviteLink();}catch(e){console.warn('[Init] Personal invite check:',e?.message);}
  try{checkGiftLinks();}catch(e){console.warn('[Init] Gift links check:',e?.message);}
  // Show personal invite link if already generated
  try { applyRadianceFont(); } catch(e) { console.warn('[init] applyRadianceFont:', e); }
  try { trackRadianceTime(); } catch(e) { console.warn('[init] trackRadianceTime:', e); }
  // Post-init setup: account switcher, periodic updates
  setTimeout(_postInitSetup, 500);
  // Check & listen for maintenance mode
  try { checkMaintenanceMode(); } catch(e) { console.warn('[init] checkMaintenanceMode:', e); }
  try { _listenGlobalSettingsConsolidated(); } catch(e) { console.warn('[init] _listenGlobalSettingsConsolidated:', e); }
  // Listen for force-refresh and session-clear signals from admin
  try { _listenForceRefresh(); } catch(e) { console.warn('[init] _listenForceRefresh:', e); }
  try { _listenClearSessions(); } catch(e) { console.warn('[init] _listenClearSessions:', e); }
  // Poll for ban/suspension/warning enforcement via Supabase (every 15s)
  let _wasBanned = CU.banned || false;
  let _wasSuspended = !!(CU.suspension || CU.suspendedUntil);
  try {
    setInterval(async () => {
      try {
        const u = await FortizedSocial.getUserByName(CU.username, { columns: 'username,banned,ban_reason,suspension,suspended_until,active_warning,raw' });
        if (!u) return;
        // Ban check
        if (u.banned) { _wasBanned = true; _showBanScreen({ reason: u.banReason || 'You have been banned.' }); }
        else if (_wasBanned) { location.reload(); }
        // Suspension check
        const suspData = u.suspension || (u.suspendedUntil ? { until: u.suspendedUntil } : null);
        if (suspData && suspData.until && new Date(suspData.until) > new Date()) { _wasSuspended = true; _showSuspendScreen(suspData); }
        else if (_wasSuspended && !suspData) { location.reload(); }
        // Warning check
        if (u.activeWarning) {
          const w = u.activeWarning;
          _showWarningOverlay(w.reason || 'Violation of Terms of Use', w.issuedBy, w.contentData || null);
          FortizedSocial.adminClearWarning(CU.username).catch(()=>{});
        }
        // Force logout check
        _checkForceLogout(u);
      } catch (e) { console.debug('[Init] enforcement poll failed', e); }
    }, 120000); // Reduced to 2min (was 15s) — egress emergency
  } catch(e) { console.warn('[init] enforcement poller:', e); }
  if(CU.personalInviteCode){const d=document.getElementById('invite-link-display');if(d){const l=location.origin+location.pathname+'?ref='+CU.personalInviteCode;d.textContent=l;d.style.cursor='pointer';d.onclick=()=>navigator.clipboard.writeText(l).then(()=>toast('Copied!','success'));}}
  // Start report polling for all staff
  try { if(hasStaffAccess())setTimeout(startReportPolling,2000); } catch(e) { console.warn('[init] reportPolling:', e); }
  // Listen for real-time staff changes so sidebar updates dynamically
  try { _listenStaffChanges(); } catch(e) { console.warn('[init] _listenStaffChanges:', e); }
  // Listen for real-time bastion updates from other members
  setTimeout(_listenBastionUpdates, 1500);
  setTimeout(_listenDmUpdates, 2000);
  setTimeout(_listenGroupDmUpdates, 2500);

  // Event listeners
  document.addEventListener('contextmenu',e=>{e.preventDefault();handleContextMenu(e);});
  document.addEventListener('click',e=>{
    const menu=document.getElementById('ctx-menu');
    if(menu&&!menu.contains(e.target))_closeCtxMenu();
    const np=document.getElementById('notif-panel');
    if(notifPanelOpen&&np&&!np.contains(e.target)&&e.target.id!=='rb-notifs'&&!e.target.closest('#tb-notif-btn')){notifPanelOpen=false;np.classList.remove('open');}
    const ep=document.getElementById('emoji-picker');
    if(ep&&ep.classList.contains('show')&&!ep.contains(e.target)){
      const clickedEmojiBtn = e.target.closest('[id^="emoji-btn-"]') || e.target.closest('.cit-btn');
      if(!clickedEmojiBtn) ep.classList.remove('show');
    }
  });
  document.querySelectorAll('.modal-overlay').forEach(overlay=>{
    overlay.addEventListener('click',e=>{if(e.target===overlay)overlay.classList.remove('open');});
  });
  document.addEventListener('keydown',e=>{if(e.key==='Escape')_closeCtxMenu();if(e.ctrlKey&&e.shiftKey&&e.key==='A')tryOpenAdmin();});

  // Background refresh
  setTimeout(async()=>{
    try{
      const fresh=await Promise.race([
        FortizedSocial.getUserByName(username),
        new Promise((_,r)=>setTimeout(()=>r(new Error('t')),6000))
      ]);
      if(fresh?.username){
        // Preserve radiance data if the DB returned null but local has valid values
        // (migration safety — ensures we never lose radiance on refresh)
        if(!fresh.radianceUntil && CU.radianceUntil && new Date(CU.radianceUntil)>new Date()) fresh.radianceUntil=CU.radianceUntil;
        if(!fresh.radiancePlus && CU.radiancePlus && new Date(CU.radiancePlus)>new Date()) fresh.radiancePlus=CU.radiancePlus;
        // Preserve quest/onyx data — local is source of truth since saves may be in-flight
        if (CU.onyx !== undefined && (fresh.onyx === undefined || fresh.onyx < CU.onyx)) fresh.onyx = CU.onyx;
        if (CU.lastDailyReward && !fresh.lastDailyReward) fresh.lastDailyReward = CU.lastDailyReward;
        if (CU.lastDaily && !fresh.lastDaily) fresh.lastDaily = CU.lastDaily;
        if (CU.dailyStreak && !fresh.dailyStreak) fresh.dailyStreak = CU.dailyStreak;
        if (CU.questsDailyLog) fresh.questsDailyLog = { ...(fresh.questsDailyLog||{}), ...CU.questsDailyLog };
        if (CU.completedQuests?.length) { const m = new Set([...(fresh.completedQuests||[]), ...CU.completedQuests]); fresh.completedQuests = [...m]; }
        if (CU.questsRewarded?.length) { const m = new Set([...(fresh.questsRewarded||[]), ...CU.questsRewarded]); fresh.questsRewarded = [...m]; }
        // Preserve shop inventory — local is source of truth since saves may be in-flight
        if (CU.unlockedAppearances?.length) { const m = new Set([...(fresh.unlockedAppearances||[]), ...CU.unlockedAppearances]); fresh.unlockedAppearances = [...m]; }
        if (CU.ownedDecorations?.length) { const m = new Set([...(fresh.ownedDecorations||[]), ...CU.ownedDecorations]); fresh.ownedDecorations = [...m]; }
        if (CU.activeDecoration && !fresh.activeDecoration) fresh.activeDecoration = CU.activeDecoration;
        if (CU.onyxBadge && !fresh.onyxBadge) { fresh.onyxBadge = true; fresh.onyxBadgeSpent = Math.max(fresh.onyxBadgeSpent||0, CU.onyxBadgeSpent||0); }
        if (CU.displayFont && !fresh.displayFont) fresh.displayFont = CU.displayFont;
        if (CU.displayEffect && !fresh.displayEffect) fresh.displayEffect = CU.displayEffect;
        if (CU.displayColor && !fresh.displayColor) fresh.displayColor = CU.displayColor;
        if (CU.profileTheme && !fresh.profileTheme) fresh.profileTheme = CU.profileTheme;
      if (CU.wantToPlay?.length && !fresh.wantToPlay?.length) fresh.wantToPlay = CU.wantToPlay;
      // Preserve profile widgets
      if (CU.profileWidgets?.length && !fresh.profileWidgets?.length) fresh.profileWidgets = CU.profileWidgets;
      // Preserve Spotify connection data
      if (CU.spotifyConnected && !fresh.spotifyConnected) fresh.spotifyConnected = CU.spotifyConnected;
      if (CU.spotifyToken && !fresh.spotifyToken) fresh.spotifyToken = CU.spotifyToken;
      if (CU.spotifyRefreshToken && !fresh.spotifyRefreshToken) fresh.spotifyRefreshToken = CU.spotifyRefreshToken;
      if (CU.spotifyTokenExpiry && !fresh.spotifyTokenExpiry) fresh.spotifyTokenExpiry = CU.spotifyTokenExpiry;
      if (CU.spotifyNowPlaying && !fresh.spotifyNowPlaying) fresh.spotifyNowPlaying = CU.spotifyNowPlaying;
      // Preserve game collection
      if (CU.gameCollection?.length && (!fresh.gameCollection?.length || fresh.gameCollection.length < CU.gameCollection.length)) fresh.gameCollection = CU.gameCollection;
        CU=fresh;saveLocal();updateUserbar();renderRailBastions();updateOnyxDisplay();
        // Re-persist radiance/quest data to DB if it was preserved from local cache
        if(CU.radianceUntil||CU.radiancePlus||CU.completedQuests?.length) saveUser().catch(e => console.warn('[Save] Failed:', e?.message));
      }
    }catch{}
  },1000);

  setInterval(async()=>{try{await updateNotifBadge();}catch{}},120000); // Reduced to 2min (was 30s) — egress emergency
  // Real-time notification listener
  try {
    // Notification listeners are now handled via Socket.IO in initCrossDeviceSync()
  } catch(e) { console.warn('[Notif] Listener setup failed:', e?.message); }
  try { initIdleDetection(); } catch(e) { console.warn('[init] initIdleDetection:', e); }
  // Start Spotify polling if already connected
  try { if (CU?.spotifyToken) _pollSpotifyNowPlaying(); } catch(e) { console.warn('[Spotify] Init poll failed:', e?.message); }
  // Auto-detect game activity in Tauri desktop app (Discord-style)
  try { _startAutoActivityDetection(); } catch(e) { console.warn('[init] autoActivityDetection:', e); }
  try { restoreCustomStatusTimer(); } catch(e) { console.warn('[init] restoreCustomStatusTimer:', e); }
  // Discord-style: restore the user's chosen status from last session
  try { FtzStatus.restoreManualStatus(); } catch(e) { console.warn('[init] restoreManualStatus:', e); }
  try { updateUserbar(); } catch(e) { console.warn('[init] updateUserbar2:', e); }
  initDragDrop();
  clearTimeout(_st);
  if(window._loadingSafetyTimer)clearTimeout(window._loadingSafetyTimer);
  }catch(e){
    console.error('[Fortized] Init error:',e);
    if(_sl)_sl.style.display='none';
    clearTimeout(_st);
    if(window._loadingSafetyTimer)clearTimeout(window._loadingSafetyTimer);
    // Fallback: ensure home view is visible even if init partially failed
    try { showView('home'); } catch (e) { console.debug('[Nav] showView failed', e); }
  }
})();






