async function saveOverviewConfig() {
  const b = CU.bastions?.[curBastion];
  if (!b) return;
  b.overview = {
    welcomeText: document.getElementById('ov-ed-welcome')?.value?.trim() || '',
    accentColor: document.getElementById('ov-ed-accent')?.value || '',
    bannerHeight: document.getElementById('ov-ed-banner-height')?.value || 'default',
    layoutStyle: document.getElementById('ov-ed-layout')?.value || 'centered',
    ctaLabel: document.getElementById('ov-ed-cta-label')?.value?.trim() || '',
    ctaUrl: document.getElementById('ov-ed-cta-url')?.value?.trim() || '',
    footerText: document.getElementById('ov-ed-footer')?.value?.trim() || '',
    showStats: document.getElementById('ov-ed-stats')?.checked ?? true,
    showRooms: document.getElementById('ov-ed-rooms')?.checked ?? true,
    showAnnouncements: document.getElementById('ov-ed-announcements')?.checked ?? true,
    showForums: document.getElementById('ov-ed-forums')?.checked ?? true,
    showRoles: document.getElementById('ov-ed-roles')?.checked ?? true,
    showInvite: document.getElementById('ov-ed-invite')?.checked ?? true,
  };
  document.getElementById('modal-ov-editor')?.remove();
  try {
    await saveUser();
    if (b.globalId) {
      await firebase.database().ref('bastions/' + b.globalId + '/overview').set(b.overview);
      await firebase.database().ref('globalBastions/' + b.globalId + '/overview').set(b.overview);
    }
    toast('Overview updated!', 'success');
  } catch(e) { toast('Failed to save: ' + e.message, 'error'); }
  renderOverviewRoom();
}

