async function saveAutoMod() {
  const ml = parseInt(document.getElementById('mention-limit')?.value)||10;
  const btn=document.querySelector('[onclick*="saveAutoMod"]');
  if(btn){btn.classList.add('btn-loading');btn.disabled=true;}
  CU.bastions[curBastion].automod.mentionLimit = ml;
  await saveUser(); _syncBastionToGlobal(curBastion);
  if(btn){btn.classList.remove('btn-loading');btn.disabled=false;}
  toast('AutoMod saved!', 'success');
}
async function generateInvite() {
  const b = CU.bastions[curBastion];
  const _bPrefix = (b.name||'b').replace(/[^a-zA-Z0-9]/g,'').slice(0,4).toLowerCase();
  const code = _bPrefix + '-' + CU.username.slice(0,4) + '-' + Date.now().toString(36).toUpperCase() + '-' + Math.random().toString(36).slice(2,6).toUpperCase();
  const expiryHours=parseInt(document.getElementById('invite-expiry')?.value)||0;
  const maxUses=parseInt(document.getElementById('invite-max-uses')?.value)||0;
  const invite = {code, uses:0, created:new Date().toISOString(), createdBy: CU.username};
  if(expiryHours)invite.expires=new Date(Date.now()+expiryHours*3600000).toISOString();
  if(maxUses)invite.maxUses=maxUses;
  b.invites = [...(b.invites||[]), invite];
  // Ensure bastion has a globalId before generating invite links
  if (!b.globalId) {
    b.globalId = CU.username + '_' + Date.now();
    await FortizedSocial.addBastionMember(b.globalId, CU.username);
  }
  const bid = b.globalId;
  await saveUser();
  try {
    // Sync invites to globalBastions
    await firebase.database().ref('globalBastions/'+bid+'/invites').set(b.invites);
    // Also save to dedicated invites collection for faster lookup
    await FortizedSocial.saveInvite(code, {code, bastionId: bid, bastionName: b.name, createdBy: CU.username, created: invite.created, expires: invite.expires||null, maxUses: invite.maxUses||0, uses:0});
  } catch(e) { console.warn('[Invite] Sync failed:', e?.message); }
  // Sync full bastion data to global
  _syncBastionToGlobal(curBastion);
  renderBSettingsMain('invites');
  toast('🔗 Invite created!', 'success');
  showFeedbackToast('creating an invite', 'invite_create');
  navigator.clipboard.writeText('https://fortized.com/app?invite='+code).then(()=>toast('Copied to clipboard!','info')).catch(()=>{});
}
function copyInvite(code) {
  navigator.clipboard.writeText('https://fortized.com/app?invite='+code).then(()=>toast('🔗 Invite link copied!','success')).catch(()=>toast('Copy failed','error'));
  // Track invite daily quest
  const today = new Date().toDateString();
  if (CU && (!CU.questsDailyLog || CU.questsDailyLog.invite !== today)) {
    CU.questsDailyLog = CU.questsDailyLog || {};
    CU.questsDailyLog.invite = today;
    CU.onyx = (CU.onyx||0) + 9;
    saveUser(true);
    toast('+9 Onyx — Invite quest complete!','success');
  }
}
async function revokeInvite(i) {
  CU.bastions[curBastion].invites.splice(i,1);
  await saveUser(); renderBSettingsMain('invites'); toast('Invite revoked','info');
}
async function loadBastionMembersList() {
  const b = CU.bastions[curBastion];
  const el = document.getElementById('bsettings-members-list'); if(!el) return;
  el.innerHTML = '<div style="color:var(--muted);font-size:13px;">Loading…</div>';
  let members=[];
  try { members = await FortizedSocial.getBastionMembers(b.globalId||b.name)||[]; } catch(e) { console.warn('[Bastion] Members list load:', e?.message); }
  if(!members.length) members=[b.owner];
  const roles = b.roles||[];
  const memberRoles = b.memberRoles||{};
  const isOwner = b.owner===CU.username;
  el.innerHTML = members.map(u=>{
    const uRoleIds = memberRoles[u]||[];
    const uRoles = roles.filter(r=>uRoleIds.includes(r.id));
    const roleTags = uRoles.map(r=>`<span style="font-size:10px;font-weight:700;padding:2px 7px;border-radius:var(--radius-pill);border:1px solid ${r.color}33;color:${r.color};background:${r.color}15;">${escapeHTML(r.name)}</span>`).join(' ');
    const repScore = getReputation(b.globalId||b.name, u);
    const repTier = getRepTier(repScore);
    const repBadge = repScore > 0 ? `<span style="font-size:9px;font-weight:700;padding:2px 6px;border-radius:var(--radius-pill);border:1px solid ${repTier.color}33;color:${repTier.color};background:${repTier.color}15;">${repTier.label}</span>` : '';
    return `<div style="display:flex;align-items:center;gap:10px;padding:10px 14px;background:var(--panel);border:1px solid var(--border);border-radius:12px;margin-bottom:7px;">
      <div style="flex-shrink:0;">${buildAvatarHTML(null,u,36)}</div>
      <div style="flex:1;min-width:0;">
        <div style="font-weight:600;">${escapeHTML(u)} ${u===b.owner?'<span style="font-size:10px;color:var(--accent);">[Owner]</span>':''}</div>
        <div style="display:flex;gap:4px;flex-wrap:wrap;margin-top:3px;">${roleTags||'<span style="font-size:11px;color:var(--muted);">No roles</span>'} ${repBadge}</div>
      </div>
      ${isOwner?`
        <button class="btn-g" style="font-size:12px;padding:5px 10px;" onclick="openAssignRoleUI('${escapeHTML(u)}')">🎭 Roles</button>
        ${u!==CU.username?`<button class="btn-d" style="font-size:12px;padding:5px 10px;" onclick="kickMember('${escapeHTML(u)}')">⛔ Kick</button>`:''}`:''}
    </div>`;
  }).join('');
}
async function kickMember(username) {
  showCustomConfirm(`Kick ${username} from this bastion?`, async ()=>{
    try {
      const b=CU.bastions[curBastion];
      await FortizedSocial.removeBastionMember(b.globalId||b.name,username);
      // Clean local memberRoles so member list updates immediately
      if(b.memberRoles) delete b.memberRoles[username];
      toast(`${username} kicked`,'info');
      loadBastionMembersList();
      renderMemberList();
    } catch { toast('An error occurred. Please try again.','error'); }
  });
}
async function unbanMember(i) {
  CU.bastions[curBastion].bans=CU.bastions[curBastion].bans||[];
  CU.bastions[curBastion].bans.splice(i,1);
  await saveUser(); renderBSettingsMain('bans'); toast('Member unbanned','success');
}
function filterBSettingsMembers(q) {
  const items=document.querySelectorAll('#bsettings-members-list > div');
  const query=q.toLowerCase();
  items.forEach(el=>{el.style.display=el.textContent.toLowerCase().includes(query)?'':'none';});
}
async function banMemberByName() {
  const username=document.getElementById('ban-username-input')?.value?.trim();
  const reason=document.getElementById('ban-reason-input')?.value?.trim()||'';
  if(!username){toast('Enter a username','error');return;}
  const b=CU.bastions[curBastion];
  if(!b)return;
  b.bans=b.bans||[];
  if(b.bans.find(ban=>ban.username===username)){toast('Already banned','error');return;}
  b.bans.push({username,reason,date:new Date().toISOString()});
  try{await FortizedSocial.removeBastionMember(b.globalId||b.name,username);}catch{}
  if(b.memberRoles) delete b.memberRoles[username];
  await saveUser();
  renderBSettingsMain('bans');
  renderMemberList();
  toast(`${username} banned`,'success');
}
async function distributeOnyxRevenue(cost) {
  if (cost <= 0) return;
  const stawShare = Math.floor(cost * 0.25);
  const fortizedShare = Math.floor(cost * 0.15);
  const staffPool = Math.floor(cost * 0.40);
  // 20% is burned (removed from circulation), plus any rounding remainder
  // Get all staff members
  const staff = JSON.parse(localStorage.getItem('ftz_staff') || '{}');
  const allStaff = [...new Set([...SUPER_ADMINS, ...(staff.admins || []), ...(staff.moderators || [])])];
  const perStaff = allStaff.length > 0 ? Math.floor(staffPool / allStaff.length) : 0;
  // Send shares to recipients via Firebase
  const sends = [];
  if (stawShare > 0) {
    sends.push((async () => {
      try {
        const u = await FortizedSocial.getUserByName('staw');
        if (u) await FortizedSocial.adminUpdateUserField('staw', 'onyx', (u.onyx || 0) + stawShare);
      } catch(e) { console.warn('[Revenue] Staw share failed:', e?.message); }
    })());
  }
  if (fortizedShare > 0) {
    sends.push((async () => {
      try {
        const u = await FortizedSocial.getUserByName('fortized');
        if (u) await FortizedSocial.adminUpdateUserField('fortized', 'onyx', (u.onyx || 0) + fortizedShare);
      } catch(e) { console.warn('[Revenue] Fortized share failed:', e?.message); }
    })());
  }
  if (perStaff > 0) {
    for (const member of allStaff) {
      sends.push((async () => {
        try {
          const u = await FortizedSocial.getUserByName(member);
          if (u) await FortizedSocial.adminUpdateUserField(member, 'onyx', (u.onyx || 0) + perStaff);
        } catch(e) { console.warn('[Revenue] Staff share failed for', member, e?.message); }
      })());
    }
  }
  await Promise.all(sends);
  // Refresh current user if they are staff (their onyx may have changed)
  if (allStaff.includes(CU.username) || CU.username === 'staw' || CU.username === 'fortized') {
    await refreshCU();
    updateOnyxDisplay();
  }
}
async function boostBastion(level, cost) {
  if((CU.onyx||0)<cost){toast('Not enough Onyx!','error');return;}
  showCustomConfirm(`Boost to Level ${level} for ${cost} Onyx?`, async ()=>{
    CU.onyx=(CU.onyx||0)-cost;
    CU.bastions[curBastion].boostLevel=level;
    await saveUser(); updateOnyxDisplay(); openBoostModal();
    distributeOnyxRevenue(cost);
    toast('Boosted to Level '+level+'!','success');
  });
}
async function confirmLeaveBastion() {
  const b=CU.bastions[curBastion];
  document.getElementById('leave-title').textContent=`Leave ${b.name}?`;
  document.getElementById('leave-confirm-btn').onclick=async()=>{
    try{await FortizedSocial.removeBastionMember(b.globalId||b.name,CU.username);}catch(e){console.warn('[Bastion] Leave failed:',e?.message);}
    if(b.memberRoles) delete b.memberRoles[CU.username];
    CU.bastions.splice(curBastion,1);
    await saveUser(); closeModal('modal-leave-bastion'); curBastion=null;
    renderRailBastions(); showView('home'); toast('Left bastion','info');
  };
  openModal('modal-leave-bastion');
}
async function deleteBastion() {
  confirmDeleteBastion(curBastion);
}

function confirmDeleteBastion(idx) {
  const b = CU.bastions?.[idx];
  if (!b) return;
  const confirmWord = b.name.split(/\s+/)[0].toUpperCase();
  const overlay = document.createElement('div');
  overlay.className = 'input-dialog-overlay';
  overlay.innerHTML = `<div class="input-dialog" style="max-width:420px;">
    <h3 style="color:var(--red);margin-bottom:10px;">🛑 Delete "${escapeHTML(b.name)}"?</h3>
    <p style="margin-bottom:8px;">This action is <strong style="color:var(--red);">permanent</strong> and cannot be undone. All channels, messages, and members will be lost forever.</p>
    <p style="margin-bottom:14px;font-size:12.5px;color:var(--muted-light);">Consider transferring ownership instead — your bastion lives on with someone else in charge.</p>
    <div class="input-dialog-actions" style="margin-bottom:16px;">
      <button class="btn-g" style="flex:1;justify-content:center;" id="cdb-transfer">Transfer Ownership Instead</button>
    </div>
    <div style="border-top:1px solid var(--border);padding-top:14px;margin-top:4px;">
      <p style="font-size:12px;color:var(--muted-light);margin-bottom:10px;">To confirm deletion, type <strong style="color:#fff;font-family:'SF Mono','Cascadia Code',monospace;background:rgba(255,255,255,.06);padding:2px 6px;border-radius:4px;">${escapeHTML(confirmWord)}</strong> below:</p>
      <input type="text" id="cdb-confirm-input" placeholder="Type here to confirm…" autocomplete="off">
      <div class="input-dialog-actions">
        <button class="btn-g" style="flex:1;justify-content:center;" id="cdb-cancel">Cancel</button>
        <button class="btn-d" style="flex:1;justify-content:center;opacity:.4;pointer-events:none;" id="cdb-delete">Delete Bastion</button>
      </div>
    </div>
  </div>`;
  document.body.appendChild(overlay);

  const inp = document.getElementById('cdb-confirm-input');
  const delBtn = document.getElementById('cdb-delete');
  inp.addEventListener('input', () => {
    const match = inp.value.trim().toUpperCase() === confirmWord;
    delBtn.style.opacity = match ? '1' : '.4';
    delBtn.style.pointerEvents = match ? 'auto' : 'none';
  });

  document.getElementById('cdb-cancel').onclick = () => overlay.remove();
  overlay.addEventListener('keydown', e => { if (e.key === 'Escape') overlay.remove(); });

  document.getElementById('cdb-transfer').onclick = () => {
    overlay.remove();
    openBastion(idx);
    setTimeout(() => openBastionSettings('danger'), 100);
  };

  delBtn.onclick = async () => {
    if (inp.value.trim().toUpperCase() !== confirmWord) return;
    overlay.remove();
    try { await firebase.database().ref('globalBastions/' + (b.globalId || b.name)).remove(); } catch(e) { console.warn('[Bastion] Global remove failed:', e?.message); }
    CU.bastions.splice(idx, 1);
    await saveUser();
    curBastion = null;
    curChannel = null;
    renderRailBastions();
    showView('home');
    toast('Bastion "' + b.name + '" has been deleted permanently.', 'info');
  };
}
async function transferBastionOwnership() {
  const newOwner=document.getElementById('transfer-owner-input')?.value?.trim();
  if(!newOwner){toast('Enter a username','error');return;}
  const b=CU.bastions[curBastion];
  if(!b||b.owner!==CU.username)return;
  showCustomConfirm(`Transfer ownership of ${b.name} to ${newOwner}? You will lose owner privileges.`, async ()=>{
    b.owner=newOwner;
    if(!b.memberRoles)b.memberRoles={};
    b.memberRoles[newOwner]=['admin'];
    await saveUser();
    try{await firebase.database().ref('globalBastions/'+(b.globalId||b.name)).update({owner:newOwner});}catch{}
    renderBSettingsMain('danger');
    toast(`Ownership transferred to ${newOwner}`,'success');
  });
}

