// ─── My Bots view in user settings ───
function renderMyBotsView(main) {
  const bots = CU.bots || [];
  main.innerHTML = `
    <div style="max-width:680px;">
      <div class="settings-section-title" style="display:flex;align-items:center;justify-content:space-between;">
        <span>MY BOTS</span>
        <button class="btn-a" onclick="openCreateBotModal()" style="font-size:12px;padding:6px 16px;">+ Create Bot</button>
      </div>
      <div style="font-size:12.5px;color:var(--muted-light);margin-bottom:20px;">Build programmable entities that automate tasks, respond to commands, and connect to events in your Bastions.</div>
      <div id="my-bots-list">
        ${bots.length ? bots.map((bot,i) => `
          <div class="bot-card" style="margin-bottom:10px;" onclick="openBotEditor(${i})">
            <div class="bot-av">${bot.avatar?`<img src="${escapeHTML(bot.avatar)}">`:(bot.emblem||'<img src="/Fortized Bot.png" style="width:100%;height:100%;object-fit:cover;">')}</div>
            <div class="bot-meta">
              <div class="bot-name">${escapeHTML(bot.name)} <span class="ftz-badge badge-bot"><img src="/fortized badges/bot.png" alt="bot"><span class="badge-tooltip">Bot - Automated or system-managed account.</span></span>
                ${bot.visibility==='public'?'<span style="font-size:9px;color:var(--green);">● Public</span>':bot.visibility==='unlisted'?'<span style="font-size:9px;color:var(--muted);">○ Unlisted</span>':'<span style="font-size:9px;color:var(--muted);">🔒 Private</span>'}
              </div>
              <div class="bot-desc">${escapeHTML(bot.bio||'No description')}</div>
              <div class="bot-stats">
                <span>${bot.scriptType==='block'?'🧱 Block Script':'⚙️ Advanced'}</span>
                <span>•</span>
                <span>${(bot.commands||[]).length} commands</span>
                <span>•</span>
                <span>${(bot.scripts||[]).length} scripts</span>
                <span>•</span>
                <span>Created ${new Date(bot.createdAt||Date.now()).toLocaleDateString()}</span>
              </div>
            </div>
          </div>
        `).join('') : `
          <div style="text-align:center;padding:40px 20px;">
            <div style="font-size:36px;margin-bottom:12px;"><img src="/Fortized Bot.png" style="width:36px;height:36px;"></div>
            <div style="font-family:var(--font-display);font-size:16px;font-weight:800;margin-bottom:8px;">No Bots Yet</div>
            <div style="font-size:12.5px;color:var(--muted-light);margin-bottom:16px;">Create your first bot to start automating your Bastions.</div>
            <button class="btn-a" onclick="openCreateBotModal()">Create Bot</button>
          </div>
        `}
      </div>
    </div>`;
}

// ─── Create Bot Modal ───
let _createBotStep = 1;
function openCreateBotModal() {
  _createBotStep = 1;
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay show';
  overlay.id = 'modal-create-bot';
  overlay.innerHTML = `
    <div class="modal" style="max-width:520px;">
      <div class="modal-bar"></div>
      <div class="modal-body" id="create-bot-body"></div>
    </div>`;
  overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
  document.body.appendChild(overlay);
  renderCreateBotStep(1);
}

function renderCreateBotStep(step) {
  const body = document.getElementById('create-bot-body');
  if (!body) return;
  _createBotStep = step;

  if (step === 1) {
    body.innerHTML = `
      <div class="modal-title" style="display:flex;align-items:center;gap:8px;"><img src="/Fortized Bot.png" style="width:22px;height:22px;"> Create a Bot</div>
      <div class="modal-sub" style="margin-bottom:16px;">Step 1 of 3 — Identity</div>
      <div style="display:flex;gap:14px;margin-bottom:16px;">
        <div style="width:64px;height:64px;border-radius:16px;background:var(--panel2);border:1.5px solid rgba(255,249,62,.15);display:flex;align-items:center;justify-content:center;font-size:28px;cursor:pointer;overflow:hidden;transition:all .2s;" onclick="document.getElementById('bot-avatar-upload').click()" id="bot-avatar-prev" onmouseover="this.style.borderColor='rgba(255,249,62,.3)'" onmouseout="this.style.borderColor='rgba(255,249,62,.15)'"><img src="/Fortized Bot.png" style="width:100%;height:100%;object-fit:cover;border-radius:16px;"></div>
        <input id="bot-avatar-upload" type="file" accept="image/*" style="display:none;" onchange="previewBotAvatar(event)">
        <div style="flex:1;">
          <input class="modal-input" id="cbot-name" placeholder="Bot Name" maxlength="32">
          <input class="modal-input" id="cbot-bio" placeholder="Short bio…" maxlength="120" style="margin-top:8px;">
        </div>
      </div>
      <div class="settings-title">Visibility</div>
      <div style="display:flex;gap:8px;margin-bottom:16px;">
        <label style="flex:1;padding:10px;border-radius:10px;border:1px solid var(--border);cursor:pointer;text-align:center;font-size:12px;" onclick="this.querySelector('input').checked=true;document.querySelectorAll('.cb-vis-opt').forEach(e=>e.style.borderColor='var(--border)');this.style.borderColor='rgba(167,139,250,.4)'" class="cb-vis-opt"><input type="radio" name="bot-vis" value="private" checked style="display:none;"> 🔒 Private</label>
        <label style="flex:1;padding:10px;border-radius:10px;border:1px solid var(--border);cursor:pointer;text-align:center;font-size:12px;" onclick="this.querySelector('input').checked=true;document.querySelectorAll('.cb-vis-opt').forEach(e=>e.style.borderColor='var(--border)');this.style.borderColor='rgba(167,139,250,.4)'" class="cb-vis-opt"><input type="radio" name="bot-vis" value="unlisted" style="display:none;"> 🔗 Unlisted</label>
        <label style="flex:1;padding:10px;border-radius:10px;border:1px solid var(--border);cursor:pointer;text-align:center;font-size:12px;" onclick="this.querySelector('input').checked=true;document.querySelectorAll('.cb-vis-opt').forEach(e=>e.style.borderColor='var(--border)');this.style.borderColor='rgba(167,139,250,.4)'" class="cb-vis-opt"><input type="radio" name="bot-vis" value="public" style="display:none;"> 🌍 Public</label>
      </div>
      <div class="modal-actions">
        <button class="btn-g" onclick="document.getElementById('modal-create-bot').remove()">Cancel</button>
        <button class="btn-a" onclick="renderCreateBotStep(2)">Next →</button>
      </div>`;
  } else if (step === 2) {
    body.innerHTML = `
      <div class="modal-title" style="display:flex;align-items:center;gap:8px;"><img src="/Fortized Bot.png" style="width:22px;height:22px;"> Script Type</div>
      <div class="modal-sub" style="margin-bottom:16px;">Step 2 of 3 — Choose how your bot is programmed</div>
      <div style="display:flex;gap:10px;margin-bottom:20px;">
        <div id="stype-block" class="vis-opt active" onclick="document.querySelectorAll('#create-bot-body .vis-opt').forEach(e=>e.classList.remove('active'));this.classList.add('active')" style="flex:1;cursor:pointer;">
          <div style="font-size:28px;">🧱</div>
          <div style="font-size:13px;font-weight:700;">Block Scripting</div>
          <div style="font-size:11px;color:var(--muted-light);">Visual drag-and-drop logic blocks. No coding required.</div>
        </div>
        <div id="stype-advanced" class="vis-opt" onclick="document.querySelectorAll('#create-bot-body .vis-opt').forEach(e=>e.classList.remove('active'));this.classList.add('active')" style="flex:1;cursor:pointer;opacity:.5;">
          <div style="font-size:28px;">⚙️</div>
          <div style="font-size:13px;font-weight:700;">Advanced</div>
          <div style="font-size:11px;color:var(--muted-light);">Coming in a future update.</div>
        </div>
      </div>
      <div class="modal-actions">
        <button class="btn-g" onclick="renderCreateBotStep(1)">← Back</button>
        <button class="btn-a" onclick="renderCreateBotStep(3)">Next →</button>
      </div>`;
  } else if (step === 3) {
    body.innerHTML = `
      <div class="modal-title">🔐 Permissions</div>
      <div class="modal-sub" style="margin-bottom:16px;">Step 3 of 3 — What can your bot do?</div>
      <div style="display:flex;flex-direction:column;gap:6px;margin-bottom:20px;max-height:260px;overflow-y:auto;">
        ${BOT_PERMISSIONS.map(p => `
          <label class="bot-perm-label">
            <input type="checkbox" value="${p.key}" class="cbot-perm" ${['read_messages','send_messages','add_reactions'].includes(p.key)?'checked':''} style="accent-color:var(--accent);">
            <span style="font-size:14px;">${p.icon}</span>
            <div style="flex:1;">
              <div style="font-size:12.5px;font-weight:600;">${p.label}</div>
              <div style="font-size:11px;color:var(--muted);">${p.desc}</div>
            </div>
          </label>
        `).join('')}
      </div>
      <div class="modal-actions">
        <button class="btn-g" onclick="renderCreateBotStep(2)">← Back</button>
        <button class="btn-a" onclick="finalizeBotCreation()">Create Bot</button>
      </div>`;
  }
}

function previewBotAvatar(e) {
  const file = e.target.files[0]; if (!file) return;
  const reader = new FileReader();
  reader.onload = ev => {
    const prev = document.getElementById('bot-avatar-prev');
    if (prev) { prev.innerHTML = `<img src="${ev.target.result}" style="width:100%;height:100%;object-fit:cover;border-radius:14px;">`; prev.dataset.avatarData = ev.target.result; }
  };
  reader.readAsDataURL(file);
}

function finalizeBotCreation() {
  const name = document.getElementById('cbot-name')?.value?.trim();
  if (!name) { toast('Bot name is required', 'error'); return; }
  const bio = document.getElementById('cbot-bio')?.value?.trim() || '';
  const vis = document.querySelector('input[name="bot-vis"]:checked')?.value || 'private';
  const scriptType = document.getElementById('stype-advanced')?.classList.contains('active') ? 'advanced' : 'block';
  const perms = [...document.querySelectorAll('.cbot-perm:checked')].map(el => el.value);
  const avatarPrev = document.getElementById('bot-avatar-prev');
  const avatar = avatarPrev?.dataset?.avatarData || '';

  const bot = {
    id: 'bot_' + Date.now().toString(36) + Math.random().toString(36).slice(2,5),
    name, bio, avatar,
    emblem: '<img src="/Fortized Bot.png" style="width:100%;height:100%;object-fit:cover;">',
    visibility: vis,
    scriptType,
    permissions: perms,
    commands: [],
    scripts: [],
    owner: CU.username,
    createdAt: new Date().toISOString(),
    version: '1.0',
    enabled: true,
  };

  if (!CU.bots) CU.bots = [];
  CU.bots.push(bot);
  saveUser();
  document.getElementById('modal-create-bot')?.remove();
  toast(`Bot "${name}" created!`, 'success');
  buildProfileView('my_bots');
}

// ─── Bot Editor ───
let _editingBotIdx = null;
function openBotEditor(idx) {
  _editingBotIdx = idx;
  const bot = CU.bots?.[idx];
  if (!bot) return;
  const main = document.getElementById('profile-main');
  if (!main) return;

  main.innerHTML = `
    <div style="max-width:720px;padding-bottom:40px;">
      <button class="btn-g" onclick="buildProfileView('my_bots')" style="margin-bottom:16px;font-size:12px;">← Back to My Bots</button>
      <div style="display:flex;align-items:center;gap:14px;margin-bottom:24px;">
        <div class="bot-av" style="width:56px;height:56px;font-size:26px;">${bot.avatar?`<img src="${escapeHTML(bot.avatar)}">`:(bot.emblem||'<img src="/Fortized Bot.png" style="width:100%;height:100%;object-fit:cover;">')}</div>
        <div>
          <div style="font-family:var(--font-display);font-size:18px;font-weight:800;display:flex;align-items:center;gap:8px;">${escapeHTML(bot.name)} <span class="ftz-badge badge-bot"><img src="/fortized badges/bot.png" alt="bot"><span class="badge-tooltip">Bot - Automated or system-managed account.</span></span></div>
          <div style="font-size:12px;color:var(--muted);">Owner: @${escapeHTML(bot.owner)} · Created ${new Date(bot.createdAt).toLocaleDateString()} · v${bot.version}</div>
        </div>
        <div style="margin-left:auto;display:flex;gap:6px;">
          <button class="btn-g" onclick="toggleBot(${idx})" style="font-size:12px;">${bot.enabled!==false?'🟢 Enabled':'🔴 Disabled'}</button>
          <button class="btn-d" onclick="deleteBot(${idx})" style="font-size:12px;">Delete</button>
        </div>
      </div>

      <!-- Bot Info -->
      <div class="settings-section-title">IDENTITY</div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:20px;">
        <div><div class="settings-title">Name</div><input class="field-input" id="be-name" value="${escapeHTML(bot.name)}"></div>
        <div><div class="settings-title">Bio</div><input class="field-input" id="be-bio" value="${escapeHTML(bot.bio||'')}"></div>
      </div>
      <div style="margin-bottom:20px;">
        <div class="settings-title">Visibility</div>
        <select class="field-input" id="be-vis" style="padding:8px 12px;">
          <option value="private" ${bot.visibility==='private'?'selected':''}>🔒 Private</option>
          <option value="unlisted" ${bot.visibility==='unlisted'?'selected':''}>🔗 Unlisted</option>
          <option value="public" ${bot.visibility==='public'?'selected':''}>🌍 Public (Arsenal)</option>
        </select>
      </div>
      <button class="btn-a" onclick="saveBotIdentity(${idx})" style="margin-bottom:24px;">Save Identity</button>

      <!-- Permissions -->
      <div class="settings-section-title">PERMISSIONS</div>
      <div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:24px;">
        ${BOT_PERMISSIONS.map(p => `
          <span class="bot-perm-tag ${bot.permissions?.includes(p.key)?'granted':''}" onclick="toggleBotPerm(${idx},'${p.key}',this)" style="cursor:pointer;">${p.icon} ${p.label}</span>
        `).join('')}
      </div>

      <!-- Commands -->
      <div class="settings-section-title" style="display:flex;align-items:center;justify-content:space-between;">
        <span>COMMANDS</span>
        <button class="btn-g" onclick="addBotCommand(${idx})" style="font-size:11px;padding:4px 10px;">+ Add Command</button>
      </div>
      <div id="bot-commands-list" style="margin-bottom:24px;">
        ${(bot.commands||[]).length ? (bot.commands||[]).map((cmd,ci) => `
          <div style="display:flex;align-items:center;gap:8px;padding:8px 12px;background:var(--panel);border:1px solid var(--border);border-radius:10px;margin-bottom:6px;">
            <span style="font-family:monospace;font-size:13px;color:var(--accent);font-weight:700;">!${escapeHTML(cmd.name)}</span>
            <span style="flex:1;font-size:12px;color:var(--muted);">${escapeHTML(cmd.desc||'No description')}</span>
            <button style="background:none;border:none;color:var(--muted);cursor:pointer;font-size:16px;" onclick="removeBotCommand(${idx},${ci})">×</button>
          </div>
        `).join('') : '<div style="font-size:12.5px;color:var(--muted);padding:12px;">No commands yet. Add commands for your bot.</div>'}
      </div>

      <!-- Block Scripting -->
      <div class="settings-section-title" style="display:flex;align-items:center;justify-content:space-between;">
        <span>🧱 BLOCK SCRIPTS</span>
        <button class="btn-g" onclick="addBotScript(${idx})" style="font-size:11px;padding:4px 10px;">+ Add Script</button>
      </div>
      <div class="block-editor" id="bot-scripts-editor">
        ${(bot.scripts||[]).length ? (bot.scripts||[]).map((s,si) => renderBlockScriptRow(s, idx, si)).join('') : `
          <div style="text-align:center;padding:30px;color:var(--muted);font-size:12.5px;">
            <div style="font-size:28px;margin-bottom:8px;">🧱</div>
            No scripts yet. Add your first automation block.
          </div>
        `}
      </div>
    </div>`;
}

function renderBlockScriptRow(script, botIdx, scriptIdx) {
  const trigger = BLOCK_TRIGGERS.find(t => t.id === script.trigger) || {icon:'❓',label:'Unknown'};
  const action = BLOCK_ACTIONS.find(a => a.id === script.action) || {icon:'❓',label:'Unknown',color:'#888'};
  const cond = script.condition ? (BLOCK_CONDITIONS.find(c => c.id === script.condition) || {icon:'❓',label:'Unknown'}) : null;
  return `<div class="block-row">
    <span class="block-type when">WHEN</span>
    <span class="block-val">${trigger.icon} ${trigger.label}</span>
    ${cond ? `<span class="block-type if">IF</span><span class="block-val">${cond.icon} ${cond.label}</span>` : ''}
    <span class="block-type then">THEN</span>
    <span class="block-val" style="color:${action.color};">${action.icon} ${action.label}</span>
    <button class="block-del" onclick="event.stopPropagation();removeBotScript(${botIdx},${scriptIdx})">×</button>
  </div>`;
}

function saveBotIdentity(idx) {
  const bot = CU.bots?.[idx]; if (!bot) return;
  bot.name = document.getElementById('be-name')?.value?.trim() || bot.name;
  bot.bio = document.getElementById('be-bio')?.value?.trim() || '';
  bot.visibility = document.getElementById('be-vis')?.value || 'private';
  saveUser();
  toast('Bot identity saved!', 'success');
}

function toggleBotPerm(idx, perm, el) {
  const bot = CU.bots?.[idx]; if (!bot) return;
  if (!bot.permissions) bot.permissions = [];
  if (bot.permissions.includes(perm)) {
    bot.permissions = bot.permissions.filter(p => p !== perm);
    el.classList.remove('granted');
  } else {
    bot.permissions.push(perm);
    el.classList.add('granted');
  }
  saveUser();
}

function addBotCommand(idx) {
  const name = prompt('Command name (without !):');
  if (!name || !name.trim()) return;
  const desc = prompt('Command description (optional):') || '';
  const bot = CU.bots?.[idx]; if (!bot) return;
  if (!bot.commands) bot.commands = [];
  bot.commands.push({name: name.trim().toLowerCase().replace(/\s+/g,'_'), desc: desc.trim()});
  saveUser();
  openBotEditor(idx);
}

function removeBotCommand(idx, cmdIdx) {
  const bot = CU.bots?.[idx]; if (!bot) return;
  (bot.commands||[]).splice(cmdIdx, 1);
  saveUser();
  openBotEditor(idx);
}

function addBotScript(idx) {
  const bot = CU.bots?.[idx]; if (!bot) return;
  // Open script builder modal
  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay show';
  overlay.id = 'modal-add-script';
  overlay.innerHTML = `
    <div class="modal" style="max-width:480px;">
      <div class="modal-bar"></div>
      <div class="modal-body">
        <div class="modal-title">🧱 Add Script Block</div>
        <div class="modal-sub" style="margin-bottom:14px;">Configure: When X happens → Then do Y</div>
        <div class="settings-title">WHEN (Trigger)</div>
        <select class="field-input" id="script-trigger" style="padding:8px 12px;margin-bottom:12px;">
          ${BLOCK_TRIGGERS.map(t => `<option value="${t.id}">${t.icon} ${t.label} — ${t.desc}</option>`).join('')}
        </select>
        <div class="settings-title">IF (Condition) — optional</div>
        <select class="field-input" id="script-condition" style="padding:8px 12px;margin-bottom:12px;">
          <option value="">No condition</option>
          ${BLOCK_CONDITIONS.map(c => `<option value="${c.id}">${c.icon} ${c.label}</option>`).join('')}
        </select>
        <div class="settings-title">THEN (Action)</div>
        <select class="field-input" id="script-action" style="padding:8px 12px;margin-bottom:16px;">
          ${BLOCK_ACTIONS.map(a => `<option value="${a.id}">${a.icon} ${a.label}</option>`).join('')}
        </select>
        <div class="modal-actions">
          <button class="btn-g" onclick="document.getElementById('modal-add-script').remove()">Cancel</button>
          <button class="btn-a" onclick="saveNewScript(${idx})">Add Script</button>
        </div>
      </div>
    </div>`;
  overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
  document.body.appendChild(overlay);
}

function saveNewScript(idx) {
  const bot = CU.bots?.[idx]; if (!bot) return;
  const trigger = document.getElementById('script-trigger')?.value;
  const condition = document.getElementById('script-condition')?.value || '';
  const action = document.getElementById('script-action')?.value;
  if (!trigger || !action) { toast('Select trigger and action', 'error'); return; }
  if (!bot.scripts) bot.scripts = [];
  const script = {trigger, action, config:{}};
  if (condition) script.condition = condition;
  bot.scripts.push(script);
  saveUser();
  document.getElementById('modal-add-script')?.remove();
  openBotEditor(idx);
  toast('Script block added!', 'success');
}

function removeBotScript(idx, sIdx) {
  const bot = CU.bots?.[idx]; if (!bot) return;
  (bot.scripts||[]).splice(sIdx, 1);
  saveUser();
  openBotEditor(idx);
}

function toggleBot(idx) {
  const bot = CU.bots?.[idx]; if (!bot) return;
  bot.enabled = !bot.enabled;
  saveUser();
  openBotEditor(idx);
  toast(bot.enabled ? 'Bot enabled' : 'Bot disabled', 'info');
}

function deleteBot(idx) {
  showCustomConfirm('Permanently delete this bot? This cannot be undone.', () => {
    CU.bots.splice(idx, 1);
    saveUser();
    buildProfileView('my_bots');
    toast('Bot deleted', 'info');
  });
}

// ─── Bot Arsenal (Community Hub) ───
function renderArsenalView(main) {
  const categories = [...new Set(ARSENAL_BOTS.map(b => b.category))];
  main.innerHTML = `
    <div style="max-width:780px;">
      <div style="display:flex;align-items:center;gap:14px;margin-bottom:8px;">
        <div style="font-family:var(--font-display);font-size:22px;font-weight:800;">🏪 The Arsenal</div>
      </div>
      <div style="font-size:13px;color:var(--muted-light);margin-bottom:20px;">Browse bots created by the community. Deploy them to your Bastions with one click.</div>
      <div style="display:flex;gap:6px;margin-bottom:20px;overflow-x:auto;" id="arsenal-chips">
        <button class="gif-chip active" onclick="_arsenalFilter(this,'all')" style="padding:5px 14px;border-radius:8px;border:1px solid rgba(167,139,250,.15);background:rgba(167,139,250,.07);color:var(--purple);font-size:11px;font-weight:600;cursor:pointer;white-space:nowrap;flex-shrink:0;font-family:var(--font-ui);">All</button>
        ${categories.map(c => `<button class="gif-chip" onclick="_arsenalFilter(this,'${escapeHTML(c)}')" style="padding:5px 14px;border-radius:8px;border:1px solid rgba(255,255,255,.05);background:rgba(255,255,255,.03);color:rgba(255,255,255,.4);font-size:11px;font-weight:600;cursor:pointer;white-space:nowrap;flex-shrink:0;font-family:var(--font-ui);">${escapeHTML(c)}</button>`).join('')}
      </div>
      <div class="arsenal-grid" id="arsenal-grid">
        ${ARSENAL_BOTS.map(bot => renderArsenalCard(bot)).join('')}
      </div>
    </div>`;
}

function renderArsenalCard(bot) {
  return `<div class="bot-card" style="flex-direction:column;gap:10px;cursor:default;">
    <div style="display:flex;gap:12px;align-items:center;">
      <div class="bot-av">${bot.emblem||'<img src="/Fortized Bot.png" style="width:100%;height:100%;object-fit:cover;">'}</div>
      <div style="flex:1;min-width:0;">
        <div class="bot-name">${escapeHTML(bot.name)} <span class="ftz-badge badge-bot"><img src="/fortized badges/bot.png" alt="bot"><span class="badge-tooltip">Bot - Automated or system-managed account.</span></span></div>
        <div style="font-size:11px;color:var(--muted);">by @${escapeHTML(bot.owner)} · v${bot.version}</div>
      </div>
      <div style="display:flex;align-items:center;gap:3px;font-size:12px;color:var(--gold);">⭐ ${bot.rating}</div>
    </div>
    <div style="font-size:12.5px;color:var(--muted-light);line-height:1.5;">${escapeHTML(bot.bio)}</div>
    <div style="display:flex;flex-wrap:wrap;gap:4px;">
      ${(bot.commands||[]).map(c => `<span style="font-family:monospace;font-size:10.5px;padding:2px 7px;border-radius:6px;background:rgba(167,139,250,.08);border:1px solid rgba(167,139,250,.15);color:var(--purple);">${escapeHTML(typeof c==='string'?c:'!'+c.name)}</span>`).join('')}
    </div>
    <div style="display:flex;align-items:center;gap:8px;margin-top:4px;">
      <span style="font-size:11px;color:var(--muted);">${bot.reviews} reviews</span>
      <span style="font-size:11px;color:var(--muted);">•</span>
      <span style="font-size:11px;color:var(--muted);">${escapeHTML(bot.category)}</span>
      <div style="margin-left:auto;">
        <button class="btn-a" style="font-size:11px;padding:5px 14px;" onclick="deployArsenalBot('${bot.id}')">Deploy to Bastion</button>
      </div>
    </div>
  </div>`;
}

function _arsenalFilter(btn, category) {
  // Update chip state
  btn.parentElement.querySelectorAll('.gif-chip').forEach(b => {b.style.background='rgba(255,255,255,.03)';b.style.borderColor='rgba(255,255,255,.05)';b.style.color='rgba(255,255,255,.4)';});
  btn.style.background='rgba(167,139,250,.07)';btn.style.borderColor='rgba(167,139,250,.15)';btn.style.color='#a78bfa';
  const grid = document.getElementById('arsenal-grid');
  if (!grid) return;
  const bots = category === 'all' ? ARSENAL_BOTS : ARSENAL_BOTS.filter(b => b.category === category);
  grid.innerHTML = bots.map(b => renderArsenalCard(b)).join('');
}

function deployArsenalBot(botId) {
  const arsenalBot = ARSENAL_BOTS.find(b => b.id === botId);
  if (!arsenalBot) return;
  // Show bastion picker
  const bastions = CU.bastions || [];
  if (!bastions.length) { toast('You need a bastion first', 'error'); return; }

  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay show';
  overlay.id = 'modal-deploy-bot';
  overlay.innerHTML = `
    <div class="modal" style="max-width:400px;">
      <div class="modal-bar"></div>
      <div class="modal-body">
        <div class="modal-title">Deploy ${escapeHTML(arsenalBot.name)}</div>
        <div class="modal-sub" style="margin-bottom:14px;">Choose a bastion to deploy this bot to.</div>
        <div style="display:flex;flex-direction:column;gap:6px;max-height:260px;overflow-y:auto;margin-bottom:16px;">
          ${bastions.map((b,i) => `
            <div style="display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:10px;border:1px solid var(--border);cursor:pointer;transition:all .12s;" onclick="confirmDeployBot('${botId}',${i})">
              <span style="font-size:18px;">${b.emblem||'🏰'}</span>
              <div style="flex:1;"><div style="font-weight:600;font-size:13px;">${escapeHTML(b.name)}</div><div style="font-size:11px;color:var(--muted);">${(b.channels||[]).length} channels</div></div>
            </div>
          `).join('')}
        </div>
        <button class="btn-g" onclick="document.getElementById('modal-deploy-bot').remove()" style="width:100%;">Cancel</button>
      </div>
    </div>`;
  overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
  document.body.appendChild(overlay);
}

function confirmDeployBot(arsenalBotId, bastionIdx) {
  const arsenalBot = ARSENAL_BOTS.find(b => b.id === arsenalBotId);
  const b = CU.bastions?.[bastionIdx];
  if (!arsenalBot || !b) return;
  if (!b.deployedBots) b.deployedBots = [];
  if (b.deployedBots.find(db => db.id === arsenalBotId)) {
    toast('Bot already deployed to this bastion', 'info');
    document.getElementById('modal-deploy-bot')?.remove();
    return;
  }
  b.deployedBots.push({
    id: arsenalBot.id,
    name: arsenalBot.name,
    emblem: arsenalBot.emblem,
    bio: arsenalBot.bio,
    owner: arsenalBot.owner,
    commands: arsenalBot.commands,
    scripts: arsenalBot.scripts,
    enabled: true,
    deployedAt: new Date().toISOString(),
  });
  saveUser();
  document.getElementById('modal-deploy-bot')?.remove();
  toast(`${arsenalBot.name} deployed to ${b.name}!`, 'success');
  // System message for bot integration
  const bCh = (b.channels||[]).find(ch=>ch.type==='text')||{name:'general'};
  try { FortizedSocial.sendBastionChannelMessage(b.globalId||b.name, bCh.name, '__system__', '**'+arsenalBot.name+'** has been integrated into the bastion.'); } catch(e) { console.debug('[Bot] System msg failed:', e?.message); }
}

function openDeployBotPicker() {
  const myBots = CU.bots || [];
  if (!myBots.length) { toast('Create a bot first in Settings → Developer → My Bots', 'info'); return; }
  const b = CU.bastions?.[curBastion];
  if (!b) return;

  const overlay = document.createElement('div');
  overlay.className = 'modal-overlay show';
  overlay.id = 'modal-deploy-mybot';
  overlay.innerHTML = `
    <div class="modal" style="max-width:400px;">
      <div class="modal-bar"></div>
      <div class="modal-body">
        <div class="modal-title">Deploy Bot to ${escapeHTML(b.name)}</div>
        <div class="modal-sub" style="margin-bottom:14px;">Choose one of your bots to deploy.</div>
        <div style="display:flex;flex-direction:column;gap:6px;max-height:260px;overflow-y:auto;margin-bottom:16px;">
          ${myBots.map((bot,i) => `
            <div style="display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:10px;border:1px solid var(--border);cursor:pointer;transition:all .12s;" onclick="deployMyBot(${i})">
              <div class="bot-av" style="width:36px;height:36px;font-size:16px;">${bot.avatar?`<img src="${escapeHTML(bot.avatar)}">`:(bot.emblem||'<img src="/Fortized Bot.png" style="width:100%;height:100%;object-fit:cover;">')}</div>
              <div style="flex:1;"><div style="font-weight:600;font-size:13px;">${escapeHTML(bot.name)}</div><div style="font-size:11px;color:var(--muted);">${(bot.commands||[]).length} commands · ${(bot.scripts||[]).length} scripts</div></div>
            </div>
          `).join('')}
        </div>
        <button class="btn-g" onclick="document.getElementById('modal-deploy-mybot').remove()" style="width:100%;">Cancel</button>
      </div>
    </div>`;
  overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
  document.body.appendChild(overlay);
}

function deployMyBot(botIdx) {
  const bot = CU.bots?.[botIdx];
  const b = CU.bastions?.[curBastion];
  if (!bot || !b) return;
  if (!b.deployedBots) b.deployedBots = [];
  if (b.deployedBots.find(db => db.id === bot.id)) {
    toast('Bot already deployed here', 'info');
    document.getElementById('modal-deploy-mybot')?.remove();
    return;
  }
  b.deployedBots.push({
    id: bot.id, name: bot.name, emblem: bot.emblem, avatar: bot.avatar,
    bio: bot.bio, owner: bot.owner, commands: bot.commands, scripts: bot.scripts,
    enabled: true, deployedAt: new Date().toISOString(),
  });
  saveUser();
  document.getElementById('modal-deploy-mybot')?.remove();
  renderBSettingsMain('bots');
  toast(`${bot.name} deployed!`, 'success');
  // System message for bot integration
  const bCh = (b.channels||[]).find(ch=>ch.type==='text')||{name:'general'};
  try { FortizedSocial.sendBastionChannelMessage(b.globalId||b.name, bCh.name, '__system__', '**'+bot.name+'** has been integrated into the bastion.'); } catch(e) { console.debug('[Bot] System msg failed:', e?.message); }
}

function toggleBastionBot(botId) {
  const b = CU.bastions?.[curBastion]; if (!b) return;
  const db = (b.deployedBots||[]).find(d => d.id === botId);
  if (db) { db.enabled = !db.enabled; saveUser(); renderBSettingsMain('bots'); }
}

function removeBastionBot(botId) {
  const b = CU.bastions?.[curBastion]; if (!b) return;
  b.deployedBots = (b.deployedBots||[]).filter(d => d.id !== botId);
  saveUser();
  renderBSettingsMain('bots');
  toast('Bot removed from bastion', 'info');
}

// ── Bot identity in profiles ──
function getBotProfile(bot) {
  return {
    name: bot.name,
    bio: bot.bio || '',
    avatar: bot.avatar || '',
    emblem: bot.emblem || '<img src="/Fortized Bot.png" style="width:100%;height:100%;object-fit:cover;">',
    owner: bot.owner,
    createdAt: bot.createdAt,
    commands: bot.commands || [],
    scripts: bot.scripts || [],
    scriptType: bot.scriptType || 'block',
    isBot: true,
  };
}

// ── Superadmin bot controls ──
function renderAdminBotControls() {
  if (!CU?.isSuperAdmin) return '';
  return `
    <div class="settings-section-title">SUPERADMIN BOT CONTROLS</div>
    <div style="display:flex;flex-direction:column;gap:8px;">
      <button class="btn-g" onclick="adminListAllBots()" style="text-align:left;padding:10px 14px;">
        <div style="font-weight:600;">View All Platform Bots</div>
        <div style="font-size:11px;color:var(--muted);">Audit scripts, suspend, or delete any bot</div>
      </button>
      <button class="btn-g" onclick="adminConvertToBot()" style="text-align:left;padding:10px 14px;">
        <div style="font-weight:600;">Convert Account to Bot</div>
        <div style="font-size:11px;color:var(--muted);">Turn a user account into a BOT entity</div>
      </button>
    </div>`;
}

function adminListAllBots() {
  toast('Platform bot audit — coming in next update', 'info');
}

function adminConvertToBot() {
  const username = prompt('Username to convert to BOT:');
  if (!username || !username.trim()) return;
  toast(`Account @${username.trim()} flagged as BOT. This takes effect on next login.`, 'success');
}

