// ── Emoji Click Tooltip (Discord-style) ─────────────────
function _showEmojiTooltip(emoji, el) {
  // Remove any existing tooltip
  document.querySelector('.emoji-tooltip')?.remove();

  // Determine emoji type from data attributes or by lookup
  const emojiType = el.dataset?.emojiType || null;
  const bastionIdx = el.dataset?.bastionIdx != null ? parseInt(el.dataset.bastionIdx) : null;
  const emojiKey = el.dataset?.emoji || emoji;

  // Fortized Guide emoji
  const isFtz = emojiType === 'ftz' || FORTIZED_EMOJI_MAP[emojiKey];
  // Bastion custom emoji — check all bastions
  let bastionCustom = null;
  let bastionName = '';
  if (emojiType === 'bastion' && bastionIdx !== null) {
    const b = CU?.bastions?.[bastionIdx];
    bastionCustom = (b?.customEmojis||[]).find(ce => ce.name === emojiKey);
    bastionName = b?.name || 'Bastion';
  } else if (!isFtz && !EMOJI_NAMES[emoji]) {
    // Search all bastions for this emoji
    (CU?.bastions||[]).forEach((b, i) => {
      if (bastionCustom) return;
      const ce = (b?.customEmojis||[]).find(e => e.name === emojiKey);
      if (ce) { bastionCustom = ce; bastionName = b?.name || 'Bastion'; }
    });
  }

  let previewHTML, nameStr, originLabel, originColor, detailLine;

  if (isFtz) {
    // Fortized Guide emoji
    const ftzUrl = FORTIZED_EMOJI_MAP[emojiKey];
    previewHTML = `<img src="${ftzUrl}" onerror="this.outerHTML='<span style=\\'font-size:28px;\\'>${escapeHTML(emojiKey)}</span>'" style="width:32px;height:32px;object-fit:contain;">`;
    nameStr = ':' + emojiKey + ':';
    originLabel = 'Fortized Guide Emoji';
    originColor = 'rgba(255,249,62,.85)';
    detailLine = 'Official Fortized Guide — available everywhere';
  } else if (bastionCustom) {
    // Bastion custom emoji
    previewHTML = `<img src="${escapeHTML(bastionCustom.data)}" style="width:32px;height:32px;object-fit:contain;">`;
    nameStr = ':' + emojiKey + ':';
    originLabel = 'Bastion Emoji';
    originColor = 'rgba(88,191,255,.85)';
    detailLine = 'From: ' + escapeHTML(bastionName);
  } else {
    // Default unicode emoji
    const name = EMOJI_NAMES[emoji] || 'emoji';
    const category = EMOJI_CAT_MAP[emoji] || 'Emoji';
    const codePoints = [...emoji].map(c => 'U+' + c.codePointAt(0).toString(16).toUpperCase()).join(' ');
    const url = emojiToTwemojiUrl(emoji);
    previewHTML = `<img src="${url}" onerror="this.outerHTML='<span style=\\'font-size:28px;\\'>${emoji}</span>'" style="width:32px;height:32px;object-fit:contain;">`;
    nameStr = ':' + name.replace(/\s+/g,'_') + ':';
    originLabel = 'Default Emoji';
    originColor = 'rgba(255,255,255,.45)';
    detailLine = category + ' · ' + codePoints;
  }

  const tip = document.createElement('div');
  tip.className = 'emoji-tooltip';
  tip.innerHTML = `
    <div class="et-header">
      <div class="et-big">${previewHTML}</div>
      <div>
        <div class="et-name">${escapeHTML(nameStr)}</div>
        <div class="et-origin" style="font-size:10px;font-weight:600;color:${originColor};margin-top:2px;">${originLabel}</div>
      </div>
    </div>
    <div class="et-cat">${detailLine}</div>`;

  document.body.appendChild(tip);

  // Position near the clicked emoji
  const rect = el.getBoundingClientRect();
  const tipRect = tip.getBoundingClientRect();
  let top = rect.top - tipRect.height - 8;
  let left = rect.left + rect.width/2 - tipRect.width/2;
  if (top < 8) top = rect.bottom + 8;
  if (left < 8) left = 8;
  if (left + tipRect.width > window.innerWidth - 8) left = window.innerWidth - tipRect.width - 8;
  tip.style.top = top + 'px';
  tip.style.left = left + 'px';

  // Close on click outside or scroll
  const close = (e) => {
    if (!tip.contains(e.target)) {
      tip.remove();
      document.removeEventListener('click', close);
      document.removeEventListener('scroll', close, true);
    }
  };
  setTimeout(() => {
    document.addEventListener('click', close);
    document.addEventListener('scroll', close, true);
  }, 10);

  // Auto-close after 5s
  setTimeout(() => tip.remove(), 5000);
}

// Event delegation: left-click any emoji in chat → show tooltip
// Only for user-input emojis (messages, about me, forum posts) — not platform/UI emojis
document.addEventListener('click', function(e) {
  const img = e.target.closest('.msg-emoji, .msg-emoji-native, .emoji');
  if (!img) return;
  // Only show tooltip for emojis inside user-generated content areas
  if (!img.closest('.msg-text, .msg-reply-ref, .up-left-section-body, .ann-body, .forum-detail-content, .frc-body')) return;
  const emoji = img.dataset?.emoji || img.alt || img.textContent?.trim();
  if (emoji) { e.stopPropagation(); _showEmojiTooltip(emoji, img); }
});

function renderEmojiCell(emoji) {
  const safe = escapeHTML(emoji);
  const url = emojiToTwemojiUrl(emoji);
  // Look up a readable name: EMOJI_NAMES first, then reverse EMOJI_SHORTCODES
  let label = EMOJI_NAMES[emoji] || '';
  if (!label) {
    for (const [code, em] of Object.entries(EMOJI_SHORTCODES)) {
      if (em === emoji) { label = code.replace(/_/g, ' '); break; }
    }
  }
  if (!label) label = emoji;
  const shortcode = Object.entries(EMOJI_SHORTCODES).find(([,em]) => em === emoji)?.[0] || '';
  const displayName = shortcode ? ':' + shortcode + ':' : label;
  const isFav = _favEmojis.includes(emoji);
  return `<div onclick="insertEmoji('${safe}')" oncontextmenu="event.preventDefault();toggleFavEmoji('${safe}')" data-tip="${escapeHTML(displayName)}${isFav ? ' ★ (Right-click to unfavorite)' : ' (Right-click to favorite)'}"
    onmouseenter="document.getElementById('epp-hover-label').textContent='${escapeHTML(displayName)}${isFav ? ' ★' : ''}'"
    class="emoji-cell" style="width:38px;height:38px;position:relative;">
    <img src="${url}" style="width:26px;height:26px;object-fit:contain;" loading="lazy" onerror="this.outerHTML='<span style=\\'font-size:22px;\\'>${emoji}</span>'">
    ${isFav ? '<span style="position:absolute;top:2px;right:2px;font-size:12px;color:var(--accent);">★</span>' : ''}
  </div>`;
}

function wireEmojiHover(grid) {
  // Done via inline handlers in renderEmojiCell
}

function searchEmojis(q) {
  const grid = document.getElementById('epp-grid');
  if (!grid) return;
  if (!q.trim()) { renderEmojiTab(_emojiPickerTab); return; }
  const ql = q.toLowerCase();
  // Search unicode emojis by shortcode name
  const matches = [];
  const seen = new Set();
  // Search shortcodes
  Object.entries(EMOJI_SHORTCODES).forEach(([name, emoji]) => {
    if (name.includes(ql) && !seen.has(emoji)) { matches.push({type:'unicode',emoji,name}); seen.add(emoji); }
  });
  // Search all emoji arrays
  EMOJI_PICKER_TABS.slice(2).forEach(tab => {
    (tab.emojis||[]).forEach(e => { if (!seen.has(e) && e.includes(q)) { matches.push({type:'unicode',emoji:e,name:e}); seen.add(e); } });
  });
  // Search Fortized emojis
  FORTIZED_EMOJIS.forEach(name => {
    if (name.includes(ql)) matches.push({type:'ftz',name,url:FORTIZED_EMOJI_MAP[name]});
  });
  // Search bastion custom emojis
  (CU?.bastions||[]).forEach((b, bi) => {
    (b.customEmojis||[]).forEach(ce => {
      if (ce.name && ce.name.toLowerCase().includes(ql)) matches.push({type:'ftz',name:ce.name,url:ce.data});
    });
  });
  // Search personal emojis
  (CU?.personalEmojis||[]).forEach(pe => {
    if (pe.name && pe.name.toLowerCase().includes(ql)) matches.push({type:'ftz',name:pe.name,url:pe.data});
  });

  if (!matches.length) { grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:20px;color:rgba(255,255,255,.4);">No results for "'+escapeHTML(q)+'"</div>'; return; }
  grid.style.gridTemplateColumns = 'repeat(8,1fr)';
  grid.innerHTML = matches.slice(0,64).map(m => {
    if (m.type === 'ftz') return `<div onclick="insertFortizedEmoji('${escapeHTML(m.name)}','${escapeHTML(m.url)}')" title=":${escapeHTML(m.name)}:" style="width:34px;height:34px;border-radius:7px;display:flex;align-items:center;justify-content:center;cursor:pointer;padding:3px;"><img src="${escapeHTML(m.url)}" style="width:100%;height:100%;object-fit:contain;" onerror="this.parentElement.style.display='none'"></div>`;
    return renderEmojiCell(m.emoji);
  }).join('');
}

function setEmojiCat(idx) { setEmojiTab(EMOJI_PICKER_TABS[idx]?.id || 'smileys'); }

function insertEmoji(emoji) {
  const ta = document.getElementById(activeEmojiTarget);
  if (!ta) return;
  const pos = ta.selectionStart;
  ta.value = ta.value.slice(0, pos) + emoji + ta.value.slice(ta.selectionEnd);
  ta.selectionStart = ta.selectionEnd = pos + emoji.length;
  ta.focus();
  document.getElementById('emoji-picker').classList.remove('show');
  // Add to recent
  _recentEmojis = [emoji, ..._recentEmojis.filter(e=>e!==emoji)].slice(0,24);
  localStorage.setItem('ftz_recent_emojis', JSON.stringify(_recentEmojis));
  // Track frequency
  _trackEmojiFrequency(emoji);
}

// ═══ Radiance helper ═══
function _hasActiveRadiance() {
  return (CU?.radianceUntil && new Date(CU.radianceUntil) > new Date()) ||
         (CU?.radiancePlus && new Date(CU.radiancePlus) > new Date());
}

// ═══ Emoji & Sticker Usage ═══
// Radiance Basic & Radiance+ users can use all emojis and stickers daily.
// Non-Radiance users cannot access emoji/sticker reactions.

function insertFortizedEmoji(name, url) {
  const ta = document.getElementById(activeEmojiTarget);
  if (!ta) return;
  const token = ':' + name + ':';
  const pos = ta.selectionStart;
  ta.value = ta.value.slice(0, pos) + token + ta.value.slice(ta.selectionEnd);
  ta.selectionStart = ta.selectionEnd = pos + token.length;
  ta.focus();
  document.getElementById('emoji-picker').classList.remove('show');
  // Track frequency
  _trackEmojiFrequency(name);
}

function _trackEmojiFrequency(emoji) {
  try {
    const freq = JSON.parse(localStorage.getItem('ftz_emoji_freq')||'{}');
    freq[emoji] = (freq[emoji]||0) + 1;
    // Keep only top 100 entries
    const sorted = Object.entries(freq).sort((a,b) => b[1]-a[1]).slice(0,100);
    localStorage.setItem('ftz_emoji_freq', JSON.stringify(Object.fromEntries(sorted)));
  } catch (e) { console.debug('[Emoji] frequency save failed', e); }
}

// Emoji info popover — right-click an emoji to see details
function _showEmojiInfoPopover(emoji, type, e) {
  document.querySelector('.emoji-info-popover')?.remove();
  const pop = document.createElement('div');
  pop.className = 'emoji-info-popover';
  let nameStr = '';
  // Try to find shortcode name
  if (type === 'unicode') {
    const entry = Object.entries(EMOJI_SHORTCODES).find(([,v]) => v === emoji);
    nameStr = entry ? ':' + entry[0] + ':' : emoji;
  } else {
    nameStr = ':' + emoji + ':';
  }
  const isFtz = FORTIZED_EMOJI_MAP[emoji];
  const bName = curBastion !== null ? (CU?.bastions?.[curBastion]?.name || 'Bastion') : '';
  const bCustom = curBastion !== null ? (CU?.bastions?.[curBastion]?.customEmojis||[]).find(ce => ce.name === emoji) : null;
  let typeLabel = 'Default Emoji';
  let usageLabel = 'Can be used anywhere on Fortized.';
  if (isFtz) { typeLabel = 'Official Fortized Guide Emoji'; usageLabel = 'Official Fortized Guide Emoji — available everywhere.'; }
  if (bCustom) { typeLabel = 'Bastion Emoji'; usageLabel = 'Available in: ' + escapeHTML(bName); }
  const previewHTML = type === 'unicode'
    ? `<img src="${emojiToTwemojiUrl(emoji)}" style="width:48px;height:48px;object-fit:contain;" onerror="this.outerHTML='<span style=\\'font-size:42px\\'>${emoji}</span>'">`
    : (isFtz ? `<img src="${escapeHTML(isFtz)}" style="width:48px;height:48px;object-fit:contain;">` : (bCustom ? `<img src="${escapeHTML(bCustom.data)}" style="width:48px;height:48px;object-fit:contain;">` : emoji));
  pop.innerHTML = `<div class="eip-preview">${previewHTML}</div><div class="eip-name">${escapeHTML(nameStr)}</div><div class="eip-type">${typeLabel}</div><div style="font-size:10px;color:rgba(255,255,255,.25);text-align:center;margin-top:6px;">${usageLabel}</div>`;
  document.body.appendChild(pop);
  // Position near click
  const x = Math.min(e.clientX, window.innerWidth - 240);
  const y = Math.min(e.clientY, window.innerHeight - 200);
  pop.style.left = x + 'px'; pop.style.top = y + 'px';
  setTimeout(() => document.addEventListener('mousedown', function _c(ev) { if (!pop.contains(ev.target)) { pop.remove(); document.removeEventListener('mousedown', _c); } }), 50);
}
function _showEmojiInfo() {
  toast('Right-click any emoji for info', 'info');
}

function insertCustomEmoji(name, data) {
  insertFortizedEmoji(name, data);
}


