async function updateNotifBadge() {
  const badge=document.getElementById('notif-badge');
  const tbBadge=document.getElementById('tb-notif-badge');
  let unread = 0;
  try { unread = await FortizedSocial.getUnreadCount(CU.username) || 0; } catch (e) { console.debug('[Notif] unread count failed', e); }
  if(badge){badge.textContent=unread;badge.style.display=unread>0?'flex':'none';}
  if(tbBadge){tbBadge.textContent=unread;tbBadge.style.display=unread>0?'block':'none';}
  setFaviconNotif(unread>0);
  // Also clear bastion rail notification badges if no unread
  if (unread === 0) {
    document.querySelectorAll('.rail-notif-badge').forEach(b=>b.remove());
  }
}

async function toggleNotifPanel() {
  // Use new centered modal style (matching deep search)
  const existing = document.getElementById('notif-panel-v2');
  if (existing) {
    _closeEl('notif-panel-v2'); _closeEl('notif-panel-v2-overlay');
    notifPanelOpen = false;
    return;
  }
  notifPanelOpen = true;
  const overlay = document.createElement('div');
  overlay.className = 'notif-panel-v2-overlay';
  overlay.id = 'notif-panel-v2-overlay';
  overlay.onclick = () => { _closeEl('notif-panel-v2'); _closeEl('notif-panel-v2-overlay'); notifPanelOpen=false; };
  document.body.appendChild(overlay);
  const panel = document.createElement('div');
  panel.className = 'notif-panel-v2';
  panel.id = 'notif-panel-v2';
  panel.innerHTML = `
    <div class="modal-bar" style="flex-shrink:0;border-radius:18px 18px 0 0;"></div>
    <div class="npv-header">
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="var(--accent)" stroke-width="2"><path d="M18 8A6 6 0 006 8c0 7-3 9-3 9h18s-3-2-3-9"/><path d="M13.73 21a2 2 0 01-3.46 0"/></svg>
      <h3>Inbox</h3>
      <button onclick="markAllRead()" style="background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.06);border-radius:8px;color:rgba(255,255,255,.45);font-size:11px;font-weight:600;padding:5px 12px;cursor:pointer;transition:all .12s;">Mark all read</button>
      <button onclick="_closeEl('notif-panel-v2');_closeEl('notif-panel-v2-overlay');notifPanelOpen=false" style="background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.06);border-radius:8px;color:rgba(255,255,255,.4);cursor:pointer;width:30px;height:30px;display:flex;align-items:center;justify-content:center;transition:all .12s;">✕</button>
    </div>
    <div class="npv-tabs" id="npv-tabs">
      <button class="npv-tab active" onclick="_setNotifTab('all',this)">All</button>
      <button class="npv-tab" onclick="_setNotifTab('unread',this)">Unread</button>
      <button class="npv-tab" onclick="_setNotifTab('mentions',this)">Mentions</button>
      <button class="npv-tab" onclick="_setNotifTab('friends',this)">Friends</button>
    </div>
    <div class="npv-list" id="np-list-v2"><div style="text-align:center;padding:30px;display:flex;flex-direction:column;align-items:center;gap:8px;"><div class="skeleton skeleton-text" style="width:80%;height:14px;"></div><div class="skeleton skeleton-text" style="width:60%;height:14px;"></div><div class="skeleton skeleton-text" style="width:40%;height:14px;"></div></div></div>`;
  document.body.appendChild(panel);
  await buildNotifList();
}
let _notifTabFilter = 'all';
function _setNotifTab(tab, btn) {
  _notifTabFilter = tab;
  document.querySelectorAll('.npv-tab').forEach(t => t.classList.remove('active'));
  btn.classList.add('active');
  buildNotifList();
}

async function buildNotifList() {
  const list=document.getElementById('np-list-v2')||document.getElementById('np-list'); if(!list) return;
  try {
  let notifs=[];
  try{notifs=await FortizedSocial.getNotifications(CU.username)||[];}catch(e){console.warn('[inbox] notif fetch:',e);}
  // Robust normalization — handle all possible Firebase return types
  if (!Array.isArray(notifs)) {
    if (notifs && typeof notifs === 'object') notifs = Object.values(notifs);
    else notifs = [];
  }
  // Filter out null/undefined/non-object entries that can cause rendering errors
  notifs = notifs.filter(n => n && typeof n === 'object' && n.type);

  // Fetch user's support tickets and merge into notifications
  try {
    const allTickets = await FortizedSocial.adminGetSupportTickets();
    Object.entries(allTickets).forEach(([id, t]) => {
      if (!t || t.username !== CU.username) return;
      notifs.push({
        type: 'support_ticket',
        from: 'Support',
        time: t.submittedAt || t.createdAt || new Date().toISOString(),
        read: t.status === 'closed',
        data: { subject: t.subject || '', status: t.status || 'open', category: t.category || '', ticketId: id }
      });
    });
  } catch(e) { /* silently skip */ }

  // Sort by time descending
  notifs.sort((a,b) => new Date(b.time||0) - new Date(a.time||0));

  // Apply tab filter
  if (_notifTabFilter === 'unread') notifs = notifs.filter(n => !n.read);
  else if (_notifTabFilter === 'mentions') notifs = notifs.filter(n => n.type === 'mention');
  else if (_notifTabFilter === 'friends') notifs = notifs.filter(n => n.type === 'friend_request' || n.type === 'friend_accept');

  if(!notifs.length){
    list.innerHTML='<div style="display:flex;flex-direction:column;align-items:center;justify-content:center;padding:40px 20px;gap:10px;">'
      +'<svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="rgba(255,255,255,.15)" stroke-width="1.5"><path d="M18 8A6 6 0 006 8c0 7-3 9-3 9h18s-3-2-3-9"/><path d="M13.73 21a2 2 0 01-3.46 0"/></svg>'
      +'<div style="font-size:13px;color:var(--muted);text-align:center;">All caught up!<br><span style="font-size:11.5px;opacity:.6;">No new notifications</span></div></div>';
    return;
  }
  const svgs = {
    friend_request:'<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M17 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 00-3-3.87"/><path d="M16 3.13a4 4 0 010 7.75"/></svg>',
    friend_accept: '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 11.08V12a10 10 0 11-5.93-9.14"/><polyline points="22,4 12,14.01 9,11.01"/></svg>',
    dm:            '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15a2 2 0 01-2 2H7l-4 4V5a2 2 0 012-2h14a2 2 0 012 2z"/></svg>',
    mention:       '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="4"/><path d="M16 8v5a3 3 0 006 0v-1a10 10 0 10-3.92 7.94"/></svg>',
    bastion:       '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 9l9-7 9 7v11a2 2 0 01-2 2H5a2 2 0 01-2-2z"/></svg>',
    call:          '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 16.92v3a2 2 0 01-2.18 2 19.79 19.79 0 01-8.63-3.07A19.5 19.5 0 013.07 9.8 19.79 19.79 0 012 1.18a2 2 0 012-2h3a2 2 0 012 1.72c.127.96.361 1.903.7 2.81a2 2 0 01-.45 2.11L8.09 6.91a16 16 0 006 6l1.27-1.27a2 2 0 012.11-.45c.907.339 1.85.573 2.81.7A2 2 0 0122 16.92z"/></svg>',
    support_ticket:'<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14.5 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V7.5L14.5 2z"/><polyline points="14,2 14,8 20,8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>',
  };
  const colors = {
    friend_request:'#60a5fa', friend_accept:'#3ecf6e', dm:'#a78bfa',
    mention:'#ffd93e', bastion:'var(--accent)', call:'#3ecf6e', support_ticket:'#38bdf8',
  };
  // Pre-fetch user pfps for notifications that have a 'from' user
  const _notifUsers = {};
  const _notifUsernames = [...new Set(notifs.slice(0,25).filter(n=>n.from && n.type!=='support_ticket').map(n=>n.from))];
  await Promise.allSettled(_notifUsernames.map(async uname => {
    try { const u = await FortizedSocial.getUserByName(uname); if (u) _notifUsers[uname] = u; } catch (e) { console.debug('[Notif] user lookup failed', e); }
  }));

  list.innerHTML = notifs.slice(0,25).map(n => {
    const svg = svgs[n.type] || svgs.bastion;
    const col = colors[n.type] || 'var(--accent)';
    let text='';
    if(n.type==='friend_request') text='<strong>'+escapeHTML(n.from||'')+'</strong> sent you a friend request';
    else if(n.type==='friend_accept') text='<strong>'+escapeHTML(n.from||'')+'</strong> accepted your request — you are now friends!';
    else if(n.type==='dm') text='<strong>'+escapeHTML(n.from||'')+'</strong>: '+escapeHTML((n.data?.preview||'').slice(0,60));
    else if(n.type==='mention') text='<strong>'+escapeHTML(n.from||'')+'</strong> mentioned you';
    else if(n.type==='call') text='<strong>'+escapeHTML(n.from||'')+'</strong> called you';
    else if(n.type==='support_ticket') {
      const st = n.data?.status==='closed'?'<span style="color:var(--green);">Closed</span>':'<span style="color:#38bdf8;">Open</span>';
      text='<strong>Support Ticket</strong>: '+escapeHTML((n.data?.subject||'').slice(0,50))+' — '+st;
    }
    else text='New notification';
    const _alreadyFriends = n.type==='friend_request' && (CU?.friends||[]).includes(n.from);
    const _stillPending = n.type==='friend_request' && !_alreadyFriends && (CU?.friendRequestsReceived||[]).includes(n.from);
    const actions = _stillPending
      ? '<div class="np-actions"><button class="np-accept" onclick="event.stopPropagation();acceptFriend(\''+escapeHTML(n.from||'')+'\');buildNotifList()">Accept</button></div>'
      : (n.type==='friend_request' && _alreadyFriends
        ? '<div class="np-actions"><span style="font-size:11px;color:var(--green);font-weight:600;">Friends</span></div>'
        : '');
    // Use user's actual profile picture for personal notifications
    const _nu = _notifUsers[n.from];
    const useAvatar = n.from && n.type !== 'support_ticket' && _nu;
    const iconHtml = useAvatar
      ? '<div class="np-icon" style="padding:0;border:none;background:none;overflow:hidden;">'+buildAvatarHTML(_nu.pfp||null, _nu.displayName||n.from, 36)+'</div>'
      : '<div class="np-icon" style="color:'+col+';background:'+col+'1a;border-color:'+col+'33;">'+svg+'</div>';
    const clickAction = n.type==='dm' ? "FortizedSocial.markNotificationReadBySource(CU.username,'dm','"+escapeHTML(n.from||'')+"').then(()=>updateNotifBadge()).catch(()=>{});openDMChat('"+escapeHTML(n.from||'')+"');toggleNotifPanel()"
      : (n.type==='friend_request'||n.type==='friend_accept') ? "FortizedSocial.markNotificationReadBySource(CU.username,'"+n.type+"','"+escapeHTML(n.from||'')+"').then(()=>updateNotifBadge()).catch(()=>{});viewUserProfile('"+escapeHTML(n.from||'')+"');toggleNotifPanel()"
      : (n.type==='mention') ? "FortizedSocial.markNotificationReadBySource(CU.username,'mention','"+escapeHTML(n.from||'')+"').then(()=>updateNotifBadge()).catch(()=>{});toggleNotifPanel()"
      : (n.type==='call') ? "FortizedSocial.markNotificationReadBySource(CU.username,'call','"+escapeHTML(n.from||'')+"').then(()=>updateNotifBadge()).catch(()=>{});toggleNotifPanel()"
      : '';
    return '<div class="np-item '+(n.read?'':'unread')+'" onclick="'+clickAction+'" style="cursor:'+(clickAction?'pointer':'default')+';">'
      +iconHtml
      +'<div class="np-text"><p>'+text+'</p>'
      +'<div class="np-time">'+formatTimeAgo(n.time||'')+'</div>'+actions+'</div></div>';
  }).join('');
  } catch(err) {
    console.error('[inbox] buildNotifList error:', err);
    list.innerHTML='<div style="display:flex;flex-direction:column;align-items:center;justify-content:center;padding:40px 20px;gap:10px;">'
      +'<svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="rgba(248,113,113,.3)" stroke-width="1.5"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>'
      +'<div style="font-size:13px;color:var(--muted);text-align:center;">Something went wrong<br><span style="font-size:11.5px;opacity:.6;">Try closing and reopening your inbox</span></div></div>';
  }
}

let _markingAllRead = false;
async function markAllRead(){
  _markingAllRead = true;
  // Optimistically update UI immediately
  const badge=document.getElementById('notif-badge');
  const tbBadge=document.getElementById('tb-notif-badge');
  if(badge){badge.textContent='0';badge.style.display='none';}
  if(tbBadge){tbBadge.textContent='0';tbBadge.style.display='none';}
  setFaviconNotif(false);
  _clearAllDMBadges();
  try{
    await FortizedSocial.markNotificationsRead(CU.username);
  }catch(e){console.warn('[inbox] markAllRead:',e);}
  // Rebuild after DB is updated
  try{await updateNotifBadge();}catch{}
  try{await buildNotifList();}catch{}
  _markingAllRead = false;
}
function _clearAllDMBadges(){document.querySelectorAll('.friend-item').forEach(fi=>{fi.style.fontWeight='';fi.classList.remove('dm-unread');const badge=fi.querySelector('.dm-unread-badge');if(badge)badge.remove();});document.querySelectorAll('.rail-notif-badge').forEach(b=>b.remove());}

// ════════════════════════════════════════════
// USER PROFILE POPUP
// ════════════════════════════════════════════
async function viewUserProfile(username) {
  let u = null;
  try { u = await FortizedSocial.getUserByName(username); } catch (e) { console.debug('[Profile] user lookup failed', e); }
  if (!u) u = { username, displayName: username };
  if (username === CU.username) u = { ...u, ...CU };

  let status = 'offline';
  // Use live Socket.IO presence first, fallback to DB
  if (username === CU.username) {
    status = CU.status || 'online';
  } else {
    try {
      const presenceResult = await FortizedSocial.queryPresence([username]);
      if (presenceResult && presenceResult[username]) {
        status = presenceResult[username].status || 'offline';
      } else {
        // Socket.IO unavailable, fall back to DB
        try { status = await FortizedSocial.getStatus(username); } catch (e) { console.debug('[Profile] status fallback failed', e); }
      }
    } catch (e) {
      try { status = await FortizedSocial.getStatus(username); } catch (e) { console.debug('[Profile] status fallback failed', e); }
    }
  }
  subscribeProfileStatus(username);

  const isOwn = username === CU.username;
  const isFriend = (CU.friends||[]).includes(username);
  const hasPending = (CU.friendRequestsSent||[]).includes(username);
  const isBlocked = isUserBlocked(username);
  const ignored = isUserIgnored(username);
  const hasRadiancePlus = u.radiancePlus && new Date(u.radiancePlus) > new Date();
  const profileTheme = hasRadiancePlus ? (u.profileTheme || null) : null;
  // Auto-generate profile card background from blended theme colors
  const profileCardBg = profileTheme && profileTheme.color1 && profileTheme.color2
    ? _blendColorsForProfileCard(profileTheme.color1, profileTheme.color2)
    : null;

  const sc = FtzStatus.color(status);
  const socials = u.socials || {};
  const customStatus = u.customStatus;
  const games = u.gameCollection || [];

  // Profile theme border
  const themeBorder = profileTheme
    ? `background:linear-gradient(135deg,${profileTheme.color1},${profileTheme.color2});padding:3px;border-radius:20px;`
    : '';
  // Show custom banner if user has Radiance + banner, otherwise a nice gradient
  const hasUserRadiance = u.radianceUntil && new Date(u.radianceUntil) > new Date();
  const userBanner = (u.banner && hasUserRadiance) ? u.banner : null;
  const bannerBg = userBanner ? 'transparent' : `linear-gradient(135deg,${profileTheme?profileTheme.color1+'88':'#141a2e'},${profileTheme?profileTheme.color2+'66':'#1a1030'},${profileTheme?profileTheme.color1+'44':'#0f1828'})`;

  const modalEl = document.getElementById('user-modal-body');
  if (!modalEl) { openModal('modal-user'); return; }

  const _mutualFriendNames = isOwn ? [] : (CU?.friends||[]).filter(f => f !== CU?.username && f !== u.username && (u.friends||[]).includes(f));
  // Fetch real profile data (pfps) for mutual friends
  const _mutualFriendsData = {};
  if (_mutualFriendNames.length) {
    await Promise.all(_mutualFriendNames.slice(0, 20).map(async f => {
      try { const ud = await FortizedSocial.getUserByName(f); if (ud) _mutualFriendsData[f] = ud; } catch (e) { console.debug('[Profile] mutual friend lookup failed', e); }
    }));
  }
  const _mutualFriends = _mutualFriendNames;
  const _memberSince = (u.joinedAt||u.createdAt) ? new Date(u.joinedAt||u.createdAt).toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'}) : null;
  const _userNote = _getUserNote(username);

  // Build right-panel tab content (Activity tab — multi-activity support)
  const _activityContent = [];

  // Support both new activityState and legacy gameActivity
  let activitiesToDisplay = [];
  if (u.activityState?.activities?.length) {
    activitiesToDisplay = u.activityState.activities.sort((a, b) => (b.priority || 2) - (a.priority || 2));
  } else if (u.gameActivity?.name) {
    // Convert legacy gameActivity to new format for display
    activitiesToDisplay = [{
      id: u.gameActivity._spotify ? 'spotify' : 'game',
      type: u.gameActivity._spotify ? 'listening' : 'playing',
      name: u.gameActivity.name,
      icon: u.gameActivity.icon || '🎮',
      since: u.gameActivity.since,
      priority: u.gameActivity._spotify ? 3 : 2,
      metadata: {
        coverThumb: u.gameActivity.coverThumb,
        genre: u.gameActivity.genre,
        details: u.gameActivity.details,
        startedAt: u.gameActivity.startedAt,
        spotifyTrack: u.gameActivity.spotifyTrack,
        spotifyArtist: u.gameActivity.spotifyArtist,
        spotifyAlbumArt: u.gameActivity.spotifyAlbumArt
      }
    }];
  }

  if (activitiesToDisplay.length) {
    _activityContent.push(`
      <div class="up-right-section">
        <div class="up-right-section-title">Active Now</div>
        <div class="activities-list">
          ${activitiesToDisplay.map(activity => {
            const statusColor = FtzStatus.color(u.status || 'online');
            const displayText = formatActivityDisplay(activity);
            const coverThumb = activity.metadata?.coverThumb || activity.metadata?.spotifyAlbumArt;
            const icon = activity.icon || '🎮';
            const elapsedHTML = activity.since
              ? `<div style="font-size:10px;color:${statusColor}88;margin-top:3px;display:flex;align-items:center;gap:4px;"><svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>${_formatActivityElapsed(activity.since)}</div>`
              : '';

            return `<div class="activity-card ${activity.id === 'spotify' ? 'spotify' : ''}" style="background:linear-gradient(135deg,${statusColor}08,transparent);border-left-color:${statusColor};">
              <div class="ac-icon" style="background:${statusColor}15;border-color:${statusColor}22;color:${statusColor};font-size:18px;width:40px;height:40px;">
                ${coverThumb ? `<img src="${escapeHTML(coverThumb)}" style="width:100%;height:100%;border-radius:8px;object-fit:cover;">` : icon}
              </div>
              <div class="ac-content">
                <div class="ac-title">${escapeHTML(displayText)}</div>
                ${activity.state ? `<div class="ac-detail">${escapeHTML(activity.state)}</div>` : ''}
                ${activity.metadata?.genre ? `<div style="font-size:10px;color:rgba(255,255,255,.25);margin-top:1px;">${escapeHTML(activity.metadata.genre)}</div>` : ''}
                ${elapsedHTML}
              </div>
            </div>`;
          }).join('')}
        </div>
      </div>
    `);
  }

  if (_mutualFriends.length) _activityContent.push(`<div class="up-right-section"><div class="up-right-section-title">Mutual Friends — ${_mutualFriends.length}</div><div style="display:flex;align-items:center;flex-wrap:wrap;gap:2px;">${_mutualFriends.slice(0,12).map(f => `<div class="up-mutual-av" title="${escapeHTML(f)}" onclick="closeModal('modal-user');viewUserProfile('${escapeHTML(f)}')">${buildAvatarHTML(null,f,28)}</div>`).join('')}${_mutualFriends.length>12?`<div style="width:30px;height:30px;border-radius:50%;background:rgba(255,255,255,.05);display:flex;align-items:center;justify-content:center;font-size:9px;color:rgba(255,255,255,.3);margin-left:-5px;border:2px solid var(--panel);font-weight:700;">+${_mutualFriends.length-12}</div>`:''}</div></div>`);
  if (!_activityContent.length) _activityContent.push(`<div class="ftz-empty"><div class="ftz-empty-icon">🎮</div><div class="ftz-empty-text">No recent activity</div></div>`);

  modalEl.innerHTML = `
    <div style="${themeBorder}">
    <div class="up-card" style="position:relative;${profileCardBg ? `background:${profileCardBg};` : ''}">
    ${isBlocked ? `<div class="profile-blocked-overlay" id="profile-blocked-overlay">
      <div class="pbo-icon" style="font-size:32px;color:rgba(248,113,113,.5);"><svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="4.93" y1="4.93" x2="19.07" y2="19.07"/></svg></div>
      <div class="pbo-text">You blocked ${escapeHTML(username)}</div>
      <div class="pbo-sub">Their profile is hidden</div>
      <button class="pbo-reveal" onclick="document.getElementById('profile-blocked-overlay').style.display='none'">Show Profile</button>
    </div>` : ''}
    <!-- LEFT PANEL -->
    <div class="up-left">
      <!-- Banner -->
      <div class="up-left-banner" style="background:${bannerBg};">
        ${userBanner ? `<img src="${escapeHTML(userBanner)}" style="width:100%;height:100%;object-fit:cover;">` : ''}
        ${profileTheme ? `<div style="position:absolute;bottom:0;left:0;right:0;height:2px;background:linear-gradient(90deg,${profileTheme.color1},${profileTheme.color2});opacity:.6;z-index:1;"></div>` : ''}
      </div>
      <!-- Avatar -->
      <div class="up-left-av-area">
        <div class="profile-decoration-wrap" style="position:relative;">
          <div class="up-left-av">${buildAvatarHTML(u.pfp, u.displayName||u.username, 88)}</div>
          ${u.activeDecoration ? `<img src="${getDecorationSrc(u.activeDecoration)||''}" class="profile-decoration-overlay-lg" onerror="this.style.display='none'">` : ''}
          <span class="profile-status-dot" data-for="${escapeHTML(u.username)}" data-dot-size="22" style="position:absolute;bottom:3px;right:3px;width:22px;height:22px;z-index:3;">${FtzStatus.dotSvg(u.status||'offline', 22)}</span>
        </div>
      </div>
      <!-- Name -->
      <div class="up-left-info">
        <div class="up-left-name" style="font-family:${getDisplayFont(u)};${_getDisplayEffectCSS(u.displayEffect||'solid',u.displayColor||'#fff')}">
          ${escapeHTML(u.displayName||u.username)}
        </div>
        <div class="up-left-uname">@${escapeHTML(u.username)}${u.pronouns ? ` <span style="color:rgba(255,255,255,.25);font-weight:400;">&middot; ${escapeHTML(u.pronouns)}</span>` : ''}</div>
      </div>
      <!-- Status -->
      <div class="up-left-status">
        <div style="display:inline-flex;align-items:center;gap:6px;padding:4px 12px;background:rgba(255,255,255,.035);border:1px solid rgba(255,255,255,.05);border-radius:var(--radius-pill);">
          <span class="profile-status-dot" data-for="${escapeHTML(u.username)}" data-dot-size="10" style="width:10px;height:10px;display:inline-flex;">${FtzStatus.dotSvg(u.status||'offline', 10)}</span>
          <span class="profile-status-label" data-for="${escapeHTML(u.username)}" style="font-size:11.5px;color:rgba(255,255,255,.5);font-weight:600;">${FtzStatus.publicLabel(status)}</span>
        </div>
        ${customStatus?.text ? `<div style="font-size:10.5px;padding:4px 10px;display:inline-flex;align-items:center;gap:4px;background:rgba(255,255,255,.035);border:1px solid rgba(255,255,255,.05);border-radius:var(--radius-pill);color:rgba(255,255,255,.4);">${customStatus.emoji ? `<img src="${emojiToTwemojiUrl(customStatus.emoji)}" style="width:13px;height:13px;" onerror="this.outerHTML='${customStatus.emoji}'">` : ''} ${escapeHTML(customStatus.text)}</div>` : `<div class="profile-custom-status" data-for="${escapeHTML(u.username)}" style="display:none;"></div>`}
      </div>
      <!-- Badges -->
      <div class="up-left-badges">${renderBadgesHTML(u)}</div>
      <div class="up-left-divider"></div>
      <!-- Bio -->
      ${u.bio ? `<div class="up-left-section"><div class="up-left-section-title">About Me</div><div class="up-left-section-body">${parseMD(escapeHTML(u.bio.slice(0,300)))}${u.bio.length>300?'…':''}</div></div>` : ''}
      <!-- Member Since -->
      ${_memberSince ? `<div class="up-left-section"><div class="up-left-section-title">Member Since</div><div style="font-size:12.5px;color:rgba(255,255,255,.45);font-weight:500;">${_memberSince}</div></div>` : ''}
      <!-- Roles -->
      ${_currentView === 'bastion' && curBastion !== null ? `<div class="up-left-divider"></div><div class="up-left-section"><div class="up-left-section-title">Roles</div><div style="display:flex;flex-wrap:wrap;gap:5px;">${renderUserRoleTags(username)}</div></div>` : ''}
      <!-- Connections -->
      ${Object.values(socials).some(Boolean) ? `<div class="up-left-divider"></div><div class="up-left-section"><div class="up-left-section-title">Connections</div><div style="display:flex;flex-direction:column;gap:5px;">${_CONN_PLATFORMS.filter(p=>socials[p.key]).map(p=>`<a href="#" onclick="openExternalLink(event,'${escapeHTML(socials[p.key])}')" class="up-social-link" style="background:${p.color}0a;color:${p.color};border-color:${p.color}18;padding:7px 14px;font-size:11.5px;display:flex;align-items:center;gap:8px;">${_connIcon(p.key)} ${p.label}</a>`).join('')}</div></div>` : ''}
      <!-- Note -->
      ${_userNote ? `<div class="up-left-section"><div class="up-left-section-title">Note</div><div style="font-size:12px;color:rgba(255,255,255,.32);font-style:italic;line-height:1.55;">${escapeHTML(_userNote.slice(0,200))}</div></div>` : ''}
      <!-- Actions at bottom -->
      <div class="up-left-actions">
        ${isOwn ? `<button class="up-action-edit" onclick="closeModal('modal-user');showView('profile')"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/></svg> Edit Profile</button>` :
         `<div style="display:flex;gap:8px;flex-wrap:wrap;">
            ${isBlocked ? '' : `<button class="up-action-msg" onclick="closeModal('modal-user');openDMView('${escapeHTML(username)}')"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M21 11.5a8.38 8.38 0 01-.9 3.8 8.5 8.5 0 01-7.6 4.7 8.38 8.38 0 01-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 01-.9-3.8 8.5 8.5 0 014.7-7.6 8.38 8.38 0 013.8-.9h.5a8.48 8.48 0 018 8v.5z"/></svg> Message</button>`}
            ${isBlocked ? '' :
              isFriend ? `<button class="up-action-unfriend" onclick="closeModal('modal-user');removeFriend('${escapeHTML(username)}')">Unfriend</button>` :
              hasPending ? `<button disabled style="padding:10px 16px;background:rgba(255,255,255,.035);border:1px solid rgba(255,255,255,.06);border-radius:12px;color:rgba(255,255,255,.25);font-size:12px;">Pending…</button>` :
              `<button class="up-action-add" onclick="quickAddFriend('${escapeHTML(username)}')"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M16 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/><circle cx="8.5" cy="7" r="4"/><line x1="20" y1="8" x2="20" y2="14"/><line x1="23" y1="11" x2="17" y2="11"/></svg> Add</button>`}
          </div>
          <div style="display:flex;gap:6px;margin-top:10px;">
            <button class="up-action-util ${isBlocked?'blocked':''}" onclick="toggleBlockUser('${escapeHTML(username)}')">${isBlocked?'Unblock':'Block'}</button>
            ${!isBlocked ? (ignored
              ? `<button class="up-action-util ignored" onclick="unignoreUser('${escapeHTML(username)}')">Unignore</button>`
              : `<button class="up-action-util" onclick="showIgnorePicker('${escapeHTML(username)}')">Ignore</button>`)
            : ''}
            <button class="up-action-util" onclick="reportUser('${escapeHTML(username)}')">Report</button>
          </div>`}
      </div>
    </div>
    <!-- RIGHT PANEL -->
    <div class="up-right">
      <div class="up-right-tabs">
        <div class="up-right-tab active" onclick="_upSwitchTab(this,'up-tab-activity')">Board</div>
        <div class="up-right-tab" onclick="_upSwitchTab(this,'up-tab-activity-detail')">Activity</div>
        ${!isOwn ? `<div class="up-right-tab" onclick="_upSwitchTab(this,'up-tab-mutuals')">Mutual Friends</div>` : ''}
      </div>
      <div class="up-right-content">
        <!-- Board tab: widgets, games, general info -->
        <div id="up-tab-activity">
          <div class="up-right-section" id="up-widgets-container"></div>
          ${isOwn ? `<div id="up-widget-manager" style="margin-top:12px;padding:0 4px;text-align:center;"><button onclick="_openAddWidgetPanel()" class="add-widget-btn"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>Add Widgets</button></div>` : ''}
          ${games.length && !(u.profileWidgets||[]).some(w=>w.enabled && w.id==='game_collection') ? `<div class="up-right-section">
            <div class="up-right-section-title">Game Collection</div>
            <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(145px,1fr));gap:8px;">
              ${games.map(g=>`<div class="game-col-item"><span style="font-size:17px;">${g.coverUrl ? `<img src='${escapeHTML(g.coverUrl)}' style='width:24px;height:32px;border-radius:4px;object-fit:cover;'>` : (g.icon||ftzIcon('gamepad','15'))}</span><span style="font-size:12.5px;color:rgba(255,255,255,.55);font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escapeHTML(g.name)}</span></div>`).join('')}
            </div>
          </div>` : ''}
        </div>
        <!-- Activity tab: current game activity -->
        <div id="up-tab-activity-detail" style="display:none;">${_activityContent.join('')}</div>
        <!-- Mutual Friends tab -->
        ${!isOwn ? `<div id="up-tab-mutuals" style="display:none;">
          ${_mutualFriends.length ? `<div class="up-right-section">
            <div class="up-right-section-title">Mutual Friends — ${_mutualFriends.length}</div>
            <div style="display:flex;flex-direction:column;gap:4px;">
              ${_mutualFriends.slice(0,20).map(f => { const mfd = _mutualFriendsData[f]; const mfPfp = mfd?.pfp || null; const mfDisplay = mfd?.displayName || f; return `<div style="display:flex;align-items:center;gap:11px;padding:8px 12px;border-radius:10px;cursor:pointer;transition:all .14s;" onclick="closeModal('modal-user');viewUserProfile('${escapeHTML(f)}')" class="up-mutual-row"><div style="width:32px;height:32px;border-radius:50%;overflow:hidden;flex-shrink:0;">${buildAvatarHTML(mfPfp,mfDisplay,30)}</div><div style="font-size:13px;color:rgba(255,255,255,.6);font-weight:600;">${escapeHTML(mfDisplay)}</div></div>`; }).join('')}
            </div>
          </div>` : `<div class="ftz-empty"><div class="ftz-empty-icon">👥</div><div class="ftz-empty-text">No mutual friends</div></div>`}
        </div>` : ''}
      </div>
    </div>
    </div>
    </div>`;

  openModal('modal-user');
  // Render profile widgets if the user has any enabled
  const widgetsContainer = document.getElementById('up-widgets-container');
  if (widgetsContainer) renderProfileWidgetsOnCard(u, widgetsContainer);
  // Widget manager is the "Add Widgets" button (already in HTML above)
}

function _upSwitchTab(tabEl, panelId) {
  const card = tabEl.closest('.up-card');
  if (!card) return;
  card.querySelectorAll('.up-right-tab').forEach(t => t.classList.remove('active'));
  tabEl.classList.add('active');
  card.querySelectorAll('.up-right-content > [id^="up-tab-"]').forEach(p => p.style.display = 'none');
  const panel = card.querySelector('#' + panelId);
  if (panel) panel.style.display = '';
}

async function quickAddFriend(username) {
  username = (username||"").trim().toLowerCase();
  if (isUserBlocked(username)) { toast("Can't send friend requests to blocked users", 'error'); return; }
  try{
    const r=await FortizedSocial.sendFriendRequest(CU.username,username);
    toast(r.msg,r.ok?'success':'error');
    if(r.ok){
      await refreshCU();
      // Friend add animations
      spawnHeartAnimation(window.innerWidth/2-20, window.innerHeight/2);
      setTimeout(()=>spawnHeartAnimation(window.innerWidth/2+30, window.innerHeight/2-30), 120);
      setTimeout(()=>spawnHeartAnimation(window.innerWidth/2, window.innerHeight/2+20), 250);
    }
  }catch{toast('An error occurred. Please try again.','error');}
}

