// CUSTOM DIALOGS
// ════════════════════════════════════════════
function showCustomInput(title,message,callback,defaultValue=''){
  const overlay=document.createElement('div');overlay.className='input-dialog-overlay';
  overlay.innerHTML=`<div class="input-dialog"><h3>${escapeHTML(title)}</h3><p>${escapeHTML(message)}</p><input type="text" id="cid-field" value="${escapeHTML(defaultValue)}" placeholder="Type here…"><div class="input-dialog-actions"><button class="btn-g" style="flex:1;justify-content:center;" id="cid-cancel">Cancel</button><button class="btn-a" style="flex:1;justify-content:center;" id="cid-ok">OK</button></div></div>`;
  document.body.appendChild(overlay);
  const inp=document.getElementById('cid-field');
  const ok=document.getElementById('cid-ok');
  const cancel=document.getElementById('cid-cancel');
  if(inp)inp.focus();
  ok.onclick=()=>{const v=inp.value;overlay.remove();callback(v);};
  cancel.onclick=()=>overlay.remove();
  inp.addEventListener('keydown',e=>{if(e.key==='Enter')ok.click();if(e.key==='Escape')cancel.click();});
}

function showCustomConfirm(message,callback){
  const overlay=document.createElement('div');
  overlay.className='ftz-confirm-overlay';
  overlay.innerHTML=`<div class="ftz-confirm-card">
    <div class="ftz-confirm-title">Confirm</div>
    <div class="ftz-confirm-text">${escapeHTML(message)}</div>
    <div class="ftz-confirm-actions">
      <button class="ftz-btn ftz-btn-ghost" id="cc-cancel">Cancel</button>
      <button class="ftz-btn ftz-btn-danger" id="cc-ok">Confirm</button>
    </div>
  </div>`;
  document.body.appendChild(overlay);
  document.getElementById('cc-ok').onclick=()=>{overlay.remove();callback();};
  document.getElementById('cc-cancel').onclick=()=>overlay.remove();
  overlay.onclick=e=>{if(e.target===overlay)overlay.remove();};
  overlay.addEventListener('keydown',e=>{if(e.key==='Escape')overlay.remove();});
  overlay.focus();
}

