function resolveReport(idx, action) {
  const reports = JSON.parse(localStorage.getItem('ftz_reports')||'[]');
  if (!reports[idx]) return;
  const report = reports[idx];
  const target = report.msgFrom || report.username || '';
  // Build content data from the report for showing on enforcement screens
  const _extractMedia = (text) => {
    if (!text) return [];
    const media = [];
    const imgRx = /https?:\/\/[^\s"'<>]+\.(?:png|jpe?g|gif|webp|svg|bmp)(?:\?[^\s"'<>]*)?/gi;
    let m; while ((m = imgRx.exec(text)) !== null) media.push({ type: 'image', url: m[0] });
    const vidRx = /https?:\/\/[^\s"'<>]+\.(?:mp4|webm|mov|ogg)(?:\?[^\s"'<>]*)?/gi;
    while ((m = vidRx.exec(text)) !== null) media.push({ type: 'video', url: m[0] });
    const ftzImgRx = /\[FTZIMG:([^\|]+)\|([^\]]+)\]/gi;
    while ((m = ftzImgRx.exec(text)) !== null) media.push({ type: 'image', url: m[2] });
    const ftzVidRx = /\[FTZVID:([^\|]+)\|([^\]]+)\]/gi;
    while ((m = ftzVidRx.exec(text)) !== null) media.push({ type: 'video', url: m[2] });
    const ftzGifRx = /\[FTZGIF:(https?:\/\/[^\]]+)\]/gi;
    while ((m = ftzGifRx.exec(text)) !== null) media.push({ type: 'image', url: m[1] });
    return media;
  };
  const contentData = { offendingText: report.msgText || '', offendingMedia: _extractMedia(report.msgText || '') };

  showCustomInput('Resolution Note', 'Add a note (optional):', async (reason) => {
    report.status = 'resolved';
    report.resolution = action;
    report.resolvedBy = CU.username;
    report.resolvedAt = new Date().toISOString();
    if (reason) report.resolutionNote = reason;
    localStorage.setItem('ftz_reports', JSON.stringify(reports));
    try { await FortizedSocial.adminSaveReport(report); } catch(e) { console.warn('Report sync failed:', e); }
    logAudit('report_'+action, target||report.reporter||'?', reason||action);

    // Delete the reported message and replace with moderation notice
    if (report.type === 'message' && report.msgId && report.bastionId && action !== 'dismissed') {
      try { await _deleteAndReplaceReportedMessage(report); } catch(e) { console.warn('Message replacement failed:', e); }
    }

    // Execute the action on the reported user
    if (action === 'warned' && target) {
      await FortizedSocial.adminWarnUser(target, {
        reason: reason || report.reason || 'Violation of Terms of Use',
        issuedBy: CU.username,
        issuedAt: new Date().toISOString(),
        contentData
      }).catch(()=>{});
      logAudit('warn', target, reason || report.reason);
      toast(`Warning issued to ${target}`, 'success');
    } else if (action === 'suspended' && target) {
      _reportSuspendTarget = target;
      _reportContentData = contentData;
      adminActionUser(target, 'suspend');
    } else if (action === 'banned' && target) {
      const bans = JSON.parse(localStorage.getItem('ftz_bans')||'[]');
      const banObj = { username: target, reason: reason || report.reason, bannedBy: CU.username, bannedAt: new Date().toISOString(), category: report.reason, offendingText: contentData.offendingText, offendingMedia: contentData.offendingMedia };
      bans.push(banObj);
      localStorage.setItem('ftz_bans', JSON.stringify(bans));
      _saveBanToFirebase(banObj);
      logAudit('ban', target, reason || report.reason);
      toast(`${target} has been banned`, 'success');
    } else if (action === 'dismissed') {
      toast('Report dismissed — no action taken', 'info');
    } else {
      toast('Report ' + action, 'success');
    }
    _loadAdminPage(adminTab);
  });
}

async function _deleteAndReplaceReportedMessage(report) {
  if (!report.bastionId || !report.msgId) return;
  const mediaRx = /\[FTZ(?:IMG|VID|AUD|GIF|STICKER):[^\]]*\]/i;
  try {
    const bastionRef = firebase.database().ref('bastions');
    const snap = await bastionRef.once('value');
    const bastions = snap.val() || {};
    for (const [bid, bastion] of Object.entries(bastions)) {
      if ((bastion.name || '') !== report.bastionId && bid !== report.bastionId) continue;
      const channels = bastion.channels || [];
      for (let ci = 0; ci < channels.length; ci++) {
        const msgs = channels[ci].messages || [];
        for (let mi = 0; mi < msgs.length; mi++) {
          if (msgs[mi].id === report.msgId) {
            const msgRef = firebase.database().ref(`bastions/${bid}/channels/${ci}/messages/${mi}`);
            const msgText = msgs[mi].text || '';
            const hasMedia = mediaRx.test(msgText);
            if (hasMedia) {
              // Message contains images/videos/gifs/files — delete the entire message
              await msgRef.remove();
            } else {
              // Text-only message — replace with moderation notice
              await msgRef.update({
                text: '[This message was deleted by Fortized moderation for being inappropriate.]',
                deletedByMod: true,
                deletedAt: new Date().toISOString()
              });
            }
            return;
          }
        }
      }
    }
  } catch(e) { console.warn('Message deletion failed:', e); }
}
let _reportSuspendTarget = null;
let _reportContentData = null;

async function _loadAdminSuspensions() {
  const el = document.getElementById('admin-suspensions-list');
  if (!el) return;
  try {
    const allUsers = await FortizedSocial.getUsers();
    const suspensions = [];
    for (const u of allUsers) {
      if (u.suspension) {
        const s = u.suspension;
        const isActive = new Date(s.until) > new Date();
        suspensions.push({ username: u.username, ...s, active: isActive });
      }
    }
    suspensions.sort((a,b) => (b.active?1:0) - (a.active?1:0) || new Date(b.suspendedAt||0) - new Date(a.suspendedAt||0));
    if (!suspensions.length) { el.innerHTML = '<div class="ftz-empty" style="padding:30px 20px;"><div class="ftz-empty-text">No suspensions found</div></div>'; return; }
    el.innerHTML = suspensions.map(s => `
      <div style="background:var(--panel,#1b1e25);border:1px solid ${s.active?'rgba(168,85,247,.15)':'rgba(255,255,255,.06)'};border-radius:10px;padding:12px 16px;display:flex;align-items:center;gap:10px;margin-bottom:6px;">
        <div style="width:8px;height:8px;border-radius:50%;background:${s.active?'#a855f7':'rgba(255,255,255,.15)'};${s.active?'box-shadow:0 0 6px rgba(168,85,247,.5);':''}flex-shrink:0;"></div>
        <div style="flex:1;">
          <div style="font-weight:600;font-size:13.5px;">${escapeHTML(s.username)} <span style="font-size:10px;font-weight:700;padding:1px 6px;border-radius:var(--radius-pill);${s.active?'background:rgba(168,85,247,.1);color:#a855f7;':'background:rgba(255,255,255,.05);color:rgba(255,255,255,.3);'}">${s.active?'ACTIVE':'EXPIRED'}</span></div>
          <div style="font-size:11.5px;color:rgba(255,255,255,.4);">Reason: ${escapeHTML(s.reason||'–')} · Duration: ${escapeHTML(s.duration||'–')}</div>
          <div style="font-size:10.5px;color:rgba(255,255,255,.25);">By ${escapeHTML(s.suspendedBy||'admin')} · Until ${_fmtDateEU(s.until)}</div>
        </div>
        <button onclick="_loadAdminPage('users');setTimeout(()=>{const el=document.getElementById('admin-user-search');if(el){el.value='${escapeHTML(s.username)}';adminSearchUser();}},150);" style="padding:4px 12px;background:rgba(96,165,250,.08);border:1px solid rgba(96,165,250,.18);border-radius:7px;color:var(--blue);font-size:12px;cursor:pointer;">Inspect</button>
        ${s.active?`<button onclick="FortizedSocial.adminUnsuspendUser('${escapeHTML(s.username)}').then(()=>{logAudit('unsuspend','${escapeHTML(s.username)}','Lifted by admin');toast('${escapeHTML(s.username)} unsuspended','success');_loadAdminPage('suspensions');});" style="padding:4px 12px;background:rgba(62,207,110,.08);border:1px solid rgba(62,207,110,.18);border-radius:7px;color:var(--green);font-size:12px;cursor:pointer;">Unsuspend</button>`:''}
      </div>`).join('');
  } catch(e) {
    el.innerHTML = '<div class="ftz-empty" style="padding:30px 20px;"><div class="ftz-empty-text">Failed to load suspensions</div></div>';
  }
}

let _allTickets = [];
const _sensitiveCategories = ['ban-appeal','suspend-appeal','report'];

async function _loadAdminSupportTickets() {
  const el = document.getElementById('admin-tickets-list');
  if (!el) return;
  try {
    const raw = await FortizedSocial.adminGetSupportTickets();
    _allTickets = Object.entries(raw).map(([id, t]) => ({ id, ...t }));
    // Filter: admins only see non-sensitive categories
    if (!isSuperAdmin()) {
      _allTickets = _allTickets.filter(t => !_sensitiveCategories.includes(t.category));
    }
    _allTickets.sort((a,b) => new Date(b.submittedAt||0) - new Date(a.submittedAt||0));
    _renderTickets();
  } catch(e) {
    el.innerHTML = '<div class="ftz-empty" style="padding:30px 20px;"><div class="ftz-empty-text">Failed to load tickets</div></div>';
  }
}

function _filterTickets() {
  _renderTickets();
}

function _renderTickets() {
  const el = document.getElementById('admin-tickets-list');
  if (!el) return;
  const filter = document.getElementById('_ticket-filter')?.value || 'all';
  let tickets = _allTickets;
  if (filter === 'open') tickets = tickets.filter(t => t.status !== 'closed');
  if (filter === 'closed') tickets = tickets.filter(t => t.status === 'closed');
  if (!tickets.length) { el.innerHTML = '<div class="ftz-empty" style="padding:30px 20px;"><div class="ftz-empty-text">No tickets found</div></div>'; return; }
  const catColors = {'ban-appeal':'#f87171','suspend-appeal':'#a855f7','report':'#fb923c','general':'#60a5fa','bug':'#3ecf6e','feedback':'#fbbf24','account-recovery':'#38bdf8'};
  el.innerHTML = tickets.map(t => {
    const catCol = catColors[t.category] || '#60a5fa';
    const isClosed = t.status === 'closed';
    const isSensitive = _sensitiveCategories.includes(t.category);
    return `<div style="background:var(--panel,#1b1e25);border:1px solid ${isSensitive?'rgba(248,113,113,.12)':'rgba(255,255,255,.06)'};border-radius:10px;padding:14px 18px;margin-bottom:8px;">
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:8px;">
        <div style="width:8px;height:8px;border-radius:50%;background:${isClosed?'rgba(255,255,255,.15)':'#3ecf6e'};${isClosed?'':'box-shadow:0 0 6px rgba(62,207,110,.5);'}flex-shrink:0;"></div>
        <div style="flex:1;font-weight:700;font-size:14px;">${escapeHTML(t.subject||'No Subject')}</div>
        <span style="font-size:10px;font-weight:700;padding:2px 8px;border-radius:var(--radius-pill);background:${catCol}15;color:${catCol};border:1px solid ${catCol}25;">${escapeHTML((t.category||'general').replace(/-/g,' ').toUpperCase())}</span>
        <span style="font-size:10px;font-weight:700;padding:2px 8px;border-radius:var(--radius-pill);${isClosed?'background:rgba(255,255,255,.05);color:rgba(255,255,255,.3);':'background:rgba(62,207,110,.1);color:var(--green);'}">${isClosed?'CLOSED':'OPEN'}</span>
      </div>
      <div style="font-size:12.5px;color:rgba(255,255,255,.55);margin-bottom:6px;line-height:1.5;white-space:pre-wrap;max-height:120px;overflow-y:auto;">${escapeHTML((t.message||'').slice(0,500))}</div>
      <div style="display:flex;align-items:center;gap:12px;font-size:11px;color:rgba(255,255,255,.3);">
        <span>From: <strong style="color:rgba(255,255,255,.5);">${escapeHTML(t.username||'Unknown')}</strong></span>
        <span>Email: ${escapeHTML(t.email||'–')}</span>
        <span>${_fmtDateEU(t.submittedAt)}</span>
        <div style="margin-left:auto;display:flex;gap:6px;">
          ${!isClosed?`<button onclick="_closeTicket('${t.id}')" style="padding:4px 12px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);border-radius:7px;color:rgba(255,255,255,.5);font-size:11px;cursor:pointer;">Close</button>`:`<button onclick="_reopenTicket('${t.id}')" style="padding:4px 12px;background:rgba(96,165,250,.08);border:1px solid rgba(96,165,250,.18);border-radius:7px;color:var(--blue);font-size:11px;cursor:pointer;">Reopen</button>`}
          ${isSuperAdmin()?`<button onclick="_deleteTicket('${t.id}')" style="padding:4px 12px;background:rgba(248,113,113,.08);border:1px solid rgba(248,113,113,.18);border-radius:7px;color:var(--red);font-size:11px;cursor:pointer;">Delete</button>`:''}
        </div>
      </div>
    </div>`;
  }).join('');
}

async function _closeTicket(id) {
  try {
    const tickets = await FortizedSocial.adminGetSupportTickets();
    if (tickets[id]) { tickets[id].status = 'closed'; tickets[id].closedBy = CU.username; tickets[id].closedAt = new Date().toISOString(); }
    await FortizedSocial.adminSaveSupportTickets(tickets);
  } catch (e) { console.warn('[Admin] ticket close failed', e); }
  toast('Ticket closed','success');
  _loadAdminSupportTickets();
}

async function _reopenTicket(id) {
  try {
    const tickets = await FortizedSocial.adminGetSupportTickets();
    if (tickets[id]) { tickets[id].status = 'open'; delete tickets[id].closedBy; delete tickets[id].closedAt; }
    await FortizedSocial.adminSaveSupportTickets(tickets);
  } catch (e) { console.warn('[Admin] ticket reopen failed', e); }
  toast('Ticket reopened','success');
  _loadAdminSupportTickets();
}

async function _deleteTicket(id) {
  if (!isSuperAdmin()) { toast('Only superadmins can delete tickets','error'); return; }
  try {
    const tickets = await FortizedSocial.adminGetSupportTickets();
    delete tickets[id];
    await FortizedSocial.adminSaveSupportTickets(tickets);
  } catch (e) { console.warn('[Admin] ticket delete failed', e); }
  toast('Ticket deleted','success');
  _loadAdminSupportTickets();
}

