async function deleteReportForever(idx) {
  if (!isSuperAdmin()) { toast('Only super admins can delete reports', 'error'); return; }
  const reports = JSON.parse(localStorage.getItem('ftz_reports')||'[]');
  if (!reports[idx]) return;
  const reportId = reports[idx].id;
  if (!confirm('Permanently delete this report? This cannot be undone.')) return;
  // Remove from localStorage
  reports.splice(idx, 1);
  localStorage.setItem('ftz_reports', JSON.stringify(reports));
  // Sync updated reports to Supabase
  try {
    for (const r of reports) { await FortizedSocial.adminSaveReport(r); }
  } catch(e) { console.warn('Report sync failed:', e); }
  logAudit('report_deleted', reportId||'unknown', 'Permanently deleted by super admin');
  toast('Report permanently deleted', 'success');
  _loadAdminPage(adminTab);
}

async function loadAllReportsFromFirebase() {
  toast('Syncing reports from Supabase…', 'info');
  try {
    const remote = await FortizedSocial.adminGetReports();
    const local = JSON.parse(localStorage.getItem('ftz_reports')||'[]');
    const remoteMap = new Map();
    remote.forEach(r => { if (r.id) remoteMap.set(r.id, r); });
    const merged = [...remote];
    local.forEach(lr => { if (lr.id && !remoteMap.has(lr.id)) merged.push(lr); });
    localStorage.setItem('ftz_reports', JSON.stringify(merged));
    // Push any local-only reports to Supabase
    for (const lr of local) {
      if (lr.id && !remoteMap.has(lr.id)) {
        try { await FortizedSocial.adminSaveReport(lr); } catch(e) { console.warn('[Admin] Report save:', e?.message); }
      }
    }
    toast('Reports synced: '+merged.length+' total', 'success');
  } catch(e) { toast('Sync failed','error'); }
  _loadAdminPage('reports');
}

async function adminGiveOnyx() {
  const username = document.getElementById('eco-username')?.value?.trim();
  const amount = parseInt(document.getElementById('eco-amount')?.value)||0;
  if (!username||!amount) { toast('Fill all fields','error'); return; }
  try {
    const u = await FortizedSocial.getUserByName(username);
    if (!u) { toast('User not found','error'); return; }
    await FortizedSocial.adminUpdateUserField(username, 'onyx', (u.onyx||0)+amount);
    logAudit('give_onyx', username, '+'+amount);
    toast('Gave '+amount+' Onyx to '+username,'success');
    document.getElementById('eco-username').value = '';
    document.getElementById('eco-amount').value = '';
    if (username===CU.username) await refreshCU();
  } catch { toast('An error occurred. Please try again.','error'); }
}

// ── Audit Log Filter ──
function _filterAuditLog() {
  const search = (document.getElementById('audit-search')?.value||'').toLowerCase();
  const actionFilter = document.getElementById('audit-filter')?.value||'';
  document.querySelectorAll('.audit-row').forEach(row => {
    const matchAction = !actionFilter || row.dataset.action === actionFilter;
    const matchSearch = !search || (row.dataset.text||'').toLowerCase().includes(search);
    row.style.display = (matchAction && matchSearch) ? '' : 'none';
  });
}

// ── Global Settings Helper ──
function _updateGlobalSetting(key, value) {
  const gs = JSON.parse(localStorage.getItem('ftz_global_settings')||'{}');
  gs[key] = value;
  localStorage.setItem('ftz_global_settings', JSON.stringify(gs));
  _globalSettings = gs;
  // Persist to Supabase for cross-device sync
  try { FortizedSocial.adminSaveGlobalSettings(gs); } catch(e) { console.warn('[Admin] Global settings save:', e?.message); }
  // Apply side effects
  if (key === 'maintenanceMode') {
    if (value) {
      logAudit('maintenance_on', 'system', 'Maintenance mode enabled by ' + CU.username);
      toast('Maintenance mode ENABLED — non-staff users will see a maintenance screen.', 'info');
    } else {
      logAudit('maintenance_off', 'system', 'Maintenance mode disabled by ' + CU.username);
      toast('Maintenance mode DISABLED — platform is live.', 'success');
    }
  } else if (key === 'disableRegistration') {
    if (value) {
      logAudit('registration_disabled', 'system', 'New registrations disabled by ' + CU.username);
      toast('New registrations DISABLED — signup page is blocked.', 'info');
    } else {
      logAudit('registration_enabled', 'system', 'New registrations enabled by ' + CU.username);
      toast('New registrations ENABLED — signups are open.', 'success');
    }
  } else if (key === 'disableBastionCreation') {
    logAudit('setting_changed', 'system', key + ' set to ' + value + ' by ' + CU.username);
    toast('Bastion creation ' + (value ? 'DISABLED' : 'ENABLED'), value ? 'info' : 'success');
  } else {
    // Generic audit for other settings
    logAudit('setting_changed', 'system', key + ' set to ' + value + ' by ' + CU.username);
  }
}

