async function adjustOnyx(direction) {
  const username = document.getElementById('eco-username')?.value?.trim();
  const amount = parseInt(document.getElementById('eco-amount')?.value);
  const reason = document.getElementById('eco-reason')?.value?.trim();
  if (!username || !amount || !reason) { toast('All fields required', 'error'); return; }
  const finalAmount = Math.abs(amount) * direction;
  try {
    const u = await FortizedSocial.getUserByName(username);
    if (!u) { toast('User not found', 'error'); return; }
    const newOnyx = Math.max(0, (u.onyx || 0) + finalAmount);
    await FortizedSocial.adminUpdateUserField(username, 'onyx', newOnyx);
    logAudit('onyx_adjust', username, `${direction>0?'+':''}${finalAmount} Onyx — ${reason}`);
    toast(`${finalAmount > 0 ? 'Gave' : 'Removed'} ${Math.abs(finalAmount)} Onyx ${direction>0?'to':'from'} ${username} (new balance: ${newOnyx})`, 'success');
    if (username === CU.username) await refreshCU();
  } catch(e) { toast('Failed to adjust Onyx: ' + e.message, 'error'); }
}


