async function adjustOnyx(direction) {
  const username = document.getElementById('eco-username')?.value?.trim();
  const amount = parseInt(document.getElementById('eco-amount')?.value)||0;
  const reason = document.getElementById('eco-reason')?.value?.trim();
  if (!username) { toast('Enter a username','error'); return; }
  if (!amount||amount<=0) { toast('Enter a valid amount','error'); return; }
  if (!reason) { toast('Reason is required','error'); return; }
  let u = null;
  try { u = await FortizedSocial.getUserByName(username); } catch(e) { console.warn('[Admin] User lookup:', e?.message); }
  if (!u) { toast('User not found','error'); return; }
  const delta = direction > 0 ? amount : -amount;
  u.onyx = Math.max(0, (u.onyx||0) + delta);
  try {
    await FortizedSocial.saveUserObject(u);
    logAudit(direction>0?'onyx_give':'onyx_remove', username, `${direction>0?'+':''}${delta} Onyx - ${reason}`);
    toast(`${direction>0?'Gave':'Removed'} ${amount} Onyx ${direction>0?'to':'from'} ${username}. New balance: ${u.onyx}`,'success');
    document.getElementById('eco-amount').value='';
    document.getElementById('eco-reason').value='';
  } catch(e) { console.error('[Settings] Save failed:', e); toast('Failed to save changes. Please try again.','error'); }
}


