async function acceptBastionInvite(btn, bastionId, inviteCode) {
  btn.disabled = true;
  btn.textContent = 'Joining…';
  try {
    // Use invite-aware join that bypasses the public-only check
    await joinBastionById(bastionId, true);
    // Increment invite uses
    if (inviteCode) {
      try { await FortizedSocial.incrementInviteUses(inviteCode); } catch(e) { console.warn('[Invite] Uses increment failed:', e?.message); }
    }
    document.getElementById('invite-dialog-overlay')?.remove();
  } catch(e) { console.error('[Bastion] Invite join failed:', e); btn.disabled = false; btn.textContent = 'Accept Invite'; toast('Failed to join bastion. Please try again.','error'); }
}
function handleInviteGuestContinue(btn, bastionId, inviteCode) {
  const nameInput = document.getElementById('invite-guest-name');
  const name = (nameInput?.value||'').trim();
  if (!name) { nameInput?.focus(); toast('Please enter a name','info'); return; }
  // Store the pending invite info so we can resume after signup/login
  sessionStorage.setItem('pendingInvite', JSON.stringify({bastionId, inviteCode, guestName: name}));
  document.getElementById('invite-dialog-overlay')?.remove();
  // Redirect to login/signup flow — store invite + name for after auth
  window.location.href = '/login?invite=' + encodeURIComponent(inviteCode);
}
// Join a bastion by ID. If hasInvite=true, skip the public-only check.
async function joinBastionById(bastionId, hasInvite) {
  const all=await FortizedSocial.getGlobalBastions()||{};
  const bid = (bastionId||'').trim();
  const bidLower = bid.toLowerCase();
  let b = null, gid = bid;
  // Priority 0: Direct key lookup (globalBastions are keyed by ID)
  if (all[bid]) { b = all[bid]; b.id = bid; }
  // Priority 1: Exact ID match on data
  if (!b) { for (const [k,v] of Object.entries(all)) { if (v.id === bid) { b = v; gid = k; b.id = k; break; } } }
  // Priority 2: Case-insensitive key/ID match
  if (!b) { for (const [k,v] of Object.entries(all)) { if (k.toLowerCase() === bidLower || (v.id||'').toLowerCase() === bidLower) { b = v; gid = k; b.id = k; break; } } }
  // Priority 3: Name match as last resort
  if (!b) { for (const [k,v] of Object.entries(all)) { if ((v.name||'').toLowerCase() === bidLower) { b = v; gid = k; b.id = k; break; } } }
  if(!b){toast('Bastion not found.','error');return;}
  const already=(CU.bastions||[]).some(ub=> gid && ub.globalId===gid);
  if(already){toast('Already joined!','info');openBastion((CU.bastions||[]).findIndex(ub=> gid && ub.globalId===gid));return;}
  if(!hasInvite && b.public===false){toast('This bastion is invite-only.','error');return;}
  if(!hasInvite && (b.applicationQuestions||[]).length){showBastionApplicationForm(b);return;}
  const localB={name:b.name,emblem:b.emblem||'🏰',icon:b.icon||null,banner:b.banner||null,tagline:b.tagline||'',desc:b.desc||'',channels:b.channels||[{name:'general',type:'text',desc:'General chat'}],roles:b.roles||[],owner:b.owner,globalId:gid,public:b.public,memberRoles:b.memberRoles||{},automod:b.automod||{},boostLevel:b.boostLevel||0,customEmojis:b.customEmojis||[],invites:b.invites||[],moodDisabled:b.moodDisabled||false,moodLocked:b.moodLocked||false,lockedMood:b.lockedMood||'',customMood:b.customMood||null,memberCount:b.memberCount||1};
  CU.bastions=[...(CU.bastions||[]),localB];
  await saveUser();
  await FortizedSocial.addBastionMember(gid,CU.username);
  try{const members=await FortizedSocial.getBastionMembers(gid)||[];await firebase.database().ref('globalBastions/'+gid+'/memberCount').set(members.length);}catch{}
  renderRailBastions();
  toast('Joined '+b.name+'!','success');
  openBastion(CU.bastions.length-1);
  if (localB.welcomeEnabled !== false) {
    const wName = CU.displayName||CU.username;
    const wTemplate = localB.welcomeMessage || '**{user}** joined the bastion. Welcome!';
    const wMsg = wTemplate.replace(/\{user\}/g, '**'+wName+'**').replace(/\{bastion\}/g, '**'+(b.name||'Bastion')+'**').replace(/\{count\}/g, '');
    const wChName = localB.welcomeChannel || (b.channels||[]).find(ch=>ch.type==='text')?.name || 'general';
    try { await FortizedSocial.sendBastionChannelMessage(gid, wChName, '__system__', wMsg); } catch(e) { console.debug('[Bastion] Welcome msg failed:', e?.message); }
  }
}

