// All connection platform definitions in one place
const _CONN_PLATFORMS = [
  {key:'youtube', label:'YouTube', pattern:'youtube.com', color:'#FF4444', placeholder:'https://youtube.com/@channel'},
  {key:'roblox',  label:'Roblox',  pattern:'roblox.com',  color:'#00B2FF', placeholder:'https://roblox.com/users/...'},
  {key:'twitter', label:'X / Twitter', pattern:'x.com', color:'#1d9bf0', placeholder:'https://x.com/username'},
  {key:'tiktok',  label:'TikTok',  pattern:'tiktok.com',  color:'#ff0050', placeholder:'https://tiktok.com/@username'},
];

function validateSocialLink(key, pattern, input) {
  const val = input.value.trim();
  if (!val) return; // empty is fine
  if (!val.startsWith('https://') || !val.includes(pattern)) {
    input.style.borderColor = 'var(--red)';
    toast(`Please enter a valid ${key} profile link (must contain ${pattern})`,'error');
    input.value = '';
    setTimeout(() => input.style.borderColor = '', 2000);
  } else {
    input.style.borderColor = 'var(--green)';
    setTimeout(() => input.style.borderColor = '', 1500);
  }
}

async function saveSocialLinks() {
  CU.socials = CU.socials || {};
  let invalid = false;
  _CONN_PLATFORMS.forEach(p => {
    const inp = document.getElementById('social-'+p.key);
    if (!inp) return;
    const val = inp.value.trim();
    if (val && (!val.startsWith('https://') || !val.includes(p.pattern))) {
      toast(`Invalid ${p.key} URL - must be a valid ${p.label} profile link`,'error');
      invalid = true;
      return;
    }
    if (val) CU.socials[p.key] = val;
    else delete CU.socials[p.key];
  });
  if (invalid) return;
  await saveUser();
  toast('Connected accounts saved!','success');
}

async function saveBio() {
  const inp = document.getElementById('bio-input');
  if (!inp) return;
  CU.bio = inp.value.trim().slice(0,300);
  await saveUser();
  toast('Bio saved!','success');
}

// ════════════════════════════════════════════
// CHANNEL CATEGORIES
// ════════════════════════════════════════════
async function addCategoryPrompt() {
  showCustomInput('Add Category', 'Category name:', async (name) => {
    if (!name?.trim()) return;
    const b = CU.bastions[curBastion];
    if (!b) return;
    b.categories = b.categories || [];
    const id = 'cat-' + Date.now().toString(36);
    b.categories.push({ id, name: name.trim().toUpperCase() });
    await saveUser();
    renderBSettingsMain('channels');
    toast('Category "'+name+'" created','success');
  });
}

async function addChannelToCategory(catId, type) {
  const typeLabel = type==='voice'?'party':type;
  showCustomInput('Add Room', `Name for new ${typeLabel} room:`, async (name) => {
    if (!name?.trim()) return;
    const b = CU.bastions[curBastion];
    if (!b) return;
    b.channels = [...(b.channels||[]), { name: name.trim().toLowerCase().replace(/\s+/g,'-'), type, desc:'', categoryId: catId }];
    await saveUser();
    renderBastionSidebar(document.getElementById('sidebar-scroll'));
    renderBSettingsMain('channels');
    toast('#'+name+' created','success');
  });
}

async function deleteCategory(catId) {
  showCustomConfirm('Delete this category? Channels inside will become uncategorized.', async () => {
    const b = CU.bastions[curBastion];
    b.categories = (b.categories||[]).filter(cat => cat.id !== catId);
    // Remove categoryId from channels in this cat
    (b.channels||[]).forEach(ch => { if (ch.categoryId === catId) delete ch.categoryId; });
    await saveUser();
    renderBSettingsMain('channels');
    toast('Category deleted','info');
  });
}

// ════════════════════════════════════════════
// ROLE ASSIGNMENT UI (multi-role)
// ════════════════════════════════════════════
function openAssignRoleUI(username) {
  const b = CU.bastions?.[curBastion];
  if (!b) return;
  const roles = b.roles || [];
  if (!roles.length) { toast('No roles created yet. Create roles in the Roles tab first.','info'); return; }
  const memberRoles = b.memberRoles || {};
  const currentRoleIds = memberRoles[username] || [];
  const html = roles.map(r => `
    <label style="display:flex;align-items:center;gap:10px;padding:10px 14px;background:var(--panel);border:1.5px solid ${currentRoleIds.includes(r.id)?r.color+'66':'var(--border)'};border-radius:12px;margin-bottom:8px;cursor:pointer;">
      <input type="checkbox" data-roleid="${r.id}" ${currentRoleIds.includes(r.id)?'checked':''} style="width:16px;height:16px;accent-color:${r.color};">
      <div style="width:12px;height:12px;border-radius:50%;background:${r.color};flex-shrink:0;"></div>
      <span style="font-weight:600;color:${r.color};">${escapeHTML(r.name)}</span>
    </label>`).join('');
  // Use a temp overlay
  const overlay = document.createElement('div');
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.7);z-index:8000;display:flex;align-items:center;justify-content:center;padding:20px;';
  overlay.innerHTML = `
    <div style="background:var(--panel);border:1px solid var(--border);border-radius:22px;padding:28px;max-width:400px;width:100%;">
      <div style="font-family:var(--font-display);font-size:18px;font-weight:800;margin-bottom:6px;">Assign Roles</div>
      <div style="font-size:13px;color:var(--muted);margin-bottom:18px;">to @${escapeHTML(username)}</div>
      <div id="role-assign-list">${html}</div>
      <div style="display:flex;gap:8px;margin-top:18px;">
        <button class="btn-a" style="flex:1;" onclick="saveAssignedRoles('${escapeHTML(username)}',this.closest('[style*=fixed]'))">Save Roles</button>
        <button class="btn-g" style="flex:1;" onclick="this.closest('[style*=fixed]').remove()">Cancel</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
}

async function saveAssignedRoles(username, overlay) {
  const b = CU.bastions[curBastion];
  b.memberRoles = b.memberRoles || {};
  const checked = [...overlay.querySelectorAll('input[type=checkbox]:checked')].map(el => el.dataset.roleid);
  b.memberRoles[username] = checked;
  await saveUser();
  overlay.remove();
  toast('Roles updated for @'+username,'success');
  loadBastionMembersList();
  // Refresh member list panel in chat
  renderMemberList();
}

// ════════════════════════════════════════════
// ADMIN ALL USERS TAB
// ════════════════════════════════════════════
let allUsersData = [];
let allUsersSortBy = 'registration';

let _hqSortField = 'joined';
let _hqSortDir = -1; // -1 = descending, 1 = ascending
let _hqFilterType = 'all';
let _hqUserStatuses = {};

function sortAllUsers(by) { _hqSortField = by; _hqSortDir = -1; renderAllUsersList(allUsersData); }

function filterAllUsers(q) {
  let filtered = allUsersData;
  if (q) filtered = filtered.filter(u => (u.username||'').toLowerCase().includes(q.toLowerCase()) || (u.displayName||'').toLowerCase().includes(q.toLowerCase()) || (u.email||'').toLowerCase().includes(q.toLowerCase()));
  _applyHqFilter(filtered);
}

function _hqSortUsers(field) {
  if (_hqSortField === field) _hqSortDir *= -1;
  else { _hqSortField = field; _hqSortDir = field === 'username' ? 1 : -1; }
  // Update sort indicators
  document.querySelectorAll('[id^="hq-sort-"]').forEach(el => { el.textContent = ''; el.classList.remove('sort-active'); });
  const ind = document.getElementById('hq-sort-' + field);
  if (ind) { ind.textContent = _hqSortDir > 0 ? '▲' : '▼'; ind.classList.add('sort-active'); }
  const q = document.getElementById('all-users-search')?.value || '';
  filterAllUsers(q);
}

function _hqFilterUsers() {
  _hqFilterType = document.getElementById('hq-user-filter')?.value || 'all';
  const q = document.getElementById('all-users-search')?.value || '';
  filterAllUsers(q);
}

function _applyHqFilter(users) {
  const bans = JSON.parse(localStorage.getItem('ftz_bans')||'[]');
  const bannedNames = bans.map(b => (b.username||'').toLowerCase());
  const now = new Date();
  let filtered = users;
  if (_hqFilterType === 'online') filtered = users.filter(u => {const s = _hqUserStatuses[u.username]; return s === 'online' || s === 'away' || s === 'dnd';});
  else if (_hqFilterType === 'radiance') filtered = users.filter(u => u.radianceUntil && new Date(u.radianceUntil) > now);
  else if (_hqFilterType === 'staff') filtered = users.filter(u => getStaffRole(u.username));
  else if (_hqFilterType === 'banned') filtered = users.filter(u => bannedNames.includes((u.username||'').toLowerCase()));
  else if (_hqFilterType === 'new_24h') filtered = users.filter(u => (now - new Date(u.createdAt||u.joinedAt||0)) < 86400000);
  else if (_hqFilterType === 'new_7d') filtered = users.filter(u => (now - new Date(u.createdAt||u.joinedAt||0)) < 604800000);
  else if (_hqFilterType === 'rich') filtered = users.filter(u => (u.onyx||0) >= 1000);
  else if (_hqFilterType === 'no_friends') filtered = users.filter(u => !(u.friends||[]).length);
  else if (_hqFilterType === 'no_bastions') filtered = users.filter(u => !(u.bastions||[]).length);
  renderAllUsersList(filtered);
}

function _calcUserRisk(u) {
  const bans = JSON.parse(localStorage.getItem('ftz_bans')||'[]');
  const reps = JSON.parse(localStorage.getItem('ftz_reports')||'[]');
  let score = 0;
  if (bans.some(b => (b.username||'').toLowerCase() === (u.username||'').toLowerCase())) score += 50;
  const reportsAgainst = reps.filter(r => (r.username||r.msgFrom||'').toLowerCase() === (u.username||'').toLowerCase());
  score += reportsAgainst.length * 10;
  if (u.suspension) score += 20;
  if (!(u.friends||[]).length && !(u.bastions||[]).length) score += 5;
  const age = (Date.now() - new Date(u.createdAt||u.joinedAt||0)) / 86400000;
  if (age < 1) score += 8;
  else if (age < 7) score += 3;
  return Math.min(100, score);
}

function renderAllUsersList(users) {
  const list = document.getElementById('all-users-list');
  if (!list) return;
  const cnt = document.getElementById('admin-users-count');
  if (cnt) cnt.textContent = users.length + ' users · sorted by ' + _hqSortField + ' · filter: ' + _hqFilterType;

  const sorted = [...users].sort((a,b) => {
    let va, vb;
    switch(_hqSortField) {
      case 'username': va = (a.username||'').toLowerCase(); vb = (b.username||'').toLowerCase(); return _hqSortDir * va.localeCompare(vb);
      case 'onyx': return _hqSortDir * ((a.onyx||0) - (b.onyx||0));
      case 'friends': return _hqSortDir * ((a.friends||[]).length - (b.friends||[]).length);
      case 'bastions': return _hqSortDir * ((a.bastions||[]).length - (b.bastions||[]).length);
      case 'age':
        va = a.dateOfBirth ? new Date(a.dateOfBirth).getTime() : 0;
        vb = b.dateOfBirth ? new Date(b.dateOfBirth).getTime() : 0;
        return _hqSortDir * (va - vb);
      case 'joined':
        va = new Date(a.createdAt||a.joinedAt||'2000-01-01').getTime();
        vb = new Date(b.createdAt||b.joinedAt||'2000-01-01').getTime();
        return _hqSortDir * (va - vb);
      case 'radiance':
        va = a.radianceUntil ? new Date(a.radianceUntil).getTime() : 0;
        vb = b.radianceUntil ? new Date(b.radianceUntil).getTime() : 0;
        return _hqSortDir * (va - vb);
      case 'role':
        const rMap = {superadmin:4,admin:3,moderator:2};
        va = rMap[getStaffRole(a.username)] || 0;
        vb = rMap[getStaffRole(b.username)] || 0;
        return _hqSortDir * (va - vb);
      case 'risk': return _hqSortDir * (_calcUserRisk(a) - _calcUserRisk(b));
      case 'lastSeen':
        va = a.lastSeen ? new Date(a.lastSeen).getTime() : 0;
        vb = b.lastSeen ? new Date(b.lastSeen).getTime() : 0;
        return _hqSortDir * (va - vb);
      case 'status':
        const sMap = {online:3,away:2,dnd:1,offline:0,invisible:0};
        va = sMap[_hqUserStatuses[a.username]] || 0;
        vb = sMap[_hqUserStatuses[b.username]] || 0;
        return _hqSortDir * (va - vb);
      default:
        va = new Date(a.createdAt||a.joinedAt||'2000-01-01').getTime();
        vb = new Date(b.createdAt||b.joinedAt||'2000-01-01').getTime();
        return _hqSortDir * (va - vb);
    }
  });

  if (!sorted.length) {
    list.innerHTML = '<div style="padding:32px;text-align:center;color:rgba(255,255,255,.2);font-size:12px;">No users match filters</div>';
    return;
  }

  const bans = JSON.parse(localStorage.getItem('ftz_bans')||'[]');
  const bannedNames = bans.map(b => (b.username||'').toLowerCase());

  list.innerHTML = sorted.slice(0, 200).map((u,i) => {
    const hasRad = u.radianceUntil && new Date(u.radianceUntil) > new Date();
    const hasRadPlus = u.radiancePlus && new Date(u.radiancePlus) > new Date();
    const staffRole = getStaffRole(u.username);
    const isBanned = bannedNames.includes((u.username||'').toLowerCase());
    const risk = _calcUserRisk(u);
    const riskColor = risk >= 50 ? '#f87171' : risk >= 20 ? '#f59e0b' : risk >= 5 ? '#60a5fa' : '#3ecf6e';
    const statusVal = _hqUserStatuses[u.username] || 'offline';
    const statusColor = statusVal === 'online' ? '#3ecf6e' : statusVal === 'away' ? '#f59e0b' : statusVal === 'dnd' ? '#f87171' : '#4a4a5a';
    const roleBadge = staffRole === 'superadmin' ? '<span style="font-size:8px;font-weight:800;padding:1px 5px;border-radius:var(--radius-pill);background:rgba(255,215,62,.1);color:#ffd93e;">SA</span>'
      : staffRole === 'admin' ? '<span style="font-size:8px;font-weight:800;padding:1px 5px;border-radius:var(--radius-pill);background:rgba(248,113,113,.1);color:var(--red);">ADM</span>'
      : staffRole === 'moderator' ? '<span style="font-size:8px;font-weight:800;padding:1px 5px;border-radius:var(--radius-pill);background:rgba(96,165,250,.1);color:var(--blue);">MOD</span>' : '<span style="font-size:8px;color:rgba(255,255,255,.15);">—</span>';
    const ageDays = u.dateOfBirth ? Math.floor((Date.now() - new Date(u.dateOfBirth)) / 86400000 / 365.25) : null;
    const joinDate = u.createdAt || u.joinedAt;

    return `<div class="hq-user-row" onclick="adminInspectUser('${escapeHTML(u.username)}')" ${isBanned?'style="background:rgba(248,113,113,.03);"':''}>
      <div style="width:30px;text-align:center;font-size:10px;color:rgba(255,255,255,.2);font-weight:700;">${i+1}</div>
      <div style="width:32px;height:32px;border-radius:50%;overflow:hidden;flex-shrink:0;position:relative;">${buildAvatarHTML(u.pfp,u.displayName||u.username,32)}
        <div style="position:absolute;bottom:-1px;right:-1px;width:10px;height:10px;border-radius:50%;background:${statusColor};border:2px solid #0a0e18;"></div>
      </div>
      <div style="flex:1;min-width:100px;overflow:hidden;">
        <div style="display:flex;align-items:center;gap:4px;">
          <span style="font-size:12px;font-weight:700;color:${isBanned?'#f87171':'rgba(255,255,255,.8)'};white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escapeHTML(u.displayName||u.username)}</span>
          ${isBanned?'<span style="font-size:7px;font-weight:800;padding:1px 4px;border-radius:3px;background:var(--red);color:#fff;">BAN</span>':''}
        </div>
        <div style="font-size:9.5px;color:rgba(255,255,255,.2);">@${escapeHTML(u.username)}</div>
      </div>
      <div style="width:70px;text-align:center;"><div style="width:8px;height:8px;border-radius:50%;background:${statusColor};margin:0 auto;box-shadow:0 0 4px ${statusColor}55;"></div></div>
      <div style="width:65px;text-align:right;font-size:11px;font-weight:700;color:#ffd93e;font-family:var(--font-display);">${(u.onyx||0).toLocaleString()}</div>
      <div style="width:55px;text-align:center;font-size:11px;color:rgba(255,255,255,.4);">${(u.friends||[]).length}</div>
      <div style="width:60px;text-align:center;font-size:11px;color:rgba(255,255,255,.4);">${(u.bastions||[]).length}</div>
      <div style="width:50px;text-align:center;font-size:11px;color:rgba(255,255,255,.4);">${ageDays !== null ? ageDays : '—'}</div>
      <div style="width:75px;text-align:center;font-size:10px;color:rgba(255,255,255,.3);">${joinDate?new Date(joinDate).toLocaleDateString('en-GB',{day:'numeric',month:'short'}):'—'}</div>
      <div style="width:75px;text-align:center;font-size:10px;color:${statusVal==='online'?'#3ecf6e':'rgba(255,255,255,.3)'};">${statusVal==='online'?'Now':u.lastSeen?formatTimeAgo(u.lastSeen):'—'}</div>
      <div style="width:65px;text-align:center;">${hasRadPlus?'<span style="font-size:8px;font-weight:800;padding:1px 5px;border-radius:var(--radius-pill);background:rgba(168,85,247,.12);color:#a855f7;">R+</span>':hasRad?'<span style="font-size:8px;font-weight:800;padding:1px 5px;border-radius:var(--radius-pill);background:rgba(255,249,62,.1);color:#ffd93e;">R</span>':'<span style="font-size:8px;color:rgba(255,255,255,.12);">—</span>'}</div>
      <div style="width:50px;text-align:center;">${roleBadge}</div>
      <div style="width:55px;text-align:center;"><div style="display:inline-block;width:28px;height:4px;border-radius:2px;background:rgba(255,255,255,.06);overflow:hidden;"><div style="height:100%;width:${risk}%;background:${riskColor};border-radius:2px;"></div></div><div style="font-size:8px;color:${riskColor};margin-top:1px;">${risk}</div></div>
    </div>`}).join('');
}

function adminInspectUser(username) {
  _loadAdminPage('users');
  setTimeout(() => { const el = document.getElementById('admin-user-search'); if (el) { el.value = username; adminSearchUser(); } }, 150);
}

