// TRIAL RADIANCE LINKS (staw only)
// ════════════════════════════════════════════


async function checkTrialLink() {
  const params = new URLSearchParams(location.search);
  const trial = params.get('trial');
  if (!trial || !trial.startsWith('TRIAL-')) return;
  const match = trial.match(/^TRIAL-(\d+)d-/);
  if (!match) return;
  const days = parseInt(match[1]);
  // Show offer to the user
  const existing = JSON.parse(localStorage.getItem('ftz_trial_links')||'[]');
  const linkData = existing.find(l=>l.code===trial);
  const overlay = document.createElement('div');
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(12,14,20,.97);backdrop-filter:blur(24px);z-index:9500;display:flex;align-items:center;justify-content:center;padding:20px;';
  overlay.innerHTML = `
    <div style="background:var(--panel);border:1px solid rgba(255,249,62,.2);border-radius:28px;max-width:460px;width:100%;overflow:hidden;text-align:center;">
      <div style="height:3px;background:linear-gradient(90deg,transparent,var(--accent),transparent);"></div>
      <div style="padding:40px 36px;">
        <div style="font-size:48px;margin-bottom:16px;">✨</div>
        <div style="font-family:var(--font-display);font-size:22px;font-weight:800;margin-bottom:10px;">Special Offer from Staw</div>
        <div style="font-size:14px;color:var(--muted-light);line-height:1.65;margin-bottom:24px;">
          <strong>staw</strong> is offering you a <strong style="color:var(--accent);">${days}-day free trial of Radiance</strong>!<br>
          Get a profile glow, custom banner, and more — completely free.
        </div>
        <button class="btn-a" style="padding:13px 32px;font-size:15px;margin-bottom:10px;width:100%;" onclick="acceptRadianceTrial(${days},this.closest('[style*=fixed]'))">Accept ${days}-Day Radiance Trial</button>
        <button class="btn-g" style="padding:10px 20px;font-size:13px;width:100%;" onclick="this.closest('[style*=fixed]').remove()">No thanks</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  // Clean URL
  const url = new URL(location.href);
  url.searchParams.delete('trial');
  history.replaceState({}, '', url);
}

async function acceptRadianceTrial(days, overlay) {
  const until = new Date(Date.now() + days*86400000).toISOString();
  CU.radianceUntil = until;
  await saveUser();
  overlay.remove();
  toast(`✨ ${days}-day Radiance activated!`,'success');
  updateUserbar();
}

