let _reportPollInterval = null;
function startReportPolling() {
  if (_reportPollInterval) return;
  _reportPollInterval = setInterval(() => {
    // Only poll when admin panel is actually open
    if (!document.getElementById('admin-panel-overlay')) {
      clearInterval(_reportPollInterval);
      _reportPollInterval = null;
      return;
    }
    if (adminTab === 'reports' || adminTab === 'dashboard') {
      _syncAdminDataFromFirebase().then(()=>{
        _loadAdminPage(adminTab);
      }).catch(()=>{});
    }
  }, 60000); // refresh every 60s when panel open (reduced from 20s to limit egress)
}



