      +'<div class="ftz-ap-vol-track" onclick="ftzAudioVol(\''+aid+'\',event)"><div class="ftz-ap-vol-fill" id="'+aid+'-vol-fill" style="width:100%;"></div></div>'
      +'</div>'
      // Speed
      +'<span class="ftz-ap-speed" id="'+aid+'-speed" onclick="ftzAudioCycleSpeed(\''+aid+'\')" title="Speed">1x</span>'
