        + '<span style="font-size:22px;flex-shrink:0;">' + app.icon + '</span>'
        + '<div style="flex:1;min-width:0;">'
        + '<div style="font-size:13px;font-weight:700;color:#fff;">' + escapeHTML(app.name) + '</div>'
        + '<div style="font-size:10.5px;color:'+(isActive?'#3ecf6e':enabled?'rgba(62,207,110,.5)':'var(--muted)')+';">'+(isActive?'Currently showing as activity':enabled?'Detected — will auto-show':'Hidden — won\'t show as status')+'</div>'
        + '</div>'
