async function showDMUserPanel(username) {
  const panel = document.getElementById('dm-user-panel');
  if (!panel) return;
  panel.style.display = 'block';
  panel.innerHTML = '<div style="padding:20px;color:var(--muted);font-size:13px;text-align:center;">Loading\u2026</div>';
  subscribeProfileStatus(username);
  let u = null;
  try { u = await FortizedSocial.getUserByName(username); } catch(e) { console.debug('[DM] user lookup failed', e); }
  if (!u) u = { username, displayName: username };
  // Update DM welcome area with actual pfp
  const _wAv = document.getElementById('dm-welcome-av');
  if (_wAv) _wAv.innerHTML = buildAvatarHTML(u.pfp||null, u.displayName||username, 60);
  const _wName = document.getElementById('dm-welcome-name');
  if (_wName) _wName.textContent = u.displayName || username;
  let status = 'offline';
  try {
    const pr = await FortizedSocial.queryPresence([username]);
    if (pr && pr[username]) { status = pr[username].status || 'offline'; }
    else { try { status = await FortizedSocial.getStatus(username); } catch(e) { console.debug('[DM] status fallback failed', e); } }
  } catch(e) { console.debug('[DM] presence query failed', e); try { status = await FortizedSocial.getStatus(username); } catch(e2) { console.debug('[DM] status fallback failed', e2); } }
  const sc = FtzStatus.color(status);
  const hasR = u.radianceUntil && new Date(u.radianceUntil) > new Date();
  const hasRadiancePlus = u.radiancePlus && new Date(u.radiancePlus) > new Date();
  const profileTheme = hasRadiancePlus ? (u.profileTheme || null) : null;
  const socials = u.socials || {};
  const customStatus = u.customStatus;
  // Build connections HTML
  const activeConns = _CONN_PLATFORMS.filter(p=>socials[p.key]);
  const connHtml = activeConns.length ? '<div style="padding:12px 16px;"><div style="font-size:9.5px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:rgba(255,255,255,.2);margin-bottom:8px;">Connections</div><div style="display:flex;flex-direction:column;gap:4px;">'
    + activeConns.map(p=>'<a href="#" onclick="openExternalLink(event,\'' + escapeHTML(socials[p.key]) + '\')" style="display:flex;align-items:center;justify-content:space-between;padding:7px 12px;border-radius:10px;background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.05);text-decoration:none;transition:background .15s;" onmouseenter="this.style.background=\'rgba(255,255,255,.06)\'" onmouseleave="this.style.background=\'rgba(255,255,255,.03)\'"><span style="display:flex;align-items:center;gap:8px;font-size:12px;font-weight:600;color:'+p.color+';">'+_connIcon(p.key)+' '+p.label+'</span><span style="font-size:12px;color:rgba(255,255,255,.25);">\u2192</span></a>').join('')
    + '</div></div>' : '';
  // Banner
  const userBanner = (u.banner && hasR) ? u.banner : null;
  const bannerBg = userBanner
    ? "url('" + userBanner + "') center/cover no-repeat"
    : 'linear-gradient(135deg,' + (profileTheme?profileTheme.color1+'88':'#141a2e') + ',' + (profileTheme?profileTheme.color2+'66':'#1a1030') + ',' + (profileTheme?profileTheme.color1+'44':'#0f1828') + ')';
  panel.innerHTML =
    // Banner
    '<div style="position:relative;height:120px;background:'+bannerBg+';overflow:hidden;">'
    + (profileTheme ? '<div style="position:absolute;bottom:0;left:0;right:0;height:2px;background:linear-gradient(90deg,'+profileTheme.color1+','+profileTheme.color2+');opacity:.6;z-index:1;"></div>' : '')
    + '<div style="position:absolute;inset:0;background:linear-gradient(0deg,var(--channel) 0%,rgba(12,14,20,.5) 40%,transparent 100%);"></div>'
    + '</div>'
    // PFP
    + '<div style="padding:0 16px;margin-top:-36px;margin-bottom:8px;position:relative;z-index:2;">'
    + '<div style="position:relative;display:inline-block;">'
    + '<div style="width:72px;height:72px;border-radius:50%;background:var(--panel2);border:4px solid var(--channel);overflow:hidden;box-shadow:0 4px 16px rgba(0,0,0,.6);">' + buildAvatarHTML(u.pfp,u.displayName||u.username,64) + '</div>'
    + '<span class="profile-status-dot" data-for="'+escapeHTML(u.username)+'" data-dot-size="16" style="position:absolute;bottom:3px;right:3px;width:16px;height:16px;">'+FtzStatus.dotSvg(u.status||'offline', 16)+'</span>'
    + '</div>'
    + '</div>'
    // Display Name
    + '<div style="padding:0 16px 4px;">'
    + '<div style="font-family:var(--font-display);font-size:16px;font-weight:800;color:#fff;line-height:1.15;'+(u.displayFont&&u.displayFont!=='default'?'font-family:'+getDisplayFont(u)+';':'')+'">' + escapeHTML(u.displayName||u.username) + '</div>'
    // Username
    + '<div style="font-size:11px;color:rgba(255,255,255,.25);margin-top:2px;">@' + escapeHTML(u.username) + '</div>'
    + '</div>'
    // Status
    + '<div style="padding:6px 16px 0;display:flex;align-items:center;gap:6px;flex-wrap:wrap;">'
    + '<div style="display:inline-flex;align-items:center;gap:5px;padding:4px 10px;background:rgba(255,255,255,.03);border-radius:var(--radius-pill);">'
    + '<span class="profile-status-dot" data-for="'+escapeHTML(u.username)+'" data-dot-size="10" style="width:10px;height:10px;display:inline-flex;">'+FtzStatus.dotSvg(u.status||'offline', 10)+'</span>'
    + '<span class="profile-status-label" data-for="'+escapeHTML(u.username)+'" style="font-size:11px;color:rgba(255,255,255,.45);font-weight:600;">' + FtzStatus.publicLabel(status) + '</span>'
    + '</div>'
    // Custom Status Bubble
    + (customStatus?.text ? '<div class="cloud-status-bubble profile-custom-status" data-for="'+escapeHTML(u.username)+'" style="font-size:10.5px;padding:4px 10px;"><span class="csb-emoji">'+(customStatus.emoji?'<img src="'+emojiToTwemojiUrl(customStatus.emoji)+'" style="width:13px;height:13px;" onerror="this.outerHTML=\''+customStatus.emoji+'\'">':'')+'</span><span class="csb-text">'+escapeHTML(customStatus.text)+'</span></div>' : '<div class="profile-custom-status" data-for="'+escapeHTML(u.username)+'" style="display:none;"></div>')
    + '</div>'
    // Divider
    + '<div style="height:1px;background:rgba(255,255,255,.05);margin:10px 16px;"></div>'
    // About Me
    + (u.bio ? '<div style="padding:8px 16px;"><div style="font-size:9.5px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:rgba(255,255,255,.2);margin-bottom:5px;">About Me</div><div style="font-size:12.5px;color:rgba(255,255,255,.55);line-height:1.55;">' + escapeHTML(u.bio.slice(0,300)) + (u.bio.length>300?'\u2026':'') + '</div></div>' : '')
    // Connections
    + connHtml
    // View Full Profile button
    + '<div style="padding:12px 16px;">'
    + '<button onclick="viewUserProfile(\'' + escapeHTML(username) + '\')" style="width:100%;padding:9px;border-radius:10px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.08);color:rgba(255,255,255,.6);font-size:12px;font-weight:600;cursor:pointer;font-family:inherit;transition:all .15s;display:flex;align-items:center;justify-content:center;gap:6px;" onmouseenter="this.style.background=\'rgba(255,255,255,.08)\'" onmouseleave="this.style.background=\'rgba(255,255,255,.04)\'"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2"/><circle cx="12" cy="7" r="4"/></svg> View Full Profile</button>'
    + '</div>';
}


// ════════════════════════════════════════════
// BASTION BANNER UPLOAD
// ════════════════════════════════════════════
async function updateBastionBanner(e) {
  const file = e.target.files[0]; if (!file) return;
  if (file.size > 8 * 1024 * 1024) { toast('Max 8MB', 'error'); return; }
  const reader = new FileReader();
  reader.onload = async ev => {
    const fileData = ev.target.result;
    showCropModal(fileData, 16/5, async (cropped) => {
      CU.bastions[curBastion].banner = cropped;
      await saveUser();
      _syncBastionToGlobal(curBastion);
      renderBSettingsMain('overview');
      renderBastionSidebar(document.getElementById('sidebar-scroll'));
      toast('Bastion banner updated! ✓', 'success');
    });
  };
  reader.readAsDataURL(file);
}

// ════════════════════════════════════════════
// FAVOURITE GIFS
// ════════════════════════════════════════════
function getFavGifs() {
  return JSON.parse(localStorage.getItem('ftz_fav_gifs') || '[]');
}
function saveFavGif(gif) {
  const favs = getFavGifs();
  if (!favs.find(g => g.id === gif.id)) {
    favs.unshift(gif);
    if (favs.length > 50) favs.pop(); // cap at 50
    localStorage.setItem('ftz_fav_gifs', JSON.stringify(favs));
    toast('GIF saved to favourites!', 'success');
  } else {
    toast('Already in favourites', 'info');
  }
}
function removeFavGif(id) {
  const favs = getFavGifs().filter(g => g.id !== id);
  localStorage.setItem('ftz_fav_gifs', JSON.stringify(favs));
}
function renderFavGifs(targetInput) {
  const favs = getFavGifs();
  const grid = document.getElementById('giphy-grid');
  const browser = document.getElementById('gif-category-browser');
  if (!grid) return;
  if (browser) browser.style.display = 'none';
  grid.style.display = '';
  if (!favs.length) {
    grid.innerHTML = '<div style="grid-column:1/-1;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:30px 20px;gap:8px;">'
      + '<div style="font-size:28px;">⭐</div>'
      + '<div style="text-align:center;font-size:12.5px;color:var(--muted);">No saved GIFs yet.<br>Hover a GIF and click ★ to save it!</div></div>';
    return;
  }
  grid.innerHTML = favs.map(gif => {
    const url = gif.url || '';
    return `<div class="gif-card" data-id="${gif.id}" data-url="${escapeHTML(url)}" data-input="${escapeHTML(targetInput)}" style="position:relative;border-radius:10px;overflow:hidden;cursor:pointer;background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.05);break-inside:avoid;margin-bottom:8px;transition:all .2s cubic-bezier(.22,1,.36,1);">
      <img src="${escapeHTML(url)}" style="width:100%;display:block;border-radius:9px;" loading="lazy" draggable="false">
      <div class="gif-hover-overlay" style="position:absolute;inset:0;opacity:0;transition:.18s;background:linear-gradient(to top,rgba(0,0,0,.7) 0%,transparent 45%);display:flex;align-items:flex-end;justify-content:space-between;padding:10px;pointer-events:none;border-radius:10px;"></div>
      <button onclick="event.stopPropagation();removeFavGif('${gif.id}');renderFavGifs('${escapeHTML(targetInput)}')" title="Remove" style="position:absolute;top:6px;right:6px;background:rgba(0,0,0,.55);backdrop-filter:blur(10px);border:1px solid rgba(255,255,255,.1);color:#ff6b6b;border-radius:8px;width:28px;height:28px;font-size:12px;cursor:pointer;display:flex;align-items:center;justify-content:center;opacity:0;transition:.18s;pointer-events:auto;">✕</button>
    </div>`;
  }).join('');
  grid.querySelectorAll('.gif-card').forEach(card => {
    const ov = card.querySelector('.gif-hover-overlay');
    const del = card.querySelector('button');
    card.addEventListener('mouseenter', () => { card.style.transform='scale(1.03) translateY(-2px)'; card.style.boxShadow='0 8px 24px rgba(0,0,0,.35)'; card.style.borderColor='rgba(255,249,62,.12)'; if(ov)ov.style.opacity='1'; if(del)del.style.opacity='1'; });
    card.addEventListener('mouseleave', () => { card.style.transform=''; card.style.boxShadow=''; card.style.borderColor='rgba(255,255,255,.05)'; if(ov)ov.style.opacity='0'; if(del)del.style.opacity='0'; });
    card.addEventListener('click', () => sendGifDirectly(card.dataset.id, card.dataset.input, card.dataset.url));
  });
}

