let _gameActivityInterval = null;
let _autoActivityPoller = null;
let _userCustomApps = JSON.parse(localStorage.getItem('ftz_custom_apps')||'[]');

// ── Automatic Game Activity Detection (Tauri / Discord-style) ──
// In the desktop app, automatically polls running processes and sets
// game activity when a known/custom game is detected — no user action needed.
const AUTO_ACTIVITY_POLL_MS = 15_000; // check every 15s

// Which detected apps are enabled for display (Discord-style per-app toggle)
// Stored as { "appname_lower": false } — if missing or true, app is enabled.
let _disabledActivityApps = JSON.parse(localStorage.getItem('ftz_disabled_activity_apps') || '{}');

function _isAppActivityEnabled(appName) {
  return _disabledActivityApps[appName.toLowerCase()] !== false;
}

function _setAppActivityEnabled(appName, enabled) {
  if (enabled) {
    delete _disabledActivityApps[appName.toLowerCase()];
  } else {
    _disabledActivityApps[appName.toLowerCase()] = false;
  }
  localStorage.setItem('ftz_disabled_activity_apps', JSON.stringify(_disabledActivityApps));
}

// Returns ALL matched apps from the process list (for the settings picker)
function _matchAllRunningApps(processList) {
  if (!processList || !Array.isArray(processList)) return [];
  const customApps = _userCustomApps.map(a => ({
    name: a.name, icon: a.icon || '🎮',
    keywords: [a.name.toLowerCase()]
  }));
  const allApps = [...KNOWN_GAMES, ...customApps];
  const gameCollection = (CU?.gameCollection || []).map(g => ({
    name: g.name, icon: g.icon || '🎮',
    keywords: [g.name.toLowerCase()]
  }));
  const combined = [...allApps, ...gameCollection];
  const found = [];
  const seen = new Set();
  for (const proc of processList) {
    const pName = (typeof proc === 'string' ? proc : proc?.name || '').toLowerCase();
    if (!pName) continue;
    for (const app of combined) {
      if (seen.has(app.name)) continue;
      const matched = (app.keywords || []).some(kw => pName.includes(kw))
        || pName.includes(app.name.toLowerCase());
      if (matched) {
        seen.add(app.name);
        found.push({ name: app.name, icon: app.icon });
      }
    }
  }
  return found;
}

// Returns the first ENABLED match (used by the auto-poller)
function _matchRunningApp(processList) {
  const all = _matchAllRunningApps(processList);
  return all.find(a => _isAppActivityEnabled(a.name)) || null;
}

function _startAutoActivityDetection() {
  if (_autoActivityPoller) return;
  // Skip if desktop detection is already handling this
  if (_desktopGameDetectionActive) return;
  // Only works in Electron desktop app
  if (!window.fortizedDesktop?.isDesktopApp) return;
  const activityEnabled = () => localStorage.getItem('ftz_activity_detection') !== 'false';
  const getProcs = () => window.fortizedDesktop?.getProcesses?.();
  // Poll Electron for running processes
  _autoActivityPoller = setInterval(async () => {
    if (!CU?.username || !activityEnabled()) return;
    try {
      const procs = await getProcs();
      if (!procs) return;
      const detected = _matchRunningApp(procs);
      if (detected) {
        const gameActivity = activityState.activities.find(a => a.id === 'game');
        if (!gameActivity || gameActivity.name !== detected.name) {
          setGameActivity(detected.name, detected.icon);
        }
      } else {
        const gameActivity = activityState.activities.find(a => a.id === 'game');
        if (gameActivity && !gameActivity._manual) {
          setGameActivity(null);
        }
      }
    } catch(e) { console.debug('[Activity] auto-detect poll failed', e); }
  }, AUTO_ACTIVITY_POLL_MS);
  // Run once immediately
  (async () => {
    if (!activityEnabled()) return;
    try {
      const procs = await getProcs();
      if (!procs) return;
      const detected = _matchRunningApp(procs);
      if (detected) setGameActivity(detected.name, detected.icon);
    } catch(e) { console.debug('[Activity] initial detect failed', e); }
  })();
}

function _stopAutoActivityDetection() {
  if (_autoActivityPoller) { clearInterval(_autoActivityPoller); _autoActivityPoller = null; }
}

async function detectGameActivity() {
  // Only works in Electron desktop app — uses native process detection
  if (!window.fortizedDesktop?.isDesktopApp) return null;
  try {
    const procs = await window.fortizedDesktop.getProcesses();
    if (procs) {
      const detected = _matchRunningApp(procs);
      if (detected) return detected;
    }
  } catch(e) { console.debug('[Activity] detectGameActivity failed', e); }
  return null;
}

async function openActivityDetector() {
  // If already playing, offer to stop
  const gameActivity = activityState.activities.find(a => a.id === 'game');
  if (gameActivity) {
    setGameActivity(null);
    return;
  }
  const detected = await detectGameActivity();
  if (detected) {
    setGameActivity(detected.name, detected.icon);
  }
}

