function _showScreenInRoom(isRemote) {
  // Remove standalone overlay first
  _closeEl('vc-screen-overlay');
  const room = document.getElementById('vc-call-bar');
  if (!room) { renderScreenShareView(isRemote); return; }
  // Inject content panel above controls
  _closeEl('vc-content-panel');
  const panel = document.createElement('div');
  panel.id = 'vc-content-panel';
  panel.style.cssText = 'flex:2;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,.5);position:relative;border-radius:16px;margin:0 28px;overflow:hidden;min-height:0;';
  const vid = document.createElement('video');
  vid.id = 'vc-screen-video'; vid.autoplay = true;
  if (!isRemote) vid.muted = true;
  vid.style.cssText = 'max-width:100%;max-height:100%;border-radius:12px;';
  const closeBtn = document.createElement('button');
  closeBtn.style.cssText = 'position:absolute;top:10px;right:10px;background:rgba(0,0,0,.6);border:none;color:#fff;width:30px;height:30px;border-radius:50%;cursor:pointer;font-size:16px;display:flex;align-items:center;justify-content:center;';
  closeBtn.textContent='✕';
  closeBtn.onclick = ()=>{ _closeEl('vc-content-panel'); if(_vc.screenStream){ _vc.screenStream.getTracks().forEach(t=>t.stop()); _vc.screenStream=null; firebase.database().ref(_vc.sigRef+'/meta').update({screenShare:false}); } };
  const label = document.createElement('div');
  label.style.cssText = 'position:absolute;bottom:10px;left:14px;background:rgba(0,0,0,.7);padding:3px 10px;border-radius:8px;font-size:12px;color:#fff;font-weight:600;';
  label.textContent = isRemote ? (_vc.partner||'Partner')+' is sharing' : 'Your screen';
  panel.appendChild(vid); panel.appendChild(closeBtn); panel.appendChild(label);
  // Insert between participants and controls
  const controls = room.lastElementChild;
  room.insertBefore(panel, controls);
  if (!isRemote && _vc.screenStream) {
    vid.srcObject = _vc.screenStream;
  } else if (isRemote) {
    // remoteStream may have multiple tracks - use the video track (screen)
    if (_vc.remoteStream) {
      const videoTracks = _vc.remoteStream.getVideoTracks();
      if (videoTracks.length > 0) {
        vid.srcObject = new MediaStream(videoTracks);
      } else {
        vid.srcObject = _vc.remoteStream;
      }
    }
    // Also listen for new tracks in case stream not ready
    if (_vc.pc) {
      const _prevOnTrack = _vc.pc.ontrack;
      _vc.pc.ontrack = (e) => {
        // Keep audio working via the original handler
        if (_prevOnTrack) _prevOnTrack(e);
        _vc.remoteStream = e.streams[0];
        if (e.track.kind === 'video') {
          const vtracks = e.streams[0].getVideoTracks();
          const screenVid = document.getElementById('vc-screen-video');
          if (screenVid && vtracks.length > 0) screenVid.srcObject = new MediaStream(vtracks);
        }
      };
    }
  }
}

