// ════════════════════════════════════════════════════
// ACCOUNT SWITCHER
// ════════════════════════════════════════════════════
let _acctSwitcherOpen = false;
function toggleAccountSwitcher() {
  const panel = document.getElementById('account-switcher-panel');
  if (!panel) return;
  _acctSwitcherOpen = !_acctSwitcherOpen;
  panel.style.display = _acctSwitcherOpen ? 'block' : 'none';
  if (_acctSwitcherOpen) renderAccountSwitcher();
}
function renderAccountSwitcher() {
  const el = document.getElementById('acct-switcher-list');
  if (!el) return;
  const accounts = getSavedAccounts();
  el.innerHTML = accounts.map(a => `
    <div class="acct-item ${a.username===CU?.username?'active-acct':''}" onclick="switchToAccount('${escapeHTML(a.username)}')">
      <div style="width:28px;height:28px;border-radius:50%;background:var(--panel2);border:1px solid var(--border);display:flex;align-items:center;justify-content:center;font-size:12px;overflow:hidden;flex-shrink:0;">${buildAvatarHTML(a.pfp||null,a.username,28)}</div>
      <div style="flex:1;min-width:0;">
        <div style="font-size:13px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escapeHTML(a.displayName||a.username)}</div>
        <div style="font-size:10.5px;color:var(--muted);">@${escapeHTML(a.username)}</div>
      </div>
      ${a.username===CU?.username?'<span style="font-size:9px;font-weight:700;color:var(--accent);background:var(--accent-dim);padding:2px 6px;border-radius:var(--radius-pill);">ACTIVE</span>':''}
    </div>`).join('');
}
function getSavedAccounts() {
  try { return JSON.parse(localStorage.getItem('ftz_saved_accounts')||'[]'); } catch { return []; }
}
function saveCurrentToAccounts() {
  if (!CU) return;
  const accounts = getSavedAccounts();
  const idx = accounts.findIndex(a=>a.username===CU.username);
  const entry = { username:CU.username, displayName:CU.displayName||CU.username, pfp:CU.pfp||null };
  if (idx>=0) accounts[idx] = entry; else accounts.push(entry);
  localStorage.setItem('ftz_saved_accounts', JSON.stringify(accounts));
}
async function switchToAccount(username) {
  if (username === CU?.username) { toggleAccountSwitcher(); return; }
  const cached = localStorage.getItem('ftz_user_'+username);
  if (cached) {
    // Save current user's full data and account entry before switching
    saveCurrentToAccounts();
    if (CU?.username) {
      localStorage.setItem('ftz_user_'+CU.username, JSON.stringify(CU));
    }
    // Set old account away, new account online
    try { if (CU?.username) await FortizedSocial.setStatus(CU.username, 'away'); } catch(e) { console.debug('[Account] status set away failed', e); }
    try { await FortizedSocial.setStatus(username, 'online'); } catch(e) { console.debug('[Account] status set online failed', e); }
    // Set both localStorage keys for consistency
    localStorage.setItem('ftz_current', username);
    localStorage.setItem('fortized_current_user', username);
    window.location.reload();
  } else {
    // No cached data — try fetching from server before giving up
    try {
      const user = await FortizedSocial.getUserByName(username);
      if (user?.username) {
        saveCurrentToAccounts();
        if (CU?.username) localStorage.setItem('ftz_user_'+CU.username, JSON.stringify(CU));
        localStorage.setItem('ftz_user_'+user.username, JSON.stringify(user));
        localStorage.setItem('ftz_current', user.username);
        localStorage.setItem('fortized_current_user', user.username);
        try { await FortizedSocial.setStatus(user.username, 'online'); } catch(e) { console.debug('[Account] status set online failed', e); }
        window.location.reload();
        return;
      }
    } catch(e) { console.warn('[Account] switch fetch failed', e); }
    toast('Account not found — please sign in again', 'error');
    toggleAccountSwitcher();
    showAddAccountModal();
  }
}
function addAnotherAccount() {
  toggleAccountSwitcher();
  showAddAccountModal();
}

function showAddAccountModal() {
  document.getElementById('add-acct-modal')?.remove();
  const overlay = document.createElement('div');
  overlay.id = 'add-acct-modal';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(12,14,20,.92);backdrop-filter:blur(18px);z-index:9800;display:flex;align-items:center;justify-content:center;padding:20px;';
  overlay.innerHTML = `
    <div style="background:var(--panel);border:1px solid var(--border);border-radius:24px;max-width:400px;width:100%;overflow:hidden;box-shadow:0 30px 80px rgba(0,0,0,.8);">
      <div style="height:3px;background:linear-gradient(90deg,transparent,var(--accent),transparent);"></div>
      <div style="padding:28px 28px 20px;">
        <div style="display:flex;align-items:center;gap:12px;margin-bottom:24px;">
          <div style="width:46px;height:46px;border-radius:14px;background:var(--accent-dim);border:1px solid var(--accent-mid);display:flex;align-items:center;justify-content:center;font-size:22px;">👤</div>
          <div>
            <div style="font-family:var(--font-display);font-size:18px;font-weight:800;">Add Account</div>
            <div style="font-size:12px;color:var(--muted);">Sign in with another Fortized account</div>
          </div>
        </div>
        <div style="margin-bottom:12px;">
          <label style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.07em;color:var(--muted);display:block;margin-bottom:6px;">Username</label>
          <input id="add-acct-user" class="field-input" placeholder="Enter username…" style="width:100%;" autocomplete="username">
        </div>
        <div style="margin-bottom:20px;">
          <label style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.07em;color:var(--muted);display:block;margin-bottom:6px;">Password</label>
          <input id="add-acct-pass" type="password" class="field-input" placeholder="Enter password…" style="width:100%;" autocomplete="current-password">
        </div>
        <div id="add-acct-err" style="font-size:12.5px;color:var(--red);margin-bottom:10px;display:none;border-radius:9px;padding:8px 12px;background:rgba(248,113,113,.08);border:1px solid rgba(248,113,113,.2);"></div>
        <div style="display:flex;gap:8px;">
          <button class="btn-a" id="add-acct-btn" style="flex:1;" onclick="submitAddAccount()">Sign In & Switch</button>
          <button class="btn-g" style="padding:10px 18px;" onclick="document.getElementById('add-acct-modal').remove()">Cancel</button>
        </div>
      </div>
      <div style="padding:12px 28px;border-top:1px solid var(--border);background:rgba(0,0,0,.15);">
        <div style="font-size:11.5px;color:var(--muted);text-align:center;">Signed in as <strong style="color:var(--accent);">@${escapeHTML(CU?.username||'')}</strong></div>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
  setTimeout(() => document.getElementById('add-acct-user')?.focus(), 60);
  document.getElementById('add-acct-pass')?.addEventListener('keydown', e => { if(e.key==='Enter') submitAddAccount(); });
}

async function submitAddAccount() {
  const username = document.getElementById('add-acct-user')?.value?.trim()?.toLowerCase();
  const password = document.getElementById('add-acct-pass')?.value;
  const errEl = document.getElementById('add-acct-err');
  const btn = document.getElementById('add-acct-btn');
  if (!username || !password) {
    if(errEl){errEl.textContent='Please enter both username and password.';errEl.style.display='block';}
    return;
  }
  if (btn) { btn.disabled=true; btn.textContent='Signing in…'; }
  try {
    let result = null;
    // Method 1: FortizedSocial.login
    if (typeof FortizedSocial.login === 'function') {
      try {
        const r = await FortizedSocial.login(username, password);
        if (r?.ok && r?.user?.username) result = r.user;
        else if (r?.username) result = r;
      } catch(e1) { if (!result && e1?.message?.includes('password')) throw e1; }
    }
    // Method 2: FortizedSocial.loginUser (may not exist)
    if (!result && typeof FortizedSocial.loginUser === 'function') {
      try { const r2 = await FortizedSocial.loginUser(username, password); if(r2?.username) result=r2; } catch(e) { console.debug('[Auth] loginUser fallback failed', e); }
    }
    // Method 3: Manual password check (fetch user + compare)
    if (!result) {
      const u = await FortizedSocial.getUserByName(username).catch(()=>null);
      if (!u) throw new Error('No account found with username "' + username + '"');
      const pw = String(u.password||'');
      const pwOk = pw === password || pw.toLowerCase() === password.toLowerCase();
      if (!pwOk) throw new Error('Incorrect password');
      result = u;
    }
    if (!result?.username) throw new Error('Could not authenticate — check credentials');
    // Save current user's full data before switching
    saveCurrentToAccounts();
    if (CU?.username) {
      localStorage.setItem('ftz_user_'+CU.username, JSON.stringify(CU));
    }
    localStorage.setItem('ftz_user_'+result.username, JSON.stringify(result));
    const accounts = getSavedAccounts();
    const idx = accounts.findIndex(a=>a.username===result.username);
    const entry = {username:result.username,displayName:result.displayName||result.username,pfp:result.pfp||null};
    if(idx>=0) accounts[idx]=entry; else accounts.push(entry);
    localStorage.setItem('ftz_saved_accounts', JSON.stringify(accounts));
    // Set both localStorage keys for consistency
    localStorage.setItem('ftz_current', result.username);
    localStorage.setItem('fortized_current_user', result.username);
    // Update statuses
    try { if (CU?.username) await FortizedSocial.setStatus(CU.username, 'away'); } catch(e) { console.debug('[Auth] status away failed', e); }
    try { await FortizedSocial.setStatus(result.username, 'online'); } catch(e) { console.debug('[Auth] status online failed', e); }
    document.getElementById('add-acct-modal')?.remove();
    toast('Switching to @'+result.username+'…', 'success');
    setTimeout(()=>window.location.reload(), 700);
  } catch(e) {
    if(errEl){errEl.textContent=e.message||'Login failed — please check your credentials';errEl.style.display='block';}
    if(btn){btn.disabled=false;btn.textContent='Sign In & Switch';}
  }
}
// Close switcher on outside click
document.addEventListener('click', e => {
  if (_acctSwitcherOpen) {
    const panel = document.getElementById('account-switcher-panel');
    // Check if click target is inside the panel or is a button that toggles the switcher
    const isToggleBtn = e.target.closest && e.target.closest('[onclick*="toggleAccountSwitcher"]');
    if (panel && !panel.contains(e.target) && !isToggleBtn) {
      _acctSwitcherOpen = false;
      panel.style.display = 'none';
    }
  }
}, true);


