// ADMIN: GRANT RADIANCE
// ════════════════════════════════════════════════════
async function adminGrantRadiance() {
  const username = document.getElementById('radiance-username')?.value?.trim();
  const days = parseInt(document.getElementById('radiance-days')?.value||'7');
  if (!username) { toast('Enter a username', 'error'); return; }
  try {
    const until = new Date(Date.now() + days*86400000).toISOString();
    await FortizedSocial.adminUpdateUserField(username, 'radianceUntil', until);
    toast(`Radiance granted to ${username} for ${days} days`, 'success');
    logAudit('grant_radiance', username, `${days} days`);
    document.getElementById('radiance-username').value = '';
  } catch(e) {
    toast('Could not grant Radiance: '+e.message, 'error');
  }
}

async function adminGrantRadiancePlus() {
  const username = document.getElementById('radiance-username')?.value?.trim();
  const days = parseInt(document.getElementById('radiance-days')?.value||'30');
  if (!username) { toast('Enter a username', 'error'); return; }
  try {
    const until = new Date(Date.now() + days*86400000).toISOString();
    await FortizedSocial.adminUpdateUserField(username, 'radiancePlus', until);
    await FortizedSocial.adminUpdateUserField(username, 'radianceUntil', until);
    toast(`Radiance+ granted to ${username} for ${days} days`, 'success');
    logAudit('grant_radiance_plus', username, `${days} days`);
  } catch(e) {
    toast('Could not grant Radiance+: '+e.message, 'error');
  }
}


async function joinByInvite(code) {
  if (!code) return;
  toast('Looking up invite…', 'info');
  try {
    // Strategy 1: Check the dedicated invites collection first
    let foundBastion = null, inviterName = null;
    try {
      const inviteData = await FortizedSocial.getInvite(code);
      if (inviteData && inviteData.bastionId) {
        const b = await FortizedSocial.getGlobalBastion(inviteData.bastionId);
        if (b) {
          foundBastion = b;
          // Ensure the bastion has correct id from the invite data
          if (!foundBastion.id) foundBastion.id = inviteData.bastionId;
          inviterName = inviteData.createdBy || b.owner;
        }
      }
    } catch(e) { console.debug('[Invite] strategy 1 lookup failed', e); }

    // Strategy 2: Search all global bastions for matching invite code
    if (!foundBastion) {
      const allBastions = await FortizedSocial.getGlobalBastions() || {};
      for (const [key, b] of Object.entries(allBastions)) {
        const invites = b.invites || [];
        const found = invites.find(inv => inv.code === code);
        if (found) {
          // Check expiry
          if (found.expires && new Date(found.expires) < new Date()) continue;
          if (found.maxUses && (found.uses||0) >= found.maxUses) continue;
          foundBastion = b;
          // Use the Firebase key as the authoritative ID
          if (!foundBastion.id) foundBastion.id = key;
          inviterName = found.createdBy || b.owner; break;
        }
      }
    }

    // Strategy 3: Search all users' bastions for the invite code
    if (!foundBastion) {
      const allUsers = await FortizedSocial.getUsers();
      for (const user of allUsers) {
        for (const b of (user.bastions||[])) {
          const found = (b.invites||[]).find(inv => inv.code === code);
          if (found) {
            foundBastion = {...b};
            // Ensure a proper globalId exists
            if (!foundBastion.globalId && !foundBastion.id) {
              foundBastion.id = (b.owner || user.username) + '_' + Date.now();
            } else {
              foundBastion.id = foundBastion.globalId || foundBastion.id;
            }
            inviterName = found.createdBy || b.owner;
            // Sync this bastion to global so it's discoverable in future
            try { await FortizedSocial.saveGlobalBastion(foundBastion.id, {...foundBastion, id: foundBastion.id}); } catch(e) { console.warn('[Invite] global bastion sync failed', e); }
            break;
          }
        }
        if (foundBastion) break;
      }
    }

    if (!foundBastion) { toast('Invite link is invalid or expired', 'error'); return; }
    const gid = foundBastion.id || foundBastion.globalId;
    const already = (CU.bastions||[]).some(ub => gid && ub.globalId === gid);
    if (already) { toast("You're already in " + foundBastion.name, 'info'); return; }
    await showBastionInviteDialog(foundBastion, inviterName || 'Someone', code);
  } catch(e) {
    toast('Could not load invite: ' + (e.message||e), 'error');
  }
}


function refreshDailyBtn() {
  const btn = document.getElementById('daily-btn');
  if (!btn) return;
  const today = new Date().toDateString();
  if (CU?.lastDailyReward === today || CU?.lastDaily === today) {
    btn.classList.add('claimed');
    btn.innerHTML = '<span>✓ Claimed!</span><strong>Come back tomorrow</strong>';
  } else {
    btn.classList.remove('claimed');
    btn.innerHTML = '<span>Claim Now</span><strong>+50 Onyx</strong>';
  }
}


// ════════════════════════════════════════════════════════════
// :EMOJI: AUTOCOMPLETE — Discord-style dropdown
// ════════════════════════════════════════════════════════════
let _acSelected = 0;
let _acResults = [];
let _acTarget = null;
let _acStartPos = -1;

function setupEmojiAutocomplete(inputId) {
  const ta = document.getElementById(inputId);
  if (!ta || ta._emojiAcBound) return;
  ta._emojiAcBound = true;

  ta.addEventListener('input', () => {
    // Try smart suggestions first (@, #, /)
    if (!_handleSmartSuggestion(ta)) {
      handleEmojiAutocomplete(ta);
    }
  });
  ta.addEventListener('keydown', (e) => {
    // Smart suggestion panel takes priority
    const sp = document.getElementById('smart-suggest-panel');
    if (sp && sp.style.display !== 'none') {
      if (e.key === 'ArrowDown') { e.preventDefault(); _sugSelected = Math.min(_sugSelected+1, _sugResults.length-1); _renderSuggestPanel(ta); }
      else if (e.key === 'ArrowUp') { e.preventDefault(); _sugSelected = Math.max(_sugSelected-1, 0); _renderSuggestPanel(ta); }
      else if (e.key === 'Enter' || e.key === 'Tab') {
        if (_sugResults[_sugSelected]) { e.preventDefault(); _applySuggestion(_sugResults[_sugSelected], ta); }
      }
      else if (e.key === 'Escape') { _hideSuggestPanel(); }
      return;
    }
    const ac = document.getElementById('emoji-ac-panel');
    if (!ac || !ac.classList.contains('show')) return;
    if (e.key === 'ArrowDown') { e.preventDefault(); _acSelected = Math.min(_acSelected+1, _acResults.length-1); renderAcPanel(ta); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); _acSelected = Math.max(_acSelected-1, 0); renderAcPanel(ta); }
    else if (e.key === 'Enter' || e.key === 'Tab') {
      if (_acResults[_acSelected]) { e.preventDefault(); applyEmojiAc(_acResults[_acSelected], ta); }
    }
    else if (e.key === 'Escape') { hideEmojiAc(); }
  });
  ta.addEventListener('blur', () => setTimeout(() => { hideEmojiAc(); _hideSuggestPanel(); }, 150));
}

function handleEmojiAutocomplete(ta) {
  const val = ta.value;
  const pos = ta.selectionStart;

  // Auto-replace completed :shortcode: patterns
  const completedMatch = val.slice(0, pos).match(/:([a-zA-Z0-9_]+):$/);
  if (completedMatch) {
    const name = completedMatch[1].toLowerCase();
    const emoji = EMOJI_SHORTCODES[name];
    if (emoji) {
      const before = val.slice(0, pos - completedMatch[0].length);
      const after = val.slice(pos);
      ta.value = before + emoji + after;
      ta.selectionStart = ta.selectionEnd = before.length + emoji.length;
      hideEmojiAc();
      return;
    }
  }

  // Find the last ':' before cursor that starts a shortcode
  let colonPos = -1;
  for (let i = pos-1; i >= Math.max(0, pos-30); i--) {
    if (val[i] === ':') { colonPos = i; break; }
    if (/\s/.test(val[i])) break;
  }
  if (colonPos === -1 || pos - colonPos < 2) { hideEmojiAc(); return; }
  const query = val.slice(colonPos+1, pos).toLowerCase();
  if (!query || query.includes(':') || query.includes(' ')) { hideEmojiAc(); return; }
  
  // Find matches — smart suggestion: exact prefix first, then contains, then synonyms
  _acResults = [];
  const seen = new Set();
  const prefixMatches = [];
  const containsMatches = [];
  // Emoji synonym map for smarter matching
  const EMOJI_SYNONYMS = {sob:'cry,sad,tears',joy:'laugh,lol,haha',heart:'love',fire:'hot,lit',skull:'dead,💀',clap:'applause,bravo',thumbsup:'like,yes,ok',thumbsdown:'dislike,no,bad',thinking:'hmm,wonder',rage:'angry,mad',rolling_eyes:'annoyed',pray:'please,hope,thanks',100:'perfect,score',star:'fav,favorite',wave:'hi,hello,bye',muscle:'strong,flex',rocket:'launch,fast',brain:'smart,think',clown:'joke,fool',ghost:'boo,spooky',alien:'ufo,space'};
  // Unicode shortcodes
  Object.entries(EMOJI_SHORTCODES).forEach(([name, emoji]) => {
    if (seen.has(emoji)) return;
    if (name.startsWith(query)) { prefixMatches.push({type:'unicode', name, emoji}); seen.add(emoji); }
    else if (name.includes(query)) { containsMatches.push({type:'unicode', name, emoji}); seen.add(emoji); }
    else { const syns = EMOJI_SYNONYMS[name]; if (syns && syns.split(',').some(s => s.startsWith(query))) { containsMatches.push({type:'unicode', name, emoji}); seen.add(emoji); } }
  });
  // Prioritize recently used emojis
  const recentPrefixes = prefixMatches.filter(m => _recentEmojis.includes(m.emoji));
  const recentContains = containsMatches.filter(m => _recentEmojis.includes(m.emoji));
  _acResults = [...recentPrefixes, ...prefixMatches.filter(m => !_recentEmojis.includes(m.emoji)), ...recentContains, ...containsMatches.filter(m => !_recentEmojis.includes(m.emoji))];
  // Fortized custom emojis
  FORTIZED_EMOJIS.forEach(name => {
    if (name.startsWith(query) || name.includes(query)) _acResults.push({type:'ftz', name, url:FORTIZED_EMOJI_MAP[name]});
  });
  // Bastion custom emojis
  if (curBastion !== null) {
    (CU?.bastions?.[curBastion]?.customEmojis||[]).forEach(ce => {
      if (ce.name.startsWith(query) || ce.name.includes(query)) _acResults.push({type:'custom', name:ce.name, url:ce.data});
    });
  }

  _acResults = _acResults.slice(0, 12);
  if (!_acResults.length) { hideEmojiAc(); return; }
  
  _acTarget = ta;
  _acStartPos = colonPos;
  _acSelected = 0;
  renderAcPanel(ta);
}

function renderAcPanel(ta) {
  let panel = document.getElementById('emoji-ac-panel');
  if (!panel) {
    panel = document.createElement('div');
    panel.id = 'emoji-ac-panel';
    panel.className = 'emoji-autocomplete';
    document.body.appendChild(panel);
  }
  // Position above the textarea
  const rect = ta.getBoundingClientRect();
  panel.style.cssText = `position:fixed;bottom:${window.innerHeight-rect.top+6}px;left:${rect.left}px;background:var(--panel);border:1px solid var(--border);border-radius:12px;padding:6px;z-index:9500;box-shadow:0 12px 40px rgba(0,0,0,.7);min-width:260px;max-width:380px;display:flex;flex-direction:column;gap:2px;`;
  
  const queryText = escapeHTML(ta.value.slice(_acStartPos+1, ta.selectionStart));
  panel.innerHTML = '';
  // Header
  const hdr = document.createElement('div');
  hdr.style.cssText = 'font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:rgba(255,255,255,.3);padding:2px 6px 5px;';
  hdr.innerHTML = 'Emoji Matching <span style="color:rgba(255,249,62,.7);">:' + queryText + ':</span>';
  panel.appendChild(hdr);
  _acResults.forEach((r, i) => {
    const row = document.createElement('div');
    row.onclick = () => applyEmojiAcById(i);
    row.style.cssText = 'display:flex;align-items:center;gap:10px;padding:7px 10px;border-radius:8px;cursor:pointer;background:' + (i===_acSelected ? 'rgba(255,249,62,.12)' : 'transparent') + ';';
    row.onmouseover = () => { row.style.background = 'rgba(255,255,255,.07)'; };
    row.onmouseout = () => { row.style.background = i===_acSelected ? 'rgba(255,249,62,.12)' : 'transparent'; };
    const img = document.createElement('img');
    if (r.type === 'unicode') {
      img.src = emojiToTwemojiUrl(r.emoji);
      img.style.cssText = 'width:26px;height:26px;object-fit:contain;';
      img.onerror = function() { this.style.display = 'none'; };
    } else {
      img.src = r.url || '';
      img.style.cssText = 'width:24px;height:24px;object-fit:contain;';
      img.onerror = function() { this.style.display = 'none'; };
    }
    row.appendChild(img);
    const label = document.createElement('span');
    label.style.cssText = 'font-family:monospace;font-size:12.5px;color:rgba(255,255,255,.7);';
    label.textContent = ':' + r.name + ':';
    row.appendChild(label);
    if (r.type === 'ftz') {
      const badge = document.createElement('span');
      badge.style.cssText = 'font-size:9px;background:rgba(255,249,62,.12);color:var(--accent);padding:1px 6px;border-radius:4px;margin-left:auto;';
      badge.textContent = 'Fortized';
      row.appendChild(badge);
    }
    panel.appendChild(row);
  });
  panel.style.display = 'flex';
  panel.style.flexDirection = 'column';
  if (!panel.classList.contains('show')) panel.classList.add('show');
}

function applyEmojiAcById(idx) {
  _acSelected = idx;
  if (_acTarget) applyEmojiAc(_acResults[idx], _acTarget);
}

function applyEmojiAc(result, ta) {
  const pos = ta.selectionStart;
  const before = ta.value.slice(0, _acStartPos);
  const after = ta.value.slice(pos);
  let insert;
  if (result.type === 'unicode') {
    insert = result.emoji + ' ';
    // Add to recent
    _recentEmojis = [result.emoji, ..._recentEmojis.filter(e=>e!==result.emoji)].slice(0,24);
    localStorage.setItem('ftz_recent_emojis', JSON.stringify(_recentEmojis));
  } else {
    insert = ':' + result.name + ': ';
  }
  ta.value = before + insert + after;
  ta.selectionStart = ta.selectionEnd = _acStartPos + insert.length;
  ta.focus();
  hideEmojiAc();
}

function hideEmojiAc() {
  const panel = document.getElementById('emoji-ac-panel');
  if (panel) { panel.style.display = 'none'; panel.classList.remove('show'); }
  _acResults = [];
  _acStartPos = -1;
  _acTarget = null;
}

// Wire up autocomplete when DM/GC/channel views are opened
function wireAllEmojiAutocomplete() {
  ['dm-input','gc-input','ch-input','thread-input'].forEach(setupEmojiAutocomplete);
}


// ════════════════════════════════════════════
// SMART SUGGESTION SYSTEM (@, #, /)
// ════════════════════════════════════════════
let _sugResults = [];
let _sugSelected = 0;
let _sugStartPos = -1;
let _sugType = ''; // 'mention','room','format'

function _handleSmartSuggestion(ta) {
  const val = ta.value;
  const pos = ta.selectionStart;
  if (pos === 0) { _hideSuggestPanel(); return false; }

  // Find trigger character before cursor
  let triggerPos = -1;
  let triggerChar = '';
  for (let i = pos-1; i >= Math.max(0, pos-40); i--) {
    const c = val[i];
    if (c === '@' || c === '#' || c === '/') {
      // Must be at start of word (start of input or preceded by space/newline)
      if (i === 0 || /[\s\n]/.test(val[i-1])) {
        triggerPos = i;
        triggerChar = c;
        break;
      }
    }
    if (/\s/.test(c)) break;
  }

  if (triggerPos === -1) { _hideSuggestPanel(); return false; }

  const query = val.slice(triggerPos + 1, pos).toLowerCase();

  // Build results based on trigger type
  _sugResults = [];
  _sugType = triggerChar;
  _sugStartPos = triggerPos;

  if (triggerChar === '@') {
    // Context: DMs should not show @everyone, @here, or roles
    const isDM = ta.id === 'dm-input' || ta.id === 'gc-input';
    if (!isDM) {
      // @everyone and @here
      if ('everyone'.startsWith(query)) _sugResults.push({type:'special',label:'everyone',desc:'Notify all members',icon:'📢',insert:'@everyone'});
      if ('here'.startsWith(query)) _sugResults.push({type:'special',label:'here',desc:'Notify online members',icon:'📍',insert:'@here'});
      // Roles
      if (curBastion !== null) {
        const b = CU?.bastions?.[curBastion];
        (b?.roles||[]).forEach(r => {
          if (r.name.toLowerCase().startsWith(query) || r.name.toLowerCase().includes(query)) {
            _sugResults.push({type:'role',label:r.name,desc:`${(Object.entries(b.memberRoles||{}).filter(([_,rids])=>rids.includes(r.id)).length)||0} members`,icon:'🎖',color:r.color||'#60a5fa',insert:'@'+r.name});
          }
        });
      }
    }
    // Users — from member list or friends
    const users = _getSuggestableUsers();
    users.forEach(u => {
      if (u.toLowerCase().startsWith(query) || u.toLowerCase().includes(query)) {
        _sugResults.push({type:'user',label:u,desc:'User',icon:null,pfp:_pfpCache[u]||null,insert:'@'+u});
      }
    });
    _sugResults = _sugResults.slice(0, 10);
  }
  else if (triggerChar === '#') {
    if (curBastion !== null) {
      const b = CU?.bastions?.[curBastion];
      // Rooms
      (b?.channels||[]).forEach(ch => {
        if (ch.name.toLowerCase().startsWith(query) || ch.name.toLowerCase().includes(query)) {
          const typeLabel = {text:'Text Room',voice:'Party Room',forum:'Forum Room',announcement:'Announcement Room',poll:'Poll Room'}[ch.type]||'Room';
          _sugResults.push({type:'room',label:ch.name,desc:typeLabel,icon:ch.type==='voice'?'🎉':ch.type==='forum'?'💬':ch.type==='announcement'?'📢':ch.type==='poll'?'🗳':'#',insert:'#'+ch.name});
        }
      });
      // Categories
      (b?.categories||[]).forEach(cat => {
        if (cat.name.toLowerCase().startsWith(query) || cat.name.toLowerCase().includes(query)) {
          const roomCount = (b.channels||[]).filter(ch=>ch.categoryId===cat.id).length;
          _sugResults.push({type:'category',label:cat.name,desc:`Category · ${roomCount} rooms`,icon:'📁',insert:'#'+cat.name});
        }
      });
    }
    _sugResults = _sugResults.slice(0, 10);
  }
  else if (triggerChar === '/') {
    // Format suggestions
    const formats = [
      {label:'Title1',desc:'Large heading: /Your Title/',icon:'📝',insert:'/'},
      {label:'Title2',desc:'Medium heading: //Your Title//',icon:'📝',insert:'//'},
      {label:'Subtitle',desc:'Small uppercase: ///Your Text///',icon:'📝',insert:'///'},
    ];
    formats.forEach(f => {
      if (f.label.toLowerCase().startsWith(query) || f.label.toLowerCase().includes(query)) {
        _sugResults.push({type:'format',...f});
      }
    });
    _sugResults = _sugResults.slice(0, 6);
  }

  if (!_sugResults.length) { _hideSuggestPanel(); return false; }
  _sugSelected = 0;
  _renderSuggestPanel(ta);
  return true;
}

function _getSuggestableUsers() {
  const users = new Set();
  // Current bastion members
  if (curBastion !== null) {
    const b = CU?.bastions?.[curBastion];
    if (b?.owner) users.add(b.owner);
    Object.keys(b?.memberRoles||{}).forEach(u => users.add(u));
  }
  // Friends
  (CU?.friends||[]).forEach(f => users.add(f));
  // Self
  if (CU?.username) users.add(CU.username);
  return [...users];
}

function _renderSuggestPanel(ta) {
  let panel = document.getElementById('smart-suggest-panel');
  if (!panel) {
    panel = document.createElement('div');
    panel.id = 'smart-suggest-panel';
    panel.className = 'suggest-panel';
    document.body.appendChild(panel);
  }
  const rect = ta.getBoundingClientRect();
  panel.style.cssText += `;position:fixed;bottom:${window.innerHeight-rect.top+6}px;left:${rect.left}px;display:flex;flex-direction:column;gap:2px;`;

  const typeLabels = {'@':'Mentions','#':'Rooms & Categories','/':'Formatting'};
  const queryText = ta.value.slice(_sugStartPos+1, ta.selectionStart);
  panel.innerHTML = `<div class="sp-header">${typeLabels[_sugType]||'Suggestions'} ${queryText?'— <span style="color:rgba(255,249,62,.7);">'+escapeHTML(queryText)+'</span>':''}</div>`;
  _sugResults.forEach((r, i) => {
    const row = document.createElement('div');
    row.className = 'sp-item' + (i===_sugSelected?' selected':'');
    row.onclick = () => { _sugSelected = i; _applySuggestion(r, ta); };
    row.onmouseenter = () => { _sugSelected = i; _renderSuggestPanel(ta); };

    let iconHTML;
    if (r.pfp) {
      iconHTML = `<img src="${escapeHTML(r.pfp)}" style="width:26px;height:26px;border-radius:50%;object-fit:cover;">`;
    } else if (r.icon) {
      iconHTML = `<div class="sp-icon">${r.icon}</div>`;
    } else {
      iconHTML = `<div class="sp-icon">${(r.label||'?')[0].toUpperCase()}</div>`;
    }

    let badgeHTML = '';
    if (r.type === 'role' && r.color) badgeHTML = `<span class="sp-badge" style="background:${r.color}18;color:${r.color};border:1px solid ${r.color}44;">Role</span>`;
    else if (r.type === 'special') badgeHTML = `<span class="sp-badge" style="background:rgba(255,249,62,.1);color:var(--accent);border:1px solid rgba(255,249,62,.2);">Special</span>`;

    row.innerHTML = `${iconHTML}<div style="flex:1;min-width:0;"><div class="sp-label">${escapeHTML(r.label)}</div><div class="sp-sub">${escapeHTML(r.desc||'')}</div></div>${badgeHTML}`;
    panel.appendChild(row);
  });
  panel.style.display = 'flex';
}

function _applySuggestion(result, ta) {
  const pos = ta.selectionStart;
  const before = ta.value.slice(0, _sugStartPos);
  const after = ta.value.slice(pos);
  let insert = result.insert + ' ';
  // For format suggestions, handle differently — replace the / with the format wrapper
  if (result.type === 'format') {
    // The user typed / already, and we need the wrapping format
    insert = result.insert; // just the opening slashes, user types content
  }
  ta.value = before + insert + after;
  ta.selectionStart = ta.selectionEnd = _sugStartPos + insert.length;
  ta.focus();
  _hideSuggestPanel();
  autoResize(ta);
}

function _hideSuggestPanel() {
  const panel = document.getElementById('smart-suggest-panel');
  if (panel) panel.style.display = 'none';
  _sugResults = [];
  _sugStartPos = -1;
}

function toggleEmoticonConversion(el) {
  _globalSettings.disableEmoticonConversion = !_globalSettings.disableEmoticonConversion;
  el.classList.toggle('on', !_globalSettings.disableEmoticonConversion);
  saveGlobalSettings();
  toast('Emoticon conversion ' + (_globalSettings.disableEmoticonConversion ? 'disabled' : 'enabled'), 'info');
}

// ════════════════════════════════════════════════════════
// TEXT SELECTION FORMATTING PANEL
// ════════════════════════════════════════════════════════
let _fmtActiveTA = null;
let _fmtSelStart = 0;
let _fmtSelEnd = 0;

function _initFmtPanel() {
  document.addEventListener('mouseup', (e) => {
    setTimeout(() => {
      const panel = document.getElementById('fmt-sel-panel');
      if (!panel) return;
      // Check if any chat textarea has a selection
      const textareas = document.querySelectorAll('.chat-input-row textarea');
      let foundTA = null;
      for (let i = 0; i < textareas.length; i++) {
        const ta = textareas[i];
        if (ta.selectionStart !== ta.selectionEnd && document.activeElement === ta) {
          foundTA = ta;
          break;
        }
      }
      if (!foundTA) { _hideFmtPanel(); return; }
      _fmtActiveTA = foundTA;
      _fmtSelStart = foundTA.selectionStart;
      _fmtSelEnd = foundTA.selectionEnd;
      // Position panel above the textarea
      const taRect = foundTA.getBoundingClientRect();
      const panelW = 280;
      let px = taRect.left + (taRect.width / 2) - (panelW / 2);
      let py = taRect.top - 42;
      if (px < 8) px = 8;
      if (px + panelW > window.innerWidth - 8) px = window.innerWidth - panelW - 8;
      if (py < 8) py = taRect.bottom + 6;
      panel.style.left = px + 'px';
      panel.style.top = py + 'px';
      panel.classList.add('show');
    }, 10);
  });
  document.addEventListener('mousedown', function(e) {
    const panel = document.getElementById('fmt-sel-panel');
    if (panel && panel.classList.contains('show') && !panel.contains(e.target)) {
      _hideFmtPanel();
    }
  });
}

function _hideFmtPanel() {
  const panel = document.getElementById('fmt-sel-panel');
  if (panel) panel.classList.remove('show');
  _fmtActiveTA = null;
}

function _fmtWrap(marker) {
  if (!_fmtActiveTA) return;
  const ta = _fmtActiveTA;
  const start = _fmtSelStart;
  const end = _fmtSelEnd;
  const val = ta.value;
  const selected = val.substring(start, end);
  if (!selected) { _hideFmtPanel(); return; }
  const wrapped = marker + selected + marker;
  ta.value = val.substring(0, start) + wrapped + val.substring(end);
  ta.selectionStart = start;
  ta.selectionEnd = start + wrapped.length;
  ta.focus();
  ta.dispatchEvent(new Event('input', {bubbles:true}));
  _hideFmtPanel();
}

function _fmtInsertLink() {
  if (!_fmtActiveTA) return;
  const ta = _fmtActiveTA;
  const start = _fmtSelStart;
  const end = _fmtSelEnd;
  const val = ta.value;
  const selected = val.substring(start, end);
  if (!selected) { _hideFmtPanel(); return; }
  const wrapped = '[' + selected + '](url)';
  ta.value = val.substring(0, start) + wrapped + val.substring(end);
  // Select "url" for easy replacement
  const urlStart = start + selected.length + 3;
  ta.selectionStart = urlStart;
  ta.selectionEnd = urlStart + 3;
  ta.focus();
  ta.dispatchEvent(new Event('input', {bubbles:true}));
  _hideFmtPanel();
}

// Init on load
setTimeout(_initFmtPanel, 500);

// ════════════════════════════════════════════════════════
// LIVE FORMATTING PREVIEW IN CHAT INPUT
// ════════════════════════════════════════════════════════
function _setupLivePreview(ta) {
  if (ta._livePreviewInit) return;
  ta._livePreviewInit = true;
  // Wrap textarea in a relative container if not already
  const parent = ta.parentNode;
  if (!parent.classList.contains('ci-preview-wrap')) {
    const wrap = document.createElement('div');
    wrap.className = 'ci-preview-wrap';
    wrap.style.cssText = 'position:relative;flex:1;min-width:0;display:flex;';
    parent.insertBefore(wrap, ta);
    wrap.appendChild(ta);
    // Create overlay div
    const preview = document.createElement('div');
    preview.className = 'ci-preview';
    wrap.appendChild(preview);
    ta._previewEl = preview;
  }
  // Sync on input
  ta.addEventListener('input', () => _updateLivePreview(ta));
  ta.addEventListener('scroll', () => { if (ta._previewEl) ta._previewEl.scrollTop = ta.scrollTop; });
  // Initial render
  _updateLivePreview(ta);
}

function _updateLivePreview(ta) {
  const el = ta._previewEl;
  if (!el) return;
  const val = ta.value;
  if (!val) { el.innerHTML = ''; ta.style.color = ''; return; }
  // Check if there's any formatting syntax — if not, don't show overlay
  if (!/[*~`|=@#\[]/.test(val)) { el.innerHTML = ''; ta.style.color = ''; return; }
  // Apply live formatting
  const html = _liveFormatPreview(val);
  // Only use overlay if formatting was actually applied
  if (html !== escapeHTML(val)) {
    el.innerHTML = html;
    ta.style.color = 'transparent';
    ta.style.caretColor = 'var(--text)';
    // Sync scroll
    el.scrollTop = ta.scrollTop;
  } else {
    el.innerHTML = '';
    ta.style.color = '';
  }
}

function _liveFormatPreview(text) {
  let s = escapeHTML(text);
  // Block code ``` ... ``` — render as code style
  s = s.replace(/```([^`]*?)```/g, '<span class="ci-code">```$1```</span>');
  // Inline code
  s = s.replace(/`([^`\n]+?)`/g, '<span class="ci-code">`$1`</span>');
  // Bold italic ***text***
  s = s.replace(/\*\*\*(.+?)\*\*\*/g, '<span class="ci-bold ci-italic">***$1***</span>');
  // Bold **text**
  s = s.replace(/\*\*(.+?)\*\*/g, '<span class="ci-bold">**$1**</span>');
  // Italic *text*
  s = s.replace(/(?<!\*)\*([^*\n]+?)\*(?!\*)/g, '<span class="ci-italic">*$1*</span>');
  // Strikethrough ~~text~~
  s = s.replace(/~~(.+?)~~/g, '<span class="ci-strike">~~$1~~</span>');
  // Spoiler ||text||
  s = s.replace(/\|\|(.+?)\|\|/g, '<span class="ci-spoiler">||$1||</span>');
  // Highlight ==text==
  s = s.replace(/==(.+?)==/g, '<span class="ci-highlight">==$1==</span>');
  // Small text --text--
  s = s.replace(/--([^-]+?)--/g, '<span class="ci-smalltext">--$1--</span>');
  // @mentions
  s = s.replace(/@(\w+)/g, '<span class="ci-mention">@$1</span>');
  // #room references
  s = s.replace(/#(\w[\w-]*)/g, '<span class="ci-room-ref">#$1</span>');
  return s;
}

// Hook into buildChatInputBar — after textarea is inserted, setup live preview
const _origAutoResize = typeof autoResize === 'function' ? autoResize : null;
let _livePreviewObserver = null;
function _hookLivePreviewOnInput() {
  // Disconnect previous observer to prevent duplicates
  if (_livePreviewObserver) { _livePreviewObserver.disconnect(); _livePreviewObserver = null; }
  // Observe DOM for new textareas in chat-input-row
  const observer = _livePreviewObserver = new MutationObserver(mutations => {
    mutations.forEach(m => {
      m.addedNodes.forEach(n => {
        if (n.nodeType !== 1) return;
        const tas = n.querySelectorAll ? n.querySelectorAll('.chat-input-row textarea') : [];
        tas.forEach(ta => _setupLivePreview(ta));
        if (n.matches && n.matches('.chat-input-row textarea')) _setupLivePreview(n);
      });
    });
  });
  observer.observe(document.body, {childList:true, subtree:true});
  // Also setup existing textareas
  document.querySelectorAll('.chat-input-row textarea').forEach(ta => _setupLivePreview(ta));
}
setTimeout(_hookLivePreviewOnInput, 800);


// ════════════════════════════════════════════════════════
// DRAG & DROP + PASTE UPLOAD
// ════════════════════════════════════════════════════════
function initDragDrop() {
  // Prevent default browser drag behavior globally (so files don't open in browser)
  document.addEventListener('dragover', e => e.preventDefault());
  document.addEventListener('drop', e => e.preventDefault());
  // Drag-drop is handled per chat-input-outer via inline handlers (ondragover/ondrop)
}

function handleDropOnInput(e, inputId) {
  e.preventDefault();
  e.stopPropagation();
  const outer = document.getElementById(inputId + '-outer');
  if (outer) { const ov = outer.querySelector('.drop-overlay'); if (ov) ov.classList.remove('active'); }
  const files = [...e.dataTransfer.files];
  if (!files.length) return;
  processUploadedFile(files[0], inputId);
}

function handlePaste(e, inputId) {
  const items = [...(e.clipboardData?.items || [])];
  const imageItem = items.find(i => i.type.startsWith('image/'));
  if (!imageItem) return; // let normal paste proceed
  e.preventDefault();
  const file = imageItem.getAsFile();
  if (file) processUploadedFile(file, inputId);
}

function processUploadedFile(file, inputId) {
  if (!file) return;
  const hasRadiance = CU?.radianceUntil && new Date(CU.radianceUntil) > new Date();
  const maxMB = hasRadiance ? 45 : 30;
  if (file.size > maxMB * 1024 * 1024) { toast(`Max ${maxMB}MB`, 'error'); return; }
  const reader = new FileReader();
  reader.onload = async ev => {
    const fileData = ev.target.result;
    // Queue media for NSFW review without blocking upload
    const isMedia = file.type.startsWith('image/') || file.type.startsWith('video/') || /\.(gif|webp)$/i.test(file.name);
    if (isMedia) {
      try {
        const hash = typeof _simpleImageHash === 'function' ? _simpleImageHash(fileData) : '';
        if (_nsfwBannedHashes && _nsfwBannedHashes.includes(hash)) {
          toast('This content has been banned and cannot be uploaded.', 'error');
          return;
        }
        // Send to NSFW queue for manual review — no blocking AI scan
        _flagNsfwContent(fileData, file.name, CU?.username, file.type, 'PENDING_REVIEW', '0', hash);
      } catch(e) { console.warn('NSFW queue error:', e); }
    }
    window._pendingAttachment = { name: file.name, type: file.type, data: fileData, size: file.size, context: inputId };
    const ctx = inputId==='dm-input'?'dm':inputId==='gc-input'?'gc':'ch';
    showAttachmentPreview(file.name, file.type, fileData, file.size, ctx);
  };
  reader.readAsDataURL(file);
  toast('📎 ' + file.name + ' attached', 'info');
}


// ════════════════════════════════════════════════════════
// IMAGE CROP MODAL
// ════════════════════════════════════════════════════════
let _cropCanvas, _cropCtx, _cropImg, _cropCallback;
let _cropData = {x:0,y:0,scale:1,ratio:1,dragging:false,lastX:0,lastY:0,hasAlpha:false};
let _cropAnimId = null;

function showCropModal(src, aspectRatio, callback, cropShape) {
  _cropCallback = callback;
  _cropData = {x:0,y:0,scale:1,ratio:aspectRatio||1,dragging:false,lastX:0,lastY:0,hasAlpha:false};
  document.getElementById('crop-modal-overlay')?.remove();

  const overlay = document.createElement('div');
  overlay.id = 'crop-modal-overlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.85);z-index:9900;display:flex;align-items:center;justify-content:center;padding:20px;backdrop-filter:blur(8px);';

  const isBanner = (aspectRatio||1) > 2;
  const isAvatar = (aspectRatio||1) === 1 && cropShape !== 'rounded-square';
  const isRoundedSquare = cropShape === 'rounded-square';
  const borderRadius = isAvatar ? '50%' : isRoundedSquare ? '18%' : '4px';
  const shapeLabel = isAvatar ? 'Circle (Avatar)' : isRoundedSquare ? 'Rounded Square (Emblem)' : 'Rectangle (Banner)';

  overlay.innerHTML = `
    <div style="background:var(--panel);border:1px solid rgba(255,249,62,.06);border-radius:16px;max-width:${isBanner?'680px':'480px'};width:100%;overflow:hidden;box-shadow:0 24px 64px rgba(0,0,0,.7);">
      <div style="padding:16px 20px 12px;border-bottom:1px solid rgba(255,255,255,.06);">
        <div style="font-family:var(--font-display);font-size:16px;font-weight:800;color:#fff;margin-bottom:2px;">Edit Image</div>
        <div style="display:flex;align-items:center;gap:8px;">
          <div style="font-size:12px;color:rgba(255,255,255,.4);">Scroll or drag slider to zoom</div>
          <div style="margin-left:auto;font-size:10px;padding:2px 8px;border-radius:var(--radius-pill);background:rgba(255,249,62,.06);border:1px solid rgba(255,249,62,.1);color:rgba(255,249,62,.6);font-weight:600;">${shapeLabel}</div>
        </div>
      </div>
      <!-- Canvas area with checkered bg for transparency -->
      <div id="crop-canvas-wrap" style="position:relative;width:100%;aspect-ratio:${isBanner?'16/5':'1/1'};cursor:default;overflow:hidden;background:repeating-conic-gradient(#1a1d28 0% 25%, #14171f 0% 50%) 0 0/20px 20px;touch-action:none;">
        <canvas id="crop-canvas" style="position:absolute;inset:0;width:100%;height:100%;"></canvas>
        <!-- Crop guide overlay -->
        <div id="crop-guide" style="position:absolute;inset:0;pointer-events:none;">
          <div style="position:absolute;inset:0;box-shadow:inset 0 0 0 9999px rgba(0,0,0,.5);border-radius:${borderRadius};"></div>
          <div style="position:absolute;inset:0;border:2px solid rgba(255,249,62,.5);border-radius:${borderRadius};"></div>
          ${!isAvatar && !isBanner ? `
          <!-- Rule of thirds grid -->
          <div style="position:absolute;inset:0;border-radius:4px;background:
            linear-gradient(rgba(255,255,255,.12) 1px,transparent 1px) 0 33.3%/100% 33.3%,
            linear-gradient(90deg,rgba(255,255,255,.12) 1px,transparent 1px) 33.3% 0/33.3% 100%;"></div>` : ''}
        </div>
      </div>
      <!-- Controls -->
      <div style="padding:14px 20px;display:flex;align-items:center;gap:12px;border-top:1px solid rgba(255,255,255,.07);">
        <div style="display:flex;align-items:center;gap:8px;flex:1;">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="rgba(255,255,255,.4)" stroke-width="2"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/><line x1="11" y1="8" x2="11" y2="14"/><line x1="8" y1="11" x2="14" y2="11"/></svg>
          <input type="range" id="crop-zoom" min="50" max="300" value="100" style="flex:1;accent-color:var(--accent);cursor:pointer;" oninput="setCropZoom(this.value/100)">
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="rgba(255,255,255,.4)" stroke-width="2"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/><line x1="11" y1="8" x2="11" y2="14"/></svg>
        </div>
        <button onclick="resetCrop()" style="background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.08);border-radius:10px;color:rgba(255,255,255,.5);font-size:12px;padding:7px 14px;cursor:pointer;transition:all .15s;">Reset</button>
        <button onclick="document.getElementById('crop-modal-overlay').remove()" style="background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.08);border-radius:10px;color:rgba(255,255,255,.6);font-size:12px;padding:7px 16px;cursor:pointer;transition:all .15s;">Cancel</button>
        <button onclick="applyCrop()" style="background:linear-gradient(135deg,var(--accent),#e6e034);border:none;border-radius:10px;color:var(--rail);font-size:13px;font-weight:700;padding:8px 22px;cursor:pointer;font-family:var(--font-display);box-shadow:0 2px 10px rgba(255,249,62,.2);transition:all .15s;">Apply</button>
      </div>
    </div>`;

  document.body.appendChild(overlay);

  const wrap = document.getElementById('crop-canvas-wrap');
  _cropCanvas = document.getElementById('crop-canvas');
  _cropCtx = _cropCanvas.getContext('2d');

  _cropImg = new Image();
  _cropImg.crossOrigin = 'anonymous';
  _cropImg.onload = () => {
    const w = wrap.offsetWidth || 480;
    const h = wrap.offsetHeight || 480;
    _cropCanvas.width = w * window.devicePixelRatio;
    _cropCanvas.height = h * window.devicePixelRatio;
    _cropCtx.scale(window.devicePixelRatio, window.devicePixelRatio);
    // Check if image has transparency
    const tmp = document.createElement('canvas');
    tmp.width = Math.min(_cropImg.width, 100); tmp.height = Math.min(_cropImg.height, 100);
    const tc = tmp.getContext('2d');
    tc.drawImage(_cropImg, 0, 0, tmp.width, tmp.height);
    try {
      const d = tc.getImageData(0, 0, tmp.width, tmp.height).data;
      for (let i=3; i<d.length; i+=4) { if(d[i]<255){_cropData.hasAlpha=true;break;} }
    } catch(e) { console.debug('[Crop] alpha detection failed', e); }
    // Fit image (cover the crop area)
    const imgAspect = _cropImg.width / _cropImg.height;
    const canvasAspect = w / h;
    _cropData.scale = imgAspect > canvasAspect ? h / _cropImg.height : w / _cropImg.width;
    _cropData.x = (w - _cropImg.width * _cropData.scale) / 2;
    _cropData.y = (h - _cropImg.height * _cropData.scale) / 2;
    drawCrop();
  };
  _cropImg.src = src;

  // Wheel zoom (always centered)
  wrap.addEventListener('wheel', e => {
    e.preventDefault();
    const factor = e.deltaY < 0 ? 1.08 : 0.93;
    _cropData.scale = Math.max(0.2, Math.min(8, _cropData.scale * factor));
    _centerCropImage();
    const slider = document.getElementById('crop-zoom');
    if (slider) slider.value = Math.round(_cropData.scale * 100);
    drawCrop();
  }, {passive:false});

  // Touch pinch zoom only (no drag panning)
  let _lt = 0;
  wrap.addEventListener('touchstart', e => {
    if(e.touches.length===2){_lt=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);}
    e.preventDefault();
  },{passive:false});
  wrap.addEventListener('touchmove', e => {
    if(e.touches.length===2){const d=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);_cropData.scale=Math.max(0.2,Math.min(8,_cropData.scale*(d/_lt)));_lt=d;_centerCropImage();const s=document.getElementById('crop-zoom');if(s)s.value=Math.round(_cropData.scale*100);drawCrop();}
    e.preventDefault();
  },{passive:false});
}

// Always center the image in the crop area
function _centerCropImage() {
  if (!_cropImg || !_cropCanvas) return;
  const dpr = window.devicePixelRatio || 1;
  const w = _cropCanvas.width / dpr;
  const h = _cropCanvas.height / dpr;
  _cropData.x = (w - _cropImg.width * _cropData.scale) / 2;
  _cropData.y = (h - _cropImg.height * _cropData.scale) / 2;
}

function setCropZoom(val) {
  _cropData.scale = Math.max(0.2, Math.min(8, val));
  _centerCropImage();
  drawCrop();
}

function resetCrop() {
  if (!_cropImg || !_cropCanvas) return;
  const wrap = document.getElementById('crop-canvas-wrap');
  const w = wrap ? wrap.offsetWidth : 480;
  const h = wrap ? wrap.offsetHeight : 480;
  const imgAspect = _cropImg.width / _cropImg.height;
  const canvasAspect = w / h;
  _cropData.scale = imgAspect > canvasAspect ? h / _cropImg.height : w / _cropImg.width;
  _cropData.x = (w - _cropImg.width * _cropData.scale) / 2;
  _cropData.y = (h - _cropImg.height * _cropData.scale) / 2;
  const slider = document.getElementById('crop-zoom');
  if (slider) slider.value = Math.round(_cropData.scale * 100);
  drawCrop();
}

function drawCrop() {
  if (!_cropCanvas || !_cropImg) return;
  const dpr = window.devicePixelRatio || 1;
  const w = _cropCanvas.width / dpr;
  const h = _cropCanvas.height / dpr;
  _cropCtx.clearRect(0, 0, w, h);
  // If no alpha, fill black bg
  if (!_cropData.hasAlpha) {
    _cropCtx.fillStyle = '#000';
    _cropCtx.fillRect(0, 0, w, h);
  }
  _cropCtx.drawImage(_cropImg, _cropData.x, _cropData.y,
    _cropImg.width * _cropData.scale, _cropImg.height * _cropData.scale);
}

function applyCrop() {
  const wrap = document.getElementById('crop-canvas-wrap');
  if (!wrap || !_cropCanvas || !_cropImg) return;
  const dpr = window.devicePixelRatio || 1;
  const w = _cropCanvas.width / dpr;
  const h = _cropCanvas.height / dpr;

  // GIF mode: calculate CSS crop percentages instead of canvas export (preserves animation)
  if (_cropData._isGif && _cropData._gifSrc) {
    const imgDisplayW = _cropImg.width * _cropData.scale;
    const crop = {
      leftPct: (_cropData.x / w) * 100,
      topPct: (_cropData.y / h) * 100,
      widthPct: (imgDisplayW / w) * 100
    };
    document.getElementById('crop-modal-overlay')?.remove();
    if (_cropCallback) _cropCallback({ gifData: _cropData._gifSrc, crop: crop });
    return;
  }

  const outW = _cropData.ratio > 2 ? 960 : 480;
  const outH = _cropData.ratio > 2 ? Math.round(960 / _cropData.ratio) : 480;
  const out = document.createElement('canvas');
  out.width = outW; out.height = outH;
  const ctx = out.getContext('2d');
  const scaleX = outW / w, scaleY = outH / h;
  if (!_cropData.hasAlpha) {
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, outW, outH);
  }
  ctx.drawImage(_cropImg,
    _cropData.x * scaleX, _cropData.y * scaleY,
    _cropImg.width * _cropData.scale * scaleX,
    _cropImg.height * _cropData.scale * scaleY);

  document.getElementById('crop-modal-overlay')?.remove();

  // Use blob conversion for better compression and file handling
  const mimeType = _cropData.hasAlpha ? 'image/png' : 'image/jpeg';
  const quality = _cropData.hasAlpha ? 1 : 0.93;

  out.toBlob((blob) => {
    if (!blob) {
      console.error('[Crop] Failed to create blob');
      // Fallback to data URL
      const fallback = _cropData.hasAlpha
        ? out.toDataURL('image/png')
        : out.toDataURL('image/jpeg', quality);
      if (_cropCallback) _cropCallback(fallback);
      return;
    }

    // Convert blob to data URL for storage (creates actual cropped image)
    const reader = new FileReader();
    reader.onload = (e) => {
      const result = e.target.result;
      console.debug('[Crop] Image cropped and converted:', {
        mimeType,
        size: blob.size,
        dimensions: `${outW}x${outH}`
      });
      if (_cropCallback) _cropCallback(result);
    };
    reader.onerror = () => {
      console.error('[Crop] Failed to read blob');
      // Fallback to toDataURL
      const fallback = _cropData.hasAlpha
        ? out.toDataURL('image/png')
        : out.toDataURL('image/jpeg', quality);
      if (_cropCallback) _cropCallback(fallback);
    };
    reader.readAsDataURL(blob);
  }, mimeType, quality);
}


// ════════════════════════════════════════════════════════
// REAL-TIME CROSS-DEVICE SYNC
// ════════════════════════════════════════════════════════
let _profileSyncListener = null;
let _statusSyncListener = null;
let _notifSyncListener = null;
let _supabaseUserChannel = null; // Supabase real-time subscription

function initCrossDeviceSync() {
  if (!CU?.username) return;

  // 1. SUPABASE REAL-TIME: Listen for direct database changes (table editor, etc)
  // This catches changes made outside of Socket.IO (direct Supabase edits)
  if (typeof supabase !== 'undefined' && supabase.channel) {
    try {
      _supabaseUserChannel = supabase.channel(`users:${CU.username}`)
        .on(
          'postgres_changes',
          { event: '*', schema: 'public', table: 'users', filter: `username=eq.${CU.username}` },
          (payload) => {
            try {
              if (!payload.new) return;
              const newData = payload.new;
              console.debug('[Supabase Real-time] Change detected:', newData);

              // IMPORTANT: Server data takes precedence over local cache
              if (newData.display_name && newData.display_name !== CU.displayName) {
                console.debug('[Sync] Display name updated:', newData.display_name);
                CU.displayName = newData.display_name;
                updateUserbar();
              }
              if (newData.pfp && newData.pfp !== CU.pfp) {
                console.debug('[Sync] Avatar updated');
                CU.pfp = newData.pfp;
                updateUserbar();
                document.querySelectorAll('.msg-av-inner img, .ua img, .up-left-av img').forEach(img => {
                  if (img.src !== newData.pfp) img.src = newData.pfp;
                });
              }
              if (newData.banner && newData.banner !== CU.banner) {
                console.debug('[Sync] Banner updated');
                CU.banner = newData.banner;
              }
              if (newData.status && newData.status !== CU.status) {
                console.debug('[Sync] Status updated:', newData.status);
                CU.status = newData.status;
                updateUserbar();
              }
              if (newData.onyx !== undefined && newData.onyx !== CU.onyx) {
                console.debug('[Sync] Onyx updated:', newData.onyx);
                CU.onyx = newData.onyx;
                updateOnyxDisplay();
              }
              if (newData.friends && JSON.stringify(newData.friends) !== JSON.stringify(CU.friends)) {
                console.debug('[Sync] Friends list updated');
                CU.friends = newData.friends;
              }
              if (newData.bastions && JSON.stringify(newData.bastions) !== JSON.stringify(CU.bastions)) {
                console.debug('[Sync] Bastions updated');
                CU.bastions = newData.bastions;
                renderRailBastions?.();
              }
              if (newData.group_chats && JSON.stringify(newData.group_chats) !== JSON.stringify(CU.groupChats)) {
                console.debug('[Sync] Group chats updated');
                CU.groupChats = newData.group_chats;
                const scroll = document.getElementById('sidebar-scroll');
                if (scroll) renderDMSidebar(scroll);
              }
              saveLocal();
            } catch (e) {
              console.error('[Supabase Sync Error]', e);
            }
          }
        )
        .subscribe((status) => {
          if (status === 'SUBSCRIBED') {
            console.debug('[Supabase] ✓ Real-time user listener SUBSCRIBED', `(user: ${CU.username})`);
          } else if (status === 'CLOSED') {
            console.debug('[Supabase] Real-time user listener closed - attempting to reconnect');
            setTimeout(() => initCrossDeviceSync(), 5000);
          } else if (status === 'CHANNEL_ERROR') {
            console.error('[Supabase] Channel error - reconnecting');
            setTimeout(() => initCrossDeviceSync(), 5000);
          }
        });
    } catch (e) {
      console.error('[Supabase Setup Error]', e);
    }
  }

  // 2. SOCKET.IO EVENTS: Listen to broadcasts from server
  if (!window.socket) return;

  // Listen to Socket.IO events (broadcasts to all clients)
  // These events fire when ANY user makes changes (not just current user)

  // 1. Profile updates from any device
  socket.on('profile:updated', (data) => {
    if (data.username !== CU.username) return;
    if (data.pfp && data.pfp !== CU.pfp) {
      CU.pfp = data.pfp;
      updateUserbar();
      document.querySelectorAll('.msg-av-inner img, .ua img').forEach(img => {
        if (img.src !== data.pfp) img.src = data.pfp;
      });
    }
    if (data.banner !== undefined && data.banner !== CU.banner) {
      CU.banner = data.banner;
    }
    if (data.onyx !== undefined && data.onyx > (CU.onyx||0)) {
      CU.onyx = data.onyx;
      updateOnyxDisplay();
    }
    if (data.customStatus !== undefined) {
      CU.customStatus = data.customStatus;
      refreshCustomStatusBubble?.();
      try { FtzStatus.restoreCustomTimer(); } catch(e) { console.debug('[Status] timer failed', e); }
    }
    if (data.profileWidgets) {
      CU.profileWidgets = data.profileWidgets;
      if (curView === 'profile') renderProfileWidgetsTab();
    }
    if (data.friends) { CU.friends = data.friends; }
    if (data.groupChats) {
      const hadNew = (data.groupChats||[]).length > (CU.groupChats||[]).length;
      CU.groupChats = data.groupChats;
      if (hadNew) {
        const scroll = document.getElementById('sidebar-scroll');
        if (scroll) renderDMSidebar(scroll);
      }
    }
    if (data.bastions) {
      CU.bastions = data.bastions;
      renderRailBastions();
    }
    if (data.onboardingInterests) {
      CU.onboardingInterests = data.onboardingInterests;
    }
    saveLocal();
  });

  // 2. Presence/Status updates — when user changes status on another device
  socket.on('presence:update', (data) => {
    if (data.username === CU.username) {
      // Status changed on another device
      if (data.status && data.status !== CU.status) {
        CU.status = data.status;
        updateUserbar();
      }
      if (data.gameActivity !== undefined) {
        CU.gameActivity = data.gameActivity;
      }
      if (data.activityState !== undefined) {
        CU.activityState = data.activityState;
      }
    }
  });

  // 3. Activity changes
  socket.on('activity:changed', (data) => {
    if (data.username === CU.username) {
      CU.currentActivity = data.gameActivity || data.activityState;
      if (curView === 'profile') {
        const actEl = document.getElementById('user-activity-display');
        if (actEl) actEl.textContent = CU.currentActivity || 'Online';
      }
    }
  });

  // 4. Friend request notifications
  socket.on('friend:request', (data) => {
    if (data.to === CU.username) {
      updateNotifBadge().catch(()=>{});
      if (Notification?.permission === 'granted' && document.hidden && CU?.status !== 'dnd') {
        try {
          const n = new Notification('Friend Request', {
            body: (data.from || 'Someone') + ' sent you a friend request',
            icon: '/Fortized icon.png',
            badge: '/Fortized icon.png',
            tag: 'friend_request',
          });
          n.onclick = () => { window.focus(); n.close(); };
          setTimeout(() => n.close(), 8000);
        } catch(e) { console.debug('[Notif] failed', e); }
      }
      playNotifSound('message');
    }
  });

  // 5. Friend accepted
  socket.on('friend:accepted', (data) => {
    if (data.from === CU.username || data.to === CU.username) {
      // Refresh friend list
      try { FortizedSocial.getUserByUsername(CU.username).then(user => {
        if (user?.friends) { CU.friends = user.friends; saveLocal(); }
      }).catch(()=>{}); } catch(e) { console.debug('[Friend] refresh failed', e); }
    }
  });

  // 6. Notification broadcast
  socket.on('notification:new', (notif) => {
    if (notif.username === CU.username || notif.to === CU.username) {
      updateNotifBadge().catch(()=>{});
      if (notif.type === 'dm' && notif.from) {
        unhideDMConversation('dm_' + notif.from);
      }
      if (Notification?.permission === 'granted' && document.hidden && CU?.status !== 'dnd') {
        let title = 'Fortized', body = 'New notification';
        if (notif.type === 'dm') { title = notif.from || 'New Message'; body = notif.preview || 'Sent you a message'; }
        else if (notif.type === 'mention') { title = 'Mention'; body = (notif.from || 'Someone') + ' mentioned you'; }
        try {
          const n = new Notification(title, {
            body, icon: '/Fortized icon.png', badge: '/Fortized icon.png', tag: notif.type || 'notif',
          });
          n.onclick = () => { window.focus(); n.close(); };
          setTimeout(() => n.close(), 8000);
        } catch(e) { console.debug('[Notif] failed', e); }
      }
      playNotifSound(notif.type === 'mention' ? 'mention' : 'message');
    }
  });

  // 7. Bastion updates
  socket.on('bastion:updated', (data) => {
    if (data.bastionId && CU.bastions) {
      const idx = CU.bastions.findIndex(b => (b.globalId || b.name) === data.bastionId);
      if (idx >= 0) {
        Object.assign(CU.bastions[idx], data.updates);
        renderRailBastions();
      }
    }
  });

  // 8. Announcement broadcasts
  socket.on('announcement:new', (data) => {
    if (document.hidden && CU?.status !== 'dnd') {
      try {
        const n = new Notification('📢 Announcement', {
          body: data.message || 'New announcement',
          icon: '/Fortized icon.png',
          badge: '/Fortized icon.png',
          tag: 'announcement',
        });
        n.onclick = () => { window.focus(); n.close(); };
        setTimeout(() => n.close(), 10000);
      } catch(e) { console.debug('[Announce] failed', e); }
    }
  });

  // 9. Request notification permission
  if (Notification?.permission === 'default') {
    setTimeout(() => {
      Notification.requestPermission().catch(()=>{});
    }, 3000);
  }
}

function stopCrossDeviceSync() {
  // Clean up Supabase real-time subscriptions
  if (_supabaseUserChannel) {
    try {
      supabase.removeChannel(_supabaseUserChannel);
      _supabaseUserChannel = null;
    } catch(e) {
      console.debug('[Supabase] Unsubscribe failed', e);
    }
  }
  // Socket.IO listeners are auto-cleaned up on disconnect
}


