async function purchaseRadiance(isPlus, days, cost) {
  const balance = CU?.onyx || 0;
  if (balance < cost) {
    // Not enough onyx — show dialog
    const ov = document.createElement('div');
    ov.style.cssText = 'position:fixed;inset:0;background:rgba(12,14,20,.88);backdrop-filter:blur(12px);z-index:9100;display:flex;align-items:center;justify-content:center;';
    ov.innerHTML = `<div style="background:var(--panel);border:1px solid var(--border);border-radius:20px;padding:28px;max-width:380px;width:90%;text-align:center;">
      <div style="font-size:40px;margin-bottom:14px;">😕</div>
      <div style="font-family:var(--font-display);font-size:18px;font-weight:800;margin-bottom:8px;">Not Enough Onyx</div>
      <div style="font-size:13.5px;color:var(--muted-light);line-height:1.6;margin-bottom:20px;">You need <strong style="color:var(--accent);">${cost} <img src="/Onyx.png" style="width:14px;height:14px;object-fit:contain;vertical-align:middle;"></strong> but only have <strong>${balance} <img src="/Onyx.png" style="width:14px;height:14px;object-fit:contain;vertical-align:middle;"></strong>.<br>Complete quests to earn more Onyx!</div>
      <div style="display:flex;gap:8px;">
        <button onclick="this.closest('[style*=fixed]').remove();switchAtelierTab('quests',document.getElementById('atnav-quests'))" style="flex:1;padding:10px;background:var(--accent);color:var(--rail);font-family:var(--font-display);font-weight:700;border:none;border-radius:10px;cursor:pointer;">Complete Quests</button>
        <button onclick="this.closest('[style*=fixed]').remove()" style="flex:1;padding:10px;background:rgba(255,255,255,.06);color:var(--muted-light);border:1px solid var(--border);border-radius:10px;cursor:pointer;">Not Now</button>
      </div>
    </div>`;
    document.body.appendChild(ov);
    return;
  }
  showCustomConfirm(
    `Purchase ${isPlus ? 'Radiance+' : 'Radiance'} for ${days} days (${cost} Onyx)?`,
    async () => {
      CU.onyx = (CU.onyx || 0) - cost;
      const until = new Date(Date.now() + days * 86400000).toISOString();
      if (isPlus) { CU.radiancePlus = until; CU.radianceUntil = until; }
      else { CU.radianceUntil = until; }
      await saveUser();
      updateOnyxDisplay();
      distributeOnyxRevenue(cost);
      toast(`✨ ${isPlus ? 'Radiance+' : 'Radiance'} active for ${days} days!`, 'success');
      renderAtelierTab('radiance');
    }
  );
}

async function cancelRadiance() {
  showCustomConfirm(
    'Cancel your Radiance subscription? Perks will stop when the current period ends.',
    async () => {
      delete CU.radianceUntil;
      delete CU.radiancePlus;
      await saveUser();
      toast('Radiance subscription cancelled.', 'info');
      renderAtelierTab('radiance');
    }
  );
}

function buildGiftRadianceUI() {
  const friends = CU?.friends || [];
  const gifted = CU?.giftedRadiance || {};
  let html = `<div style="padding:12px 16px;border-bottom:1px solid rgba(255,255,255,.04);display:flex;align-items:center;gap:8px;">
    <button onclick="createRadianceGiftLink()" style="flex:1;padding:8px;border-radius:10px;background:rgba(255,249,62,.08);border:1px solid rgba(255,249,62,.15);color:var(--accent);font-size:12px;font-weight:700;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:6px;transition:all .15s;" onmouseover="this.style.background='rgba(255,249,62,.14)'" onmouseout="this.style.background='rgba(255,249,62,.08)'"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M10 13a5 5 0 007.54.54l3-3a5 5 0 00-7.07-7.07l-1.72 1.71"/><path d="M14 11a5 5 0 00-7.54-.54l-3 3a5 5 0 007.07 7.07l1.71-1.71"/></svg> Copy Gift Link (600 Onyx)</button>
  </div>`;
  if (!friends.length) {
    return html + '<div style="font-size:13px;color:rgba(255,255,255,.3);padding:16px;">Add friends to gift them directly.</div>';
  }
  html += friends.slice(0, 8).map(f => {
    const fg = gifted[f];
    const hasGifted = fg && new Date(fg.until) > new Date();
    const daysLeft = hasGifted ? Math.ceil((new Date(fg.until) - Date.now()) / 86400000) : 0;
    return `<div style="display:flex;align-items:center;gap:10px;padding:10px 16px;border-bottom:1px solid rgba(255,255,255,.04);">
      <div style="width:34px;height:34px;border-radius:50%;overflow:hidden;flex-shrink:0;background:var(--panel2);display:flex;align-items:center;justify-content:center;font-size:13px;">${buildAvatarHTML(null, f, 34)}</div>
      <div style="flex:1;font-size:13.5px;font-weight:600;">${escapeHTML(f)}</div>
      ${hasGifted
        ? `<span style="font-size:11.5px;color:rgba(255,255,255,.4);">${daysLeft}d left</span>
           <button onclick="cancelGiftRadiance('${escapeHTML(f)}')" style="background:rgba(248,113,113,.1);border:1px solid rgba(248,113,113,.18);color:var(--red);font-size:11px;padding:4px 10px;border-radius:7px;cursor:pointer;">Cancel</button>`
        : `<button onclick="sendRadianceGiftToUser('${escapeHTML(f)}')" style="background:rgba(255,249,62,.1);border:1px solid rgba(255,249,62,.2);color:var(--accent);font-size:11.5px;font-weight:700;padding:5px 12px;border-radius:7px;cursor:pointer;">Send (600 Onyx)</button>`}
    </div>`;
  }).join('');
  return html;
}

async function giftRadianceTo(friendUsername) {
  const cost = 600;
  if ((CU?.onyx || 0) < cost) { toast('Not enough Onyx!', 'error'); return; }
  showCustomConfirm(
    `Gift 30 days of Radiance to ${friendUsername} for ${cost} Onyx?`,
    async () => {
      CU.onyx = (CU.onyx || 0) - cost;
      if (!CU.giftedRadiance) CU.giftedRadiance = {};
      const until = new Date(Date.now() + 30 * 86400000).toISOString();
      CU.giftedRadiance[friendUsername] = { until, cost };
      try {
        await FortizedSocial.adminUpdateUserField(friendUsername, 'radianceUntil', until);
        await FortizedSocial.addNotification(friendUsername, {
          type: 'gift', from: CU.username,
          msg: `${CU.username} gifted you 30 days of Radiance! ✨`,
          time: new Date().toISOString()
        });
      } catch(e) { console.warn('[Gift] radiance gift notification failed', e); }
      await saveUser();
      updateOnyxDisplay();
      distributeOnyxRevenue(cost);
      toast(`✨ Gifted Radiance to ${friendUsername}!`, 'success');
      renderAtelierTab('radiance');
    }
  );
}

async function cancelGiftRadiance(friendUsername) {
  showCustomConfirm(`Cancel ${friendUsername}'s gifted Radiance?`, async () => {
    if (CU.giftedRadiance) delete CU.giftedRadiance[friendUsername];
    try { await FortizedSocial.adminUpdateUserField(friendUsername, 'radianceUntil', null); } catch(e) { console.warn('[Gift] cancel radiance failed', e); }
    await saveUser();
    toast('Gift cancelled.', 'info');
    renderAtelierTab('radiance');
  });
}

// ── Gift Link System (Radiance & Shop Items) ──────────────
// Generates shareable gift links and handles claiming

function generateGiftCode() {
  return CU.username.slice(0,4) + Date.now().toString(36).toUpperCase() + Math.random().toString(36).slice(2,6).toUpperCase();
}

async function createRadianceGiftLink() {
  const cost = 600;
  if ((CU?.onyx || 0) < cost) { toast('Not enough Onyx! (600 required)', 'error'); return; }
  showCustomConfirm(`Create a Radiance gift link for 600 Onyx? Anyone who claims it gets 30 days of Radiance.`, async () => {
    const code = generateGiftCode();
    CU.onyx = (CU.onyx || 0) - cost;
    if (!CU.pendingGifts) CU.pendingGifts = {};
    CU.pendingGifts[code] = { type:'radiance', days:30, from:CU.username, created:new Date().toISOString(), claimed:false };
    try {
      await firebase.database().ref('gifts/' + code).set(CU.pendingGifts[code]);
    } catch(e) { console.warn('[Gift] radiance link save failed', e); }
    await saveUser();
    updateOnyxDisplay();
    distributeOnyxRevenue(cost);
    const link = location.origin + '/app?gift_radiance=' + code;
    navigator.clipboard.writeText(link).then(()=>toast('Gift link copied to clipboard!','success')).catch(()=>toast('Link: '+link,'info'));
    renderAtelierTab('radiance');
  });
}

async function sendRadianceGiftToUser(friendUsername) {
  const cost = 600;
  if ((CU?.onyx || 0) < cost) { toast('Not enough Onyx!', 'error'); return; }
  showCustomConfirm(`Gift 30 days of Radiance to ${friendUsername} for ${cost} Onyx?`, async () => {
    const code = generateGiftCode();
    CU.onyx = (CU.onyx || 0) - cost;
    if (!CU.pendingGifts) CU.pendingGifts = {};
    CU.pendingGifts[code] = { type:'radiance', days:30, from:CU.username, created:new Date().toISOString(), claimed:false, target:friendUsername };
    try {
      await firebase.database().ref('gifts/' + code).set(CU.pendingGifts[code]);
      // Send as DM with gift link
      const link = location.origin + '/app?gift_radiance=' + code;
      const _giftMsgRef = firebase.database().ref('dms/' + [CU.username, friendUsername].sort().join('__')).push(); await _giftMsgRef.set({id:_giftMsgRef.key,
        from: CU.username, text: link, timestamp: new Date().toISOString()
      });
      await firebase.database().ref('notifications/' + friendUsername).push({
        type:'gift', from:CU.username, msg:`${CU.username} sent you a Radiance gift!`, time:new Date().toISOString()
      });
    } catch(e) { console.warn('[Gift] radiance DM gift failed', e); }
    await saveUser();
    updateOnyxDisplay();
    distributeOnyxRevenue(cost);
    toast(`Radiance gift sent to ${friendUsername}!`, 'success');
    renderAtelierTab('radiance');
  });
}

async function claimGift(giftCode) {
  if (!CU?.username) { toast('Please log in to claim gifts.', 'error'); return; }
  try {
    const snap = await firebase.database().ref('gifts/' + giftCode).get();
    if (!snap.exists()) { toast('Gift not found or expired.', 'error'); return; }
    const gift = snap.val();
    if (gift.claimed) { toast('This gift has already been claimed!', 'info'); return; }
    if (gift.target && gift.target !== CU.username) { toast('This gift is for someone else.', 'error'); return; }
    if (gift.from === CU.username) { toast('You cannot claim your own gift!', 'info'); return; }
    // Mark as claimed
    await firebase.database().ref('gifts/' + giftCode).update({ claimed:true, claimedBy:CU.username, claimedAt:new Date().toISOString() });
    if (gift.type === 'radiance') {
      const until = new Date(Date.now() + (gift.days||30) * 86400000).toISOString();
      CU.radianceUntil = until;
      await saveUser();
      toast('You received 30 days of Radiance! Enjoy your perks.', 'success');
    } else if (gift.type === 'item') {
      if (!CU.ownedItems) CU.ownedItems = [];
      CU.ownedItems.push(gift.itemId);
      await saveUser();
      toast(`You received: ${gift.itemName || 'Shop Item'}!`, 'success');
    }
    // Notify gifter
    try {
      await firebase.database().ref('notifications/' + gift.from).push({
        type:'gift_claimed', from:CU.username, msg:`${CU.username} claimed your ${gift.type==='radiance'?'Radiance':'item'} gift!`, time:new Date().toISOString()
      });
    } catch(e) { console.debug('[Gift] claim notification failed', e); }
  } catch (e) { toast('Failed to claim gift.', 'error'); }
}

