// Render gift embed for parseMD
function _renderGiftEmbed(type, giftCode) {
  // Render with a unique container ID so we can async-update with real Firebase data
  const embedId = 'gift-embed-' + giftCode;
  // Check local data first
  let giftData = CU?.pendingGifts?.[giftCode] || null;
  const initialHTML = _buildGiftEmbedHTML(type, giftCode, giftData);
  // Async-fetch from Firebase to get real gift data (sender, claimed status, item name)
  setTimeout(async () => {
    try {
      const snap = await firebase.database().ref('gifts/' + giftCode).once('value');
      if (snap.exists()) {
        const el = document.getElementById(embedId);
        if (el) el.outerHTML = _buildGiftEmbedHTML(type, giftCode, snap.val());
      }
    } catch(e) { console.debug('[Gift] embed fetch failed', e); }
  }, 100);
  return `<span id="${embedId}">${initialHTML}</span>`;
}
function _buildGiftEmbedHTML(type, giftCode, giftData) {
  const from = giftData?.from || 'Someone';
  const claimed = giftData?.claimed || false;
  const giftSvg = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 12v10H4V12"/><path d="M2 7h20v5H2z"/><path d="M12 22V7"/><path d="M12 7H7.5a2.5 2.5 0 010-5C11 2 12 7 12 7z"/><path d="M12 7h4.5a2.5 2.5 0 000-5C13 2 12 7 12 7z"/></svg>';
  if (type === 'radiance') {
    return `<div class="ftz-embed" style="--embed-color:#ffd93e;"><div class="ftz-embed-inner"><div class="ftz-embed-stripe"></div><div class="ftz-embed-content"><div class="ftz-embed-head">${giftSvg} Radiance Gift</div><div class="ftz-embed-body"><div class="ftz-embed-title">${escapeHTML(from)} gifts you Radiance</div><div class="ftz-embed-desc">30 days of Radiance perks — profile glow, custom banner, increased uploads & more</div></div>${claimed?'<div style="padding:6px 14px 12px;font-size:11px;color:rgba(255,255,255,.3);font-weight:600;">Already claimed</div>':'<div class="ftz-embed-btn primary" onclick="event.stopPropagation();claimGift(\''+escapeHTML(giftCode)+'\')">Claim Radiance</div>'}</div></div></div>`;
  } else {
    const itemName = giftData?.itemName || 'Shop Item';
    return `<div class="ftz-embed" style="--embed-color:var(--purple);"><div class="ftz-embed-inner"><div class="ftz-embed-stripe"></div><div class="ftz-embed-content"><div class="ftz-embed-head">${giftSvg} Item Gift</div><div class="ftz-embed-body"><div class="ftz-embed-title">${escapeHTML(from)} gifts you: ${escapeHTML(itemName)}</div><div class="ftz-embed-desc">A shop item gift from a friend</div></div>${claimed?'<div style="padding:6px 14px 12px;font-size:11px;color:rgba(255,255,255,.3);font-weight:600;">Already claimed</div>':'<div class="ftz-embed-btn primary" style="background:#a78bfa;" onclick="event.stopPropagation();claimGift(\''+escapeHTML(giftCode)+'\')">Claim Item</div>'}</div></div></div>`;
  }
}

// Check for gift links on page load
function checkGiftLinks() {
  const params = new URLSearchParams(location.search);
  const radGift = params.get('gift_radiance');
  const itemGift = params.get('gift_item');
  if (radGift) { setTimeout(() => claimGift(radGift), 1500); }
  if (itemGift) { setTimeout(() => claimGift(itemGift), 1500); }
}

async function claimDailyQuest() {
  // Both daily claim AND invite renew every day
  const today = new Date().toDateString();
  if (CU.lastDailyReward === today || CU.lastDaily === today) {
    toast('Already claimed today! Come back tomorrow 🕛', 'info');
    return;
  }
  // Streak tracking: check if yesterday was claimed
  const yesterday = new Date(Date.now() - 86400000).toDateString();
  const wasYesterday = CU.lastDailyReward === yesterday || CU.lastDaily === yesterday;
  if (wasYesterday) {
    CU.dailyStreak = (CU.dailyStreak || 0) + 1;
  } else {
    CU.dailyStreak = 1;
  }
  const streakBonus = CU.dailyStreak >= 7 ? 25 : CU.dailyStreak >= 3 ? 10 : 0;
  const totalReward = 50 + streakBonus;
  CU.onyx = (CU.onyx || 0) + totalReward;
  CU.lastDailyReward = today;
  CU.lastDaily = today;
  // Mark daily quest as done for today (not permanently — resets each day)
  if (!CU.questsDailyLog) CU.questsDailyLog = {};
  CU.questsDailyLog.daily_claim = today;
  updateOnyxDisplay();
  // Save immediately (bypass debounce) so Firebase doesn't overwrite with old onyx
  await saveUser(true);
  if (typeof animateOnyxGain === 'function') animateOnyxGain(totalReward);
  toast(`🎁 +${totalReward} Onyx claimed!${streakBonus ? ' ('+streakBonus+' streak bonus!)' : ''}`, 'success');
  renderAtelierTab('quests');
}

// Check if a daily-renewing quest is done today
function isDailyQuestDone(questId) {
  const today = new Date().toDateString();
  const log = CU?.questsDailyLog || {};
  if (questId === 'daily_claim') {
    return CU?.lastDailyReward === today || CU?.lastDaily === today;
  }
  if (questId === 'invite' || questId === 'send_msg') {
    return log[questId] === today;
  }
  return false;
}

// Track send_msg daily quest — called from sendDM / sendGCMessage / sendChannelMsg
async function _trackSendMsgQuest() {
  if (!CU) return;
  const today = new Date().toDateString();
  if (!CU.questsDailyLog) CU.questsDailyLog = {};
  if (CU.questsDailyLog.send_msg === today) return; // already done today
  CU.questsDailyLog.send_msg = today;
  CU.onyx = (CU.onyx || 0) + 10;
  updateOnyxDisplay();
  await saveUser(true);
  if (typeof animateOnyxGain === 'function') animateOnyxGain(10);
  toast('💬 Quest complete: Send a Message — +10 Onyx!', 'success');
}

// ════════════════════════════════════════════════════════════
// DAILY QUEST POPUP — "Hearken, Hearken!"
// ════════════════════════════════════════════════════════════
function _showDailyQuestPopup() {
  if (!CU) return;
  const today = new Date().toDateString();
  // Don't show if already claimed today or already dismissed today
  if (CU.lastDailyReward === today || CU.lastDaily === today) return;
  if (CU._questPopupDismissed === today) return;
  // Don't show if already visible
  if (document.getElementById('daily-quest-popup')) return;

  const overlay = document.createElement('div');
  overlay.id = 'daily-quest-popup';
  overlay.className = 'quest-popup-overlay';
  overlay.innerHTML = `
    <div class="quest-popup-card" style="position:relative;">
      <div class="quest-popup-shimmer"></div>
      <img src="/Fortized Conquer.png" class="quest-popup-img" alt="Fortized Conquer">
      <div class="quest-popup-body">
        <div class="quest-popup-label">DAILY QUEST</div>
        <div class="quest-popup-title">Hearken, Hearken!<br>A new quest is available to you!</div>
        <div class="quest-popup-desc">Claim your daily reward of <strong style="color:var(--accent);">50 Onyx</strong> and continue your conquest. Consistency is the key to greatness.</div>
        <div class="quest-popup-reward">
          <img src="/Onyx.png" style="width:16px;height:16px;object-fit:contain;">
          +50 Onyx
        </div>
        <div class="quest-popup-btns">
          <button class="qp-btn qp-close" onclick="_dismissDailyPopup(false)">Complete Later</button>
          <button class="qp-btn qp-claim" onclick="_dismissDailyPopup(true)">Claim Now</button>
        </div>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  requestAnimationFrame(() => requestAnimationFrame(() => overlay.classList.add('visible')));
}

async function _dismissDailyPopup(claim) {
  const overlay = document.getElementById('daily-quest-popup');
  if (overlay) {
    overlay.classList.remove('visible');
    setTimeout(() => overlay.remove(), 450);
  }
  if (claim) {
    await claimDailyQuest();
  } else {
    // Remember dismissal so we don't show again today
    if (CU) CU._questPopupDismissed = new Date().toDateString();
  }
}


// ════════════════════════════════════════════════════════════
// SETTINGS UNSAVED CHANGES SYSTEM
// ════════════════════════════════════════════════════════════
let _settingsOriginal = null; // snapshot of CU before editing
let _settingsDirty = false;

function markSettingsDirty() {
  // Compare current input values against original snapshot to detect real changes
  if (!_settingsOriginal || !CU) {
    // No snapshot — can't compare, skip (don't blindly show the bar)
    return;
  }
  let hasChanges = false;
  const dnInp = document.getElementById('dn-input');
  const bioInp = document.getElementById('bio-input');
  const emailInp = document.getElementById('email-input');
  const pwOld = document.getElementById('pw-old');
  const pwNew = document.getElementById('pw-new');
  if (dnInp && dnInp.value.trim() !== (_settingsOriginal.displayName || CU.username || '')) hasChanges = true;
  if (bioInp && bioInp.value.trim() !== (_settingsOriginal.bio || '')) hasChanges = true;
  if (emailInp && emailInp.value.trim() !== (_settingsOriginal.email || '')) hasChanges = true;
  if (pwOld && pwOld.value) hasChanges = true;
  if (pwNew && pwNew.value) hasChanges = true;
  // Check socials
  ['youtube','roblox','spotify','twitter'].forEach(key => {
    const inp = document.getElementById('social-' + key);
    if (inp && inp.value.trim() !== ((_settingsOriginal.socials || {})[key] || '')) hasChanges = true;
  });
  // Check pronouns
  const pronounsInp = document.getElementById('pronouns-input');
  if (pronounsInp && pronounsInp.value.trim() !== (_settingsOriginal.pronouns || '')) hasChanges = true;
  // Check if pfp/banner changed (from crop modal)
  if (CU.pfp !== _settingsOriginal.pfp) hasChanges = true;
  if (CU.banner !== _settingsOriginal.banner) hasChanges = true;
  // Check profileTheme
  if (JSON.stringify(CU.profileTheme||null) !== JSON.stringify(_settingsOriginal.profileTheme||null)) hasChanges = true;

  if (hasChanges && !_settingsDirty) {
    _settingsDirty = true;
    // Only show bar if profile/myprofile tab is visible (not just modal open)
    const dnInput = document.getElementById('dn-input');
    if (dnInput && dnInput.closest('[style*="display"]') !== null) {
      document.getElementById('unsaved-bar')?.classList.add('show');
    }
  } else if (!hasChanges && _settingsDirty) {
    _settingsDirty = false;
    document.getElementById('unsaved-bar')?.classList.remove('show');
  }
}

function clearSettingsDirty() {
  _settingsDirty = false;
  document.getElementById('unsaved-bar')?.classList.remove('show');
}


// Module-level helper to blend two colors for profile card backgrounds
function _blendColorsForProfileCard(color1, color2) {
  // Parse hex colors
  const c1 = parseInt(color1.substring(1), 16);
  const c2 = parseInt(color2.substring(1), 16);

  // Extract RGB components
  const r1 = (c1 >> 16) & 255, g1 = (c1 >> 8) & 255, b1 = c1 & 255;
  const r2 = (c2 >> 16) & 255, g2 = (c2 >> 8) & 255, b2 = c2 & 255;

  // Average the colors (50/50 blend)
  let r = Math.round((r1 + r2) / 2);
  let g = Math.round((g1 + g2) / 2);
  let b = Math.round((b1 + b2) / 2);

  // Desaturate to reduce color intensity (make it more neutral/light)
  const brightness = (r + g + b) / 3;
  const desaturate = 0.4;  // 40% saturation
  r = Math.round(r * desaturate + brightness * (1 - desaturate));
  g = Math.round(g * desaturate + brightness * (1 - desaturate));
  b = Math.round(b * desaturate + brightness * (1 - desaturate));

  // Lighten to ensure readability
  const lighten = 0.25;  // Add 25% lightness
  r = Math.min(255, Math.round(r + (255 - r) * lighten));
  g = Math.min(255, Math.round(g + (255 - g) * lighten));
  b = Math.min(255, Math.round(b + (255 - b) * lighten));

  return '#' + [r, g, b].map(x => ('0' + x.toString(16)).slice(-2)).join('');
}
function updateProfilePreview() {
  // Update the profile card preview in real-time as user makes changes
  const previewContainer = document.querySelector('[style*="sticky"]');
  if (!previewContainer || !previewContainer.querySelector('.up-card')) return;

  // Get current input values
  const dnInp = document.getElementById('dn-input');
  const bioInp = document.getElementById('bio-input');
  const displayName = dnInp ? dnInp.value.trim() || CU.username : (CU.displayName || CU.username);
  const bio = bioInp ? bioInp.value.trim() : (CU.bio || '');

  // Get theme colors
  const themeC1 = CU.profileTheme?.color1 || null;
  const themeC2 = CU.profileTheme?.color2 || themeC1 || null;
  const profileCardBg = (themeC1 && themeC2) ? _blendColorsForProfileCard(themeC1, themeC2) : null;

  // Get status color
  const sc = FtzStatus.color(CU.status || 'online');
  const cs = CU.customStatus;
  const hasRadiance = CU?.radianceUntil && new Date(CU.radianceUntil) > new Date();
  const userBanner = (CU.banner && hasRadiance) ? CU.banner : null;
  const previewBg = themeC1 ? `linear-gradient(135deg,${themeC1}ee,${themeC2||themeC1}bb)` : `linear-gradient(135deg,#141a2e,#1a1035,#0f1828)`;

  // Update the preview card background
  const cardEl = previewContainer.querySelector('.up-card');
  if (cardEl) {
    cardEl.style.background = profileCardBg || '';
  }

  // Update border styling
  const cardWrapper = previewContainer.querySelector('[style*="border-radius:16px"]');
  if (cardWrapper && themeC1) {
    cardWrapper.style.borderColor = 'transparent';
    cardWrapper.style.backgroundImage = `linear-gradient(var(--panel),var(--panel)),linear-gradient(135deg,${themeC1},${themeC2||themeC1})`;
    cardWrapper.style.backgroundOrigin = 'border-box';
    cardWrapper.style.backgroundClip = 'padding-box,border-box';
    cardWrapper.style.boxShadow = `0 8px 40px rgba(0,0,0,.35),0 0 28px ${themeC1}15`;
  }

  // Update banner background
  const bannerEl = previewContainer.querySelector('[style*="height:100px"]');
  if (bannerEl) {
    if (userBanner) {
      bannerEl.style.backgroundImage = `url('${escapeHTML(userBanner)}')`;
    } else {
      bannerEl.style.background = previewBg;
    }
  }

  // Update display name
  const displayNameEl = previewContainer.querySelector('[style*="font-size:17px"]');
  if (displayNameEl) {
    displayNameEl.textContent = displayName;
    displayNameEl.style.fontFamily = _getDisplayFontCSS(CU.displayFont || 'default');
    const effectCss = _getDisplayEffectCSS(CU.displayEffect || 'solid', CU.displayColor || '#fff');
    displayNameEl.setAttribute('style', displayNameEl.getAttribute('style') + ';' + effectCss);
  }

  // Update bio
  const bioEl = Array.from(previewContainer.querySelectorAll('div')).find(el =>
    el.textContent && el.textContent.includes('About Me')
  );
  if (bioEl && bio) {
    const bioText = bioEl.parentElement.querySelector('div:last-child');
    if (bioText) {
      bioText.textContent = bio.slice(0, 120) + (bio.length > 120 ? '…' : '');
    }
  }

  markSettingsDirty();
}


function resetSettingsChanges() {
  // Only revert CU data if we're actually on the profile view with settings inputs visible
  if (_settingsOriginal && CU && document.getElementById('dn-input')) {
    CU.displayName = _settingsOriginal.displayName;
    CU.bio = _settingsOriginal.bio;
    CU.email = _settingsOriginal.email;
    CU.pfp = _settingsOriginal.pfp;
    CU.banner = _settingsOriginal.banner;
    CU.socials = _settingsOriginal.socials ? structuredClone(_settingsOriginal.socials) : {};
    CU.password = _settingsOriginal.password;
    CU.notifSettings = _settingsOriginal.notifSettings ? structuredClone(_settingsOriginal.notifSettings) : {};
    CU.pronouns = _settingsOriginal.pronouns || '';
    CU.profileTheme = _settingsOriginal.profileTheme ? structuredClone(_settingsOriginal.profileTheme) : null;
    notifSettings = CU.notifSettings;
    saveLocal();
    updateUserbar();
    buildProfileView('myprofile');
  }
  clearSettingsDirty();
}

async function saveAllSettings() {
  // If the settings inputs aren't on screen, go back to profile to save
  if (!document.getElementById('dn-input')) {
    showView('profile');
    toast('Redirected to settings — make your changes and save', 'info');
    return;
  }
  // Collect all open input values
  const dnInp = document.getElementById('dn-input');
  const bioInp = document.getElementById('bio-input');
  const emailInp = document.getElementById('email-input');
  if (dnInp && dnInp.value.trim()) CU.displayName = dnInp.value.trim();
  if (bioInp) CU.bio = bioInp.value.trim().slice(0,300);
  if (emailInp && emailInp.value.trim()) CU.email = emailInp.value.trim();
  // Save password if changed
  const pwOld = document.getElementById('pw-old');
  const pwNew = document.getElementById('pw-new');
  if (pwOld && pwNew && pwOld.value && pwNew.value) {
    if (pwOld.value !== CU.password) { toast('Current password is wrong', 'error'); return; }
    if (pwNew.value.length < 6) { toast('New password must be 6+ chars', 'error'); return; }
    CU.password = pwNew.value;
  }
  // Save notification settings
  CU.notifSettings = notifSettings;
  // Save pronouns
  const pronounsInp = document.getElementById('pronouns-input');
  if (pronounsInp) CU.pronouns = pronounsInp.value.trim().slice(0,40);
  // Save socials if present
  ['youtube','roblox','twitter'].forEach(key => {
    const inp = document.getElementById('social-' + key);
    if (inp) {
      CU.socials = CU.socials || {};
      if (inp.value.trim()) CU.socials[key] = inp.value.trim();
      else delete CU.socials[key];
    }
  });
  await saveUser();
  updateUserbar();
  applyRadianceFont();
  // Update snapshot so future edits compare against saved state
  _settingsOriginal = CU ? structuredClone({displayName:CU.displayName,bio:CU.bio,email:CU.email,password:CU.password,pfp:CU.pfp,banner:CU.banner,socials:CU.socials,notifSettings:CU.notifSettings,pronouns:CU.pronouns,profileTheme:CU.profileTheme}) : null;
  clearSettingsDirty();
  toast('Settings saved!', 'success');
  buildProfileView('myprofile');
}


// ════════════════════════════════════════════════════════════
// DISCORD-STYLE NOTIFICATION TOASTS (bottom-right)
// ════════════════════════════════════════════════════════════
let _notifToastQueue = [];
let _notifToastActive = null;
let _notifDigestBuffer = [];
let _notifDigestTimer = null;

function _isPriorityNotif(notif) {
  if (!notif) return false;
  if (notif.type === 'mention' || notif.type === 'friend_request') return true;
  const chId = notif.data?.channelId;
  return !!(chId && (notifSettings.priorityChannels || []).includes(chId));
}

function shouldDeliverRealtimeNotif(notif) {
  // Don't deliver notifications that are already read
  if (notif.read) return false;
  // Don't deliver DM notifications if user is currently viewing that DM
  if (notif.type === 'dm' && notif.from && curDM === (notif.from||'').toLowerCase()) return false;
  // Don't deliver mention notifications if user is currently in a bastion channel
  if (notif.type === 'mention' && curBastion !== null && curChannel !== null && curChannel !== 'overview') return false;
  if (notifSettings.priorityOnly && !_isPriorityNotif(notif)) return false;
  if (notif.type === 'dm' && notifSettings.messages === false) return false;
  if (notif.type === 'mention' && notifSettings.mentions === false) return false;
  if (notif.type === 'friend_request' && notifSettings.friendRequests === false) return false;
  return true;
}

function queueDigestNotif(notif) {
  _notifDigestBuffer.push(notif);
  if (_notifDigestTimer) return;
  _notifDigestTimer = setTimeout(() => {
    const n = _notifDigestBuffer.length;
    _notifDigestBuffer = [];
    _notifDigestTimer = null;
    if (n > 0) toast('🧾 Digest: ' + n + ' new notifications', 'info');
  }, 90000);
}

function showNotifToast(notif) {
  // DND: suppress all notification popups
  if (CU?.status === 'dnd') return;
  // Suppress notifications from blocked or ignored users
  if (notif.from && (isUserBlocked(notif.from) || isUserIgnored(notif.from))) return;
  // Each toast stacks above the previous
  const existing = document.querySelectorAll('.ftz-notif-toast');
  const offset = existing.length * 82; // stack offset

  const toast = document.createElement('div');
  toast.className = 'ftz-notif-toast';
  toast.style.bottom = (24 + offset) + 'px';

  const title = notif.from || 'Fortized';
  const body = notif.type === 'friend_request' ? `${notif.from} sent you a friend request`
    : notif.type === 'friend_accept' ? `${notif.from} accepted your friend request`
    : notif.type === 'gift' ? notif.msg || 'You received a gift!'
    : notif.data?.preview || notif.msg || 'New notification';

  toast.innerHTML = `
    <div class="ftz-notif-av">${buildAvatarHTML(null, notif.from||'?', 40)}</div>
    <div class="ftz-notif-body">
      <div class="ftz-notif-title">${escapeHTML(title)}</div>
      <div class="ftz-notif-text">${escapeHTML(body)}</div>
    </div>
    <button class="ftz-notif-close" onclick="event.stopPropagation();dismissNotifToast(this.closest('.ftz-notif-toast'))">×</button>`;

  // Click → open DM or relevant view
  toast.addEventListener('click', () => {
    dismissNotifToast(toast);
    if (notif.type === 'dm' && notif.from) openDMView(notif.from);
    else if (notif.type === 'friend_request') openModal('modal-add-friend');
  });

  document.body.appendChild(toast);
  // Auto-dismiss after 6s
  setTimeout(() => dismissNotifToast(toast), 6000);
  // Update badge count
  updateNotifBadge().catch(()=>{});
  playNotifSound('message');
}

function dismissNotifToast(toast) {
  if (!toast || !toast.parentNode) return;
  toast.style.animation = 'notifSlideOut .25s ease forwards';
  setTimeout(() => {
    toast.remove();
    // Reposition remaining toasts
    document.querySelectorAll('.ftz-notif-toast').forEach((t, i) => {
      t.style.bottom = (24 + i * 82) + 'px';
    });
  }, 260);
}

// Hook into FortizedSocial notifications for cross-device toasts
function initNotifToasts() {
  if (!CU?.username) return;
  const ref = firebase.database().ref('notifications/' + CU.username);
  ref.on('child_added', snap => {
    const n = snap.val();
    if (!n || n.seen) return;
    if (!shouldDeliverRealtimeNotif(n)) return;
    if (notifSettings.digestMode) { queueDigestNotif(n); return; }
    // Mark as seen
    snap.ref.update({seen: true}).catch(()=>{});
    // Show toast (only for new ones - check timestamp)
    const age = Date.now() - new Date(n.time || 0).getTime();
    if (age < 30000) showNotifToast(n); // only if < 30s old
    updateNotifBadge().catch(()=>{});
  });
  // Real-time friend status subscriptions — update all UI when friends come online/go offline
  _subscribeFriendStatuses();
}

let _friendStatusSubs = {};
function _subscribeFriendStatuses() {
  // Unsubscribe old Supabase channels
  Object.values(_friendStatusSubs).forEach(sub => { try { FortizedSocial.sb.removeChannel(sub); } catch(e) { console.debug('[Friends] status sub cleanup failed', e); } });
  _friendStatusSubs = {};
  const friends = CU?.friends || [];
  if (!friends.length) return;
  // Subscribe to Supabase statuses table for each friend (NOT Firebase)
  friends.forEach(f => {
    try {
      const uid = Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
      const sub = FortizedSocial.sb.channel('friend-st-' + f + '-' + uid)
        .on('postgres_changes', {
          event: '*',
          schema: 'public',
          table: 'statuses',
          filter: 'username=eq.' + f,
        }, payload => {
          const row = payload.new;
          if (!row) return;
          const st = FtzStatus.sanitize(row.status || 'offline');
          const color = FtzStatus.color(st);
          // Update all status dots for this user across the entire app
          FtzStatus.updateDots(f, st);
          document.querySelectorAll('.profile-status-label[data-for="'+f+'"]').forEach(el => {
            el.textContent = FtzStatus.publicLabel(st);
          });
          // Update DM home status dots and text
          const homeDot = document.querySelector('.dm-home-status[data-for="'+CSS.escape(f)+'"]');
          if (homeDot) { homeDot.style.background = color; homeDot.style.boxShadow = '0 0 8px '+color+'55'; }
          const homeText = document.querySelector('.dm-home-status-text[data-for="'+CSS.escape(f)+'"]');
          if (homeText) homeText.textContent = FtzStatus.publicLabel(st);
          // Refresh Active Now sidebar if it's visible (debounced)
          _debouncedActiveNowRefresh();
        })
        .subscribe();
      _friendStatusSubs[f] = sub;
    } catch(e) { console.debug('[Friends] status sub failed for', f, e); }
  });
}



// ════════════════════════════════════════════════════════════
// OWN PROFILE MINI-PANEL (Discord-style bottom-left popup)
// ════════════════════════════════════════════════════════════
let _ownProfileOpen = false;
function toggleOwnProfilePanel() {
  if (_ownProfileOpen) { closeOwnProfilePanel(); return; }
  _ownProfileOpen = true;
  document.getElementById('own-profile-panel')?.remove();
  
  const STATUS_OPTS = [
    {id:'online',   label:'Online',          color:'#3ecf6e'},
    {id:'away',     label:'Away',            color:'#f59e0b'},
    {id:'dnd',      label:'Do Not Disturb',  color:'#f87171'},
    {id:'invisible',label:'Invisible',       color:'#6b7280'},
  ];
  const st = CU?.status || 'online';
  const cs = CU?.customStatus;
  
  const panel = document.createElement('div');
  panel.id = 'own-profile-panel';
  panel.className = 'own-profile-panel';
  panel.innerHTML = `
    <!-- Banner -->
    <div style="height:100px;position:relative;background:${CU?.banner?`url('${CU.banner}') center/cover no-repeat`:'linear-gradient(135deg,#161a2e 0%,#0d1a3a 50%,#1a1030 100%)'};cursor:pointer;" onclick="closeOwnProfilePanel();viewUserProfile('${CU?.username||''}')">
      <div style="position:absolute;inset:0;background:linear-gradient(0deg,var(--panel) 0%,rgba(12,14,24,.4) 55%,transparent 100%);"></div>
    </div>
    <!-- Avatar row -->
    <div style="display:flex;align-items:flex-end;gap:11px;padding:0 18px;margin-top:-32px;position:relative;z-index:2;">
      <div style="width:64px;height:64px;border-radius:50%;overflow:hidden;border:4px solid var(--panel);cursor:pointer;background:#161a28;box-shadow:0 6px 20px rgba(0,0,0,.6);flex-shrink:0;transition:transform .18s cubic-bezier(.22,1,.36,1);" onclick="closeOwnProfilePanel();viewUserProfile('${CU?.username||''}')">
        ${CU?.pfp?`<img src="${CU.pfp}" style="width:100%;height:100%;object-fit:cover;" onerror="this.src='${_defaultPfpUrl(CU?.displayName||CU?.username||'')}'">` : `<img src="${_defaultPfpUrl(CU?.displayName||CU?.username||'')}" style="width:100%;height:100%;object-fit:cover;">`}
      </div>
      <div style="display:flex;align-items:center;gap:7px;padding-bottom:7px;">
        <span style="width:10px;height:10px;border-radius:50%;background:${{online:'#3ecf6e',away:'#f59e0b',dnd:'#f87171',invisible:'#6b7280'}[st]||'#3ecf6e'};box-shadow:0 0 8px ${{online:'#3ecf6e',away:'#f59e0b',dnd:'#f87171',invisible:'#6b7280'}[st]||'#3ecf6e'}55;flex-shrink:0;"></span>
        <span style="font-size:12px;color:rgba(255,255,255,.5);font-weight:500;">${{online:'Online',away:'Idle',dnd:'Do Not Disturb',invisible:'Invisible'}[st]||'Online'}</span>
      </div>
    </div>
    <!-- Name block -->
    <div style="padding:10px 18px 0;">
      <div style="font-family:var(--font-display);font-size:17px;font-weight:800;color:#fff;cursor:pointer;line-height:1.2;transition:color .12s;" onclick="closeOwnProfilePanel();viewUserProfile('${CU?.username||''}')" onmouseover="this.style.color='var(--accent)'" onmouseout="this.style.color='#fff'">${escapeHTML(CU?.displayName||CU?.username||'')}</div>
      <div style="font-size:12px;color:rgba(255,255,255,.28);margin-top:3px;">@${escapeHTML(CU?.username||'')}</div>
      ${cs?.text?`<div style="display:inline-flex;align-items:center;gap:5px;margin-top:9px;padding:5px 13px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.06);border-radius:var(--radius-pill);font-size:12px;color:rgba(255,255,255,.5);">${cs.emoji||''} ${escapeHTML(cs.text)}</div>`:''}
    </div>
    <!-- Divider -->
    <div style="height:1px;background:rgba(255,255,255,.06);margin:13px 18px 7px;"></div>
    <!-- Status options -->
    <div style="padding:2px 10px;">
      ${[
        {id:'online',    label:'Online',           color:'#3ecf6e', desc:null},
        {id:'away',      label:'Idle',             color:'#f59e0b', desc:null},
        {id:'dnd',       label:'Do Not Disturb',   color:'#f87171', desc:'You will not receive desktop notifications'},
        {id:'invisible', label:'Invisible',        color:'#6b7280', desc:'You will appear offline'},
      ].map(s=>`
        <div onclick="setMyStatus('${s.id}');closeOwnProfilePanel()" style="display:flex;align-items:center;gap:11px;padding:9px 11px;border-radius:10px;cursor:pointer;transition:all .14s;${st===s.id?'background:rgba(255,255,255,.06);':''}" onmouseover="this.style.background='rgba(255,255,255,.07)'" onmouseout="this.style.background='${st===s.id?'rgba(255,255,255,.06)':'transparent'}'">
          <span style="width:12px;height:12px;border-radius:50%;background:${s.color};flex-shrink:0;${st===s.id?'box-shadow:0 0 10px '+s.color+'55;':''}"></span>
          <div style="flex:1;min-width:0;">
            <div style="font-size:13px;font-weight:${st===s.id?'700':'500'};color:${st===s.id?'#fff':'rgba(255,255,255,.6)'};">${s.label}</div>
            ${s.desc?`<div style="font-size:11px;color:rgba(255,255,255,.25);margin-top:2px;">${s.desc}</div>`:''}
          </div>
          ${st===s.id?'<svg style="flex-shrink:0;" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="var(--accent)" stroke-width="2.5"><polyline points="20,6 9,17 4,12"/></svg>':''}
        </div>`).join('')}
    </div>
    <!-- Custom Status -->
    <div style="height:1px;background:rgba(255,255,255,.06);margin:5px 18px;"></div>
    <div onclick="openStatusPicker();closeOwnProfilePanel()" style="display:flex;align-items:center;gap:11px;padding:9px 11px;margin:3px 10px;border-radius:10px;cursor:pointer;transition:all .14s;" onmouseover="this.style.background='rgba(255,255,255,.06)'" onmouseout="this.style.background='transparent'">
      <span style="font-size:13px;display:flex;">${ftzIcon('pencil','14')}</span>
      <span style="font-size:13px;color:rgba(255,255,255,.5);font-weight:500;">${cs?.text?'Edit Custom Status':'Set Custom Status'}</span>
    </div>
    <!-- Actions -->
    <div style="padding:7px 10px 12px;display:flex;gap:7px;">
      <button onclick="closeOwnProfilePanel();showView('profile')" style="flex:1;padding:8px 0;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.07);border-radius:10px;color:rgba(255,255,255,.55);font-size:12.5px;font-weight:600;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:7px;transition:all .14s;">
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4z"/></svg>
        Edit Profile
      </button>
      <button onclick="closeOwnProfilePanel();toggleAccountSwitcher()" style="flex:1;padding:8px 0;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.07);border-radius:10px;color:rgba(255,255,255,.55);font-size:12.5px;font-weight:600;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:7px;transition:all .14s;white-space:nowrap;">
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M16 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/><circle cx="8.5" cy="7" r="4"/><line x1="20" y1="8" x2="20" y2="14"/><line x1="23" y1="11" x2="17" y2="11"/></svg>
        Switch
      </button>
    </div>`;
  
  document.body.appendChild(panel);
  // Close on outside click
  setTimeout(() => {
    document.addEventListener('mousedown', _closeOwnProfileOutside, {once:true});
  }, 50);
}

function _closeOwnProfileOutside(e) {
  const panel = document.getElementById('own-profile-panel');
  const btn = document.getElementById('ua-clickable');
  if (panel && !panel.contains(e.target) && !btn?.contains(e.target)) {
    closeOwnProfilePanel();
  } else if (panel && (panel.contains(e.target) || btn?.contains(e.target))) {
    // Re-register the listener
    document.addEventListener('mousedown', _closeOwnProfileOutside, {once:true});
  }
}

function closeOwnProfilePanel() {
  _ownProfileOpen = false;
  document.getElementById('own-profile-panel')?.remove();
}


// ════════════════════════════════════════════════════════════
// MINI PROFILE PREVIEW (first click) → full card (second click)
// ════════════════════════════════════════════════════════════
async function showMiniProfilePreview(username, anchorEl) {
  document.getElementById('mini-profile-preview')?.remove();
  let u = null;
  try { u = await FortizedSocial.getUserByName(username); } catch(e) { console.debug('[Profile] user lookup failed', e); }
  if (!u) u = { username, displayName: username };
  let status = 'offline';
  // Use live Socket.IO presence first, fallback to DB
  if (username === CU?.username) {
    u = { ...u, ...CU }; status = CU.status || 'online';
  } else {
    try {
      const presenceResult = await FortizedSocial.queryPresence([username]);
      if (presenceResult && presenceResult[username]) {
        status = presenceResult[username].status || 'offline';
      } else {
        try { status = await FortizedSocial.getStatus(username); } catch(e) { console.debug('[Profile] status fallback failed', e); }
      }
    } catch(e) { console.debug('[Profile] presence query failed', e);
      try { status = await FortizedSocial.getStatus(username); } catch(e2) { console.debug('[Profile] status fallback failed', e2); }
    }
  }
  subscribeProfileStatus(username);

  const sc = FtzStatus.color(status);
  const isOwn = username === CU?.username;
  const hasRadiancePlus = u.radiancePlus && new Date(u.radiancePlus) > new Date();
  const profileTheme = hasRadiancePlus ? (u.profileTheme || null) : null;
  const customStatus = u.customStatus;

  const panel = document.createElement('div');
  panel.id = 'mini-profile-preview';
  panel.className = 'mini-profile-preview';
  panel.setAttribute('role', 'dialog');
  panel.setAttribute('aria-label', 'Profile preview for ' + (u.displayName || u.username));
  if (profileTheme) {
    panel.style.borderColor = 'transparent';
    panel.style.backgroundImage = `linear-gradient(160deg,${profileTheme.color1}0a,var(--panel) 30%,var(--panel) 70%,${profileTheme.color2}08),linear-gradient(135deg,${profileTheme.color1}40,${profileTheme.color2}40)`;
    panel.style.backgroundOrigin = 'border-box';
    panel.style.backgroundClip = 'padding-box,border-box';
    panel.style.borderWidth = '1.5px';
    panel.style.borderStyle = 'solid';
    panel.style.boxShadow = `0 20px 60px rgba(0,0,0,.6),0 4px 20px rgba(0,0,0,.35)`;
  }
  const hasUserRadiance = u.radianceUntil && new Date(u.radianceUntil) > new Date();
  const userBanner = (u.banner && hasUserRadiance) ? u.banner : null;
  const bannerBg = userBanner
    ? `<img src="${escapeHTML(userBanner)}" style="width:100%;height:100%;object-fit:cover;">`
    : `<div style="width:100%;height:100%;background:linear-gradient(135deg,${profileTheme?profileTheme.color1+'44':'#1a1a2e'},${profileTheme?profileTheme.color2+'33':'#0f3460'});"></div>`;
  const _previewGames = u.gameCollection || u.registeredGames || [];
  const _previewMutuals = isOwn ? [] : (CU?.friends||[]).filter(f => f !== CU?.username && f !== username && (u.friends||[]).includes(f));
  const _memberSince = u.joinedAt||u.createdAt ? new Date(u.joinedAt||u.createdAt).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}) : null;
  const _isFriend = (CU?.friends||[]).includes(username);
  const _hasPending = (CU?.friendRequestsSent||[]).includes(username) || (CU?.friendRequestsReceived||[]).includes(username);
  panel.innerHTML = `
    <!-- Banner -->
    <div class="mpp-banner">
      ${bannerBg}
      ${profileTheme ? `<div style="position:absolute;bottom:0;left:0;right:0;height:2px;background:linear-gradient(90deg,${profileTheme.color1},${profileTheme.color2});opacity:.7;z-index:1;"></div>` : ''}
    </div>
    <!-- Avatar -->
    <div class="mpp-av-area">
      <div class="profile-decoration-wrap" style="flex-shrink:0;cursor:pointer;" onclick="document.getElementById('mini-profile-preview')?.remove();viewUserProfile('${escapeHTML(username)}')">
        <div class="mpp-av">${buildAvatarHTML(u.pfp, u.displayName||u.username, 64)}</div>
        ${u.activeDecoration ? `<img src="${getDecorationSrc(u.activeDecoration)||''}" class="profile-decoration-overlay" onerror="this.style.display='none'">` : ''}
        <span class="profile-status-dot" data-for="${escapeHTML(username)}" data-dot-size="18" style="position:absolute;bottom:2px;right:2px;width:18px;height:18px;z-index:3;">${FtzStatus.dotSvg(u.status||'offline', 18)}</span>
      </div>
    </div>
    <!-- Identity -->
    <div class="mpp-identity">
      <div class="mpp-displayname" onclick="document.getElementById('mini-profile-preview')?.remove();viewUserProfile('${escapeHTML(username)}')" style="font-family:${getDisplayFont(u)};${_getDisplayEffectCSS(u.displayEffect||'solid',u.displayColor||'#fff')}">${escapeHTML(u.displayName||u.username)}</div>
      <div class="mpp-username">@${escapeHTML(u.username)}${u.pronouns ? ` <span style="color:rgba(255,255,255,.2);font-weight:400;">&middot; ${escapeHTML(u.pronouns)}</span>` : ''}</div>
    </div>
    <!-- Status -->
    <div class="mpp-status-row">
      <div class="mpp-status-pill">
        <span class="sdot profile-status-dot" data-for="${escapeHTML(username)}" data-dot-size="10" style="display:inline-flex;">${FtzStatus.dotSvg(u.status||'offline', 10)}</span>
        <span class="profile-status-label" data-for="${escapeHTML(username)}">${FtzStatus.publicLabel(status)}</span>
      </div>
      <div class="profile-custom-status cloud-status-bubble" data-for="${escapeHTML(username)}" style="${customStatus?.text ? 'display:inline-flex;' : 'display:none;'}font-size:10.5px;padding:4px 10px;align-items:center;gap:4px;background:rgba(255,255,255,.035);border:1px solid rgba(255,255,255,.05);border-radius:var(--radius-pill);color:rgba(255,255,255,.45);">${customStatus?.text ? `<span class="csb-emoji">${customStatus.emoji ? `<img src="${emojiToTwemojiUrl(customStatus.emoji)}" style="width:13px;height:13px;" onerror="this.outerHTML='${customStatus.emoji}'">` : ''}</span><span class="csb-text">${escapeHTML(customStatus.text).slice(0,30)}</span>` : ''}</div>
    </div>
    <!-- Activity Status - Multi-activity support -->
    ${(() => {
      let activitiesToShow = [];
      if (u.activityState?.activities?.length) {
        activitiesToShow = u.activityState.activities.sort((a, b) => (b.priority || 2) - (a.priority || 2)).slice(0, 2);
      } else if (u.gameActivity?.name) {
        activitiesToShow = [{
          id: u.gameActivity._spotify ? 'spotify' : 'game',
          type: u.gameActivity._spotify ? 'listening' : 'playing',
          name: u.gameActivity.name,
          icon: u.gameActivity.icon || '🎮',
          since: u.gameActivity.since,
          priority: u.gameActivity._spotify ? 3 : 2,
          metadata: {
            coverThumb: u.gameActivity.coverThumb,
            genre: u.gameActivity.genre,
            spotifyAlbumArt: u.gameActivity.spotifyAlbumArt
          }
        }];
      }

      if (!activitiesToShow.length) return '';

      const statusColor = FtzStatus.color(u.status || 'online');
      return `<div class="mpp-divider"></div><div class="mpp-section">
        <div class="mpp-section-title" style="color:${statusColor}88;">Active Now</div>
        ${activitiesToShow.map((a, idx) => {
          const coverThumb = a.metadata?.coverThumb || a.metadata?.spotifyAlbumArt;
          const accentBg = statusColor + (idx === 0 ? '08' : '04');
          const accentBorder = statusColor + (idx === 0 ? '15' : '08');
          const _coverHTML = coverThumb
            ? `<img src="${escapeHTML(coverThumb)}" style="width:100%;height:100%;object-fit:cover;border-radius:6px;" onerror="this.outerHTML='<span style=font-size:14px>${a.icon||'🎮'}</span>'">`
            : `<span style="font-size:14px;">${a.icon||'🎮'}</span>`;
          const _elapsedHTML = a.since ? `<div style="font-size:9px;color:${statusColor}66;margin-top:1.5px;display:flex;align-items:center;gap:3px;"><svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>${_formatActivityElapsed(a.since)}</div>` : '';
          return `<div style="display:flex;align-items:center;gap:10px;padding:10px 11px;background:${accentBg};border:1px solid ${accentBorder};border-radius:10px;${idx > 0 ? 'margin-top:8px;' : ''}"><div style="width:36px;height:48px;border-radius:6px;background:linear-gradient(135deg,${statusColor}12,${statusColor}06);display:flex;align-items:center;justify-content:center;flex-shrink:0;overflow:hidden;border:1px solid ${statusColor}22;">${_coverHTML}</div><div style="min-width:0;flex:1;"><div style="font-size:12px;font-weight:700;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escapeHTML(a.name)}</div>${a.metadata?.genre?`<div style="font-size:9.5px;color:rgba(255,255,255,.28);margin-top:1.5px;">${escapeHTML(typeof a.metadata.genre==='string'?a.metadata.genre:a.metadata.genre[0]||'')}</div>`:''}${_elapsedHTML}</div></div>`;
        }).join('')}
      </div>`;
    })()}
    <!-- Badges -->
    <div class="mpp-badges-row">${renderBadgesHTML ? renderBadgesHTML(u) : ''}</div>
    ${u.bio ? `<div class="mpp-divider"></div><div class="mpp-section"><div class="mpp-section-title">About Me</div><div class="mpp-section-body">${parseMD(escapeHTML(u.bio.slice(0,150)))}${u.bio.length>150?'…':''}</div></div>` : ''}
    ${_memberSince ? `<div class="mpp-section"><div class="mpp-section-title">Member Since</div><div class="mpp-section-body">${_memberSince}</div></div>` : ''}
    <!-- Roles -->
    ${_currentView === 'bastion' && curBastion !== null ? (() => {
      const _canManageRoles = hasPerm('manage_roles') || (CU?.bastions?.[curBastion]?.owner === CU?.username);
      const _roleTags = renderUserRoleTags(username);
      const _addBtn = _canManageRoles && !isOwn ? `<button class="mpp-role-add-btn" onclick="_mppToggleRolePicker('${escapeHTML(username)}')" title="Manage Roles" style="width:22px;height:22px;border-radius:6px;border:1px dashed rgba(255,255,255,.15);background:none;color:rgba(255,255,255,.3);cursor:pointer;display:inline-flex;align-items:center;justify-content:center;font-size:14px;transition:all .15s;margin-top:4px;" onmouseover="this.style.borderColor='rgba(255,255,255,.3)';this.style.color='rgba(255,255,255,.6)'" onmouseout="this.style.borderColor='rgba(255,255,255,.15)';this.style.color='rgba(255,255,255,.3)'">+</button>` : '';
      return `<div class="mpp-divider"></div><div class="mpp-section"><div class="mpp-section-title" style="display:flex;align-items:center;justify-content:space-between;">Roles</div><div class="mpp-roles-row" id="mpp-roles-container">${_roleTags}${_addBtn}</div><div id="mpp-role-picker" style="display:none;"></div></div>`;
    })() : ''}
    <!-- Games -->
    ${_previewGames.length ? `<div class="mpp-divider"></div><div class="mpp-section"><div class="mpp-section-title">Games</div><div class="mpp-game-row">${_previewGames.slice(0,4).map(g=>`<div class="mpp-game-chip">${g.coverUrl ? `<img src="${escapeHTML(g.coverUrl)}" style="width:14px;height:18px;border-radius:2px;object-fit:cover;">` : (g.icon||ftzIcon('gamepad','12'))} ${escapeHTML(g.name)}</div>`).join('')}${_previewGames.length>4?`<div class="mpp-game-chip">+${_previewGames.length-4} more</div>`:''}</div></div>` : ''}
    <!-- Widgets -->
    <div id="mpp-widgets-area"></div>
    <!-- Mutuals -->
    ${_previewMutuals.length ? `<div class="mpp-divider"></div><div class="mpp-section"><div class="mpp-section-title">Mutual Friends</div><div style="display:flex;align-items:center;">${_previewMutuals.slice(0,6).map(f => `<div class="mpp-mutual-av" title="${escapeHTML(f)}" onclick="document.getElementById('mini-profile-preview')?.remove();viewUserProfile('${escapeHTML(f)}')">${buildAvatarHTML(null,f,22)}</div>`).join('')}${_previewMutuals.length>6?`<span style="font-size:10.5px;color:rgba(255,255,255,.28);margin-left:5px;">+${_previewMutuals.length-6}</span>`:''}</div></div>` : ''}
    <div class="mpp-divider"></div>
    <!-- Actions -->
    <div class="mpp-actions">
      ${isOwn ? `<button class="mpp-btn-primary" onclick="document.getElementById('mini-profile-preview')?.remove();showView('profile')"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M11 4H4a2 2 0 00-2 2v14a2 2 0 002 2h14a2 2 0 002-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 013 3L12 15l-4 1 1-4 9.5-9.5z"/></svg> Edit Profile</button>` :
      `<button class="mpp-btn-primary" onclick="document.getElementById('mini-profile-preview')?.remove();openDMView('${escapeHTML(username)}')"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M21 11.5a8.38 8.38 0 01-.9 3.8 8.5 8.5 0 01-7.6 4.7 8.38 8.38 0 01-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 01-.9-3.8 8.5 8.5 0 014.7-7.6 8.38 8.38 0 013.8-.9h.5a8.48 8.48 0 018 8v.5z"/></svg> Message</button>`}
      <button class="mpp-btn-secondary" onclick="document.getElementById('mini-profile-preview')?.remove();viewUserProfile('${escapeHTML(username)}')"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2"/><circle cx="12" cy="7" r="4"/></svg> Profile</button>
      ${!isOwn && !_isFriend && !_hasPending ? `<button class="mpp-btn-secondary" title="Add Friend" onclick="quickAddFriend('${escapeHTML(username)}')"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M16 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2"/><circle cx="8.5" cy="7" r="4"/><line x1="20" y1="8" x2="20" y2="14"/><line x1="23" y1="11" x2="17" y2="11"/></svg></button>` : ''}
    </div>`;

  // Position near the anchor element
  document.body.appendChild(panel);
  // Render mini widgets (favourite game & primary bastion only, compact)
  const _mppWidgetArea = panel.querySelector('#mpp-widgets-area');
  if (_mppWidgetArea && (u.profileWidgets||[]).some(w => w.enabled && (w.id === 'favourite_game' || w.id === 'primary_bastion'))) {
    let _mwHtml = '<div class="mpp-divider"></div>';
    (u.profileWidgets||[]).forEach(w => {
      if (!w.enabled) return;
      if (w.id === 'favourite_game' && w.config?.gameName) {
        const fg = (u.gameCollection||[]).find(g => g.name === w.config.gameName);
        if (fg) _mwHtml += `<div class="mpp-section"><div class="mpp-section-title">Favourite Game</div><div class="mpp-game-row"><div class="mpp-game-chip" style="background:rgba(245,158,11,.06);border-color:rgba(245,158,11,.15);color:rgba(245,158,11,.8);">${fg.coverUrl ? `<img src="${escapeHTML(fg.coverUrl)}" style="width:14px;height:18px;border-radius:2px;object-fit:cover;">` : '⭐'} ${escapeHTML(fg.name)}</div></div></div>`;
      }
      if (w.id === 'primary_bastion' && w.config?.bastionIdx !== undefined) {
        const b = u.bastions?.[w.config.bastionIdx];
        if (b) _mwHtml += `<div class="mpp-section"><div class="mpp-section-title">Primary Bastion</div><div class="mpp-game-row"><div class="mpp-game-chip" style="background:rgba(96,165,250,.06);border-color:rgba(96,165,250,.15);color:rgba(96,165,250,.8);cursor:pointer;" onclick="document.getElementById('mini-profile-preview')?.remove();joinBastionFromWidget('${escapeHTML(b.name||'')}',${w.config.bastionIdx})">${b.emblem ? `<img src="${escapeHTML(b.emblem)}" style="width:14px;height:14px;border-radius:3px;object-fit:cover;">` : '🏰'} ${escapeHTML(b.name||'Bastion')}</div></div></div>`;
      }
    });
    _mppWidgetArea.innerHTML = _mwHtml;
  }
  const rect = anchorEl?.getBoundingClientRect() || {left:100, top:100, width:40};
  const PW = panel.offsetWidth || 340;
  const PH = panel.offsetHeight || 300;
  let left = rect.left + rect.width + 8;
  let top = rect.top;
  if (left + PW > window.innerWidth - 8) left = rect.left - PW - 8;
  if (top + PH > window.innerHeight - 8) top = window.innerHeight - PH - 8;
  if (top < 8) top = 8;
  panel.style.left = Math.max(8, left) + 'px';
  panel.style.top = Math.max(8, top) + 'px';

  // Close on outside click or Escape key
  setTimeout(() => {
    function _closePanel() { panel.remove(); document.removeEventListener('mousedown', _closeMouse); document.removeEventListener('keydown', _closeKey); }
    function _closeMouse(e) { if (!panel.contains(e.target) && e.target !== anchorEl) _closePanel(); }
    function _closeKey(e) { if (e.key === 'Escape') { e.stopPropagation(); _closePanel(); } }
    document.addEventListener('mousedown', _closeMouse);
    document.addEventListener('keydown', _closeKey);
  }, 100);
}

// Inline role picker for mini profile preview
function _mppToggleRolePicker(username) {
  const picker = document.getElementById('mpp-role-picker');
  if (!picker) return;
  if (picker.style.display !== 'none') { picker.style.display = 'none'; return; }
  const b = CU?.bastions?.[curBastion];
  if (!b || !b.roles?.length) { toast('No roles configured', 'info'); return; }
  const memberRoles = (b.memberRoles || {})[username] || [];
  picker.innerHTML = b.roles.map(r => {
    const has = memberRoles.includes(r.id);
    return `<div class="mpp-role-pick-item" data-rid="${escapeHTML(r.id)}" onclick="_mppToggleRole('${escapeHTML(username)}','${escapeHTML(r.id)}',this)" style="display:flex;align-items:center;gap:8px;padding:6px 10px;border-radius:8px;cursor:pointer;transition:background .12s;${has?'background:rgba(255,255,255,.06);':'background:transparent;'}" onmouseover="this.style.background='rgba(255,255,255,.08)'" onmouseout="this.style.background='${has?"rgba(255,255,255,.06)":"transparent"}'">
      <span style="width:10px;height:10px;border-radius:50%;background:${r.color||'#60a5fa'};flex-shrink:0;"></span>
      <span style="flex:1;font-size:12px;font-weight:600;color:rgba(255,255,255,.7);">${escapeHTML(r.name)}</span>
      <span style="font-size:14px;color:${has?'#3ecf6e':'rgba(255,255,255,.15)'};">${has?'✓':'○'}</span>
    </div>`;
  }).join('');
  picker.style.display = 'block';
  picker.style.cssText += 'margin-top:6px;padding:4px;background:rgba(0,0,0,.2);border:1px solid rgba(255,255,255,.06);border-radius:10px;';
}

async function _mppToggleRole(username, roleId, el) {
  const b = CU?.bastions?.[curBastion];
  if (!b) return;
  if (!b.memberRoles) b.memberRoles = {};
  if (!b.memberRoles[username]) b.memberRoles[username] = [];
  const roles = b.memberRoles[username];
  const has = roles.includes(roleId);
  if (has) {
    b.memberRoles[username] = roles.filter(r => r !== roleId);
  } else {
    b.memberRoles[username] = [...roles, roleId];
  }
  const nowHas = b.memberRoles[username].includes(roleId);
  // Update toggle indicator
  const indicator = el.querySelector('span:last-child');
  if (indicator) { indicator.textContent = nowHas ? '✓' : '○'; indicator.style.color = nowHas ? '#3ecf6e' : 'rgba(255,255,255,.15)'; }
  el.style.background = nowHas ? 'rgba(255,255,255,.06)' : 'transparent';
  el.onmouseout = function() { this.style.background = nowHas ? 'rgba(255,255,255,.06)' : 'transparent'; };
  // Update role tags display
  const container = document.getElementById('mpp-roles-container');
  if (container) {
    const addBtn = container.querySelector('.mpp-role-add-btn');
    const tagsHtml = renderUserRoleTags(username);
    container.innerHTML = tagsHtml + (addBtn ? addBtn.outerHTML : '');
  }
  // Save and sync
  try {
    await saveUser();
    _syncBastionToGlobal(curBastion);
  } catch(e) { console.warn('Role save failed:', e); }
  // Refresh member list
  try { renderMemberList(); } catch (e) { console.debug('[Members] render failed', e); }
}


// Per-user appearance key — each account gets its own theme
function _appearanceKey() {
  const u = (typeof CU !== 'undefined' && CU?.username) || localStorage.getItem('ftz_current') || localStorage.getItem('fortized_current_user') || '';
  return u ? 'ftz_appearance_' + u : 'ftz_appearance';
}
function _darkenHex(hex, pct) {
  // Darken a hex color by a percentage (0-1). E.g. 0.188 = 18.8% darker
  const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
  const f = 1 - pct;
  return '#' + [Math.round(r*f),Math.round(g*f),Math.round(b*f)].map(v=>Math.max(0,Math.min(255,v)).toString(16).padStart(2,'0')).join('');
}
function applyAppearance(themeId) {
  // Migrate old 'fortized' id to 'fortized_classic'
  if (themeId === 'fortized') themeId = 'fortized_classic';
  localStorage.setItem(_appearanceKey(), themeId);
  // ALL themes keep Fortized yellow accent
  document.documentElement.style.setProperty('--accent',     '#fff93e');
  document.documentElement.style.setProperty('--accent-dim', 'rgba(255,249,62,.1)');
  document.documentElement.style.setProperty('--accent-mid', 'rgba(255,249,62,.22)');
  const canvasEl = document.getElementById('global-canvas');
  let canvasColor, glassHeavy, glassMid, glassLight;
  let sidebarColor;
  if (themeId === 'dark_realm') {
    canvasColor = '#030407';
    sidebarColor = '#050710';
    glassHeavy = 'rgba(3,4,7,.94)'; glassMid = 'rgba(3,4,7,.88)'; glassLight = 'rgba(3,4,7,.82)';
    document.documentElement.style.setProperty('--bg',         '#030407');
    document.documentElement.style.setProperty('--rail',       '#020304');
    document.documentElement.style.setProperty('--sidebar',    sidebarColor);
    document.documentElement.style.setProperty('--channel',    '#060810');
    document.documentElement.style.setProperty('--panel',      '#080b14');
    document.documentElement.style.setProperty('--panel2',     '#0a0e18');
    document.documentElement.style.setProperty('--panel3',     '#0d111c');
    document.documentElement.style.setProperty('--border',     '#141a2a');
    document.documentElement.style.setProperty('--muted',      '#3a4458');
    document.documentElement.style.setProperty('--muted-light','#5a6a7e');
  } else if (themeId === 'midnight_citadel') {
    canvasColor = '#050812';
    sidebarColor = '#080e1a';
    glassHeavy = 'rgba(5,8,18,.94)'; glassMid = 'rgba(5,8,18,.88)'; glassLight = 'rgba(5,8,18,.82)';
    document.documentElement.style.setProperty('--bg',         '#050812');
    document.documentElement.style.setProperty('--rail',       '#030610');
    document.documentElement.style.setProperty('--sidebar',    sidebarColor);
    document.documentElement.style.setProperty('--channel',    '#0a1120');
    document.documentElement.style.setProperty('--panel',      '#0d1528');
    document.documentElement.style.setProperty('--panel2',     '#101a30');
    document.documentElement.style.setProperty('--panel3',     '#141e38');
    document.documentElement.style.setProperty('--border',     '#1a2848');
    document.documentElement.style.setProperty('--muted',      '#3a5080');
    document.documentElement.style.setProperty('--muted-light','#6088b8');
  } else if (themeId === 'onyx_pure') {
    canvasColor = 'linear-gradient(170deg, #010103 0%, #08061a 100%)';
    sidebarColor = '#020206';
    glassHeavy = 'rgba(1,1,3,.94)'; glassMid = 'rgba(1,1,3,.88)'; glassLight = 'rgba(1,1,3,.82)';
    document.documentElement.style.setProperty('--bg',         '#010103');
    document.documentElement.style.setProperty('--rail',       '#010102');
    document.documentElement.style.setProperty('--sidebar',    sidebarColor);
    document.documentElement.style.setProperty('--channel',    '#030308');
    document.documentElement.style.setProperty('--panel',      '#04040c');
    document.documentElement.style.setProperty('--panel2',     '#06060f');
    document.documentElement.style.setProperty('--panel3',     '#080812');
    document.documentElement.style.setProperty('--border',     '#0e0e1e');
    document.documentElement.style.setProperty('--muted',      '#2a2a3e');
    document.documentElement.style.setProperty('--muted-light','#44445e');
  } else {
    // Fortized Classic (default)
    canvasColor = '#13161d';
    sidebarColor = '#181a1f';
    glassHeavy = 'rgba(19,22,29,.96)'; glassMid = 'rgba(19,22,29,.82)'; glassLight = 'rgba(19,22,29,.68)';
    document.documentElement.style.setProperty('--bg',         '#13161d');
    document.documentElement.style.setProperty('--rail',       '#0f1119');
    document.documentElement.style.setProperty('--sidebar',    sidebarColor);
    document.documentElement.style.setProperty('--channel',    '#15171e');
    document.documentElement.style.setProperty('--panel',      '#1b1e25');
    document.documentElement.style.setProperty('--panel2',     '#1f232b');
    document.documentElement.style.setProperty('--panel3',     '#23272f');
    document.documentElement.style.setProperty('--border',     '#252b3a');
    document.documentElement.style.setProperty('--muted',      '#4e5a6f');
    document.documentElement.style.setProperty('--muted-light','#7d8a9e');
  }
  // ── Layered Depth Architecture: update the Global Canvas ──
  if (canvasEl) canvasEl.style.background = canvasColor;
  document.documentElement.style.setProperty('--canvas-color', canvasColor);
  if (glassHeavy) {
    document.documentElement.style.setProperty('--glass-heavy', glassHeavy);
    document.documentElement.style.setProperty('--glass-mid', glassMid);
    document.documentElement.style.setProperty('--glass-light', glassLight);
    document.documentElement.style.setProperty('--glass-ultra-light', glassMid.replace(/[\d.]+\)$/, m => (parseFloat(m) * 0.55).toFixed(2) + ')'));
  }
  // Secondary sidebar is 18.8% darker than the main sidebar color
  document.documentElement.style.setProperty('--sidebar-ctx', _darkenHex(sidebarColor, 0.188));
  // Reset body gradient — canvas now handles it
  document.body.style.background = '';
  // All themes keep yellow accent
  {
    document.documentElement.style.setProperty('--accent',     '#fff93e');
    document.documentElement.style.setProperty('--accent-dim', 'rgba(255,249,62,.1)');
    document.documentElement.style.setProperty('--accent-mid', 'rgba(255,249,62,.22)');
  }
  // Re-render appearance settings if it's currently open
  const activeNav = document.querySelector('.profile-nav-item.active');
  if (activeNav && activeNav.id === 'pnav-appearance') buildProfileView('appearance');
  // Also sync userbar and chatbar colors
  const userbarEl = document.querySelector('.userbar');
  const chatInputOuter = document.querySelector('.chat-input-outer');
  if (userbarEl) userbarEl.style.background = '';
  if (chatInputOuter) chatInputOuter.style.background = '';
  const toastMsgs = {midnight_citadel:'🌙 Midnight Citadel', dark_realm:'🌑 Dark Realm', onyx_pure:'⬛ Onyx Pure', fortized_classic:'⚡ Fortized Classic'};
  toast((toastMsgs[themeId]||'⚡ Theme')+' activated!', 'success');
}

