// ── Load & render events list ──
async function _loadEvents(bastionId) {
  const container = document.getElementById('ev-tab-content');
  if (!container) return;
  container.innerHTML = '<div style="text-align:center;padding:40px;color:var(--muted);font-size:12px;">Loading events…</div>';
  try {
    const snap = await firebase.database().ref('events/' + bastionId).get();
    if (!snap.exists()) {
      container.innerHTML = '<div class="ev-empty"><svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.2" style="opacity:.2;"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg><div>No events yet</div><div style="font-size:11px;color:var(--muted);margin-top:4px;">Create one to get started!</div></div>';
      return;
    }
    const events = [];
    snap.forEach(c => { const v = c.val(); v._key = c.key; events.push(v); });
    events.sort((a,b) => new Date(a.date||0) - new Date(b.date||0));
    window._eventsCache = { bastionId, events };
    const now = new Date();
    const b = CU.bastions?.[curBastion];
    const isOwner = b?.owner === CU.username;
    const hasAdmin = hasPerm('administrator') || hasPerm('manage_channels');
    const canManage = isOwner || hasAdmin;

    // Split into live/upcoming and past
    const upcoming = events.filter(ev => !ev.cancelled && new Date(ev.date) >= now || ev.status === 'live');
    const past = events.filter(ev => ev.cancelled || (new Date(ev.date) < now && ev.status !== 'live'));

    let html = '<div class="ev-list">';
    if (upcoming.length) {
      html += upcoming.map(ev => _renderEventCard(ev, bastionId, canManage, now)).join('');
    }
    if (past.length) {
      html += '<div class="ev-section-label">Past & Cancelled</div>';
      html += past.map(ev => _renderEventCard(ev, bastionId, canManage, now, true)).join('');
    }
    if (!upcoming.length && !past.length) {
      html += '<div class="ev-empty">No events</div>';
    }
    html += '</div>';
    container.innerHTML = html;
    _updateEventsBadge(bastionId);
  } catch { container.innerHTML = '<div class="ev-empty">Failed to load events</div>'; }
}

function _renderEventCard(ev, bastionId, canManage, now, isPast) {
  const d = new Date(ev.date);
  const endD = ev.endDate ? new Date(ev.endDate) : null;
  const rsvps = ev.rsvps ? Object.keys(ev.rsvps).length : 0;
  const userRsvp = ev.rsvps?.[CU.username];
  const isLive = ev.status === 'live';
  const isCancelled = !!ev.cancelled;
  const isCreator = ev.createdBy === CU.username;
  const diff = d - now;
  const days = Math.floor(diff / 86400000);
  const hours = Math.floor((diff % 86400000) / 3600000);
  const mins = Math.floor((diff % 3600000) / 60000);
  const countdown = isCancelled ? 'Cancelled' : isLive ? '🔴 LIVE NOW' : isPast ? 'Ended' : days > 0 ? days+'d '+hours+'h' : hours > 0 ? hours+'h '+mins+'m' : mins > 0 ? mins+'m' : 'Starting soon!';
  const bannerBg = ev.banner ? 'background-image:url('+escapeHTML(ev.banner)+');background-size:cover;background-position:center;' : 'background:linear-gradient(135deg,rgba(255,249,62,.08),rgba(96,165,250,.06));';
  const liveClass = isLive ? ' ev-card-live' : '';
  const cancelClass = isCancelled ? ' ev-card-cancelled' : '';
  const pastClass = isPast ? ' ev-card-past' : '';

  return '<div class="event-card'+liveClass+cancelClass+pastClass+'">'
    + '<div class="ec-banner" style="'+bannerBg+'">'
    + (ev.banner ? '' : '<span style="font-size:32px;">'+(ev.emoji||'📅')+'</span>')
    + '<div class="ec-date-badge"><div class="edb-month">'+d.toLocaleString('en',{month:'short'})+'</div><div class="edb-day">'+d.getDate()+'</div></div>'
    + (isLive ? '<div class="ec-live-badge">🔴 LIVE</div>' : '')
    + '</div>'
    + '<div class="ec-body">'
    + '<div class="ec-title-row"><div class="ec-title">'+escapeHTML(ev.title||'')+'</div>'
    + '<button class="ec-menu-btn" onclick="_showEventMenu(event,\''+escapeHTML(bastionId)+'\',\''+ev._key+'\','+(canManage||isCreator?'true':'false')+')">⋯</button></div>'
    + (ev.description ? '<div class="ec-desc">'+escapeHTML(ev.description.slice(0,200))+'</div>' : '')
    + (ev.location ? '<div class="ec-location"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="flex-shrink:0;opacity:.5;"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg> <span>'+escapeHTML(ev.location)+'</span></div>' : '')
    + (ev.frequency && ev.frequency !== 'once' ? '<div class="ec-frequency">↻ '+({daily:'Daily',weekly:'Weekly',biweekly:'Bi-weekly',monthly:'Monthly'}[ev.frequency]||'')+'</div>' : '')
    + '<div class="ec-meta">'
    + '<span>'+rsvps+' interested</span>'
    + '<div class="event-countdown">'+countdown+'</div>'
    + '<div class="ec-rsvp">'
    + '<button class="rsvp-yes '+(userRsvp?'active':'')+'" onclick="_rsvpEvent(\''+escapeHTML(bastionId)+'\',\''+ev._key+'\')">'
    + (userRsvp ? '✓ Going' : 'Interested')
    + '</button></div></div>'
    + (endD ? '<div style="font-size:10px;color:var(--muted);margin-top:4px;">Ends '+endD.toLocaleString('en',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})+'</div>' : '')
    + '</div></div>';
}

// ── Event context menu ──
function _showEventMenu(e, bastionId, eventKey, canManage) {
  e.stopPropagation();
  document.querySelectorAll('.ev-ctx-menu').forEach(m=>m.remove());
  const cached = window._eventsCache?.events?.find(ev=>ev._key===eventKey);
  const isLive = cached?.status === 'live';
  const isCancelled = !!cached?.cancelled;
  const isPast = cached ? new Date(cached.date) < new Date() && !isLive : false;

  const menu = document.createElement('div');
  menu.className = 'ev-ctx-menu';
  let items = '';
  items += '<div class="ev-ctx-item" onclick="_addEventToCalendar(\''+eventKey+'\')"><span>Add to Calendar</span><span style="opacity:.4;">›</span></div>';
  if (canManage && !isLive && !isCancelled && !isPast) {
    items += '<div class="ev-ctx-item" onclick="_startEventEarly(\''+escapeHTML(bastionId)+'\',\''+eventKey+'\')"><span>Start Event</span></div>';
  }
  if (canManage && !isCancelled) {
    items += '<div class="ev-ctx-item ev-ctx-highlight" onclick="_openEventForm(\''+eventKey+'\')"><span>Edit Event</span></div>';
  }
  if (canManage && !isCancelled) {
    items += '<div class="ev-ctx-item ev-ctx-danger" onclick="_cancelEvent(\''+escapeHTML(bastionId)+'\',\''+eventKey+'\')"><span>Cancel Event</span></div>';
  }
  items += '<div class="ev-ctx-item" onclick="_copyEventLink(\''+escapeHTML(bastionId)+'\',\''+eventKey+'\')"><span>Copy Event Link</span></div>';
  items += '<div class="ev-ctx-item ev-ctx-report" onclick="_reportEvent(\''+escapeHTML(bastionId)+'\',\''+eventKey+'\')"><span>Report Event</span><span style="color:var(--red);">🚩</span></div>';
  menu.innerHTML = items;

  document.body.appendChild(menu);
  const btn = e.target.closest('.ec-menu-btn');
  if (btn) {
    const rect = btn.getBoundingClientRect();
    menu.style.top = rect.bottom + 4 + 'px';
    menu.style.left = Math.min(rect.left, window.innerWidth - 200) + 'px';
  } else {
    menu.style.top = e.clientY + 'px';
    menu.style.left = e.clientX + 'px';
  }
  setTimeout(() => {
    const close = (ev) => { if (!menu.contains(ev.target)) { menu.remove(); document.removeEventListener('click', close); } };
    document.addEventListener('click', close);
  }, 10);
}

// ── Event creation / edit form ──
let _evFormBannerData = '';
function _openEventForm(editKey) {
  const b = CU.bastions?.[curBastion];
  if (!b) return;
  const bastionId = b.globalId||b.name;
  const existing = editKey ? window._eventsCache?.events?.find(ev=>ev._key===editKey) : null;
  const isEdit = !!existing;
  _evFormBannerData = existing?.banner || '';

  document.querySelectorAll('.ev-ctx-menu').forEach(m=>m.remove());

  const ov = document.createElement('div');
  ov.className = 'input-dialog-overlay';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.7);backdrop-filter:blur(4px);z-index:9950;display:flex;align-items:center;justify-content:center;padding:20px;';

  const now = new Date();
  const defDate = existing ? new Date(existing.date) : new Date(now.getTime() + 3600000);
  const dateVal = defDate.getFullYear() + '-' + String(defDate.getMonth()+1).padStart(2,'0') + '-' + String(defDate.getDate()).padStart(2,'0');
  const timeVal = String(defDate.getHours()).padStart(2,'0') + ':' + String(defDate.getMinutes()).padStart(2,'0');
  const endDateVal = existing?.endDate ? new Date(existing.endDate) : null;
  const endDStr = endDateVal ? endDateVal.getFullYear()+'-'+String(endDateVal.getMonth()+1).padStart(2,'0')+'-'+String(endDateVal.getDate()).padStart(2,'0') : '';
  const endTStr = endDateVal ? String(endDateVal.getHours()).padStart(2,'0')+':'+String(endDateVal.getMinutes()).padStart(2,'0') : '';
  const freqVal = existing?.frequency || 'once';
  const locVal = existing?.location || '';

  ov.innerHTML = '<div class="ev-form-card">'
    + '<div class="modal-bar"></div>'
    + '<div class="ev-form-title">' + (isEdit ? 'Edit Event' : 'Create Event') + '</div>'
    + '<div class="ev-form-body">'
    + '<label class="ev-form-label">Event Name <span style="color:var(--red);">*</span></label>'
    + '<input class="field-input ev-form-input" id="ev-f-title" placeholder="e.g. Game Night, Community Hangout…" maxlength="100" value="' + escapeHTML(existing?.title||'') + '">'
    + '<label class="ev-form-label">Description</label>'
    + '<textarea class="field-input ev-form-input" id="ev-f-desc" placeholder="What\'s the event about?" rows="3" maxlength="500" style="resize:vertical;">' + escapeHTML(existing?.description||'') + '</textarea>'
    + '<label class="ev-form-label">Banner Image <span style="font-size:10px;color:var(--muted);">(optional)</span></label>'
    + '<div class="ev-banner-upload" id="ev-f-banner-zone">'
    + '<input type="file" id="ev-f-banner-file" accept="image/*" style="display:none;">'
    + '<div id="ev-f-banner-preview" class="ev-banner-preview' + (_evFormBannerData ? ' has-img' : '') + '">'
    + (_evFormBannerData ? '<img src="' + escapeHTML(_evFormBannerData) + '">' : '')
    + '</div>'
    + '<div class="ev-banner-actions">'
    + '<button type="button" class="btn-g ev-banner-btn" onclick="document.getElementById(\'ev-f-banner-file\').click()">' + (_evFormBannerData ? 'Change Image' : 'Upload Image') + '</button>'
    + (_evFormBannerData ? '<button type="button" class="btn-g ev-banner-btn ev-banner-remove" onclick="_evRemoveBanner()">Remove</button>' : '')
    + '</div></div>'
    + '<label class="ev-form-label">Location <span style="font-size:10px;color:var(--muted);">(optional)</span></label>'
    + '<input class="field-input ev-form-input" id="ev-f-location" placeholder="e.g. Voice Channel, Discord Stage, Twitch…" maxlength="150" value="' + escapeHTML(locVal) + '">'
    + '<div class="ev-form-row">'
    + '<div style="flex:1;"><label class="ev-form-label">Start Date <span style="color:var(--red);">*</span></label><input type="date" class="field-input ev-form-input" id="ev-f-date" value="' + dateVal + '"></div>'
    + '<div style="flex:1;"><label class="ev-form-label">Start Time <span style="color:var(--red);">*</span></label><input type="time" class="field-input ev-form-input" id="ev-f-time" value="' + timeVal + '"></div>'
    + '</div>'
    + '<div class="ev-form-row">'
    + '<div style="flex:1;"><label class="ev-form-label">End Date <span style="font-size:10px;color:var(--muted);">(optional)</span></label><input type="date" class="field-input ev-form-input" id="ev-f-end-date" value="' + endDStr + '"></div>'
    + '<div style="flex:1;"><label class="ev-form-label">End Time</label><input type="time" class="field-input ev-form-input" id="ev-f-end-time" value="' + endTStr + '"></div>'
    + '</div>'
    + '<label class="ev-form-label">Event Frequency</label>'
    + '<select class="field-input ev-form-input" id="ev-f-freq">'
    + '<option value="once"' + (freqVal==='once' ? ' selected' : '') + '>One-time</option>'
    + '<option value="daily"' + (freqVal==='daily' ? ' selected' : '') + '>Daily</option>'
    + '<option value="weekly"' + (freqVal==='weekly' ? ' selected' : '') + '>Weekly</option>'
    + '<option value="biweekly"' + (freqVal==='biweekly' ? ' selected' : '') + '>Bi-weekly</option>'
    + '<option value="monthly"' + (freqVal==='monthly' ? ' selected' : '') + '>Monthly</option>'
    + '</select>'
    + '</div>'
    + '<div class="ev-form-actions">'
    + '<button class="btn-g" onclick="this.closest(\'.input-dialog-overlay\').remove()">Cancel</button>'
    + '<button class="btn-a" onclick="_reviewEvent(\'' + escapeHTML(bastionId) + '\',' + (isEdit ? '\'' + editKey + '\'' : 'null') + ')">' + (isEdit ? 'Review Changes' : 'Review Event') + '</button>'
    + '</div></div>';

  document.body.appendChild(ov);
  ov.onclick = e => { if (e.target === ov) ov.remove(); };
  document.getElementById('ev-f-title')?.focus();

  // Banner file upload handler
  const fileInput = document.getElementById('ev-f-banner-file');
  if (fileInput) fileInput.addEventListener('change', function() {
    const file = this.files?.[0];
    if (!file) return;
    if (file.size > 2 * 1024 * 1024) { toast('Image must be under 2MB','error'); this.value = ''; return; }
    const reader = new FileReader();
    reader.onload = function(e) {
      _evFormBannerData = e.target.result;
      const prev = document.getElementById('ev-f-banner-preview');
      if (prev) { prev.innerHTML = '<img src="' + _evFormBannerData + '">'; prev.classList.add('has-img'); }
      const zone = document.getElementById('ev-f-banner-zone');
      if (zone) {
        const acts = zone.querySelector('.ev-banner-actions');
        if (acts) acts.innerHTML = '<button type="button" class="btn-g ev-banner-btn" onclick="document.getElementById(\'ev-f-banner-file\').click()">Change Image</button>'
          + '<button type="button" class="btn-g ev-banner-btn ev-banner-remove" onclick="_evRemoveBanner()">Remove</button>';
      }
    };
    reader.readAsDataURL(file);
  });
}

function _evRemoveBanner() {
  _evFormBannerData = '';
  const prev = document.getElementById('ev-f-banner-preview');
  if (prev) { prev.innerHTML = ''; prev.classList.remove('has-img'); }
  const fileInput = document.getElementById('ev-f-banner-file');
  if (fileInput) fileInput.value = '';
  const zone = document.getElementById('ev-f-banner-zone');
  if (zone) {
    const acts = zone.querySelector('.ev-banner-actions');
    if (acts) acts.innerHTML = '<button type="button" class="btn-g ev-banner-btn" onclick="document.getElementById(\'ev-f-banner-file\').click()">Upload Image</button>';
  }
}

// ── Review event preview ──
function _reviewEvent(bastionId, editKey) {
  const title = document.getElementById('ev-f-title')?.value?.trim();
  if (!title) { toast('Event name is required','error'); return; }
  const desc = document.getElementById('ev-f-desc')?.value?.trim() || '';
  const dateStr = document.getElementById('ev-f-date')?.value;
  const timeStr = document.getElementById('ev-f-time')?.value;
  if (!dateStr || !timeStr) { toast('Start date and time are required','error'); return; }
  const startDate = new Date(dateStr + 'T' + timeStr);
  if (isNaN(startDate.getTime())) { toast('Invalid date/time','error'); return; }
  const endDateStr = document.getElementById('ev-f-end-date')?.value;
  const endTimeStr = document.getElementById('ev-f-end-time')?.value;
  let endDate = null;
  if (endDateStr && endTimeStr) {
    endDate = new Date(endDateStr + 'T' + endTimeStr);
    if (isNaN(endDate.getTime())) endDate = null;
  }
  const location = document.getElementById('ev-f-location')?.value?.trim() || '';
  const frequency = document.getElementById('ev-f-freq')?.value || 'once';
  const banner = _evFormBannerData;

  // Build preview
  const d = startDate;
  const bannerBg = banner ? 'background-image:url(' + escapeHTML(banner) + ');background-size:cover;background-position:center;' : 'background:linear-gradient(135deg,rgba(255,249,62,.08),rgba(96,165,250,.06));';
  const freqLabels = {once:'One-time',daily:'Daily',weekly:'Weekly',biweekly:'Bi-weekly',monthly:'Monthly'};
  const freqLabel = freqLabels[frequency] || 'One-time';

  // Hide form, show preview
  const formCard = document.querySelector('.ev-form-card');
  if (formCard) formCard.style.display = 'none';

  const previewCard = document.createElement('div');
  previewCard.className = 'ev-form-card ev-preview-card';
  previewCard.innerHTML = '<div class="modal-bar"></div>'
    + '<div class="ev-form-title">Event Preview</div>'
    + '<div style="padding:14px 22px 0;">'
    + '<div class="event-card" style="margin-bottom:0;pointer-events:none;">'
    + '<div class="ec-banner" style="' + bannerBg + '">'
    + (banner ? '' : '<span style="font-size:32px;">📅</span>')
    + '<div class="ec-date-badge"><div class="edb-month">' + d.toLocaleString('en',{month:'short'}) + '</div><div class="edb-day">' + d.getDate() + '</div></div>'
    + '</div>'
    + '<div class="ec-body">'
    + '<div class="ec-title">' + escapeHTML(title) + '</div>'
    + (desc ? '<div class="ec-desc">' + escapeHTML(desc.slice(0,200)) + '</div>' : '')
    + (location ? '<div class="ec-location"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" style="flex-shrink:0;opacity:.5;"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg> <span>' + escapeHTML(location) + '</span></div>' : '')
    + '<div class="ec-meta">'
    + '<span>0 interested</span>'
    + '<span style="color:var(--accent);font-weight:700;">' + d.toLocaleString('en',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}) + '</span>'
    + '</div>'
    + (endDate ? '<div style="font-size:10px;color:var(--muted);margin-top:4px;">Ends ' + endDate.toLocaleString('en',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}) + '</div>' : '')
    + (frequency !== 'once' ? '<div style="font-size:10px;color:var(--accent);margin-top:4px;font-weight:700;">↻ ' + freqLabel + '</div>' : '')
    + '</div></div></div>'
    + '<div class="ev-form-actions">'
    + '<button class="btn-g" onclick="_evBackToForm()">Back</button>'
    + '<button class="btn-a" id="ev-publish-btn" onclick="_publishEvent(\'' + escapeHTML(bastionId) + '\',' + (editKey ? '\'' + editKey + '\'' : 'null') + ')">Publish Event</button>'
    + '</div>';

  const ov = document.querySelector('.input-dialog-overlay');
  if (ov) ov.appendChild(previewCard);
}

function _evBackToForm() {
  const preview = document.querySelector('.ev-preview-card');
  if (preview) preview.remove();
  const form = document.querySelector('.ev-form-card');
  if (form) form.style.display = '';
}

async function _publishEvent(bastionId, editKey) {
  const btn = document.getElementById('ev-publish-btn');
  if (btn) { btn.disabled = true; btn.textContent = 'Publishing…'; }

  const title = document.getElementById('ev-f-title')?.value?.trim();
  const desc = document.getElementById('ev-f-desc')?.value?.trim() || '';
  const dateStr = document.getElementById('ev-f-date')?.value;
  const timeStr = document.getElementById('ev-f-time')?.value;
  const startDate = new Date(dateStr + 'T' + timeStr);
  const endDateStr = document.getElementById('ev-f-end-date')?.value;
  const endTimeStr = document.getElementById('ev-f-end-time')?.value;
  let endDate = null;
  if (endDateStr && endTimeStr) {
    endDate = new Date(endDateStr + 'T' + endTimeStr);
    if (isNaN(endDate.getTime())) endDate = null;
  }
  const location = document.getElementById('ev-f-location')?.value?.trim() || '';
  const frequency = document.getElementById('ev-f-freq')?.value || 'once';
  const banner = _evFormBannerData;

  const ev = {
    title: title, description: desc, date: startDate.toISOString(),
    banner: banner, location: location, frequency: frequency,
    createdBy: CU.username, createdAt: new Date().toISOString()
  };
  if (endDate) ev.endDate = endDate.toISOString();
  if (!editKey) ev.shareCode = Math.random().toString(36).slice(2,8).toUpperCase();

  try {
    let savedKey = editKey;
    if (editKey) {
      const old = window._eventsCache?.events?.find(e => e._key===editKey);
      if (old?.rsvps) ev.rsvps = old.rsvps;
      if (old?.shareCode) ev.shareCode = old.shareCode;
      if (old?.status) ev.status = old.status;
      ev.createdBy = old?.createdBy || CU.username;
      ev.createdAt = old?.createdAt || ev.createdAt;
      await firebase.database().ref('events/' + bastionId + '/' + editKey).set(ev);
      toast('Event updated!','success');
    } else {
      const ref = await firebase.database().ref('events/' + bastionId).push(ev);
      savedKey = ref.key;
      toast('Event created!','success');
    }

    // Show success with copy link
    const shareCode = ev.shareCode;
    const link = window.location.origin + '/app?event=' + shareCode + '&bastion=' + encodeURIComponent(bastionId);
    _showEventPublished(link, editKey);
    _loadEvents(bastionId);
  } catch(err) {
    console.error('[Event] Save failed'); toast('Failed to save event. Please try again.','error');
    if (btn) { btn.disabled = false; btn.textContent = 'Publish Event'; }
  }
}

function _showEventPublished(link, wasEdit) {
  // Replace preview with success
  const ov = document.querySelector('.input-dialog-overlay');
  if (!ov) return;
  ov.innerHTML = '<div class="ev-form-card ev-published-card">'
    + '<div class="modal-bar"></div>'
    + '<div style="padding:30px 28px;text-align:center;">'
    + '<div style="font-size:40px;margin-bottom:10px;">🎉</div>'
    + '<div class="ev-form-title" style="padding:0;margin-bottom:6px;">' + (wasEdit ? 'Event Updated!' : 'Event Published!') + '</div>'
    + '<div style="font-size:12px;color:var(--muted);margin-bottom:20px;">Share this link so others can find your event</div>'
    + '<div class="ev-share-link-box">'
    + '<input type="text" class="field-input ev-form-input ev-share-input" id="ev-share-link" value="' + escapeHTML(link) + '" readonly onclick="this.select()">'
    + '<button class="btn-a ev-copy-link-btn" onclick="_evCopyPublishedLink()">Copy</button>'
    + '</div>'
    + '<div style="margin-top:18px;">'
    + '<button class="btn-g" onclick="this.closest(\'.input-dialog-overlay\').remove()">Done</button>'
    + '</div></div></div>';
}

function _evCopyPublishedLink() {
  const input = document.getElementById('ev-share-link');
  if (!input) return;
  navigator.clipboard.writeText(input.value).then(() => {
    toast('Link copied!','success');
    const btn = input.parentElement?.querySelector('.ev-copy-link-btn');
    if (btn) { btn.textContent = 'Copied!'; setTimeout(() => { btn.textContent = 'Copy'; }, 1500); }
  }).catch(() => { input.select(); document.execCommand('copy'); toast('Link copied!','success'); });
}

// ── RSVP ──
async function _rsvpEvent(bastionId, eventKey) {
  const path = 'events/' + bastionId + '/' + eventKey + '/rsvps/' + CU.username;
  try {
    const snap = await firebase.database().ref(path).get();
    if (snap.exists()) { await firebase.database().ref(path).remove(); toast('RSVP removed','info'); }
    else { await firebase.database().ref(path).set(true); toast('RSVP confirmed!','success'); }
    _loadEvents(bastionId);
  } catch { toast('Something went wrong. Please try again.','error'); }
}

// ── Start event early ──
async function _startEventEarly(bastionId, eventKey) {
  showCustomConfirm('Start this event now? It will be marked as LIVE.', async () => {
    try {
      await firebase.database().ref('events/' + bastionId + '/' + eventKey + '/status').set('live');
      toast('Event is now LIVE!','success');
      _loadEvents(bastionId);
      _updateEventsBadge(bastionId);
    } catch { toast('Something went wrong. Please try again.','error'); }
  });
}

// ── Cancel event ──
async function _cancelEvent(bastionId, eventKey) {
  showCustomConfirm('Cancel this event? This cannot be undone.', async () => {
    try {
      await firebase.database().ref('events/' + bastionId + '/' + eventKey + '/cancelled').set(true);
      await firebase.database().ref('events/' + bastionId + '/' + eventKey + '/status').remove();
      toast('Event cancelled','info');
      _loadEvents(bastionId);
      _updateEventsBadge(bastionId);
    } catch { toast('Something went wrong. Please try again.','error'); }
  });
}

// ── Copy event link ──
function _copyEventLink(bastionId, eventKey) {
  const cached = window._eventsCache?.events?.find(ev=>ev._key===eventKey);
  const code = cached?.shareCode || eventKey;
  const link = location.origin + '/app?event=' + code + '&bastion=' + encodeURIComponent(bastionId);
  navigator.clipboard.writeText(link).then(() => toast('Event link copied!','success')).catch(() => toast('Failed to copy','error'));
  document.querySelectorAll('.ev-ctx-menu').forEach(m=>m.remove());
}

// ── Add to external calendar ──
function _addEventToCalendar(eventKey) {
  const cached = window._eventsCache?.events?.find(ev=>ev._key===eventKey);
  if (!cached) return;
  document.querySelectorAll('.ev-ctx-menu').forEach(m=>m.remove());
  const d = new Date(cached.date);
  const end = cached.endDate ? new Date(cached.endDate) : new Date(d.getTime() + 3600000);
  const fmt = dt => dt.toISOString().replace(/[-:]/g,'').replace(/\.\d+/,'');
  const gcalUrl = 'https://calendar.google.com/calendar/render?action=TEMPLATE&text='+encodeURIComponent(cached.title)+'&dates='+fmt(d)+'/'+fmt(end)+'&details='+encodeURIComponent(cached.description||'');
  window.open(gcalUrl, '_blank');
}

// ── Report event ──
function _reportEvent(bastionId, eventKey) {
  document.querySelectorAll('.ev-ctx-menu').forEach(m=>m.remove());
  showCustomInput('Report Event','Reason for reporting:', async (reason) => {
    if (!reason) return;
    try {
      await firebase.database().ref('reports/events').push({
        bastionId, eventKey, reporter: CU.username, reason, at: new Date().toISOString()
      });
      toast('Event reported. Thank you!','success');
    } catch(e) { console.error('[Report] Submit failed:', e); toast('Failed to submit report. Please try again.','error'); }
  });
}

// ── Events notification badge ──
async function _updateEventsBadge(bastionId) {
  if (!bastionId) {
    const b = CU.bastions?.[curBastion];
    if (!b) return;
    bastionId = b.globalId||b.name;
  }
  try {
    const snap = await firebase.database().ref('events/' + bastionId).get();
    if (!snap.exists()) { _setEventsBadge(0, false); return; }
    const now = new Date();
    let liveCount = 0;
    let upcomingSoon = 0;
    snap.forEach(c => {
      const ev = c.val();
      if (ev.cancelled) return;
      if (ev.status === 'live') liveCount++;
      const d = new Date(ev.date);
      const diff = d - now;
      if (diff > 0 && diff < 3600000) upcomingSoon++; // within 1 hour
    });
    _setEventsBadge(liveCount + upcomingSoon, liveCount > 0);
  } catch(e) { console.debug('[Events] badge update failed', e); }
}

function _setEventsBadge(count, isLive) {
  const sidebarBtn = document.querySelector('.ch-sidebar-action[onclick*="events"]');
  if (!sidebarBtn) return;
  // Remove old badge
  const oldBadge = sidebarBtn.querySelector('.ev-notif-badge');
  if (oldBadge) oldBadge.remove();
  // Add badge if count > 0
  if (count > 0) {
    const badge = document.createElement('span');
    badge.className = 'ev-notif-badge';
    badge.textContent = count;
    sidebarBtn.appendChild(badge);
  }
  // Red highlight for live events
  if (isLive) {
    sidebarBtn.classList.add('ev-live-highlight');
  } else {
    sidebarBtn.classList.remove('ev-live-highlight');
  }
}

// ── Calendar view ──
async function _renderCalendar(bastionId) {
  const container = document.getElementById('ev-tab-content');
  if (!container) return;
  const monthNames = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  const dayNames = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];

  // Load events for this month
  let events = [];
  try {
    const snap = await firebase.database().ref('events/' + bastionId).get();
    if (snap.exists()) {
      snap.forEach(c => { const v = c.val(); v._key = c.key; events.push(v); });
    }
    window._eventsCache = { bastionId, events };
  } catch(e) { console.warn('[Events] fetch failed', e); }

  const firstDay = new Date(_calYear, _calMonth, 1).getDay();
  const daysInMonth = new Date(_calYear, _calMonth + 1, 0).getDate();
  const today = new Date();

  let html = '<div class="ev-cal">';
  html += '<div class="ev-cal-nav">';
  html += '<button class="ev-cal-arrow" onclick="_calMonth--;if(_calMonth<0){_calMonth=11;_calYear--;}; _renderCalendar(\''+escapeHTML(bastionId)+'\')">&lt;</button>';
  html += '<div class="ev-cal-month">'+monthNames[_calMonth]+' '+_calYear+'</div>';
  html += '<button class="ev-cal-arrow" onclick="_calMonth++;if(_calMonth>11){_calMonth=0;_calYear++;}; _renderCalendar(\''+escapeHTML(bastionId)+'\')">&gt;</button>';
  html += '</div>';

  html += '<div class="ev-cal-grid">';
  // Day headers
  dayNames.forEach(d => { html += '<div class="ev-cal-dayname">'+d+'</div>'; });
  // Empty cells before first day
  for (let i = 0; i < firstDay; i++) html += '<div class="ev-cal-cell ev-cal-empty"></div>';
  // Day cells
  for (let day = 1; day <= daysInMonth; day++) {
    const cellDate = new Date(_calYear, _calMonth, day);
    const isToday = cellDate.toDateString() === today.toDateString();
    const dayEvents = events.filter(ev => {
      if (ev.cancelled) return false;
      const ed = new Date(ev.date);
      return ed.getFullYear() === _calYear && ed.getMonth() === _calMonth && ed.getDate() === day;
    });
    const hasEvents = dayEvents.length > 0;
    const hasLive = dayEvents.some(ev => ev.status === 'live');
    html += '<div class="ev-cal-cell'+(isToday?' ev-cal-today':'')+(hasEvents?' ev-cal-has-event':'')+(hasLive?' ev-cal-has-live':'')+'" onclick="_showCalDayEvents('+day+',\''+escapeHTML(bastionId)+'\')">';
    html += '<div class="ev-cal-day">'+day+'</div>';
    if (hasEvents) {
      html += '<div class="ev-cal-dots">';
      dayEvents.slice(0,3).forEach(ev => {
        html += '<div class="ev-cal-dot'+(ev.status==='live'?' live':'')+'"></div>';
      });
      html += '</div>';
    }
    html += '</div>';
  }
  html += '</div>';

  // Event list below calendar for selected day
  html += '<div id="ev-cal-day-detail"></div>';
  html += '</div>';
  container.innerHTML = html;
}

function _showCalDayEvents(day, bastionId) {
  const detail = document.getElementById('ev-cal-day-detail');
  if (!detail) return;
  const events = window._eventsCache?.events || [];
  const dayEvents = events.filter(ev => {
    if (ev.cancelled) return false;
    const ed = new Date(ev.date);
    return ed.getFullYear() === _calYear && ed.getMonth() === _calMonth && ed.getDate() === day;
  });
  // Highlight selected day
  document.querySelectorAll('.ev-cal-cell.selected').forEach(c=>c.classList.remove('selected'));
  const cells = document.querySelectorAll('.ev-cal-cell:not(.ev-cal-empty):not(.ev-cal-dayname)');
  if (cells[day-1]) cells[day-1].classList.add('selected');

  if (!dayEvents.length) {
    detail.innerHTML = '<div style="text-align:center;padding:16px;color:var(--muted);font-size:12px;">No events on this day</div>';
    return;
  }
  const b = CU.bastions?.[curBastion];
  const canManage = b?.owner === CU.username || hasPerm('administrator') || hasPerm('manage_channels');
  const now = new Date();
  detail.innerHTML = '<div class="ev-cal-day-list">' + dayEvents.map(ev => _renderEventCard(ev, bastionId, canManage, now)).join('') + '</div>';
}

// ════════════════════════════════════════════
// USER NOTES (private, localStorage)
// ════════════════════════════════════════════
function _openUserNote(username) {
  if (!username) return;
  const notes = JSON.parse(localStorage.getItem('ftz_user_notes_' + CU.username) || '{}');
  const existing = notes[username] || '';
  showCustomInput('Note on ' + username, 'Private note (only visible to you):', (note) => {
    if (note === null) return;
    notes[username] = note;
    localStorage.setItem('ftz_user_notes_' + CU.username, JSON.stringify(notes));
    toast(note ? 'Note saved!' : 'Note cleared','success');
  }, existing);
}
function _getUserNote(username) {
  const notes = JSON.parse(localStorage.getItem('ftz_user_notes_' + CU.username) || '{}');
  return notes[username] || '';
}

// ════════════════════════════════════════════
// SLOW MODE PER CHANNEL
// ════════════════════════════════════════════
let _slowModeCooldowns = {};
function _getSlowMode(bastionId, chName) {
  return parseInt(localStorage.getItem('ftz_slowmode_' + bastionId + '_' + chName) || '0');
}
function _setSlowMode(bastionId, chName, seconds) {
  if (seconds > 0) localStorage.setItem('ftz_slowmode_' + bastionId + '_' + chName, seconds);
  else localStorage.removeItem('ftz_slowmode_' + bastionId + '_' + chName);
  toast(seconds > 0 ? 'Slow mode: ' + seconds + 's' : 'Slow mode disabled','success');
  // Update via Firebase for all users
  try { firebase.database().ref('bastionSettings/' + bastionId + '/slowmode/' + chName).set(seconds); } catch(e) { console.warn('[SlowMode] save failed', e); }
}
// Sync slow mode from Firebase so all users see the setting
function _syncSlowMode(bastionId, chName) {
  try {
    firebase.database().ref('bastionSettings/' + bastionId + '/slowmode/' + chName).on('value', snap => {
      const v = parseInt(snap.val() || '0');
      if (v > 0) localStorage.setItem('ftz_slowmode_' + bastionId + '_' + chName, v);
      else localStorage.removeItem('ftz_slowmode_' + bastionId + '_' + chName);
    });
  } catch(e) { console.debug('[SlowMode] sync listener failed', e); }
}
function _checkSlowMode() {
  if (curBastion === null) return true;
  const b = CU.bastions?.[curBastion]; const ch = b?.channels?.[curChannel];
  const bid = b?.globalId||b?.name; const chName = ch?.name||'general';
  if (!bid) return true;
  const cooldown = _getSlowMode(bid, chName);
  if (!cooldown) return true;
  const key = bid + '_' + chName;
  const last = _slowModeCooldowns[key] || 0;
  const elapsed = (Date.now() - last) / 1000;
  if (elapsed < cooldown) {
    toast('Slow mode: wait ' + Math.ceil(cooldown - elapsed) + 's', 'info');
    return false;
  }
  _slowModeCooldowns[key] = Date.now();
  return true;
}
function _showSlowModeSettings(bastionId, chName) {
  const current = _getSlowMode(bastionId, chName);
  const opts = [0, 30, 60, 300];
  const labels = ['Off', '30s', '1m', '5m'];
  let html = '<div style="padding:20px;"><div style="font-family:var(--font-display);font-size:15px;font-weight:800;margin-bottom:12px;">Slow Mode</div>';
  html += '<div style="display:flex;gap:8px;flex-wrap:wrap;">';
  opts.forEach((s,i) => {
    html += `<button class="btn-${s===current?'a':'g'}" style="padding:8px 16px;font-size:12px;" onclick="_setSlowMode('${escapeHTML(bastionId)}','${escapeHTML(chName)}',${s});document.getElementById('modal-slowmode')?.remove();">${labels[i]}</button>`;
  });
  html += '</div></div>';
  _showQuickModal('modal-slowmode', html);
}

// ════════════════════════════════════════════
// FRIEND LIST SORTING
// ════════════════════════════════════════════
let _friendSortMode = 'online';
async function renderFriendsSorted(mode) {
  _friendSortMode = mode || _friendSortMode;
  const list = document.getElementById('friends-list');
  if (!list) return;
  const friends = CU?.friends || [];
  const pending = CU?.friendRequestsReceived || [];
  let html = '';
  // Pending section first
  if (pending.length) {
    html += `<div style="font-family:var(--font-display);font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);margin-bottom:8px;">Pending — ${pending.length}</div>`;
    pending.forEach(f => { html += `<div class="activity-item"><div class="act-icon">${buildAvatarHTML(null,f,40)}</div><div class="act-text"><p><strong>${escapeHTML(f)}</strong> sent you a friend request</p></div><div style="display:flex;gap:6px;"><button class="rn-accept" onclick="acceptFriend('${escapeHTML(f)}')">✓</button><button class="rn-decline" onclick="declineFriend('${escapeHTML(f)}')">✕</button></div></div>`; });
  }
  if (!friends.length) { list.innerHTML = html || `<div class="empty-state"><div class="ei" style="color:rgba(255,255,255,.15);">${ftzIcon('users','48')}</div><h3>No friends yet</h3><p>Add friends by username!</p><button class="btn-a" onclick="openModal('modal-add-friend')">+ Add Friend</button></div>`; return; }
  // Fetch statuses
  let statuses = {};
  try { const snap = await firebase.database().ref('statuses').get(); if (snap.exists()) statuses = snap.val(); } catch(e) { console.debug('[Friends] status fetch failed', e); }
  let sorted = [...friends];
  if (_friendSortMode === 'online') sorted.sort((a,b) => { const sa = statuses[a]==='online'?2:statuses[a]==='away'?1:0; const sb = statuses[b]==='online'?2:statuses[b]==='away'?1:0; return sb-sa; });
  else if (_friendSortMode === 'alpha') sorted.sort((a,b) => a.localeCompare(b));
  else if (_friendSortMode === 'recent') sorted.reverse();
  html += `<div style="display:flex;align-items:center;gap:6px;margin:10px 0 8px;">
    <span style="font-family:var(--font-display);font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);">Friends — ${friends.length}</span>
    <span style="margin-left:auto;display:flex;gap:4px;">
      <button class="asf-chip ${_friendSortMode==='online'?'active':''}" onclick="renderFriendsSorted('online')" style="font-size:10px;padding:2px 8px;">Online</button>
      <button class="asf-chip ${_friendSortMode==='alpha'?'active':''}" onclick="renderFriendsSorted('alpha')" style="font-size:10px;padding:2px 8px;">A-Z</button>
      <button class="asf-chip ${_friendSortMode==='recent'?'active':''}" onclick="renderFriendsSorted('recent')" style="font-size:10px;padding:2px 8px;">Recent</button>
    </span>
  </div>`;
  sorted.forEach(f => {
    const st = statuses[f] || 'offline';
    const stColor = st==='online'?'#3ecf6e':st==='away'?'#f59e0b':st==='dnd'?'#f87171':'#4a4a5a';
    html += `<div class="activity-item" id="friend-sorted-${escapeHTML(f)}"><div class="act-icon" style="position:relative;">${buildAvatarHTML(null,f,40)}<div style="position:absolute;bottom:0;right:0;width:10px;height:10px;border-radius:50%;background:${stColor};border:2px solid var(--panel);"></div></div><div class="act-text"><p style="font-weight:600;">${escapeHTML(f)}</p><div><span style="font-size:10px;color:${stColor};">${st}</span><span id="friend-sorted-act-${escapeHTML(f)}" style="font-size:10px;color:rgba(255,255,255,.2);margin-left:6px;"></span></div></div><div style="display:flex;gap:6px;"><button class="btn-g" style="padding:6px 12px;font-size:12px;" onclick="openDMView('${escapeHTML(f)}')" style="display:inline-flex;align-items:center;">${ftzIcon('chat','14')}</button><button class="btn-d" style="padding:6px 12px;font-size:12px;" onclick="removeFriend('${escapeHTML(f)}')">Remove</button></div></div>`;
  });
  list.innerHTML = html;

  // Async: fetch user data to show activities
  try {
    const profiles = await (FortizedSocial.getUsersByNames ? FortizedSocial.getUsersByNames(sorted) : Promise.all(sorted.map(f => FortizedSocial.getUserByName(f))));
    const profileMap = {};
    (profiles || []).forEach(u => { if (u) profileMap[u.username] = u; });

    sorted.forEach(f => {
      const u = profileMap[f];
      if (!u) return;

      let activityText = '';
      if (u.activityState?.activities?.length) {
        const primaryActivity = u.activityState.activities.sort((a, b) => (b.priority || 2) - (a.priority || 2))[0];
        if (primaryActivity) activityText = formatActivityDisplay(primaryActivity);
      } else if (u.gameActivity?.name) {
        activityText = formatActivityDisplay({
          id: u.gameActivity._spotify ? 'spotify' : 'game',
          type: u.gameActivity._spotify ? 'listening' : 'playing',
          name: u.gameActivity.name,
          metadata: { genre: u.gameActivity.genre }
        });
      }
      const actEl = document.getElementById('friend-sorted-act-'+f);
      if (actEl && activityText) actEl.textContent = '🎮 ' + activityText;
    });
  } catch(e) { console.debug('[Friends] activity fetch failed', e); }
}

// ════════════════════════════════════════════
// FAVOURITES / QUICK ACCESS
// ════════════════════════════════════════════
function _getFavourites() { return JSON.parse(localStorage.getItem('ftz_favourites_' + CU.username) || '[]'); }
function _saveFavourites(favs) { localStorage.setItem('ftz_favourites_' + CU.username, JSON.stringify(favs)); }
function _toggleFavourite(type, id, label) {
  const favs = _getFavourites();
  const idx = favs.findIndex(f => f.type === type && f.id === id);
  if (idx >= 0) { favs.splice(idx,1); toast('Removed from favourites','info'); }
  else { favs.unshift({ type, id, label }); toast('Added to favourites!','success'); }
  _saveFavourites(favs);
  _renderFavourites();
}
function _renderFavourites() {
  const favs = _getFavourites();
  let section = document.getElementById('fav-section');
  if (!favs.length) { if (section) section.remove(); return; }
  if (!section) {
    section = document.createElement('div');
    section.className = 'fav-section'; section.id = 'fav-section';
    const nav = document.querySelector('.sidebar-nav');
    if (nav) nav.parentElement.insertBefore(section, nav.nextElementSibling);
    else return;
  }
  section.innerHTML = `<div class="fav-header">${ftzIcon('star','12')} Quick Access</div>` +
    favs.slice(0,5).map(f => `<div class="fav-item" onclick="_openFavourite('${f.type}','${escapeHTML(f.id)}')"><span class="fav-star">★</span>${escapeHTML(f.label||f.id)}</div>`).join('');
}
function _openFavourite(type, id) {
  if (type === 'dm') openDMView(id);
  else if (type === 'channel') { /* navigate to channel */ toast('Opening channel…','info'); }
}

// ════════════════════════════════════════════
// NOTIFICATION SETTINGS PER CHANNEL
// ════════════════════════════════════════════
function _getChannelNotifSetting(channelKey) {
  const settings = JSON.parse(localStorage.getItem('ftz_channel_notifs_' + CU.username) || '{}');
  return settings[channelKey] || 'all';
}
function _setChannelNotifSetting(channelKey, mode) {
  const settings = JSON.parse(localStorage.getItem('ftz_channel_notifs_' + CU.username) || '{}');
  settings[channelKey] = mode;
  localStorage.setItem('ftz_channel_notifs_' + CU.username, JSON.stringify(settings));
}
function _showChannelNotifSettings(channelKey, channelName) {
  document.querySelector('.notif-settings-modal')?.remove();
  const current = _getChannelNotifSetting(channelKey);
  const el = document.createElement('div');
  el.className = 'notif-settings-modal';
  el.onclick = e => { if (e.target === el) el.remove(); };
  const modes = [
    { id:'all', icon:ftzIcon('bell','16'), label:'All Messages', desc:'Get notified for every message' },
    { id:'mentions', icon:'@', label:'Mentions Only', desc:'Only when you are mentioned' },
    { id:'muted', icon:ftzIcon('bellOff','16'), label:'Muted', desc:'No notifications from this channel' },
  ];
  el.innerHTML = `<div class="ns-card">
    <h3>Notifications — ${escapeHTML(channelName||'Channel')}</h3>
    ${modes.map(m=>`<div class="ns-opt ${current===m.id?'active':''}" onclick="_setChannelNotifSetting('${escapeHTML(channelKey)}','${m.id}');this.closest('.notif-settings-modal').remove();toast('Notification setting updated','success');">
      <div class="nso-icon">${m.icon}</div>
      <div><div class="nso-label">${m.label}</div><div class="nso-desc">${m.desc}</div></div>
    </div>`).join('')}
  </div>`;
  document.body.appendChild(el);
}

// ════════════════════════════════════════════
// POLLS 2.0 — Enhanced polls with timers, anonymous voting, result graphs
// ════════════════════════════════════════════
function _createPoll2(container, context) {
  let pollOptions = ['',''];
  let isAnonymous = false;
  let expiresIn = 0;
  const modal = document.createElement('div');
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(12,14,20,.88);backdrop-filter:blur(12px);z-index:8000;display:flex;align-items:center;justify-content:center;';
  modal.onclick = e => { if (e.target === modal) modal.remove(); };
  const _renderPollCreate = () => {
    modal.innerHTML = `<div style="background:var(--panel);border:1px solid var(--border);border-radius:22px;max-width:420px;width:100%;padding:24px;">
      <div style="font-family:var(--font-display);font-size:17px;font-weight:800;margin-bottom:14px;">Create Poll</div>
      <input id="poll2-question" class="settings-input" placeholder="Ask a question…" style="margin-bottom:12px;font-size:14px;">
      <div id="poll2-options" style="margin-bottom:12px;">
        ${pollOptions.map((o,i)=>`<div style="display:flex;gap:6px;margin-bottom:6px;align-items:center;">
          <input class="settings-input poll2-opt-input" value="${escapeHTML(o)}" placeholder="Option ${i+1}" style="flex:1;">
          ${i>1?`<button onclick="this.parentElement.remove()" style="background:none;border:none;color:var(--red);cursor:pointer;font-size:16px;">✕</button>`:''}
        </div>`).join('')}
      </div>
      <button class="btn-g" style="padding:5px 12px;font-size:11px;margin-bottom:14px;" onclick="document.getElementById('poll2-options').insertAdjacentHTML('beforeend','<div style=\\'display:flex;gap:6px;margin-bottom:6px;align-items:center;\\'><input class=\\'settings-input poll2-opt-input\\' placeholder=\\'Option\\' style=\\'flex:1;\\'><button onclick=\\'this.parentElement.remove()\\' style=\\'background:none;border:none;color:var(--red);cursor:pointer;font-size:16px;\\'>✕</button></div>')">+ Add Option</button>
      <div style="display:flex;gap:12px;margin-bottom:16px;">
        <label style="display:flex;align-items:center;gap:6px;font-size:12px;color:var(--muted-light);cursor:pointer;">
          <input type="checkbox" id="poll2-anon"> Anonymous voting
        </label>
        <select id="poll2-expire" class="settings-input" style="width:auto;font-size:11px;">
          <option value="0">No expiry</option>
          <option value="3600000">1 hour</option>
          <option value="86400000">24 hours</option>
          <option value="604800000">7 days</option>
        </select>
      </div>
      <div style="display:flex;gap:8px;justify-content:flex-end;">
        <button class="btn-g" onclick="this.closest('[style*=fixed]').remove()">Cancel</button>
        <button class="btn-a" onclick="_submitPoll2(this.closest('[style*=fixed]'))">Create Poll</button>
      </div>
    </div>`;
  };
  _renderPollCreate();
  document.body.appendChild(modal);
}
function _submitPoll2(modal) {
  const question = document.getElementById('poll2-question')?.value?.trim();
  if (!question) { toast('Enter a question','error'); return; }
  const optInputs = document.querySelectorAll('.poll2-opt-input');
  const options = [...optInputs].map(i=>i.value.trim()).filter(Boolean);
  if (options.length < 2) { toast('Need at least 2 options','error'); return; }
  const isAnon = document.getElementById('poll2-anon')?.checked || false;
  const expiresIn = parseInt(document.getElementById('poll2-expire')?.value || '0');
  const poll = {
    question, options: options.map(o=>({label:o,votes:{}})), anonymous: isAnon,
    expiresAt: expiresIn > 0 ? new Date(Date.now()+expiresIn).toISOString() : null,
    createdBy: CU.username, createdAt: new Date().toISOString(),
  };
  // Send as a special message
  const text = `[POLL] ${question}`;
  if (curDM) {
    const key = [CU.username,curDM].sort().join('__');
    firebase.database().ref('dms/'+key).push({ from:CU.username, text, timestamp:new Date().toISOString(), poll });
  } else if (curBastion !== null) {
    const b = CU.bastions?.[curBastion]; const ch = b?.channels?.[curChannel];
    const bid = b?.globalId||b?.name; const chName = ch?.name||'general';
    if (bid) firebase.database().ref(`bastionMsgs/${bid}/${chName}`).push({ from:CU.username, text, timestamp:new Date().toISOString(), poll });
  }
  modal.remove();
  toast('Poll created!','success');
}

// ════════════════════════════════════════════
// HELPER: Quick modal for various features
// ════════════════════════════════════════════
function _showQuickModal(id, html) {
  document.getElementById(id)?.remove();
  const el = document.createElement('div');
  el.id = id;
  el.style.cssText = 'position:fixed;inset:0;background:rgba(12,14,20,.85);backdrop-filter:blur(12px);z-index:8000;display:flex;align-items:center;justify-content:center;';
  el.onclick = e => { if (e.target === el) el.remove(); };
  el.innerHTML = `<div style="background:var(--panel);border:1px solid var(--border);border-radius:20px;max-width:400px;width:100%;">${html}</div>`;
  document.body.appendChild(el);
}
function _closeEl(id) { const el = document.getElementById(id); if (el) { el.style.opacity='0'; el.style.transition='opacity .15s'; setTimeout(()=>el.remove(),150); } }

// ════════════════════════════════════════════
// LAST SEEN TRACKING
// ════════════════════════════════════════════
function _updateLastSeen() {
  if (!CU?.username) return;
  const now = new Date().toISOString();
  try { firebase.database().ref('users/' + CU.username + '/lastSeen').set(now); } catch(e) { console.debug('[LastSeen] write failed', e); }
}
// Update last seen every 2 minutes
if (typeof window !== 'undefined') setInterval(_updateLastSeen, 120000);

