// INIT NEW FEATURES ON APP LOAD
// ════════════════════════════════════════════
function _initNewFeatures() {
  _initKeyboardShortcuts();
  _initRailNavTooltips();
  _initGlobalTooltips();
  _renderFavourites();
}
// Hook into existing init — call after page loads
if (typeof window !== 'undefined') setTimeout(_initNewFeatures, 1500);

// ── Joyster System Account ──
async function _ensureJoysterAccount() {
  try {
    let joysterUser = await FortizedSocial.getUserByName(JOYSTER_ACCOUNT);
    if (!joysterUser) {
      // Create the joyster system account
      joysterUser = {
        username: JOYSTER_ACCOUNT,
        password: '__system_joyster_' + Date.now(),
        email: '',
        displayName: 'Joyster',
        pfp: null,
        banner: null,
        onyx: 99999,
        status: 'online',
        friends: [],
        friendRequestsSent: [],
        friendRequestsReceived: [],
        bastions: [],
        notifications: [],
        radianceUntil: null,
        lastDaily: null,
        createdAt: new Date().toISOString(),
        isBot: true,
        isAdmin: true,
        isSuperAdmin: true,
        isProtected: true,
        bio: 'Royal Jester of the Kingdom of Fortized. I serve the King~ ehheheh',
      };
      await FortizedSocial.saveUserObject(joysterUser);
    } else {
      // Ensure flags are set
      let needsUpdate = false;
      if (!joysterUser.isBot) { joysterUser.isBot = true; needsUpdate = true; }
      if (!joysterUser.isAdmin) { joysterUser.isAdmin = true; needsUpdate = true; }
      if (!joysterUser.isProtected) { joysterUser.isProtected = true; needsUpdate = true; }
      if (!joysterUser.isSuperAdmin) { joysterUser.isSuperAdmin = true; needsUpdate = true; }
      if (joysterUser.displayName !== 'Joyster') { joysterUser.displayName = 'Joyster'; needsUpdate = true; }
      if (needsUpdate) await FortizedSocial.saveUserObject(joysterUser);
    }
  } catch(e) { console.warn('[System] Joyster account init failed', e); }
}

